using namespace std;
using P = pair<int, int>;

int main() {
	int N;
	cin >> N;
	vector<ll> a(N);
	vector<int> indx(N + 1);
	for (int i = 0; i < N; ++i) {
		cin >> a[i];
		indx[a[i]] = i;
	}

	vector<P> d(N + 1);
	d[1] = P(0, N - 1);
	vector<int> tmp;
	tmp.push_back(indx[1]);
	for (int i = 2; i <= N; ++i) {
		int l, r;
		int m = indx[i];
		int it = lower_bound(tmp.begin(), tmp.end(), m) - tmp.begin();
		if (it == tmp.size()) {
			r = N - 1;
			l = tmp[it - 1] + 1;
		} else if (it == 0) {
			r = tmp[it] - 1;
			l = 0;
		} else {
			r = tmp[it] - 1;
			l = tmp[it - 1] + 1;
		}

		tmp.push_back(indx[i]);
		sort(tmp.begin(), tmp.end());
		d[i] = P(l, r);
	}

	ll res = 0;
	for (int i = 1; i <= N; ++i) {
		int l = indx[i] - d[i].first + 1;
		int r = d[i].second - indx[i] + 1;

		res += (l * r * i);
	}

	cout << res << endl;

	return 0;
}

