    cin >> N;
    SegmentTree st = SegmentTree(N);
    FOR(i, 0, N) {
        cin >> a;
        st.update(i, a);
    }

    LL ans = 0;
    FOR(l, 0, N) {
        FOR(r, l, N) {
            ans += st.query(l, r + 1);
        }
    }
    cout << ans << endl;

    return 0;
}

