typedef long long ll;

struct para
{
    int m, M;
};

vector<para> T;
int l, size;

void Stworz(int n)
{
    int p = 1;
    while (p < n)
        p *= 2;
    l = p;
    size = 2 * p - 1;
    for (int i = 0; i <= size; ++i)
        T.push_back({1e9, -1e9});
}

void Dodaj(int a, int x)
{
    a += l;
    T[a] = {x, x};
    a /= 2;
    while (a != 0)
    {
        T[a].m = min(T[2 * a].m, T[2 * a + 1].m);
        T[a].M = max(T[2 * a].M, T[2 * a + 1].M);
        a /= 2;
    }
}

int Min(int a, int b)
{
    if (a > b)
        return 1e9;
    a += l;
    b += l;
    int odp = min(T[a].m, T[b].m);
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            odp = min(odp, T[a + 1].m);
        if (b % 2 == 1)
            odp = min(odp, T[b - 1].m);
        a /= 2;
        b /= 2;
    }
    return odp;
}

int Max(int a, int b)
{
    if (a > b)
        return -1e9;
    a += l;
    b += l;
    int odp = max(T[a].M, T[b].M);
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            odp = max(odp, T[a + 1].M);
        if (b % 2 == 1)
            odp = max(odp, T[b - 1].M);
        a /= 2;
        b /= 2;
    }
    return odp;
}

