#include<stdio.h>

struct data
{
    int x,v;
    data(){};
    data(int x, int v):x(x),v(v){};
    bool operator<(const data &r)const{
        return v<r.v;
    }
};

data tree[1000005];
int n;
typedef long long LL;

data min(data a, data b)
{
    if(a<b)return a;
    return b;
}
void update(int n, int s, int e, int si, int ei, data v)
{
    if(e<si|s>ei)return;
    if(si<=s&&e<=ei){
        tree[n]=v;
        return;
    }
    int m=(s+e)/2,lch=2*n,rch=lch+1;
    update(lch,s,m,si,ei,v);
    update(rch,m+1,e,si,ei,v);
    tree[n]=min(tree[lch],tree[rch]);
}

data query(int n, int s, int e, int si, int ei)
{
    if(e<si|s>ei)return data(0,1e9);
    if(si<=s&&e<=ei){
        return tree[n];
    }
    int m=(s+e)/2,lch=2*n,rch=lch+1;
    data v1,v2;
    v1=query(lch,s,m,si,ei);
    v2=query(rch,m+1,e,si,ei);
    return min(v1,v2);
}

LL g(int X, int Y)
{
    return (LL)X*(X+1)/2-(LL)Y*(Y+1)/2-(LL)(X-Y-1)*(X-Y)/2;
}

LL f(int s, int e)
{
    if(s>e)return 0;
    data t=query(1,1,n,s,e);
    int X=e-s+1,Y=t.x-s;
    return g(X,Y)*t.v+f(s,t.x-1)+f(t.x+1,e);
}

