	if(x==y)return;
	if(rankh[x]<rankh[y]){
		par[x]=y;
		size[y]+=size[x];
	}
	else{
		par[y]=x;
		if(rankh[x]==rankh[y])rankh[x]++;
		size[x]+=size[y];
