void init( ll n_ ){
  memset( dat, 0, sizeof( dat ) );
  n = 1;
  while( n < n_ ){
    n *= 2;
    d++;
  }
  dls = n;
  ep = n - 1;
  v_num = 2 * n - 1;

  for( ll i = 0; i < 2 * n ; i++ ) dat[i] = INT_MAX;
}

void update( ll k,ll a ){
  k += n - 1;
  dat[k] = a;
  ll max = 0;
  REP( i, n - 1, 2 * n ){
    max = fmax( max, dat[i] );
  }
  REP( i, k + 1, 2 * n ){
    dat[i] = max;
  }
  while( k > 0 ){
    k = ( k - 1 ) / 2;
    dat[ k ] = fmin( dat[ k * 2 + 1 ], dat[ k * 2 + 2 ] );
  }
}

ll query(ll a, ll b, ll k, ll l , ll r){
  if( r <= a || b <= l){
    return INT_MAX;
  }else if( a <= l && r <= b ){
    return dat[k];
  }
  else{
    ll vl = query( a, b, k * 2 + 1, l, ( l + r ) / 2 );
    ll vr = query( a, b, k * 2 + 2, ( l + r ) / 2, r);
    return fmin( vl, vr );
  }
}

