const int maxn = 1e6 + 10;
const int inf = 0x7fffffff;
class stack {
    protected:
        int st[maxn], tp;
    public:
        stack() { tp = 0; }
        void clear() { tp = 0; }
        int top() { return st[tp]; }
        void pop() { tp--; }
        bool empty() { return !tp; }
        void push(int x) { st[++tp] = x; }
}T;
int n;
LL ans, a[maxn];
int l[maxn], r[maxn];
int main() {
    n = in();
    for(int i = 1; i <= n; i++) a[i] = in();
    a[0] = a[n + 1] = -inf;
    T.push(0);
    for(int i = 1; i <= n; i++) {
        while(!T.empty() && a[i] <= a[T.top()]) T.pop();
        l[i] = T.top(); T.push(i);
    }
    T.clear(); T.push(n + 1);
    for(int i = n; i >= 1; i--) {
        while(!T.empty() && a[i] < a[T.top()]) T.pop();
        r[i] = T.top(); T.push(i);
    }
    for(int i = 1; i <= n; i++) ans += 1LL * (i - l[i]) * (r[i] - i) * a[i];
    printf("%lld\n", ans);
    return 0;
}

