int main()
{
    int N;
    scanf("%d\n", &N);
    vector<int> A_inv(N);
    for (int i = 0; i < N; ++i){
        int Ai;
        scanf("%d", &Ai); --Ai; getchar();
        A_inv[Ai] = i;
    }
    set<int, greater<int>> lower;
    set<int> upper;
    long long result = 0;
    for (int i = 0; i < N; ++i){
        int l, u;
        {
            auto lit = lower.upper_bound(A_inv[i]);
            if (lit == lower.end()){
                l = -1;
            }else{
                l = *lit;
            }
            auto uit = upper.upper_bound(A_inv[i]);
            if (uit == upper.end()){
                u = N;
            }else{
                u = *uit;
            }
        }
        result += static_cast<long long>(i + 1) * (A_inv[i] - l) * (u - A_inv[i]);
        lower.emplace(A_inv[i]);
        upper.emplace(A_inv[i]);
    }
    printf("%lld\n", result);
}

#include <stack>
