const int MaxN = 200000 + 10 ;
int N , P[MaxN] , Np[MaxN] ;
int Siz[MaxN] , Find[MaxN] ;
long long Ans ;
int F( int Nod ) {
	return Find[Nod] ? ( Find[Nod] == Nod ? Nod : Find[Nod] = F( Find[Nod] ) ) : 0 ;
}
inline void Merge( int A , int B ) {
	A = F(A) ;
	B = F(B) ;
	if( B ) {
		Siz[A] += Siz[B] ;
		Find[B] = A ;
	}
}
int main() {
	Readin( N ) ;
	for(register int i = 0 ; ++i <= N ; ) {
		Readin( P[i] ) ;
		Np[P[i]] = i ;
	}
	for(register int i = N ; i ; --i ) {
		Ans += 1ll * ( Siz[F(Np[i]-1)] + 1 ) * ( Siz[F(Np[i]+1)] + 1 ) * i ;
		Find[Np[i]] = Np[i] ;
		Siz[Np[i]] = 1 ;
		Merge( Np[i] , Np[i] - 1 ) ;
		Merge( Np[i] , Np[i] + 1 ) ;
	}
	return not printf( "%lld\n" , Ans ) ;
}

