    for (int i = n - 1; i >= 0; --i)
    {
        while (st.size() > 0 && st.top().first >= P[i])
            st.pop();
        next[i] = st.top().second;
        st.push({P[i], i});
    }
    long long sum = 0;
    for (int i = 0; i < n; ++i)
    {
        sum += P[i] * (next[i] - i) * (i - prev[i] + 1);
    }
