  st.clear();
  rrep(i, 1, n + 2) {
    while (st.size() > 0 && a[st.back()] >= a[i]) st.pop_back();
    R[i] = st.size() > 0 ? st.back() : n + 1;
    st.push_back(i);
  }

  ll ans = 0;
  rep(i, 1, n + 1) ans += a[i] * (R[i] - i) * (i - L[i] + 1);

