void init(int N_){
  N=1;
  while(N<N_){
    N*=2;
  }
  FOR(i,0,2*N-1){
    DAT[i]=INT_MAX;
  }
}
//
void update(int K,int A){
  K+=N-1;
  DAT[K]=A;
  while(K>0){
    K=(K-1)/2;
    DAT[K]=min(DAT[K*2+1],DAT[K*2+2]);
  }
}
