const int MAX_N = 200050;

int bit[MAX_N], a[MAX_N];
int N;

int sum(int i) {
    int s = 0;
    while (i > 0) {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}

void add(int i, int x) {
    while (i <= N) {
        bit[i] += x;
        i += i & -i;
    }
}

int seg(int i, int j) {
    assert(i <= j);
    if (i == 0) {
        return sum(j);
    } else {
        return sum(j) - sum(i-1);
    }
}

int findr(int i) {
    if (seg(i, N) == N - i + 1) {
        return N;
    } else {
        int lb = i;
        int ub = N;
        while (lb + 1 < ub) {
            int mid = (lb + ub) / 2;
            if (seg(i, mid) == mid - i + 1) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return lb;
    }
}

int findl(int i) {
    if (seg(1, i) == i) {
        return 1;
    } else {
        int lb = 1;
        int ub = i;
        while (lb + 1 < ub) {
            int mid = (lb + ub) / 2;
            if (seg(mid, i) == i - mid + 1) {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        return ub;
    }
}

long long seg_num(long long i, long long j) {
    if (j < i) {
        return 0;
    } else {
        return (j - i + 1 + 1) * (j - i + 1) / 2;
    }
}

int main(int argc, char **argv) {
