    for (int i = 0; i < MAX_N; i++) {
        bit[i] = 0;
    }
    std::vector<std::pair<int, int>> vec;

    for (int i = 1; i <= N; i++) {
        vec.push_back(std::pair<int,int>({a[i], i}));
    }
    std::sort(vec.begin(), vec.end());

    long long ret = 0;
    for (int i = vec.size() - 1; 0 <= i; i--) {
        int loc = vec[i].second;
        int val = vec[i].first;
        assert(val == i + 1);
        add(loc, 1);
        int left = findl(loc);
        int right = findr(loc);
        long long num = seg_num(left, right) - seg_num(loc + 1, right) - seg_num(left, loc - 1);
        //std::cout << val << " " << loc << " " << left << " " << right << " " << num << std::endl;
        ret += num * val;
    }

    //std::cout << seg_num(1, 3) << " " << 

    std::cout << ret << std::endl;

    return 0;
}

