int dirx[8] = {-1,0,0,1,-1,-1,1,1};
int diry[8] = {0,1,-1,0,-1,1,-1,1};

int rb[200000];
int lb[200000];

long long solve(int * p, int n) {
	long long cnt = 0;
	vector<int> st;
	REP(i, 0, n){
		while(!st.empty() && p[st.back()] > p[i])
			st.pop_back();
		if (st.empty())
			lb[i] = -1;
		else
			lb[i] = st.back();
		st.push_back(i);
	}
	st.clear();
	REPN(i, n - 1,-1) {
		while(!st.empty() && p[st.back()] > p[i])
			st.pop_back();
		if (st.empty())
			rb[i] = n;
		else
			rb[i] = st.back();
		st.push_back(i);
	}

	REP(i,0,n) {
		cnt += p[i] * (i - lb[i]) * (rb[i] - i);
	}
	return cnt;
}

