        return;
    }

    int tm = (tl + tr) / 2;
    build(v * 2, tl, tm);
    build(v * 2 + 1, tm + 1, tr);

    t[v] = min(t[v * 2], t[v * 2 + 1]);
}

int getMin(int v, int tl, int tr, int l, int r) {
    if (l > r)
        return INT_MAX;

    if (tl == l && tr == r) {
        return t[v];
    }

    int tm = (tl + tr) / 2;

    int ans1 = INT_MAX, ans2 = INT_MAX;
    if (l <= min(r, tm))
        ans1 = getMin(v * 2, tl, tm, l, min(r, tm));
    if (max(l, tm + 1) <= r)
        ans2 = getMin(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);

    return min(ans1, ans2);
}

int find_min_pos (int x, int pos) {
    int l = pos, r = n + 1;
    while (r - l > 1) {
        int m = (l + r) / 2;
        int mn = getMin(1, 1, n, pos, m);
        if (mn >= x) {
            l = m;
        }
        else {
            r = m;
        }
    }

    return l + 1;
}


