void build (int v, int tl, int tr) {
	if (tl == tr)
		t[v] = make_pair (a[tl], 1ll);
	else {
		int tm = (tl + tr)>>1;
		build (v*2, tl, tm);
		build (v*2+1, tm+1, tr);
		t[v] = combine (t[v*2], t[v*2+1]);
	}
}

pair<ll,ll> get_min (int v, int tl, int tr, int l, int r) {
	if (l > r)
		return make_pair (inf, 0);
	if (l == tl && r == tr)
		return t[v];
	int tm = (tl + tr) / 2;
	return combine (
		get_min (v*2, tl, tm, l, min(r,tm)),
		get_min (v*2+1, tm+1, tr, max(l,tm+1), r)
	);
}

ll ans = 0;
int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(NULL);
	ll cur = inf;
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	build(1, 0, N-1);
	for(int l = 0; l < n; l++){
		int r = l;
		cur = inf;
		while(1){
			if(r == n) break;
			pair <ll, ll> m = get_min(1, 0, N-1, l, r);
			cur = min(m.ff, cur);
			ans+=cur;
			r++;
		}
	}
	cout << ans;
	return 0;
}

