    REP(i, N) cin >> a[i];

    //orderは値a[i]がa内で何番目に出てくるかを格納する
    REP(i, N) order[a[i] - 1] = i;

    //ある値iより小さい値たちの、位置order[i]を格納する。
    set<int> S;

    //番犬
    S.insert(-1);
