    for(int i = 1; i <= n; i++)cin >> a[i];

    SegTree<int> tree(a, 1e9, [](int a, int b){return min(a, b);}, [](int a, int b){return b;});
    ll sum = 0;


    for(int i = 1; i <= n; i++) {

        int l, r;


        //left
        {
            int lef = 0, rig = i + 1; //get(k, i) == iとなるような最小のk xxxxxxoooo /(]
            while(rig - lef > 1) {
                int mid = (rig + lef) / 2;
                (tree.get(mid, i + 1) == a[i] ? rig : lef) = mid;
            }
            l = rig;
        }

        //right
        {
            int lef = i, rig = n + 2; //ooooooooxxx
            while(rig - lef > 1) {
                int mid = (rig + lef) / 2;
                (tree.get(i, mid) == a[i] ? lef : rig) = mid;
            }
            r = lef;
        }
