		}
		FORR(i, 0, n-1){
			node[i]=min(node[i*2+1], node[i*2+2]);
		}
	}

	// k番目(0-indexed)をaに変更
	void update(int k, const T &a){
		k+=n-1;
		node[k]=a;
		while(k>0){
			k=(k-1)/2;
			node[k]=min(node[k*2+1], node[k*2+2]);
		}
	}

	// [a, b)の最小値を求める
	// k: 節点の番号、その節点は[l, r)に対応づく
	T query(int a, int b, int k, int l, int r){
		// [a, b)と[l, r)が交差しなければMAX
		if(r<=a || b<=l){
			return MAX;
		}
		// [a, b)と[l, r)が完全に含んでいればこの節点の値
		if(a<=l && r<=b){
			return node[k];
		}
		// そうでなければ2つの子の最小値
		else{
			T v1=query(a, b, k*2+1, l, (l+r)/2), v2=query(a, b, k*2+2, (l+r)/2, r);
			return min(v1, v2);
		}
	}

	T query(int a, int b){
		return query(a, b, 0, 0, n);
	}
};

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	// cout<<setprecision(10)<<fixed;
	int n;
	vi a(252525);
	cin>>n;
	REP(i, n){
		cin>>a[i];
	}
	SegmentTree_min<int> st(a);
	ll ans=0;
	REP(i, n){
		ll l1=-1, u1=i+1;
		while(u1-l1>1){
			ll mid=(l1+u1)/2;
			if(st.query(mid, i+1)==a[i]){
				u1=mid;
			}
			else{
				l1=mid;
			}
		}
		ll l2=i, u2=n+1;
		while(u2-l2>1){
			ll mid=(l2+u2)/2;
			if(st.query(i, mid+1)==a[i]){
				l2=mid;
			}
			else{
				u2=mid;
			}
		}
		// DEBUG(u1);
		// DEBUG(l2);
		ans+=a[i]*((i-u1+1)*(l2-i+1));
	}
	cout<<ans<<'\n';
	return 0;
}

