const long long Maxn = 200005;
const long long inf = 1e9;
long long a[Maxn];
vector <long long> NSVL, NSVR;
int main() {
   long long n;
   scanf("%lld", &n);
   for(long long i = 1; i <= n; i++) {
      scanf("%lld", &a[i]);
   }      
   a[0] = -inf;
   a[n + 1] = -inf;

   NSVL.resize(n + 2), NSVR.resize(n + 2);

   stack <long long> s;
   s.push(0);
   for(long long i = 1; i <= n; i++) {
      while(a[s.top()] >= a[i]) {
         s.pop();
      }
      NSVL[i] = s.top();
      s.push(i);
   }
   while(!s.empty()) {
      s.pop();
   }

   s.push(n + 1);
   for(long long i = n; i >= 1; i--) {
      while(a[s.top()] >= a[i]) {
         s.pop();
      }
      NSVR[i] = s.top();
      s.push(i);
   }
   while(!s.empty()) {
      s.pop();
   }

    long long ans = 0LL;
   for(long long i = 1; i <= n; i++) {
    ans += a[i] * 1LL * (NSVR[i] - i) * (i - NSVL[i]);
   }
   cout << ans<< endl;

   return 0;
}

