pair<long long, long long> seg_find(long long now, long long w_l, long long w_r, long long n_l, long long n_r) {
	if (w_l >= n_r||w_r <= n_l) return make_pair(999999, 0);
	if (w_l <= n_l&&n_r <= w_r) return seg_memo[now];
	pair<long long, long long> a = seg_find(now * 2, w_l, w_r, n_l, (n_l + n_r) / 2),b = seg_find(now * 2 + 1, w_l, w_r,(n_l + n_r) / 2,n_r);
	if (a.first < b.first) {
		return a;
	}
	else {
		return b;
	}
}
long long setting(long long now) {
	if (seg_memo[now * 2].first < seg_memo[now * 2 + 1].first) {
		seg_memo[now] = seg_memo[now * 2];
	}
	else {
		seg_memo[now] = seg_memo[now * 2 + 1];
	}
	if(now != 1) setting(now / 2);
	return 0;
}
int main() {
