LL solve()
{
  LL ret = 0;

  for (size_t i = 0; i < N; i++) {
    vecList.push_back(make_pair(A[i], i));
  }

  sort(vecList.begin(), vecList.end(), greater<II>());
  memset(posVec, -1, sizeof(posVec));

  for (size_t i = 0; i < N; i++) {
