struct SegmentTree {
	std::vector<int> seg;
	bool f = true; // t : min, f : max
	int sz = 1, n = 0;

	SegmentTree(int n, bool f) : n(n), f(f) {
		while(sz < n) sz *= 2;
		seg.assign(sz * 2 - 1, (f ? n : -1));
	}

	int update(int k, int x) {
		k += sz - 1;
		seg[k] = x;

		while(k) {
			k = (k - 1) / 2;

			if(f) seg[k] = std::min(seg[2 * k + 1], seg[2 * k + 2]);
			else seg[k] = std::max(seg[2 * k + 1], seg[2 * k + 2]);
		}
	}

	int get(int a, int b, int k, int l, int r) {
		if(b<=l||r<=a) return (f ? n : -1);
		if(a<=l&&r<=b) return seg[k];

		if(f) return std::min(get(a, b, 2 * k + 1, l, (l + r) / 2), get(a, b, 2 * k + 2, (l + r) / 2, r));
		else return std::max(get(a, b, 2 * k + 1, l, (l + r) / 2), get(a, b, 2 * k + 2, (l + r) / 2, r));
	}

	int get(int a, int b) {
		return get(a, b, 0, 0, sz);
	}

	void p() {
		for(int i = 0; i < n; i++) cout << get(i, i + 1) << " ";
		cout << endl;
	}
};

int main(){
