	for(int i = 0; i < n; i++) cin >> a[i];

	std::vector<std::vector<i64>> li(n, std::vector<i64>(2, -1));
	{
		SegmentTree seg(n, 0);
		for(int i = 0; i < n; i++) {
			li[i][0] = seg.get(0, a[i]); seg.update(a[i] - 1, i);
		}
	}

	{
		SegmentTree seg(n, 1);
		for(int i = n - 1; i >= 0; i--) {
			li[i][1] = seg.get(0, a[i]); seg.update(a[i] - 1, i);
		}
	}

	i64 ans = 0;
	for(i64 i = 0; i < n; i++) {
		ans += (i - li[i][0]) * a[i] * (li[i][1] - i);
	}
	cout << ans << endl;
