#define MAX_N (200000)
#define NUM_ELEM (1 << 21)
#define SIZE_BUF (2 * NUM_ELEM - 1)
#define INF (1000000000)

using namespace std;

long revs[MAX_N];

long buf[SIZE_BUF];

void st_init(const long *as, long N) {
  // fill leaves
  for (int i = 0; i < N; i++) {
    buf[NUM_ELEM - 1 + i] = as[i];
  }
  for (int i = N; i < NUM_ELEM; i++) {
    buf[NUM_ELEM - 1 + i] = INF;
  }

  // calculate inner nodes
  for (int i = NUM_ELEM - 2; i >= 0; i--) {
    const int chl = 2 * i + 1, chr = 2 * i + 2;
    buf[i] = min(buf[chl], buf[chr]);
  }
}

long st_query_r(long queryb, long querye, long cur, long curb, long cure) {
  if (curb >= querye || cure <= queryb) {  // no intersection
    return INF;
  } else if (queryb <= curb && cure <= querye) {  // inclusion
    return buf[cur];
  } else {
    const long m = (curb + cure) / 2, chl = 2 * cur + 1, chr = 2 * cur + 2;
    return min(st_query_r(queryb, querye, chl, curb, m),
               st_query_r(queryb, querye, chr, m, cure));
  }
}

long st_query(long queryb, long querye) {
  return st_query_r(queryb, querye, 0, 0, NUM_ELEM);
}

long solve(const long *as, long b, long e) {
  if (e - b == 0) {
    return 0;
  } else if (e - b == 1) {
    return as[b];
  }
  // find smallest value in range
  long a_min = st_query(b, e), i_min = revs[a_min];
  return a_min * (i_min - (b - 1)) * (e - i_min) + solve(as, b, i_min) +
         solve(as, i_min + 1, e);
}

int main(int argc, char *argv[]) {
  // read inputs
  long N, as[MAX_N];
  scanf("%ld", &N);
  for (int i = 0; i < N; i++) {
    scanf("%ld", &as[i]);
  }

  // create reverse map
  for (int i = 0; i < N; i++) {
    revs[as[i]] = i;
  }

  // solve
  st_init(as, N);
  printf("%ld\n", solve(as, 0, N));

  return 0;
}

