			int l=i->first,r=i->second;
			assert(l<=c && c<r);
			res+=ll(x)*(c-l+1)*(r-c);
			f.erase(i);
			if(l<c) f[l]=c;
			if(c+1<r) f[c+1]=r;
		}
		cout<<res<<endl;
	}
}

