class AGC005B
{
public:
	AGC005B()
	{
		cin >> n;
		n = n + 1;

		a.resize(n);
		a[0].value = 0;
		a[0].index = 0;
		rep(i, 1, n)
		{
			cin >> a[i].value;
			a[i].index = i;
		}
	}
	void Run(void)
	{
		ll l;
		ll r;
		ll ans = 0;
		sort(all(a));
		set<ll> a_set;

		a_set.insert(0);
		rep(i, 1, n)
		{
			auto it = a_set.lower_bound(a[i].index);

			if (it == a_set.end())
			{
				r = n - a[i].index;
				it--;
				l = (a[i].index - *it);
			}
			else
			{
				r = (*it - a[i].index);
				it--;
				l = (a[i].index - *it);
			}
			ans += a[i].value * l * r;
			a_set.insert(a[i].index);
		}

		cout << ans;
	}
private:
	ll n;
	vector <A> a;
};

