/*
・SparseTable
  > 前処理 O(NlogN)
  > query O(1)
[備考] 静的な配列における, 任意区間の最小値を定数時間で求められるデータ構造.
[使用例]
SparseTable<int> st(V);     // V(vector)で初期化し, 前処理を行う
st.query(l,r);              // 半開区間[l,r)における最小値
*/

template<typename T> struct SparseTable {
  vector<vector<T>> st;
  SparseTable() {}
  SparseTable(const vector<T> &v) {
    int b = 0;
    while((1 << b) <= v.size()) ++b;
    st.assign(b, vector<T>(1 << b));
    for(int i = 0; i < v.size(); i++) st[0][i] = v[i];
    for(int i = 1; i < b; i++) {
      for(int j = 0; j + (1 << i) <= (1 << b); j++) {
        st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
      }
    }
  }
  inline T query(int l, int r) {
    int b = 32 - __builtin_clz(r - l) - 1;
    return (min(st[b][l], st[b][r - (1 << b)]));
  }
};

signed main() {

  SS(int, N);
  SV(int, A, N);

  SparseTable<int> st(A);

  // [l, r]
  auto check = [&](int piv, int l, int r) {
    return st.query(l, r + 1) == A[piv];
  };

  ll res = 0;
  REP(i, N) {
    // A[i]
    int left = i, right = i;
    {
      int ng = -1;
      while (left - ng > 1) {
        int mid = (left + ng) / 2;
        if (check(i, mid, i)) {
          left = mid;
        } else {
          ng = mid;
        }
      }
    }
    {
      int ng = N;
      while (ng - right > 1) {
        int mid = (right + ng) / 2;
        if (check(i, i, mid)) {
          right = mid;
        } else {
          ng = mid;
        }
      }
    }
    res += (i - left + 1) * (right - i + 1) * A[i];
  }

  print(res);

}

