class SegmentTree {
    int n;
    vector<int> dat;

    // i は接点の番号、l, rはその接点が[l, r)に対応していることを示す
    int query_sub(int a, int b, int i, int l, int r) {
        if (r <= a || b <= l) return 1<<30;
        if (a <= l && r <= b)
            return dat[i];
        else {
            int vl = query_sub(a, b, i * 2 + 1, l, (l + r) / 2);
            int vr = query_sub(a, b, i * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }

public:
    // 葉がn個のセグメント木
    // 実際の葉の数は完全二分木にしているので少し増える
    SegmentTree(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat = vector<int>(2 * n - 1, N);
    }
    // i に x を入れる
    void update(int i, int x) {
        i += n - 1;
        dat[i] = x;
        while (i > 0) {
            i = (i - 1) / 2;
            dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
        }
    }
    // [a, b) の最小値を求める
    int query(int a, int b) { return query_sub(a, b, 0, 0, n); }
    // 配列にアクセス
    int at(int i) { return dat[i + n - 1]; }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);


    cin>>N;
    SegmentTree sg(N+9);

    rep(i,N) cin>>nums[i];

