// template

class UnionFind {
	vector<int> to;
	vector<int> cnt;
	vector<int> rank;

public:
	UnionFind(int N) {
		to = vector<int>(N); REP(i, N) to[i] = i;
		cnt = vector<int>(N, 1);
		rank = vector<int>(N, 1);
	}

	size_t size() {
		return to.size();
	}

	int root(int node) {
		if (node == to[node]) {
			return node;
		}
		to[node] = root(to[node]);
		return to[node];
	}

	int count(int node) {
		return cnt[root(node)];
	}

	int same(int a, int b) {
		return root(a) == root(b);
	}


	void unite(int a, int b) {
		if (rank[a] < rank[b]) swap(a, b);
		int rootb = root(b), roota = root(a);
		to[rootb] = roota;
		cnt[roota] += cnt[rootb];
		if (rank[a] == rank[b]) ++rank[a];
	}
};

#define int long long

void solve() {
	int N; cin >> N;
	vector<bool> check(N);
	UnionFind uf(N);
	vector<int> A(N); for (auto &a : A) {
		cin >> a;
	}
	vector<pii> valpos;
	REP(i, N) {
		valpos.emplace_back(A[i], i);
	}

	sort(ALL(valpos), greater<pii>());

	int res = 0;
	for (auto &vp : valpos) {
		int val = vp.first;
		int pos = vp.second;
		check[pos] = true;
		int right = 1;
		int left = 1;
		if (pos + 1 < N and check[pos + 1]) {
			right += uf.count(pos + 1);
			uf.unite(pos, pos + 1);
		}
		if (pos - 1 >= 0 and check[pos - 1]) {
			left += uf.count(pos - 1);
			uf.unite(pos, pos - 1);
		}

		res += val * (left*right);
	}
	cout << res << endl;
}

