template<typename T> void m_sort_(T a[], T b[], int l, int r, bool as) {
	if(r - l < 2) { return; }

	int m = (l + r) / 2;
	m_sort_(a, b, l, m, as);
	m_sort_(a, b, m, r, as);

	int ll = l, rr = m, bb = 0;
	while(bb < r - l) {
		bool l_flag;
		if(rr == r || ll == m) { l_flag = (rr == r); }
		else { l_flag = ( as ? (a[ll] <= a[rr]) : (a[rr] <= a[ll]) ); }

		b[bb++] = (l_flag ? a[ll++] : a[rr++]);
	}

	for(int i = l; i < r; i++) { a[i] = b[i - l]; }
}
template<typename T> void m_sort(T a[], int l, int r, bool as = true) {
	T *b = new T[r - l];
	m_sort_(a, b, l, r, as);
	delete[] b;
}

