int main() {
	int n;

	cin >> n;
	vector<int> a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}

	vector<int> right(n + 1, -1);
	vector<int> left(n + 1, -1);

	vector<int> to_left(n, 0);
	vector<int> to_right(n, 0);

	int to = -1;
	for (int i = 0; i < n; i++) {
		to_right[i] = i + 1;
		if (to > i) {
			to_right[i] = to;
			continue;
		} else {
			to = i + 1;
		}

		while (to < n) {
			if (a[to] < a[to - 1]) {
				to_right[i] = to;
				break;
			}
			to++;
		}
	}

	to = n;
	for (int i = n - 1; i >= 0; i--) {
		to_left[i] = i - 1;
		if (to < i) {
			to_left[i] = to;
			continue;
		} else if (to >= i) {
			to = i - 1;
		}

		while (to >= 0) {
			if (a[to] < a[to + 1]) {
				to_left[i] = to;
				break;
			}
			to--;
		}
	}

	for (int i = 0; i < n; i++) {
		right[a[i]] = n - i - 1;
		for (int j = i + 1; j < n; j = to_right[j]) {
			if (a[j] < a[i]) {
				right[a[i]] = j - i - 1;
				break;
			}
		}
		left[a[i]] = i;
		for (int j = i - 1; j >= 0; j = to_left[j]) {
			if (a[j] < a[i]) {
				left[a[i]] = i - j - 1;
				break;
			}
		}
	}

	long long ans = 0;
	for (int i = 1; i <= n; i++) {
		ans += (long long) i * (left[i] + 1) * (right[i] + 1);
	}

	cout << ans << endl;
	return 0;
}

