void build ( int id = 1 , int l = 1 , int r = n + 1 ) {
	if ( r - l < 2 ) {
		seg [ id ] = ar [ l ] ;
		return ; 
	}
	int mid = ( r + l ) >> 1 , lc = id << 1 , rc = lc | 1 ;
	build ( lc , l , mid ) ;
	build ( rc , mid , r ) ;
	seg [ id ] = min ( seg [ lc ] , seg [ rc ] ) ; 
}

int get ( int x , int y , int id = 1 , int l = 1 , int r = n + 1 ) {
	if ( r <= x || l >= y ) return n + 1 ;
	if ( l >= x && r <= y ) return seg [ id ] ;
	int mid = ( r + l ) >> 1 ;
	return min ( get ( x , y , id << 1 , l , mid )
		     , get ( x , y , id << 1 | 1 , mid , r ) ) ; 
}

