#include <bits/stdc++.h>
#define INF (1LL<<60)
#define N 200001
#define T (1<<18)
using namespace std;
typedef long long ll;
ll n,p[N];
ll tree[T*2-1];

void update(ll i,ll x) {
  i+=(T-1);
  tree[i] = x;
  while(i!=0){
    i=(i-1)/2;
    tree[i] = min(tree[i*2+1],tree[i*2+2]);
  }
}

ll find(int a ,int b,int ima,int L,int R){
  if(R<=a || b<=L) return INF;
  if(a<=L && R<=b) return tree[ima];
  ll M = (R+L)/2;
  return min(find(a,b,ima*2+1,L,M),find(a,b,ima*2+2,M,R));
}

ll search(int L,int R,int E){
  while(L<R){
    int M=(L+R)/2;
    if(find(M,E+1,0,0,T)==p[E]) R=M;
    else L=M+1;
  }
  return L-1;
}


ll search2(int L,int R,int E){
  while(L<R){
    int M=(L+R)/2;
    if(find(E,M+1,0,0,T)==p[E]) L=M+1;
    else R=M;
  }
  return L;
}


int main(){
  cin>>n;
  for(int i=0;i<T;i++)update(i,INF);
  for(int i=0;i<n;i++)cin>>p[i],update(i,p[i]);
  ll sum=0;
  for(int i=0;i<n;i++){
    ll l=search(0,i,i);
    ll r=search2(i,n,i);
    sum+=p[i]*(i-l)*(r-i);
  }
  cout<<sum<<endl;
  return 0;
}

