class SegmentTree
{
  public:
    SegmentTree(int n)
    {
        int c = 1;
        while (c < n)
            c <<= 1;
        N = c;
        node.resize(2 * N - 1);
        REP(i, node.size())
        {
            node[i] = n;
        }
    }

    void set(int l, int r, int v, int k = 0, int tl = 0, int tr = -1)
    {
        if (tr == -1)
            tr = N - 1;
        if (tr < l || r < tl)
            return;

        if (l <= tl && tr <= r)
        {
            node[k] = std::min(v, node[k]);
            return;
        }
        set(l, r, v, 2 * k + 1, tl, (tl + tr) / 2);
        set(l, r, v, 2 * k + 2, (tl + tr) / 2 + 1, tr);
    }

    int get(int n)
    {
        int k = N - 1 + n;
        int min = node[0];
        while (k > 0)
        {
            min = std::min(min, node[k]);
            k = (k - 1) / 2;
        }
        return min;
    }

  private:
    int N;
    vector<int> node;
};

