const int MAX_N = 200000 + 10;
LL N;
LL A[MAX_N];
VI L;
LL args[MAX_N];
LL ans = 0;

void solve() {
    REP(i, N) {
        args[A[i]] = i + 1;
    }
    FOR(n, 1, N + 1) {
        if (n == 1) {
            ans += args[n] * (N - args[n] + 1);
            L.PB(args[n]);
        } else {
            int ins = lower_bound(ALL(L), args[n]) - L.begin();
            int l, r;
            if (ins == 0) {
                l = args[n];
            } else {
                l = args[n] - L[ins-1];
            }
            if (ins == n - 1) {
                r = N - args[n] + 1;
            } else {
                r = L[ins] - args[n];
            }
            //cout << n << " " << ins << " " << l << " " << r << endl;
            ans += l * r * n;
            auto it = lower_bound(ALL(L), args[n]);
            L.insert(it, args[n]);
        }
    }
    cout << ans << endl;
}

