// 遅延評価セグメント木
// X : datの要素の型    M : lazyの要素の型
template <typename X, typename M>
class SegTreeLazyProportional {
public:

	// 根/下の葉 から 上の葉 への更新
	using FX = function<X(X, X)>;
	// lazyの要素をdatに移すの更新
	using FA = function<X(X, M)>;
	// lazyをupdate()などで上書きする更新
	using FM = function<M(M, M)>;
	// 高さによる葉への影響
	using FP = function<M(M, int)>;

	// モノイド(集合X, 二項演算fx,fa,fm,fp 単位元ex,em)についてサイズnで構築
	SegTreeLazyProportional(int n_, FX fx_, FA fa_, FM fm_, FP fp_, X ex_, M em_)
		: n(), fx(fx_), fa(fa_), fm(fm_), fp(fp_), ex(ex_), em(em_), dat(n_ * 4, ex), lazy(n_ * 4, em) {
		int x = 1;
		while (n_ > x) x *= 2;
		n = x;
	}

	// i番目の要素をxにセット。build()で構築
	void set(int i, X x) { dat[i + n - 1] = x; }

	// まとめてセグ木を構築する。O(n)
	void build() {
		for (int k = n - 2; k >= 0; k--) dat[k] = fx(dat[2 * k + 1], dat[2 * k + 2]);
	}

	// [a,b)全てにfa(x)を作用させる。O(log(n))
	void update(int a, int b, M x) { update(a, b, x, 0, 0, n); }

	// [a,b)全てにfxを作用させた値を取得。O(log(n))
	X query(int a, int b) { return query_sub(a, b, 0, 0, n); }

	// datとlazyを出力する
	void print(int w)
	{
#ifdef _MSC_VER
		for (int i = 0; i < n * 2 - 1; ++i)
		{
			debug(std::right << std::setw(w) << dat[i] << (_Is_pow_2(i + 2) ? " |" : "") << " ");
		}
		debugln("");
		for (int i = 0; i < n * 2 - 1; ++i)
		{
			debug(std::right << std::setw(w) << (lazy[i] == ex ? "-" : to_string(lazy[i])) << (_Is_pow_2(i + 2) ? " |" : "") << " ");
		}
		debugln("");
#endif // _MSC_VER
	}

private:

	int n;
	FX fx;
	FA fa;
	FM fm;
	FP fp;
	const X ex;
	const M em;
	vector<X> dat;
	vector<M> lazy;

	/* lazy eval */
	void eval(int k, int len) {
		if (lazy[k] == em) return;  // 更新するものが無ければ終了
		if (k < n - 1) {            // 葉でなければ子に伝搬
			lazy[k * 2 + 1] = fm(lazy[k * 2 + 1], lazy[k]);
			lazy[k * 2 + 2] = fm(lazy[k * 2 + 2], lazy[k]);
		}
		// 自身を更新
		dat[k] = fa(dat[k], fp(lazy[k], len));
		lazy[k] = em;
	}

	void update(int a, int b, M x, int k, int l, int r) {
		eval(k, r - l);
		if (a <= l && r <= b) {  // 完全に内側の時
			lazy[k] = fm(lazy[k], x);
			eval(k, r - l);
		}
		else if (a < r && l < b) {                     // 一部区間が被る時
			update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
			update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
			dat[k] = fx(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	X query_sub(int a, int b, int k, int l, int r) {
		eval(k, r - l);
		if (r <= a || b <= l) {  // 完全に外側の時
			return ex;
		}
		else if (a <= l && r <= b) {  // 完全に内側の時
			return dat[k];
		}
		else {  // 一部区間が被る時
			X vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
			X vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
			return fx(vl, vr);
		}
	}
};

void Main()
{
	int N;
	cin >> N;

	using X = int;
	using M = int;
	auto fx = [](X x1, X x2) -> X { return min(x1, x2); };
	auto fa = [](X x, M m) -> X { return m; };
	auto fm = [](M m1, M m2) -> M { return m2; };
	auto fp = [](M m, long long n) -> M { return m; };
	X ex = INF;
	M em = 0;
	SegTreeLazyProportional<X, M> rmq(N, fx, fa, fm, fp, ex, em);

	//rmq.print(3);

	for (int i = 0; i < N; ++i)
	{
		int a;
		cin >> a;
		rmq.set(i, a);
	}
	rmq.build();

	int ret = 0;

	//rmq.print(2);

	for (int l = 0; l < N; ++l)
		for (int r = l; r < N; ++r)
		{
			//debug_headcout(l << "," << r, rmq.query(l, r + 1));
			ret += rmq.query(l, r + 1);
		}

	cout << ret;
}

