int search_small(int index){
	ll x = sum(index);
	int ok = -1;
	int ng = index;
	while(abs(ok-ng)>1){
		int mid = (ok+ng)/2;
		if(sum(mid)<x)ok = mid;
		else ng = mid;
	}
	return ok;
}
