//// UnionFind
struct UnionFind{
	vector<int> v,l,r;
	UnionFind(int n) : v(n, -1) {
		l=r=vector<int>(n);
		rep(i,n)l[i]=r[i]=i;
	}

	int find(int x) { return v[x] < 0 ? x : v[x] = find(v[x]); }
	bool unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return false;
		if (-v[x] < -v[y]) swap(x, y);
		v[x] += v[y]; v[y] = x;
		minch(l[x],l[y]);
		maxch(r[x],r[y]);
		return true;
	}
	bool root(int x) { return v[x] < 0; }
	bool same(int x, int y) { return find(x) == find(y); }
	int size(int x) { return -v[find(x)]; }
};


