  rep(i,n){
    bit.plus(place[i+1],1);
    int left=place[i+1]-bit.lower_bound(bit.sum(place[i+1])-1);
    int right=bit.lower_bound(bit.sum(place[i+1])+1)-place[i+1];
    ans+=(ll)left*right*(i+1);
  }
  cout<<ans<<endl;
}

