typedef pair<int,int> pi;
typedef long long lint;

struct seg{
	pi tree[530000];
	int lim;
	void init(int n, int *a){
		for(lim = 1; lim <= n; lim <<= 1);
		for(int i=1; i<=n; i++){
			tree[i + lim] = pi(a[i], i);
		}
		for(int i=lim; i; i--){
			tree[i] = min(tree[2*i], tree[2*i+1]);
		}
	}
	pi query(int s, int e){
		s += lim;
		e += lim;
		pi ret(1e9, 1e9);
		while(s < e){
			if(s%2 == 1) ret = min(ret, tree[s++]);
			if(e%2 == 0) ret = min(ret, tree[e--]);
			s >>= 1;
			e >>= 1;
		}
		if(s == e) ret = min(ret, tree[s]);
		return ret;
	}
}seg;

int n, a[200005];

lint solve(int s, int e){
	if(s > e) return 0;
	pi v = seg.query(s, e);
	lint ret = solve(s, v.second - 1) + solve(v.second + 1, e);
	ret += (v.second - s + 1) * (e - v.second + 1) * v.first;
	return ret;
}

