template <typename T>
class fenwick_tree {
  int size, depth;
  vector<T> data;

public:
  fenwick_tree() = default;
  explicit fenwick_tree(int n)
    : size(n), depth(int(log2(n)) + 1), data(n + 1) {}

  T query(int i) {
    T result = 0;
    for (; i > 0; i -= i & -i) result += data[i];
    return result;
  }
  void update(int i, T x) {
    for (; i <= size; i += i & -i) data[i] += x;
  }
  int lower_bound(T x) {
    T sum = 0;
    int pos = 0;
    for (int i = depth; i >= 0; --i) {
      int j = pos + (1 << i);
      if (j <= size && sum + data[j] < x) {
        sum += data[j];
        pos += 1 << i;
      }
    }
    return pos + 1;
  }
};

