      l = idx;
    else {
      int pos = ft.lower_bound(left_cnt);
      l = idx - pos;
    }
    int pos = ft.lower_bound(left_cnt + 1);
    r = pos - idx;
    ans += val * l * r;
    ft.update(idx, 1);
  }
  cout << ans << endl;

  return 0;
}

