lint sum(int l,int r){
    if(l==r) return A[l];

    lint min=200001;
    int im;
    for(int i=l;i<=r;i++){
        if(A[i]<min){ min=A[i]; im=i; }
    }
    lint s=0;
    for(int i=1;i<=r-l+1;i++){
        lint left=(l>im-i+1?l:im-i+1),right=(im<r-i+1?im:r-i+1);
        s+=right-left+1;
    }
    return min*s+(im>l?sum(l,im-1):0)+(im<r?sum(im+1,r):0);    
}
