int n, a[200200], two[200200], dp[20][200200];

void precalc() {
    two[0] = -1;
    for (int i = 1; i < 200200; i++) two[i] = 1 + two[i / 2];
    for (int i = 0; i < n; i++) dp[0][i] = a[i];
    for (int lvl = 1; (1 << lvl) <= n; lvl++) {
        for (int i = 0; i + (1 << lvl) <= n; i++) {
            dp[lvl][i] = min(dp[lvl - 1][i],
                             dp[lvl - 1][i + (1 << (lvl - 1))]);
        }
    }
}

int getmin(int l, int r) {
    if (l > r) return inf;
    int lvl = two[r - l + 1];
    int ans1 = dp[lvl][l];
    int ans2 = dp[lvl][r - (1 << lvl) + 1];
    return min(ans1, ans2);
}

int main(){

    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", a + i);

    precalc();

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        int L = i, R = i;
        int l = 0, r = i - 1;
        while (l <= r) {
            int mid = (l + r) >> 1;
            if (getmin(mid, i) == a[i]) {
                L = mid;
                r = mid - 1;
            } else l = mid + 1;
        }
        l = i; r = n - 1;
        while (l <= r) {
            int mid = (l + r) >> 1;
            if (getmin(i, mid) == a[i]) {
                R = mid;
                l = mid + 1;
            } else r = mid - 1;
        }
        ans += (R - i + 1) * 1ll * (i - L + 1) * a[i];
    }

    cout << ans << endl;

    return 0;
}

