const long long int MAX_N = 200010;

long long int n, dat[2*MAX_N-1];

void init(long long int n_) {
	n = 1;
	while (n < n_) n *= 2;

	for (long long int i = 0; i < 2*n-1; i++) dat[i] = INT_MAX;
}

void update(long long int k, long long int a) {
	k += n-1;
	dat[k] = a;
	while (k > 0) {
		k = (k-1)/2;
		dat[k] = min(dat[k*2+1], dat[k*2+2]);
	}
}

long long int query(long long int a, long long int b, long long int k, long long int l, long long int r) {
	if (r <= a || b <= l) return INT_MAX;

	if (a <= l && r <= b) return dat[k];
	else {
		long long int vl = query(a, b, k*2+1, l, (l+r)/2);
		long long int vr = query(a, b, k*2+2, (l+r)/2, r);
		return min(vl, vr);
	}
}

int main() {
	long long int nn;
	cin >> nn;
	init(nn);
	long long int a;
	for (long long int i = 0; i < nn; i++) {
		cin >> a;
		update(i, a);
	}
	long long int sum = 0;
	/*for (long long int i = 0; i < 8; i++) {
		cout << dat[i] << endl;
	}*/
	for (long long int i = 0; i < nn; i++) {
		for (long long int j = i; j < nn; j++) {
			sum += query(i, j+1, 0, 0, n);
			//cout << i << ' ' << j << ' ' << query(i, j, 0, 0, n) << endl;
		}
	}
	cout << sum << endl;
	return 0;
}

