using namespace std;
int a[200010],n,l[800010],r[800010],tree[800010];
void build(int v,int s,int f)
{
	l[v]=s;r[v]=f;
	if (s==f) 
	{
		tree[v]=s;
		return;
	}
	build(2*v,s,(s+f)/2);
	build(2*v+1,(s+f)/2+1,f);
	if (a[tree[2*v]]<a[tree[2*v+1]]) tree[v]=tree[2*v];
	else tree[v]=tree[2*v+1];
}
int find(int v,int s,int f)
{
	if (s<=l[v]&&f>=r[v])
	{
		return tree[v];
	}
	int t1=0,t2=0;
	if (s<l[2*v+1]) t1=find(2*v,s,f);
	if (f>r[2*v]) t2=find(2*v+1,s,f);
	if (t1!=0&&t2!=0)
	{
		if (a[t1]<a[t2]) return t1;
		else return t2;
	}
	else return t1+t2;
}
long long work(int l,int r)
{
	if (r<l) return 0;
	if (r==l) return a[l];
	int minn=find(1,l,r);
	long long ans=(long long)1*(minn-l+1)*(r-minn+1)*a[minn];
	return ans+work(l,minn-1)+work(minn+1,r);
}
main()
{
	cin>>n;
	for (int i=1;i<=n;i++) 
	{
		cin>>a[i];
	}
	build(1,1,n);
	cout<<work(1,n)<<endl;
}

