lint fact[3'000'000];
void fact_init(lint n, lint m = Mod) {
	if (3'000'000 <= n) return;
	fact[0] = fact[1] = 1;
	for (lint i = 2; i <= n; ++i) {
		fact[i] = i * fact[i - 1] % m;
	}
}

lint modpow(lint x, lint n, lint m = Mod) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % m;
		x = x * x % m;
		n >>= 1;
	}
	return res;
}

lint intpow(lint x, lint n) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}

lint comb(lint n, lint r, lint m = Mod) {
	if (r == 0 || r == n) return 1;
	lint res = fact[n] * modpow(fact[n - r], m - 2, m) % m * modpow(fact[r], m - 2, m) % m;
	return res < 0 ? res + m : res;
}

map<lint, lint> factring(lint n) {
	map<lint, lint> res;
	for (lint i = 2; i * i <= n; ++i) {
		while (n % i == 0) {
			n /= i;
			++res[i];
		}
	}
	if (n != 1) ++res[n];
	return res;
}

template<class T>
class segment_tree {
private:

	int size;
	vector<T>dat;
	T identity;
	function<T(T, T)>func;

	T query_sub(int a, int b, int k, int l, int r) const {
		if (r <= a || b <= l) return identity;
		if (a <= l && r <= b) return dat[k];
		const T& vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
		const T& vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
		return func(vl, vr);
	}

public:

	segment_tree(int size_, const T& identity, const function<T(T, T)>& func)
		:identity(identity), func(func)
	{
		int x = 1;
		while (size_ > x) x <<= 1;
		size = x;
		dat.resize(2 * size - 1, identity);
	}

	void update(int i, const T& x) {
		i += size - 1;
		dat[i] = x;
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = func(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	// [a, b)
	T query(int a, int b) const { return query_sub(a, b, 0, 0, size); }

	const T& operator[](size_t index) const { return dat[index + size - 1]; }
	T& operator[](size_t index) { return dat[index + size - 1]; }
};

int n;
lint sum;
int main() {
	scanf("%d", &n);

	segment_tree<int>seg(n, 10000000, [](int x, int y) {return min(x, y); });

	rep(i, n) {
		int a;
		scanf("%d", &a);
		seg.update(i, a);
	}

	rep(i, n) {
		const int a = seg[i];

		lint cnt1, cnt2;

		int l = -1, r = i;
		while (abs(r - l) > 1) {
			int mid = l + (r - l) / 2;
			if (seg.query(mid, i + 1) == a) r = mid;
			else l = mid;
		}

		cnt1 = i - r + 1;

		l = i, r = n;
		while (abs(r - l) > 1) {
			int mid = l + (r - l) / 2;
			if (seg.query(i, mid + 1) == a) l = mid;
			else r = mid;
		}

		cnt2 = l - i + 1;

		sum += cnt1 * cnt2 * a;
	}

	cout << sum << endl;
}

