template< typename Monoid >
struct SegmentTree {
  using F = function< Monoid(Monoid, Monoid) >;

  int sz;
  vector< Monoid > seg;

  const F f;
  const Monoid M1;

  SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
  }

  void set(int k, const Monoid &x) {
    seg[k + sz] = x;
  }

  void build() {
    for(int k = sz - 1; k > 0; k--) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  void update(int k, const Monoid &x) {
    k += sz;
    seg[k] = x;
    while(k >>= 1) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  Monoid query(int a, int b) {
    Monoid L = M1, R = M1;
    for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if(a & 1) L = f(L, seg[a++]);
      if(b & 1) R = f(seg[--b], R);
    }
    return f(L, R);
  }

  Monoid operator[](const int &k) const {
    return seg[k + sz];
  }

  template< typename C >
  int find_subtree(int a, const C &check, Monoid &M, bool type) {
    while(a < sz) {
      Monoid nxt = type ? f(seg[2 * a + type], M) : f(M, seg[2 * a + type]);
      if(check(nxt)) a = 2 * a + type;
      else M = nxt, a = 2 * a + 1 - type;
    }
    return a - sz;
  }


  template< typename C >
  int find_first(int a, const C &check) {
    Monoid L = M1;
    if(a <= 0) {
      if(check(f(L, seg[1]))) return find_subtree(1, check, L, false);
      return -1;
    }
    int b = sz;
    for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if(a & 1) {
        Monoid nxt = f(L, seg[a]);
        if(check(nxt)) return find_subtree(a, check, L, false);
        L = nxt;
        ++a;
      }
    }
    return -1;
  }

  template< typename C >
  int find_last(int b, const C &check) {
    Monoid R = M1;
    if(b >= sz) {
      if(check(f(seg[1], R))) return find_subtree(1, check, R, true);
      return -1;
    }
    int a = sz;
    for(b += sz; a < b; a >>= 1, b >>= 1) {
      if(b & 1) {
        Monoid nxt = f(seg[--b], R);
        if(check(nxt)) return find_subtree(b, check, R, true);
        R = nxt;
      }
    }
    return -1;
  }
};


int N;
vector<ll> A;
void input(){
    fast_io();
    cin >> N;
    A.push_back(0LL);
    for (int i = 0; i < N; i++)
    {
        ll a; cin >> a;
        A.push_back(a);
    }
}

int solve(){
    // A[i]の左l(i),右r(i)個はA[i]以上。
    // A[i]の足される回数はl(i)*r(i)回。
    vector<ll> L(N+1,0),R(N+1,0);
    SegmentTree< ll > seg(N+2, [](ll a, ll b) { return min(a, b); }, LL_INF);
    for (int i = 1; i <= N; i++)
    {
        seg.set(i,A[i]);
    }
    seg.set(0,0LL);
    seg.set(N+1,0LL);
    seg.build();
    for (int i = 1; i <= N; i++)
    {
        int lok,rok,lng,rng;
        lok = rok = i;
        lng = 0;
        rng = N+1;
        while(abs(rok-rng)>1){
            int rmid = (rok+rng)/2;
            if(seg.query(i,rmid+1)==A[i]) rok = rmid;
            else rng = rmid;
        }
        while(abs(lok-lng)>1){
            int lmid = (lok+lng)/2;
            if(seg.query(lmid,i+1)==A[i]) lok = lmid;
            else lng = lmid;
        }
        L[A[i]] = i-lok+1;
        R[A[i]] = rok-i+1;
    }
    ll ans = 0;
    for (int i = 1; i <= N; i++)
    {
        ans += i*L[i]*R[i];
    }
    cout << ans << endl;
    return 0;
}   

