    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> lf(n);
    vector<int> rg(n);

    stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] > a[i]) {
            int id = st.top();
            st.pop();
            rg[id] = i - 1;
        }
        st.push(i);
    }
    while (!st.empty()) {
        int id = st.top();
        st.pop();

        rg[id] = n - 1;
    }

    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && a[st.top()] > a[i]) {
            int id = st.top();
            st.pop();
            lf[id] = i + 1;
        }
        st.push(i);
    }
    while (!st.empty()) {
        int id = st.top();
        st.pop();

        lf[id] = 0;
    }

    long long result = 0;
    for (int i = 0; i < n; ++i) {
        result += 1LL * a[i] * (i - lf[i] + 1) * (rg[i] - i + 1);
    }

    cout << result << endl;

