const int N = 200200;

int tree[N * 4];
int arr[N], n, posOf[N];

void build(int v, int tl, int tr) {
	if (tl == tr) {
		tree[v] = arr[tl];
		return;
	}
	int tm = (tl + tr) >> 1;
	build((v << 1) + 1, tl, tm);
	build((v << 1) + 2, tm + 1, tr);
	tree[v] = min(tree[(v << 1) + 1], tree[(v << 1) + 2]);
}

int getMin(int v, int tl, int tr, int l, int r) {
	if (tl == l && tr == r) {
		return tree[v];
	}
	int tm = (tl + tr) >> 1;
	if (r <= tm) {
		return getMin((v << 1) + 1, tl, tm, l, r);
	}
	else if (l > tm) {
		return getMin((v << 1) + 2, tm + 1, tr, l, r);
	}
	else {
		return min(getMin((v << 1) + 1, tl, tm, l, tm),
				   getMin((v << 1) + 2, tm + 1, tr, tm + 1, r));
	}
}

int getMin(int l, int r) {
	return getMin(0, 0, n - 1, l, r);
}

ll globalRes = 0;

void rec(int l, int r) {
	if (l > r) return;
	int val = getMin(l, r);
	int pos = posOf[val];
	globalRes += 1LL * (pos - l + 1) * (r - pos + 1) * val;
	rec(l, pos - 1);
	rec(pos + 1, r);
}

void solve() {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%d", arr + i);
		posOf[arr[i]] = i;
	}
	build(0, 0, n - 1);
	rec(0, n - 1);
	cout << globalRes << endl;
}

