        return 0;
    }
    int target = query(l, r, 0, 0, n_dat);
    int target_idx = idx[target];
    long long ret = 0;
    ret += (long long)target * (target_idx - l + 1) * (r - target_idx);
    ret += solve(l, target_idx);
    ret += solve(target_idx + 1, r);
    return ret;
}

