ll solve(int l, int r) {
	if (l > r)return 0;
	if (l == r)return a[l];
	int min = l;
	for (int i = l + 1; i <= r; i++) {
		if (a[min] > a[i])min = i;
	}
	return solve(l, min - 1) + solve(min + 1, r) + (r - min + 1)*(min - l + 1)*a[min];
}

