    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    RangeMinimumQuerySegTree<ll> RMQ(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        get_idx[A[i]] = i;
        RMQ.update(i, A[i]);
    }
    divide_conquer(0, N, RMQ);
    cout << ans << endl;
    return 0;
}

