template <class T, class Comp=std::less<T>>
auto cartesian_tree(vec<T> const& a, Comp const& comp={}) {
    usize n = a.size();
    vec<T> stack;
    vec<usize> p(n, n);
    for (usize i=0; i<n; i++) {
        usize j = n;
        while (!stack.empty() && comp(a.at(i), a.at(stack.back()))) {
            j = stack.back();
            stack.pop_back();
        }
        if (j!=n) {
            p.at(j) = i;
        }
        if (!stack.empty()) {
            p.at(i) = stack.back();
        }
        stack.push_back(i);
    }

    usize root = n;
    vec<vec<usize>> g(n);
    for (usize i=0; i<n; i++) {
        if (p.at(i)==n) {
            root = i;
        } else {
            g.at(p.at(i)).push_back(i);
        }
    }
    return std::make_pair(root, g);
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);
    std::cout << std::setprecision(15) << std::fixed;

    usize n;
    std::cin >> n;
    vec<usize> a(n);
    for (usize& x: a) std::cin >> x;

    usize r;
    vec<vec<usize>> g;
    std::tie(r, g) = cartesian_tree(a);

    usize ans = 0;
    auto dfs = [&](auto&& f, usize x) -> usize {
        usize sz = 1;
        usize now = a.at(x);
        for (usize y: g.at(x)) {
            usize s = f(f, y);
            sz += s;
            now *= s + 1;
        }
        ans += now;
        return sz;
    };
    dfs(dfs, r);

    std::cout << ans << '\n';
}

