			if(seg[tmp*2+1] != 0){
				tmp = tmp*2+1;
			}else tmp = tmp*2;
		}
		if(tmp == -1) left[i] = nn;
		else left[i] = tmp+1;
		tmp = -1;
		get2(1,1,nn,where[i]+1,N);
