			if(seg[tmp*2] != 0){
				tmp = tmp*2;
			}else tmp = tmp*2+1;
		}
		if(tmp == -1) right[i] = nn+N-1;
		else right[i] = tmp-1;
		left[i] -= (nn-1); right[i] -= (nn-1);
		int x = nn+where[i]-1;
		if(x < nn || x > nn+N-1) while(true);
