	// 自分よりデカい奴がいる右R
	// (R - C) * (C - L)回コイツは選ばれる
	ll ans = 0;
	set<ll> ids;
	ids.insert(0);
	ids.insert((ll)n + 1);
	rep(i, 0, n) {
		ll val = a[i].first;
		ll idx = a[i].second;
		// この時、自分よりデカい奴のインデックスが保存されてる
		ids.insert(idx);
		auto itr = ids.find(idx);
		int L = *--itr;
		int R = *++++itr;
		ans += (R - idx) * (idx - L) * val;
	}
	cout << ans << endl;
	return 0;

}

