        vector<ll> parent,rank,tree_w;
    public:
        UnionFind(int size){
            for (int i=0; i<size; i++){
                parent.push_back(i);
                rank.push_back(0);
                tree_w.push_back(1);
            }
        }

        int findset(int x){
            return x==parent[x] ? x : parent[x]=findset(parent[x]);
        }

        void unite(int x,int y){
            x=findset(x);y=findset(y);
            if (x==y) return;
            if (rank[x]>rank[y]) swap(x,y);
            parent[x]=y;
            tree_w[y]+=tree_w[x];
            if (rank[x]==rank[y]) rank[y]+=1;
        }

        ll tree_weight(int x){
            return tree_w[findset(x)];
        }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    rep(i,n){
        cin >> a[i];
        a[i]--;
    }
    rep(i,n) pos[a[i]]=i;
    UnionFind uf(n);
    bool check[n]={};
    ll ans=0LL;
    rrep(i,n-1){
        ll l=max<ll>(pos[i]-1,0);
        ll r=min<ll>(pos[i]+1,n-1);
        ll lnum=1LL;
        ll rnum=1LL;
        if (check[l]){
            lnum+=uf.tree_weight(l);
        }
        if (check[r]){
            rnum+=uf.tree_weight(r);
        }
        if (check[l]){
            uf.unite(l,pos[i]);
        }
        if (check[r]){
            uf.unite(r,pos[i]);
        }
        check[pos[i]]=true;
        ans+=(i+1)*lnum*rnum;
    }
    cout << ans << endl;
    return 0;
}

