using namespace std;

const int N_MAX = 200002;
const int BITS = 18;

int n;

int p[N_MAX];

int rm[N_MAX][BITS];

int rmq (int l, int r)
{
    int lg = r - l + 1;
    int b = 0;
    while((1 << (b + 1)) <= lg)
        b++;
    return min(rm[l][b], rm[r - (1 << b) + 1][b]);
}

int main()
{
    cin >> n;
    for(int i = 1; i <= n; i++)
        cin >> p[i];
    for(int i = 1; i <= n; i++)
        rm[i][0] = p[i];
    for(int b = 1; b < BITS; b++)
        for(int i = 1; i <= n; i++)
            if(i + (1 << b) - 1 <= n)
                rm[i][b] = min(rm[i][b - 1], rm[i + (1 << (b - 1))][b - 1]);
    ll ans = 0;
    for(int i = 1; i <= n; i++)
    {
        int posl, posr;
        int l, r;
        l = 1;
        r = i;
        while(l < r)
        {
            int mid = (l + r) / 2;
            if(rmq(mid, i) < p[i])
                l = mid + 1;
            else
                r = mid;
        }
        posl = l;
        l = i;
        r = n;
        while(l < r)
        {
            int mid = (l + r + 1) / 2;
            if(rmq(i, mid) < p[i])
                r = mid - 1;
            else
                l = mid;
        }
        posr = r;
        ans += 1LL * (i - posl + 1) * (posr - i + 1) * p[i];
    }
    cout << ans << "\n";
    return 0;
}

