    REP(i, N){
        scanf("%d", &a[i + 1]);
    }
    a[0] = 0; a[N + 1] = 0;
    long long ans = 0;
    for(int i = 1; i <= N; i++){
        if(a[i] == 1){
            ans += i * (N - i + 1);
        }else if(a[i] == N){
            ans += i * (N - i + 1) * N;
        }else{
            int left = 1, right = 1;
            while(a[i] < a[i - left]){
                left++;
            }
            while(a[i] < a[i + right]){
                right++;
            }
            ans += a[i] * left * right;
        }
    }
    printf("%lld\n", ans);
