	template<class T>auto get_factorial_array(std::size_t size)
	{
		std::vector<T> ret(size + 1);
		ret[0] = 1;
		for (std::size_t i = 1; i <= size; ++i)
		{
			ret[i] = ret[i - 1] * T(i);
		}
		return ret;
	}
