struct data_t
{
	std::int64_t first;
	std::int64_t last;
	std::int64_t middle;
	std::unique_ptr<data_t> left;
	std::unique_ptr<data_t> right;
	data_t(std::int64_t s, std::int64_t e):first(s), last(e), middle(-1), left(), right()
	{

	}
	std::pair<std::int64_t, std::int64_t> add(std::int64_t index)
	{
		if (middle != -1)
		{
			if (index < middle)
			{
				return left->add(index);
			}
			else
			{
				return right->add(index);
			}
		}
		else
		{
			middle = index;
			left = std::make_unique<data_t>(first, index);
			right = std::make_unique<data_t>(index + 1, last);
			return std::make_pair(first, last);
		}
	}
};

