#define int long long
#define SEGVAL (262144)

typedef pair < int , int > Pi;

struct Data {
  int l, c, r, val;
};

struct Segtree {

  Pi data[800005];

  Segtree() {
    fill_n(data, 800005, Pi(8101919, 364364));
  }

  void add(int k, Pi x) {
    int now = k + SEGVAL - 1;
    data[now] = x;
    while(now != 0) {
      now = (now - 1) / 2;
      data[now] = min(data[now * 2 + 1], data[now * 2 + 2]);
    }
  }

  Pi query(int a, int b, int k, int l, int r) {
    if(b < l || r < a) return (Pi(8101919, 364364));
    if(l <= a && b <= r) return (data[k]);
    return (min(query(a, (a + b) / 2, k * 2 + 1, l, r), query((a + b) / 2 + 1, b, k * 2 + 2, l, r)));
  }
}; 

int a[200005];
queue < Data > que;
Segtree tree;

main()
{
  int n, nn = SEGVAL;
  int ans = 0;


  cin >> n;

  for(int i = 0; i < n; i++) {
    cin >> a[i];
    tree.add(i, Pi(a[i], i));
    if(a[i] == 1) que.push( (Data) { 0, i, n - 1, 1 } );
  }


  while(!que.empty()) {
    Data d = que.front(); que.pop();
    int l = d.l, c = d.c, r = d.r, val = d.val;

    ans += (c - l + 1) * (r - c + 1) * val;

    if(c > l) {
      Pi data = tree.query(0, nn - 1, 0, l, c - 1);
      que.push( (Data) { l, data.second, c - 1, data.first } );
    }

    if(c < r) {
      Pi data = tree.query(0, nn - 1, 0, c + 1, r);
      que.push( (Data) { c + 1, data.second, r, data.first } );
    }
  }

  cout << ans << endl;

  return (0);
}

