typedef long long int ll;

vector<int> v;

ll goukei(auto s, auto g, int mai) {
  if (s == g) {
    return *s - mai;
  }

  auto d = min_element(s, g + 1);
  int m = *d - mai;

  if (d == s) {
    return goukei(d + 1, g, mai + m) + (m * (g - s + 1) * (g - s + 2) / 2);
  } else if (d == g) {
    return goukei(s, d - 1, mai + m) + (m * (g - s + 1) * (g - s + 2) / 2);
  } else {
    return goukei(s, d - 1, mai + m) + goukei(d + 1, g, mai + m) +
           (m * (g - s + 1) * (g - s + 2) / 2);
  }
}

