    stack <int> st;
    st.push(-1);
    for (int i = 0; i < n; i++) {
        while(st.top() != -1 && a[st.top()] > a[i]) {
            R[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    while(st.top() != -1) {
        R[st.top()] = n;
        st.pop();
    }
    for (int i = n - 1; i >= 0; i--) {
        while(st.top() != -1 && a[st.top()] >= a[i]) {
            L[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    while(st.top() != -1) {
        L[st.top()] = -1;
        st.pop();
    }
    int ans = 0;
    for (int i = 0; i < n; i++) {
        ans += (i - L[i]) * (R[i] - i) * a[i];
    }
    cout << ans;
}   


