{
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
        cin >> a[i];

    st.push(0);
    a[0] = 0;

    for (int i = 1; i <= n; i++)
    {
        while(a[st.top()] > a[i]) st.pop();
        l[i] = i - st.top();
        st.push(i);
    }

    st.push(n+1);
    a[n+1] = 0;

    for (int i = n; i >= 1; i--)
    {
        while(a[st.top()] > a[i]) st.pop();
        r[i] = st.top() - i;
        st.push(i);
    }

    ll ans = 0;
    for (int i = 1; i <= n; i++)
        ans += l[i]*r[i] * a[i];

    cout << ans;
