int f(const vector<int> &v,int b,int e) {
  int s=e-b;
  if ( s==0 ) return 0;
  if ( s==1 ) return v[b];
  int m=b;
  int t=v[b];
  for ( int i=b+1;i<e;i++ )
    if ( v[i]<t ) {
      m=i;
      t=v[i];
    }
  return v[m]*(e-m)*(m-b+1)+f(v,b,m)+f(v,m+1,e);
}
