    }
    int t = 2 * n - 1;
    a[t / 2 + 1] = x;
    a[t / 2] = x - 1;
    a[t / 2 + 2] = x + 1;
    book[x] = book[x - 1] = book[x + 1] = 1;
    if (t / 2 - 1 > 0 && x + 2 <= t) {
        a[t / 2 - 1] = x + 2;
        book[x + 2] = 1;
