    int to = 1;
    for (int i = 1; i <= t; ++i) {
        if (a[i] != 0) continue;
        while (book[to] != 0) to++;
        a[i] = to;
        book[to] = 1;
    }
    printf("Yes\n");
    for (int i = 1; i <= t; ++i) {
        printf("%d\n", a[i]);
    }
}

