int find_l(vector <int> an, int i) {
    int l = -1;
    for (int k = 0; k < i; k++) {
        if (an[k] < an[i]) l = k;
    }
    return l;
}

int find_l(set <int> visited_i, int i) {
    auto pl = visited_i.upper_bound(i);
    if (pl == visited_i.begin()) return -1;
    pl--;
    return *pl;
}

int find_r(vector <int> an, int i) {
    int r = an.size();
    for (int k = an.size() - 1; k >= i + 1; k--) {
        if (an[k] < an[i]) r = k;
    }
    return r;
}

int find_r(set <int> visited_i, int i, int n) {
    auto pr = visited_i.lower_bound(i);
    if (pr == visited_i.end()) return n;
    return *pr;
}

