    set <int> visited_i;
    for (int a = 1; a <= n; a++) {
        int i = position[a - 1];
        int l = find_l(visited_i, i);
        int r = find_r(visited_i, i, n);
        res += (i - l) * (r - i) * an[i];
        visited_i.insert(i);
