#define MAX_N (200000)
#define INF (1000000000)

long solve(long *as, long b, long e) {
  if (e - b == 0) {
    return 0;
  } else if (e - b == 1) {
    return as[b];
  }
  // find smallest value in range
  long a_min = INF, i_min = -1;
  for (int i = b; i < e; i++) {
    const long a = as[i];
    if (a < a_min) {
      a_min = a;
      i_min = i;
    }
  }
  return a_min * (i_min - (b - 1)) * (e - i_min) + solve(as, b, i_min) +
         solve(as, i_min + 1, e);
}

int main(int argc, char *argv[]) {
  // read inputs
  long N, as[MAX_N];
  scanf("%ld", &N);
  for (int i = 0; i < N; i++) {
    scanf("%ld", &as[i]);
  }

  // solve
  printf("%ld\n", solve(as, 0, N));

  return 0;
}

