void build(){
  for(int i = 0; i < n; i++)
    st[i][0] = a[i];

  for(int k = 1; (1<<k) <= n; k++)
    for(int i = 0; i+(1<<k) <= n; i++)
      st[i][k] = min(st[i][k-1], st[i+(1<<(k-1))][k-1]);
}

int get(int a, int b){
  int k = log2(b-a+1);
  return min(st[a][k], st[b-(1<<k)+1][k]);
}

