    while(lo <= hi){
      mid = ((lo+hi)>>1) + (hi-lo==1);
      if (get(i, mid) < a[i]) hi = mid-1;
      else lo = mid;
      if (lo == hi){
        r[i] = lo;
        break;
      }
    }

    lo = 0, hi = i;
    while(lo <= hi){
      mid = ((lo+hi)>>1);
      if (get(mid, i) < a[i]) lo = mid+1;
      else hi = mid;
      if (lo == hi){
        l[i] = lo;
        break;
      }
    }
  }

  for(int i = 0; i < n; i++)
    ans += a[i] * 1LL* (r[i]-i+1) * (i-l[i]+1);

