void dfs(ll L, ll R)
{
	if (judge(L, R))return;
	ll temp = RMQ(L, R);
	sum = sum + (ll)(temp - L + 1) * (R - temp + 1) * save[temp];
	if (L <= temp - 1)dfs(L, temp - 1);
	if (R >= temp + 1)dfs(temp + 1, R);
}
