// Range Minimum Query
class RMQ {
private:
  int n;
  vector<int> data;
  vector<int> pos;
public:
  RMQ(int n_){
    n=1;
    while(n<n_) n*=2;
    data = vector<int>(2*n-1, INF);
    pos  = vector<int>(2*n-1, -1);
  }
  void update(int k, int a){ // update data[k]=a, k(0-indexed)
    k+=n-1;
    data[k]=a;
    pos[k] =k-n+1;
    while(k>0){
      k = (k-1)/2;
      if(data[k*2+1]<data[k*2+2]){
        data[k] = data[k*2+1];
        pos[k]  = pos[k*2+1];
      } else {
        data[k] = data[k*2+2];
        pos[k]  = pos[k*2+2];
      }
    }
  }
  pair<int,int> query(int a,int b,int k=0,int l=0,int r=-1){ //min value in [a,b)
    if(r==-1) r=n;
    // k := current node, range of k := [l,r)
    if(r<=a || b<=l) return mp(INF,-1);
    if(a<=l && r<=b) return mp(data[k],pos[k]);
    pair<int,int> vl=query(a,b,k*2+1,l,(l+r)/2);
    pair<int,int> vr=query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
  inline int operator[](int idx){ return data[idx+n-1]; }
}; // END class RMQ

RMQ rmq(1);

// 閉区間[l,r]
long search(int l, int r){
  if(l>r) return 0;
  if(l==r) return rmq[l];

  int pos = rmq.query(l,r+1).se;

  return search(l, pos-1) + search(pos+1,r) + (long)(pos-l+1)*(r-pos+1)*rmq[pos];
}

int main(){
  int n;
  cin>>n;
  rmq = RMQ(n);
  rep(i,n){
    int d;
    scanf("%d", &d);
    rmq.update(i,d);
  }

  long res = search(0,n-1);

  cout<<res<<endl;

  return 0;
}

