int find(int node){
    if(node == dsu[node]) return node;
    return dsu[node] = find(dsu[node]);
}

void combine(int a, int b){
    a = find(a); b = find(b);
    if(a == b) return;
    if(ranks[a] <= ranks[b]){
        dsu[a] = b;
        ranks[b] += ranks[a];
    } else {
        dsu[b] = a;
        ranks[a] += ranks[b];
    }
}

