template<typename T>
class SegTree {
  int n;
  vector<T> seg;

  // irrelevant value for query
  const T NIL = INF;

  // binary operator for query
  T binop(T a, T b) {
    return min(a, b);
  }

  void update(int k, int l, int r, int p, T x) {
    if (p < l || r <= p)
      return;
    if (r - l == 1)
      seg[k] = x;
    else {
      update(2*k+1, l, (l+r)/2, p, x);
      update(2*k+2, (l+r)/2, r, p, x);
      seg[k] = binop(seg[2*k+1], seg[2*k+2]);
    }
  }
  T query(int k, int l, int r, int a, int b) {
    if (b <= l || r <= a)
      return NIL;
    if (a <= l && r <= b)
      return seg[k];
    else {
      T ret = NIL;
      ret = binop(ret, query(2*k+1, l, (l+r)/2, a, b));
      ret = binop(ret, query(2*k+2, (l+r)/2, r, a, b));
      return ret;
    }
  }
public:
  SegTree(int n): n(n), seg(4*n) {}
  void init() {
    for (int i = 0; i < 4*n; i++)
      seg[i] = NIL;
  }
  // update p-th value to x
  void update(int p, T x) {
    update(0, 0, n, p, x);
  }
  // query for range [l, r)
  T query(int l, int r) {
    return query(0, 0, n, l, r);
  }
};

int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  cin >> n;
  SegTree<int> seg(n);
  REP (i, n) {
    cin >> a[i];
    seg.update(i, a[i]);
  }

  long long sum = 0;
  REP (i, n) {
    int l, r;

    // find left
    l = -1, r = i;
    while (r - l > 1) {
      int m = (l + r) / 2;
      if (seg.query(m, i+1) == a[i])
        r = m;
      else
        l = m;
    }
    int lv = r;

    // find right
    l = i, r = n;
    while (r - l > 1) {
      int m = (l + r) / 2;
      if (seg.query(i, m+1) == a[i])
        l = m;
      else
        r = m;
    }
    int rv = l;
    sum += (long long)a[i] * (rv - i + 1) * (i - lv + 1); 
  }
  cout << sum << endl;

  return 0;
}

