int main() {
	scanf("%d", &n);

	for(int i = 1; i <= n; i++)
		scanf("%d", &a[i]);

	stack <int> s;
	for(int i = 1; i <= n; i++) {
		while(!s.empty() && a[s.top()] > a[i])
			s.pop();

		lft[i] = s.empty() ? 0 : s.top();
		s.push(i);
	}

	while(!s.empty()) s.pop();

	for(int i = n; i > 0; i--) {
		while(!s.empty() && a[s.top()] > a[i])
			s.pop();

		rgt[i] = s.empty() ? n + 1 : s.top();
		s.push(i);
	}

	long long ans = 0;
	for(int i = 1; i <= n; i++)
		ans += 1LL * a[i] * (rgt[i] - i) * (i - lft[i]);

	printf("%lld\n", ans);
