//SegmentTreeMin
template<typename ValueType>
class SegmentTreeMin{
public:
  SegmentTreeMin(){}
  SegmentTreeMin(int n, ValueType max_value){
    this->N = 1;
    this->max_value = max_value;
    while (this->N < n) this->N *= 2;
    this->data.resize(2 * N - 1, this->max_value);
  }
  //init
  void init(int n, ValueType max_value){
    this->N = 1;
    this->max_value = max_value;
    while (this->N < n) this->N *= 2;
    this->data.resize(2 * N - 1, this->max_value);
  }
  // update k th element
  void update(int k, ValueType val){
    k += N - 1;
    data[k] = val;
    while (k > 0){
      k = (k - 1) / 2;
      data[k] = std::min(data[2 * k + 1], data[2 * k + 2]);
    }
  }
  //min [a, b)
  ValueType min(int a, int b) {
    return min(a, b, 0, 0, N);
  }
  ValueType min(int a, int b, int k, int l, int r){
    if (r <= a or b <= l) return max_value;
    if (a <= l and r <= b) return data[k];
    int med = (l + r) / 2;
    return std::min(min(a, b, 2 *k + 1, l, med), min(a, b, 2 * k + 2, med, r));
  }
private:
  std::vector<ValueType> data;
  int N;
  ValueType max_value;
};

SegmentTreeMin<int> seg(MAX_N, INF);
int left_check(int i, int val){
  int left = -1;
  int right = i;
  while (right - left > 1){
    int med = (right + left) / 2;
    int tmp = seg.min(med, i);
    if (tmp < val){
      left = med;
    }else{
      right = med;
    }
  }
  return right;
}
int right_check(int i, int val){
  int left = i;
  int right = N;
  while (right - left > 1){
    int med = (right + left) / 2;
    int tmp = seg.min(i+1, med+1);
    if (tmp < val){
      right = med;
    }else{
      left = med;
    }
  }
  return left;
}
int main() {
  cin >> N;
  A.resize(N);
  for (int i = 0; i < N; i++){
    cin >> A[i];
  }
  for (int i = 0; i < N; i++){
    seg.update(i, A[i]);
  }
  ll result = 0;
  for (int i = 0; i < N; i++){
    int l = left_check(i, A[i]);
    int r = right_check(i, A[i]);

    result += (ll)A[i] * (i-l+1) * (r-i+1);
  }
