template <typename T,typename E>
struct SegmentTree{
private:
    typedef std::function<T(T,T)> F;
    typedef std::function<T(T,E)> G;
    int n;
    std::vector<T> init;
    F f;//function for merge
    G g;//function for update
    std::vector<T> node;

public:
    explicit SegmentTree(
            int sz,
            F cal,
            G upd,
            std::vector<T> initv=std::vector<T>(1,std::numeric_limits<T>::max())
    ){
        n=1;
        init=initv;
        f=cal;
        g=upd;
        while(n<sz)n=n*2;
        node.resize(static_cast<unsigned int>(2 * n - 1), init[0]);
        for (int i = 0; i <sz ; ++i) node[i+n-1]=init[i+1];
        for (int i = n-2; i >= 0 ; --i) node[i]=f(node[2*i+1],node[2*i+2]);
    }

    void update(int x, E val){//x:0-indexed
        x+=n-1;
        node[x]=g(node[x],val);
        while(x>0){
            x=(x-1)/2;
            node[x]=f(node[2*x+1],node[2*x+2]);
        }
    }

    T query(int p,int q,int k=0,int l=0,int r=-1){//[p,q):0-indexed
        if(r<0)r=n;
        if(r<=p||l>=q)return init[0];//out of range
        if(p<=l&&r<=q)return node[k];

        return f(query(p,q,2*k+1,l,(l+r)/2),query(p,q,2*k+2,(l+r)/2,r));
    }
};

int main(){
    int n;
    std::cin>>n;
    std::vector<int> a(n);
    std::vector<int> pos(n);
    SegmentTree<int,int> st(n+1,[](int a,int b){return std::min(a,b);},[](int a,int b){return b;});
    for (int i = 0; i < n; ++i) {
        std::cin>>a[i];
        --a[i];
        st.update(i,a[i]);
        pos[a[i]]=i;
    }

    std::vector<int> llesslen(n,-1);
    std::vector<int> rlesslen(n,-1);

    for (int i = 0; i < n; ++i) {
        int ok=0,ng=pos[i]+1;
        int mid=(ok+ng)/2;
        while(ng-ok!=1){
            int t=st.query(pos[i]-mid,pos[i]+1);
            if(t==i)ok=mid;
            else ng=mid;
            mid=(ok+ng)/2;
        }
        llesslen[i]=mid;

        ok=0;ng=n-1-pos[i]+1;mid=(ok+ng)/2;
        while(ng-ok!=1){
            if(st.query(pos[i],pos[i]+mid+1)==i)ok=mid;
            else ng=mid;
            mid=(ok+ng)/2;
        }
        rlesslen[i]=mid;
    }

    long long ans=0;
    for (int i = 0; i < n; ++i) {
        ans+=(llesslen[i]+1)*(rlesslen[i]+1)*(i+1);
    }
    std::cout<<ans<<std::endl;
    return 0;
}

