ll dfs(T &seg, int l, int r) {
  if (l == r) return 0;
  int p, val;
  tie(val, p) = seg.find(l, r);
  ll lp = p - l + 1, rp = r - p;
  if (rp < lp) swap(lp, rp);
  ll res = lp * (lp - 1) + (rp - lp + 1) * lp;
  res *= val;
  // cout << l << " " << r << " " << lp << " " << res << endl;
  res += dfs(seg, l, p);
  res += dfs(seg, p + 1, r);
  return res;
}

