#include<bits/stdc++.h>
using namespace std;
#define LS (v << 1)
#define RS (v << 1 | 1)
const int MAXN = 4 * 200010;
const int INF = ~0U >> 2;
int n;
int rea[MAXN];
int ll[MAXN],rr[MAXN];
long long ans;
struct node{
	int Min, Max;
	int l,r;
} t[MAXN];
void build(int v, int l, int r)
{
	t[v].l = l, t[v].r = r;
	if(l == r)
	{
		t[v].Min = n + 1;
		t[v].Max = 0;
		return;
	}
	int mid = (l + r) >> 1;
	build(LS, l, mid);
	build(RS, mid+1, r);
	t[v].Min = n + 1;
	t[v].Max = 0;
}
void chang(int v, int pos, int x)
{
	if(t[v].l == pos && t[v].r == pos)
	{
		t[v].Min = t[v].Max = x;
		return;
	}
	if(pos <= t[LS].r) chang(LS, pos, x);
	if(pos >= t[RS].l) chang(RS, pos, x);
	t[v].Min = min(t[LS].Min, t[RS].Min);
	t[v].Max = max(t[LS].Max, t[RS].Max);
}
int queryi(int v, int l, int r)
{
	if(t[v].l == l && t[v].r == r) return t[v].Min;
	if(r <= t[LS].r) return queryi(LS, l, r);
	else if(l >= t[RS].l) return queryi(RS, l, r);
	else return min(queryi(LS, l, t[LS].r), queryi(RS, t[RS].l, r));
}
int querya(int v, int l, int r)
{
	if(t[v].l == l && t[v].r == r) return t[v].Max;
	if(r <= t[LS].r) return querya(LS, l, r);
	else if(l >= t[RS].l) return querya(RS, l, r);
	else return max(querya(LS, l, t[LS].r), querya(RS, t[RS].l, r));
}
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
		scanf("%d", &rea[i]);
	build(1,1,n);
	chang(1, rea[1], 1);
	ll[1] = 1;
	for(int i = 2; i <= n; i++)
	{
		ll[i] = querya(1, 1, rea[i]) + 1;
		chang(1, rea[i], i);
	}
	build(1,1,n);
	chang(1, rea[n], n);
	rr[n] = n;
	for(int i = n - 1; i > 0; i--)
	{
		rr[i] = queryi(1, 1, rea[i]) - 1;
		chang(1, rea[i], i);
	}
	for(int i = 1; i <= n; i++)
		ans += (i - ll[i] + 1ll) * (rr[i] - i + 1ll) * rea[i];
	printf("%lld\n",ans);
	return 0;
}

