ll res = 0;

void solve(vi arr) {
  int sz = arr.size();
  if (sz == 0) return;
  if (sz == 1) {
    res += arr[0];
    return;
  }
  int val = arr[0], pivot = 0;
  REP(i,sz) {
    if (arr[i] < val) {
      val = arr[i];
      pivot = i;
    }
  }
  res += val * (pivot + 1) * (sz - pivot);
  {
    vi vec(arr.begin(),arr.begin()+pivot);
    solve(vec);
  }
  {
    vi vec(arr.begin()+pivot+1,arr.end());
    solve(vec);
  }
}

