int sumSubarrayMins(int A[], int n) 
{ 
    int left[n], right[n]; 
    stack<pair<int, int> > s1, s2; 
    for (int i = 0; i < n; ++i) { 
        int cnt = 1; 
        while (!s1.empty() && (s1.top().first) > A[i]) { 
            cnt += s1.top().second; 
            s1.pop(); 
        } 

        s1.push({ A[i], cnt }); 
        left[i] = cnt; 
    } 
    for (int i = n - 1; i >= 0; --i) { 
        int cnt = 1; 
        while (!s2.empty() && (s2.top().first) >= A[i]) { 
            cnt += s2.top().second; 
            s2.pop(); 
        } 

        s2.push({ A[i], cnt }); 
        right[i] = cnt; 
    } 
    int result = 0; 
    for (int i = 0; i < n; ++i) 
        result = (result + A[i] * left[i] * right[i]); 
    return result; 
} 

