            if(rmq.rmq(i, mid + 1) == a[i]) ok = mid;
            else ng = mid;
        }
        int r = ok;
        int diff = abs(abs(i - l) - abs(i - r));
        int len = min(abs(i - l), abs(i - r)) + 1;
