int main()
{
	int N;
	cin >> N;
	vector<long> a(N, 0);
	for (int i = 0; i < N; ++i) cin >> a[i];

	int min_index = N-1;
	long min = a[min_index];
	vector<long> min_sum(N, 0);
	long sum = min_sum[N-1] = min;
	for (int i = N-1; i != 0; ) {
		--i;
		if (a[i] < min) {
			min = a[i];
			min_index = i;
			min_sum[i] = min * (N - i);
		} else if (a[i] > a[i+1]) {
			min_sum[i] = min_sum[i+1] + a[i];
		} else if (a[i] - min == 1) {
			min_sum[i] = min_sum[min_index] + a[i]*(min_index - i);
		} else {
			for (int j = i + 1; j < N; ++j) {
				if (a[i] > a[j]) {
					min_sum[i] = min_sum[j] + a[i]*(j - i);
					break;
