	if(R<=mid)
		query(cur<<1,l,mid,L,R);
	else if(L>mid)
		query(cur<<1|1,mid+1,r,L,R);
	else
	{
		query(cur<<1,l,mid,L,mid);
		query(cur<<1|1,mid+1,r,mid+1,R);
