    ret+=idx*(pos[idx]-l+1)*(r-pos[idx]);
    //cout << l << ' ' << r << ' ' << (pos[idx]-l+1) << ' ' << (r-pos[idx]) << endl;
    ret+=partition_(l, pos[idx], idx);
    ret+=partition_(pos[idx]+1, r, idx);
    return ret;
}

