long long func(int l,int r){
	if(l==r) return a[l];
	long long sum=0;
	int min = a[l];
	int pos = l;
	for (int i = l+1; i <= r; ++i)
	{
		if(min>a[i]) min = a[i],pos=i;
	}
	if(pos>l) sum+=func(l,pos-1);
	if(pos<r) sum+=func(pos+1,r);
	return sum+(pos-l+1)*(r-pos+1)*min;
}
