ll tree[T*2-1];

void update(ll i,ll x) {
  i+=(T-1);
  tree[i] = x;
  while(i!=0){
    i=(i-1)/2;
    tree[i] = min(tree[i*2+1],tree[i*2+2]);
  }
}

ll find(int a ,int b,int ima,int L,int R){
  if(R<=a || b<=L) return INF;
  if(a<=L && R<=b) return tree[ima];
  ll M = (R+L)/2;
  return min(find(a,b,ima*2+1,L,M),find(a,b,ima*2+2,M,R));
}

