// ------ disjoint set ------ //
struct UnionFind {
    vector<int> data;
    int __size;
    UnionFind(int size) : data(size, -1), __size(size) { }
    bool unionSet(int x, int y) {
        if ((x = root(x)) != (y = root(y))) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x; __size--;
        }
        return x != y;
    }
    bool findSet(int x, int y) { return root(x) == root(y); }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
    int size(int x) { return -data[root(x)]; }
    int size() { return __size; }
};

int main() {
    int n; cin >> n;
    vector<int> a(n + 1), idx(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        idx[a[i]] = i;
    }

    ll ans = 0;
    UnionFind uf(n + 1);
    for (int j = n; j >= 1; j--) {
        int i = idx[j];
        ans += a[i];
        if (i - 1 >= 1 && a[i - 1] > a[i]) {
            ans += uf.size(i - 1) * uf.size(i) * a[i];
            uf.unionSet(i - 1, i);
        }
        if (i + 1 <= n && a[i + 1] > a[i]) {
            ans += uf.size(i + 1) * uf.size(i) * a[i];
            uf.unionSet(i + 1, i);
        }
    }
    cout << ans << endl;
    return 0;
}

