llint solve(vllint a) {
	if (a.size() == 0)return 0;
	int mn = 200001;
	int mni;
	rep(i, a.size()) {
		if (mn > a[i]) {
			mn = a[i];
			mni = i;
		}
	}
	vllint b, c;
	rep(j, mni) {
		b.push_back(a[j]);
	}
	for (int j = mni + 1;j < a.size();j++) {
		c.push_back(a[j]);
	}
	return mn*(a.size() - mni)*(mni + 1) + solve(b) + solve(c);
}

