int findmin(vector<int>&ar ,int st, int end)
{
	int minn = INT_MAX;
	int ind = -1;
	for(int i =st ; i<end ; i++)
	{
		if( ar[i]  < minn)
		{
			minn = ar[i];
			ind = i;
		}

	}
	return ind;
}
int solve(vector<int> &ar, int st, int end )
{
	if( st >= end)
		return 0;
	if( st == end - 1)
	{
		return ar[st];
	}
	int minn = findmin(ar, st, end);
	int res = ar[minn] * (minn - st + 1) * (end - minn );
	res += solve(ar, st, minn) + solve(ar, minn + 1, end);
	return res; 
}
