const int N = 200000 + 5;

int n;
LL ans;
int a[N];
int g[N][20];

void pre() {
	for (int i = 1; i <= n; i++) g[i][0] = i;
	for (int j = 1; (1 << j) <= n; j++) {
		for (int i = 1; i + (1 << j) - 1 <= n; i++)
			if (a[g[i][j - 1]] < a[g[i + (1 << (j - 1))][j - 1]]) g[i][j] = g[i][j - 1];
			else g[i][j] = g[i + (1 << (j - 1))][j - 1];
	}
}

int getg(int l, int r) {
	int k = (int)log2(r - l + 1 + 0.5);
	return a[g[l][k]] < a[g[r - (1 << k) + 1][k]] ? g[l][k] : g[r - (1 << k) + 1][k];
}

void solve(int l, int r) {
	if (l > r) return;
	int pos = getg(l, r);
	ans += 1LL * a[pos] * (pos - l + 1) * (r - pos + 1);
	solve(l, pos - 1);
	solve(pos + 1, r);
}

int main() {
	read(n);
	for (int i = 1; i <= n; i++) read(a[i]);
	pre();
	solve(1, n);
	printf("%lld\n", ans);
	return 0;
}

