// Range Minimum
struct SegmentTree{
    int n;
    vector<int> data;
    int init;

    SegmentTree(int n_, int ini){
        init = ini;
        n = 1;
        while(n < n_) n *= 2;
        data.assign(2*n-1, init);
    }

    void update(int k, int v){
        k += n-1;
        data[k] = v;
        while(k>0){
            k = (k-1)/2;
            data[k] = min(data[2*k+1], data[2*k+2]);
        }
    }

    // search [p,q)
    int query(int a, int b, int k, int l, int r){
        if(a <= l && r <= b){
            //assert(n-1 <= k && k < 2*n-1);
            return data.at(k);
        }
        else if(r <= a || b <= l) return init;
        else{
            int v1 = query(a,b, k*2+1, l, (l+r)/2);
            int v2 = query(a,b, k*2+2, (l+r)/2, r);
            return min(v1,v2);
        }
    }

    int query(int l,int r){
        return query(l,r,0,0,n);
    }
};

int main(){
    int N; cin >> N;
    vector<ll> a(N+2);
    a[0] = 0;
    a[N+1] = 0;
    SegmentTree seg(N+2,INF);
    for(int i=1;i<=N;i++){
        cin >> a[i];
    }
    for(int i=0;i<N+2;i++){
        seg.update(i,a[i]);
    }


    ll ans = 0;
    for(int i=1;i<=N;i++){
        ll L = [&](){
            int l,r;
            l = 0;
            r = i;
            while(r-l>1){
                int m = (l+r)/2;
                int val = seg.query(m, i);

                if(val > a[i]){
                    r  = m;
                }else{
                    l = m;
                }
            }
            return i-l;
        }();

        ll R = [&](){
            int l,r;
            l = i+1;
            r = N+2;
            while(r-l>1){
                int m = (l+r)/2;
                int val = seg.query(i+1, m);
                if(val < a[i]){
                    r = m;
                }else{
                    l = m;
                }
            }
            return l-i;
        }();

        ans += L * R * a[i];
    }
    cout << ans << endl;
}

