    pt[index2] = val;
    while (index2 > 0) {
        index2 = (index2-1)/2;
        pt[index2] = min(pt[index2 * 2 +1], pt[2*index2 + 2]);
    }
}

int getMin(int start, int end,int k, int l, int r){
    if (end <= l || r <= start) {
        return INT_MAX;
    }

    if (start <= l && r <= end) {
        return pt[k];
    }else{
        int rl = getMin(start, end, 2*k+1, l, (l+r)/2);
        int rr = getMin(start, end, 2*k+2, (l+r)/2, r);
        return min(rl, rr);
    }
}



