using namespace std;
//
const int MAX_N=1<<17;
//
int N,DAT[2*MAX_N-1];
//
void init(int N_){
  N=1;
  while(N<N_){
    N*=2;
  }
  FOR(i,0,2*N-1){
    DAT[i]=INF;
  }
}
//
void update(int K,int A){
  K+=N-1;
  DAT[K]=A;
  while(K>0){
    K=(K-1)/2;
    DAT[K]=min(DAT[K*2+1],DAT[K*2+2]);
  }
}
//
int query(int A,int B,int K,int L,int R){
  if(R<=A||B<=L){
    return INF;
  }else if(A<=L&&R<=B){
    return DAT[K];
  }else{
    int VL=query(A,B,K*2+1,L,(L+R)/2);
    int VR=query(A,B,K*2+2,(L+R)/2,R);
    return min(VL,VR);
  }
}
int main(){
  int M,P;
  cin>>M;
  N=M;
  init(N);
  FOR(i,0,M){
    cin>>P;
    update(i,P);
  }
  long long sum=0;
  FOR(i,1,M+1){
    FOR(j,0,M-i+1){
      sum+=query(j,j+i,0,0,N);
    }
  }
  cout<<sum<<endl;
  return 0;
}

