class RMQ {
public:
	static const int MAX_N = 200001;
	int n, dat[2 * MAX_N - 1];
	//[a,b)の最小値を返す
	//kは節点の番号l,rはその節点が[l,r)を保持している
	int rec(int a, int b, int k, int l, int r) {
		if (b <= l || r <= a) {
			return INT_MAX;
		}

		if (a <= l && r <= b) {
			return dat[k];
		}
		else {
			int rl = rec(a, b, 2 * k + 1, l, (l + r) / 2);
			int rr = rec(a, b, 2 * k + 2, (l + r) / 2, r);
			return min(rl, rr);
		}
	}

	void init(int n_) {
		n = 1;
		while (n < n_) n *= 2;

		for (int i = 0; i<2 * n - 1; i++) {
			dat[i] = INT_MAX;
		}
	}

	//kをaに変更
	void update(int k, int a) {
		int reaf = k + n - 1;
		dat[reaf] = a;
		while (reaf>0) {
			reaf = (reaf - 1) / 2;
			dat[reaf] = min(dat[reaf * 2 + 1], dat[2 * reaf + 2]);
		}
	}

	//query[a,b]の範囲内の最小値を返す
	int query(int a, int b) {
		return rec(a, b + 1, 0, 0, n);
	}

	int N_search(int p) {

	}
};

int main() {
	int n;
	scanf("%d", &n);
	vector<int> num(n);
	RMQ rmq;
	rmq.init(n);
	REP(i, n) {
		int a;
		scanf("%d", &num[i]);
		rmq.update(i,num[i]);
	}
	ll sum = 0;
	REP(i, n) {
		int l, r;
		int Max = i;
		int Min = 0;
		while (1) {
			int Mid = (Max + Min) / 2;
			if (rmq.query(Mid, i) == num[i]) {
				Max = Mid;
			}
			else {
				Min = Mid + 1;
			}
			if (Max == Min) {
				l = Max;
				break;
			}
		}
		Max = n - 1;
		Min = i;
		while (1) {
			int Mid = (Max + Min) / 2 + (Max+Min)%2;
			if (rmq.query(i, Mid) == num[i]) {
				Min = Mid;
			}
			else {
				Max = Mid - 1;
			}
			if (Max == Min) {
				r = Max;
				break;
			}
		}
		sum += (i - l + 1)*(r - i + 1)*num[i];
	}
	printf("%d\n", sum);
	return 0;
}

