using lint = long long;

struct UnionFind {
    vector<int> par, lb, ub;
    UnionFind(int N): par(N), lb(N), ub(N) {
        for (int i = 0; i < N; i++) {
            par[i] = i;
            lb[i] = i;
            ub[i] = i;
        }
    }

    int root(int i) {
        if (par[i] == i) {
            return i;
        } else {
            par[i] = root(par[i]);
            return par[i];
        }
    }
    void unite(int i, int j) {
        if (root(i) != root(j)) {
            lb[root(i)] = min(lb[root(i)], lb[root(j)]);
            ub[root(i)] = max(ub[root(i)], ub[root(j)]);
            par[j] = root(par[i]);
        }
        return;
    }
    bool same(int i, int j) {
        return root(i) == root(j);
    }
    int lower(int i) {
        return lb[root(i)];
    }
    int upper(int i) {
        return ub[root(i)];
    }
};

int main() {
    int N;
    cin >> N;
    vector<lint> a(N + 1), place(N + 1);
    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        place[a[i]] = i;
    }

    UnionFind uf(N + 1);
    lint ans = 0;
    for (int i = N; i >= 1; i--) {
        int pos = place[i];
        if (pos > 1 and a[pos - 1] > a[pos]) {
            uf.unite(pos - 1, pos);
        }
        if (pos < N and a[pos] < a[pos + 1]) {
            uf.unite(pos, pos + 1);
        }

        ans += i*(pos - uf.lower(pos) + 1)*(uf.upper(pos) - pos + 1);
    }

    cout << ans << endl;
    return 0;
}

