#include<bits/stdc++.h>
using namespace std;

const int max_a = 200000;
int seg[400000];
int leaf = 1;


int main()
{
    std::ios::sync_with_stdio(false);
    int N;
    cin >> N;

    // number of leaves
    int n = N;
    while (n > 0)
        leaf <<= 1, n >>= 1;
    // cout << "leaf " << leaf << endl;

    //  build seg tree
    for (int i=0; i<N; i++) cin >> seg[i + leaf - 1];
    for (int i=N; i<leaf; i++) seg[i + leaf - 1] = max_a;
    for (int i=leaf-2; i>=0; i--)
        seg[i] = min(seg[2*i + 1], seg[2*i + 2]);
    assert(seg[0] == 1);


    //  calc answer
    long long ans = 0;
    for (int i = 0; i<N; i++)
    {
        int now = i + leaf - 1;
        int target = seg[now];
        if (target == 1)
        {
            ans += (i + 1) * (N - 1 - i + 1);
            continue;
        }

        int left = now;
        int next;
        while (true)
        {
            next = (left - 1) >> 1;
            if (~now & 1 and seg[next] >= target)
                left = next;
            else
            {
                while (left < leaf - 1)
                    left = 2 * left +1;
                left--;

                if (left < leaf - 1 or seg[left] <= target)
                {
                    left++;
                    break;
                }
            }
        }

        int right = now;
        while (true)
        {
            next = (right - 1) >> 1;
            if (now & 1 and seg[next] >= target)
                right = next;
            else
            {
                while (right < leaf - 1)
                    right = 2 * right + 2;
                right++;

                if (right > 2 * leaf - 2 or seg[right] <= target)
                {
                    right--;
                    break;
                }
            }
        }
        right = min(right, N - 1 + leaf - 1);

        ans += target * (now - left + 1) * (right - now + 1);
        // cout << "ans " << target * (now - left + 1) * (right - now + 1) << " " << left - leaf + 1<< ' ' << right - leaf + 1 << endl;
    }
    cout << ans << endl;
    return 0;
}

