int getmin(int b, int e){ //[b, e]
	if (b>e) return 0;
	int d = 262144;
	for(int i=0;i<100;i++){
		if (b/d != e/d) break;
		if (b%d==0 && (e+1)%d==0){
			return rmq[262144/d + b/d];
		}
		d /= 2;
	}
	int tmp = e/d*d;
	return min(getmin(b,tmp-1),getmin(tmp,e));
}

