    index[a[i]] = i;
  }

  set<long long> s;
  s.insert(-1);
  s.insert(n);
  long long l,r;
  long long ans = 0;
  for(long long i=1;i<=n;i++){//最小値としてiをとる区間の個数を数える
    auto itr_r = s.lower_bound(index[i]);
    r = *itr_r;
    auto itr_l = --itr_r;
    l = *itr_l;
    ans += i*(index[i]-l)*(r-index[i]);
    s.insert(index[i]);
  }

  return 0;
}

