int fac[2000005], invfac[2000005];
void compute() {
	fac[0] = 1;
	for (int i = 1; i <= 2000000; i += 1) {
		fac[i] = (fac[i - 1] * i) % mod;
	}
	invfac[2000000] = inv(fac[2000000]);
	for (int i = 2000000 - 1; i >= 0; i--) {
		invfac[i] = (invfac[i + 1] * (i + 1)) % mod;
