void make_set (int v) {
	sz[v] = 1;
	p[v] = v;
}

int find_set (int v) {
	if (p[v] == v) return v;
	else return p[v] = find_set(p[v]);
}

void merge_set (int a, int b) {
	a = find_set(a), b = find_set(b);
	if (a == b) return;
	if (sz[a] < sz[b]) swap(a, b);
	p[b] = a;
	sz[a] += sz[b];
}

