class BIT {
public:
  int N;
  vi arr;
  BIT(int n) {
    N = n;
    arr = vi(N+1,0);
  }
  int sum(int x) {
    int s = 0;
    for(int i = x+1;i > 0;i -=i&(-i)) {
      s += arr[i];
    }
    return s;
  }
  void add(int x,int k) {
    for(int i = x+1;i <= N;i +=i&(-i)) {
      arr[i] += k;
    }
  }
};

