template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vec(istream& in, size_t n) {
  vector<T> ret(n);
  for (size_t i = 0; i < n; ++i) {
    ret[i] = next<T>(in);
  }
  return ret;
}


void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto p = next_vec<int>(in, n);
  vec<int> posOf(n);
  FOR(i, n) {
    --p[i];
    posOf[p[i]] = i;
  }
  vec<int> leftMost(n, -1), rightMost(n, -1);
  i64 res = 0;
  for (int i = n-1; i >= 0; --i) {
    int pos = posOf[i];
    int le = pos, ri = pos;
    if (le - 1 >= 0 && p[le - 1] > i) {
      le = leftMost[le - 1];
    }
    if (ri + 1 < n && p[ri + 1] > i) {
      ri = rightMost[ri + 1];
    }
    i64 leSize = pos - le;
    i64 riSize = ri - pos;
    res += ((leSize * riSize) + leSize + riSize + 1) * (i + 1);
    leftMost[ri] = le;
    rightMost[le] = ri;
  }
  out << res << "\n";
}

