using namespace std;


int N;
int dat[800010], n_dat, idx[200001];


int query(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) return INT_MAX;

    if(a <= l && r <= b) return dat[k];

    int vl = query(a, b, k*2+1, l, (l+r)/2);
    int vr = query(a, b, k*2+2, (l+r)/2, r);
    return min(vl, vr);
}

long long solve(int l, int r){
    //printf("l = %d, r = %d\n", l, r);
    if(l >= r){
        return 0;
    }
    int target = query(l, r, 0, 0, n_dat);
    int target_idx = idx[target];
    long long ret = 0;
    ret += target * (target_idx - l + 1) * (r - target_idx);
    ret += solve(l, target_idx);
    ret += solve(target_idx + 1, r);
    return ret;
}

int main(){
    cin >> N;
    for(int i = 0; i < 800010; i++){
        dat[i] = INT_MAX;
    }
    n_dat = 1;
    while(N > n_dat){
        n_dat *= 2;
    }
    //printf("n_dat = %d\n", n_dat);

    for(int i = 0; i < N; i++){
        cin >> dat[n_dat - 1 + i];
        idx[dat[n_dat-1+i]] = i;
        int k = n_dat - 1 + i;
        while(k > 0){
            k = (k-1)/2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }
    //printf("initialized\n");
    long long ans = 0;
    ans = solve(0, N);
    cout << ans << endl;

}

