template <class Monoid>
class SegmentTree{
  public:
    int n;
    using T = typename Monoid::value_type;
    vector<T> val;
    T identity;

    SegmentTree(){}
    SegmentTree(int n_, vector<T> v=vector<T>()){
      n = 1;
      while(n < n_)n *= 2;
      identity = Monoid::identity;
      val.assign(2*n-1, identity);

      for(size_t i = 0; i < v.size(); i++){
        val[i+n-1] = v[i];
      }
      for(int i = n - 2; i >= 0; i--){
        val[i] = Monoid::operation(val[2*i+1], val[2*i+2]);
      }
    }
    void update(int k, const T &t){
      k = k + n - 1;
      val[k] = t;
      while(k > 0){
        k = (k - 1) / 2;
        val[k] = Monoid::operation(val[2*k+1], val[2*k+2]);
      }
    }
    T query(int a, int b, int k, int l, int r){
      if(r <= a || b <= l)return identity;
      if(a <= l && r <= b)return val[k];
      T lv = query(a, b, 2*k+1, l, (l+r)/2);
      T rv = query(a, b, 2*k+2, (l+r)/2, r);
      return Monoid::operation(lv, rv);
    }
    T query(int a, int b){
      return query(a, b, 0, 0, n);
    }
    T get(int i){
      return val[i+n-1];
    }
};

template <typename T>
class RMQ{
  public:
    const static T identity;
    using value_type = T;

    RMQ(){}
    static T operation(T &l, T &r){
      return min(l, r);
    }
};

template <typename T>
const T RMQ<T>::identity = numeric_limits<T>::max();

template <typename T>
class RMAQ{
  public:
    const static T identity;
    using value_type = T;

    RMAQ(){}
    static T operation(T &l, T &r){
      return max(l, r);
    }
};

template <typename T>
const T RMAQ<T>::identity = numeric_limits<T>::min();

int main(int argc, char const* argv[])
{
  int n; cin >> n;
  vector<ll> a(n); cin >> a;
  vector<int> e(n); rep(i, n)e[i] = i;
  sort(whole(e), [&](int i, int j){
    return a[i] < a[j];
  });
  SegmentTree<RMQ<ll>> seg(n);
  SegmentTree<RMAQ<ll>> sega(n);
  ll res = 0;
  rep(i_, n){
    int i = e[i_];
    ll l = sega.query(0, i);
    if(l == RMAQ<ll>::identity)l = i + 1;
    else l = i - l;
    ll r = seg.query(i, n);
    if(r == RMQ<ll>::identity)r = n - i;
    else r = r - i;
    res += a[i] * l * r;
    seg.update(i, i);
    sega.update(i, i);
  }
  cout << res << endl;
  return 0;
}

