		where[a[i]] = i;
	}
	for(int i=1; i<=N; i++){
		tmp = -1;
		get(1,1,nn,1,where[i]-1);
		while(tmp < nn && tmp != -1){
			if(seg[tmp*2+1] != 0){
				tmp = tmp*2+1;
			}else tmp = tmp*2;
		}
		if(tmp == -1) left[i] = nn;
		else left[i] = tmp+1;
		tmp = -1;
		get2(1,1,nn,where[i]+1,N);
