#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}


ll naive(int N, vi& a) {
    ll ans = 0LL;
    for (int l=0; l<N; ++l) {
        for (int r=l; r<N; ++r) {
            int minv = INT_MAX;
            for (int i=l; i<=r; ++i) {
                minv = min(minv, a[i]);
            }
            ans += minv;
        }
    }
    return ans;
}


inline ll f(int n) {
    // nC2
    return (ll)n*(n+1)/2;
}

ll fast(int N, vi& a) {
    ll ans = 0LL;
    // 区間数は1+2+..+N =N(N+1)/2
    // 1から順に、その数がminになるのが何回あるか数える？
    // 1有り範囲: [0 .. N) =
    // 1なし2有り範囲:  [) 1の位置 [)
    // 区間長n -> f(n)=n(n+1)/2
    // kで長さaの区間がa1,a2に分割されたとき(a=a1+a2+1)
    // kを含んでいた頃：f(a) これはminがk+1以上を含む
    // kを含まない頃 (minがk+1): f(a1)+f(a2)
    // 1つの数字の出現で高々1回しかsplitは発生しない
    // ... 20万回分割していくと?
    // 後でNから逆に包含を溶いていく？
    vector<ii> b(N);
    rep(i,N) b[i] = ii(a[i], i);
    sort(ALL(b)); // (1,w)...(N,w)
    vi aR(N+1);
    rep(i,N) aR[1+i] = b[i].second;
    aR[0] = -1;//
#ifdef DEBUG
    cerr << "aR: " << aR << endl;
#endif
    vector<ll> pat(N+1);
    pat[0] = f(N);

    set<ii> spans;
    spans.insert(ii(0,N)); // (from, len)
#ifdef DEBUG
    cerr << 0 << spans << endl;
#endif

    for (int x=1; x<=N; ++x) { // 200000
        int at = aR[x];
#ifdef DEBUG
        fprintf(stderr, "x=%d, at=%d", x, at); cerr << spans << endl;
#endif
        // if (spans.empty()) {
        //     break;
        // }

        auto it = spans.lower_bound(ii(at,N+1));
        assert(it != spans.begin());
        --it;

        int from = it->first, len = it->second;
        spans.erase(it);
        pat[x] = f(len);
        // [from, at), at, [at+1, from+len)
        if (from != at) {
            int sub_len = at - from;
            spans.insert(ii(from, sub_len));
            pat[x] -= f(sub_len);
        }
        if (at != from+len-1) {
            int sub_len = (from+len) - (at+1);
            spans.insert(ii(at+1, sub_len));
            pat[x] -= f(sub_len);
        }
        ans += (ll)x * pat[x];
#ifdef DEBUG
        cerr << x << spans << endl;
#endif
    }

    // ll patR(N+1, 0);
    // patR[n] = pat[n];
    // for (int i=N-1; i>=0; --i) {
    //     patR[i] = patR[i+1]
    // }

#ifdef DEBUG
    cerr << "pat:" << pat << endl;
#endif
    return ans;
}

ll solve(int N, vi& a) {
    ll ans = fast(N,a);
    // if (N < 100) {
    //     ll naive_ans = naive(N,a);
    //     assert(ans == naive_ans);
    // }
    return ans;
}

