struct union_find {
    vector<int> data;
    union_find(int size) : data(size, -1) { }
    void unite(int x, int y) {
        x = root(x); y = root(y);
        if(x != y) {
            if(data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

signed main() {
    int n;
    cin>>n;
    vector<int> a(n);
    cin>>a;

    union_find uf(n);
    vector<pii> p(n);
    REP(i,n) p[i]={a[i],i};
    vector<bool> u(n,false);
    sort(RALL(p));

    int ans=0;
    REP(i,n) {
        u[p[i].second]=true;

        int l=0,r=0;
        if(p[i].second>0 && u[p[i].second-1]) {
            l=uf.size(p[i].second-1);
            uf.unite(p[i].second-1,p[i].second);
        }
        if(p[i].second<n-1 && u[p[i].second+1]) {
            r=uf.size(p[i].second+1);
            uf.unite(p[i].second,p[i].second+1);
        }

        ans+=p[i].first*(l+1)*(r+1);
    }
    cout<<ans<<endl;
    return 0;
}

