template <class Monoid>
class SegmentTree{
  public:
    int n;
    using T = typename Monoid::value_type;
    vector<T> val;
    T identity;

    SegmentTree(){}
    SegmentTree(int n_, vector<T> v=vector<T>()){
      n = 1;
      while(n < n_)n *= 2;
      identity = Monoid::identity;
      val.assign(2*n-1, identity);

      for(size_t i = 0; i < v.size(); i++){
        val[i+n-1] = v[i];
      }
      for(int i = n - 2; i >= 0; i--){
        val[i] = Monoid::operation(val[2*i+1], val[2*i+2]);
      }
    }
    void update(int k, const T &t){
      k = k + n - 1;
      val[k] = t;
      while(k > 0){
        k = (k - 1) / 2;
        val[k] = Monoid::operation(val[2*k+1], val[2*k+2]);
      }
    }
    T query(int a, int b, int k, int l, int r){
      if(r <= a || b <= l)return identity;
      if(a <= l && r <= b)return val[k];
      T lv = query(a, b, 2*k+1, l, (l+r)/2);
      T rv = query(a, b, 2*k+2, (l+r)/2, r);
      return Monoid::operation(lv, rv);
    }
    T query(int a, int b){
      return query(a, b, 0, 0, n);
    }
    T get(int i){
      return val[i+n-1];
    }
};

template <typename T>
class RMQ{
  public:
    const static T identity;
    using value_type = T;

    RMQ(){}
    static T operation(T &l, T &r){
      return min(l, r);
    }
};

template <typename T>
const T RMQ<T>::identity = numeric_limits<T>::max();

template <typename T>
class RMAXQ{
  public:
    const static T identity;
    using value_type = T;

    RMAXQ(){}
    static T operation(T &l, T &r){
      return max(l, r);
    }
};

template <typename T>
const T RMAXQ<T>::identity = numeric_limits<T>::min();

int main(int argc, char const* argv[])
{
  int n; cin >> n;
  vector<int> a(n); cin >> a; rep(i, n)a[i]--;
  vector<int> tr(n); rep(i, n)tr[a[i]] = i;
  SegmentTree<RMQ<int>> segmin(n);
  SegmentTree<RMAXQ<int>> segmax(n);
  ll res = 0;
  rep(j, n){
    int i = tr[j];
    ll l = segmax.query(0, i);
    if(l == RMAXQ<int>::identity)l = -1;
    ll r = segmin.query(i, n);
    if(r == RMQ<int>::identity)r = n;
    res += (ll)(a[i] + 1) * (i - l) * (r - i);
    //cerr << j << " " << a[i] << " " << l << " " << r << " " << res << endl;
    segmax.update(i, i);
    segmin.update(i, i);
  }
  cout << res << endl;
  return 0;
}

