/*
・SparseTable
  > 前処理 O(NlogN)
  > query O(1)
[備考] 静的な配列における, 任意区間の最小値を定数時間で求められるデータ構造.
[使用例]
SparseTable<int> st(V);     // V(vector)で初期化し, 前処理を行う
st.query(l,r);              // 半開区間[l,r)における最小値
*/

template<typename T> struct SparseTable {
  vector<vector<T>> st;
  SparseTable() {}
  SparseTable(const vector<T> &v) {
    int b = 0;
    while((1 << b) <= v.size()) ++b;
    st.assign(b, vector<T>(1 << b));
    for(int i = 0; i < v.size(); i++) st[0][i] = v[i];
    for(int i = 1; i < b; i++) {
      for(int j = 0; j + (1 << i) <= (1 << b); j++) {
        st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
      }
    }
  }
  inline T query(int l, int r) {
    int b = 32 - __builtin_clz(r - l) - 1;
    return (min(st[b][l], st[b][r - (1 << b)]));
  }
};

signed main() {

  SS(int,N);
  SV(int,A,N);

  SparseTable<int> st(A);

  function<bool(int, int, int)> check = [&](int l, int r, int val) {
    ll q = st.query(l, r + 1);
    return q == A[val];
  };

  ll res = 0;
  REP(i, N) {
    // 最小値がA_iとなる範囲を探す
    ll left, right;
    // 左端
    {
      ll ok = i, ng = -1;
      while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        if (check(mid, i, i)) {
          ok = mid;
        } else {
          ng = mid;
        }
      }
      left = ok;
    }
    // 右端
    {
      ll ok = i, ng = N;
      while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        if (check(i, mid, i)) {
          ok = mid;
        } else {
          ng = mid;
        }
      }
      right = ok;
    }
    // print(i, left, right);
    res += (i - left + 1) * (right - i + 1) * A[i];
  }
  print(res);

}

