	int a[N];
	init(N);
	rep(i, 0, N) {
		cin >> a[i];
		update(i, a[i]);
	}

	ll rsl = 0;
	rep(l, 0, N) rep(r, l, N) {
		rsl += query(l, r + 1, 0, 0, n);
	}

	cout << rsl << endl;
}

