int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false);
	cin >> N;
	FORULE(n,1,N) {
		cin >> a[n];
		pos[a[n]] = n;
	}

	// 最小値として含む区間を足し算すればよい
	// ある数が最小値として採用されるrangeの数 * そのある数 の総和
	// ある数が最小値として採用されるrangeの数 = そのある数より小さい数の配置された左側の場所とその数との距離 * そのある数より小さい数の配置された右側場所とその数との距離
	// そのある数より小さい数の配置された左側の場所とその数との距離 = 小さい数からに配置場所indexを set に追加していく。その追加された場所より小さい数は先に set に追加されており、indexの 差分をみれば距離が求まる
	// そのある数より小さい数の配置された右側の場所とその数との距離 = 小さい数からに配置場所indexを set に追加していく。その追加された場所より小さい数は先に set に追加されており、indexの 差分をみれば距離が求まる
	ll sumMin = 0;
	FORULE(n,1,N) {
		pair<set<int>::iterator, bool> it_pair = posSet.insert(pos[n]);
		set<int>::iterator it = it_pair.first;
		set<int>::iterator it_prev = it; it_prev--;
		set<int>::iterator it_next = it; it_next++;
		// DOUT << "---- pos["<<n<<"]="<<pos[n]<<endl;
		int leftAlt = 0;
		if(it!=posSet.begin()) {
			// DOUT << "*it_prev="<<(*it_prev)<<", *it="<<(*it)<<endl;
			leftAlt = (*it)-(*(it_prev));
		}
		else {
			// DOUT << "*it_prev="<<"END"<<", *it="<<(*it)<<endl;
			leftAlt = (*it)-0;
		}
		int rightAlt = 0;
		if((it_next)!=posSet.end()) {
			// DOUT << "*it="<<(*it)<<", *it_next="<<(*it_next) <<endl;
			rightAlt = (*(it_next))-(*it);
		}
		else {
			// DOUT << "*it="<<(*it)<<", *it_next="<<"END"<<endl;
			rightAlt = N+1 - (*it);
		}
		// DOUT << "leftAlt="<<leftAlt<<", rightAlt="<<rightAlt<<endl;
		sumMin += 1LL * n * leftAlt * rightAlt;
	}

	cout << sumMin << endl;

	return 0;
}

