int n;
ll calc(int left, int right, int v) {

	if (v > n) return 0;
	if (left > right) return 0;

	int pos = 0;
	while (pos == 0 && v <= n)
	{
		if (left <= m[v] && m[v] <= right) {
			pos = m[v];
			break;
		}
		v++;
	}
	use[v] = true;
	ll res = 0;
	ll len = right - left + 1;
	ll relp = pos - left + 1;
	res += ((len - (relp - 1)) * relp) * v;
	ll leftp = 0;
	ll rv = 0;
	ll lv = v + 1;

	while (leftp == 0 && lv <= n)
	{
		if (use[lv]) {
			lv++;
			continue;
		}
		if (m[lv] < pos) {
			leftp = m[lv];
			break;
		}
		else if (rv == 0) {
			rv = lv;
		}
		lv++;
	}

	if(lv <= n)
		res += calc(left, pos - 1, lv);
	if (rv != 0) {
		res += calc(pos + 1, right, rv);
	}
	else if(lv < n)
		res += calc(pos + 1, right, lv + 1);
	return res;
}
