int n;

void upd(int pos, int vl, int L = 0, int R = n - 1, int node = 1)
{
	if (pos > R || pos < L)return;

	if (L == R)
	{
		tree[node] = vl;
		return;
	}

	int mid = L + R >> 1;

	upd(pos, vl, L, mid, 2 * node);
	upd(pos, vl, mid + 1, R, 2 * node + 1);

	tree[node] = min(tree[2 * node], tree[2 * node + 1]);
}

int query(int L, int R, int cL = 0, int cR = n - 1, int node = 1)
{
	if (cR < L || cL > R)return INF;

	if (L <= cL && R >= cR)
	{
		return tree[node];
	}

	int mid = cL + cR >> 1;

	return min(query(L, R, cL, mid, 2 * node), query(L, R, mid + 1, cR, 2 * node + 1));
}

int main()
{
	scanf("%d", &n);

	for (int i = 0, x; i < n; i++)
	{
		scanf("%d", &x);
		pos[x] = i;
	}

	memset(tree, 0x3f, sizeof(tree));

	ll ans = 0;

	for (int i = 1; i <= n; i++)
	{
		int cur = pos[i];
		int l = cur;
		int r = n;
		int R, L;

		while (l + 1 < r)
		{
			int mid = l + r >> 1;

			int res = query(cur, mid);

			if (res > i)l = mid;
			else r = mid;
		}

		R = l;

		l = -1;
		r = cur;

		while (l + 1 < r)
		{
			int mid = l + r >> 1;

			int res = query(mid, cur);

			if (res > i)r = mid;
			else l = mid;
		}

		L = r;

		ans += ((ll)cur - L + 1)*((ll)R - cur + 1)*(ll)i;

		upd(cur, i);
	}

	printf("%lld\n", ans);

	return 0;
}

