#define init_value Inf

template <typename T>
struct segtree{
	//元データx[i]はv[n+i]
	//v[i]の親はv[i/2],子はv[i*2]とv[i*2+1]
	vector<T> v;
	int n;

	segtree(vector<T> &x){
		n=1;
		while(true){
			if(n>=x.size())break;
			n*=2;
		}
		v.resize(2*n,init_value);

		for(int i=0;i<x.size();i++){
			v[n+i]=x[i];
		}
		for(int i=n-1;i>=0;i--){
			v[i]=func(v[i*2],v[i*2+1]);
		}
	}


	void update(int x,T val){
		x+=n;
		v[x]=val;
		while(true){
			x=(x)/2;
			v[x]=func(v[x*2],v[x*2+1]);
			if(x<=0)break;
		}
	}

	//区間[l,r)におけるクエリ処理
	T query(int l,int r){
		T res = init_value;
		l+=n;r+=n;
		while(true){
			if(l%2==1){
				res=func(v[l],res);
				l++;
			}
			if(r%2==1){
				res=func(v[r-1],res);
				r--;
			}
			if(l>=r)break;
			l/=2;r/=2;
		}
		return res;
	}
	T func(T a,T b){
		return min(a,b);
	}

	void show(){
		int n = 1;
		for(int i=1;i<v.size();i++){
			for(int j=0;j<n;j++){
				if(j!=0)cout<<' ';
				cout<<v[i+j];
			}
			cout<<endl;
			i+=n-1;
			n*=2;
		}
	}

};

int main(){

	int N;
	cin>>N;

	vector<long long> a(N);
	for(int i=0;i<N;i++)cin>>a[i];

	segtree<long long> seg(a);

	vector<pair<int,int>> V(N);

	for(int i=0;i<N;i++){
		int ok = i;
		int ng = -1;
		while(abs(ok-ng)>1){
			int mid = (ok+ng)/2;
			long long m = seg.query(mid,i+1);
			if(m==a[i])ok=mid;
			else ng=mid;
		}
		V[i].first = ok;

		ok = i;
		ng = N;
		while(abs(ok-ng)>1){
			int mid = (ok+ng)/2;
			long long m = seg.query(i,mid+1);
			if(m==a[i])ok=mid;
			else ng=mid;
		}
		V[i].second = ok;

	}

	long long ans = 0;

	for(int i=0;i<N;i++){
		ans += a[i]*(i-V[i].first+1)*(V[i].second-i+1);
		//cout<<V[i].first<<','<<V[i].second<<endl;
	}

	cout<<ans<<endl;

	return 0;
}

