#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define MAX_N 200001
ll N;

long long par[MAX_N]; // 親
long long rankuf[MAX_N]; // 木の深さ
ll L[MAX_N], R[MAX_N];
ll treenum = 0;
// n要素で初期化
void init(long long n) {
	for (long long i = 0; i < n; i++) {
		par[i] = i;
    	rankuf[i] = 0;
		L[i] = i;
		R[i] = i;
	}
	treenum = n;
}
// 木の根を求める
long long find(long long x) {
	if (par[x] == x) {
		return x;
	} else {
		return par[x] = find(par[x]);
	}
}
// xとyの属する集合を併合
void unite(long long x, long long y) {
	x = find(x);
	y = find(y);
	if (x == y) return;
	if (rankuf[x] < rankuf[y]) {
		par[x] = y;
		L[y] = min(L[x], L[y]);
		R[y] = max(R[x], R[y]);
	} else {
		par[y] = x;
		L[x] = min(L[x], L[y]);
		R[x] = max(R[x], R[y]);
		if (rankuf[x] == rankuf[y]) rankuf[x]++;
	}
	treenum--;
}
// xとyが同じ集合に属するか否か
bool same(long long x, long long y) {
	return find(x) == find(y);
}

