	for(int i = N-1 ; i >= 0 ; i--){
		if (b[i]-1>=0 && a[b[i]-1]>i) unite(b[i]-1, b[i]);
		if (b[i]+1<=N-1 && a[b[i]+1]>i) unite(b[i]+1, b[i]);
