		t[v] = a[tl];
	else {
		int tm = (tl + tr) / 2;
		build (v * 2, tl, tm);
		build (v * 2 + 1, tm+1, tr);
		t[v] = min(t[v * 2], t[v * 2 + 1]);
	}
}

long long sum (int v, int tl, int tr, int l, int r) {
	if (l > r)
		return 999999999;
	if (l == tl && r == tr)
		return t[v];
	int tm = (tl + tr) / 2;
	return min(sum (v*2, tl, tm, l, min(r,tm))
		,sum (v*2+1, tm+1, tr, max(l,tm+1), r));
}

