vector<int> findnge(vector<int> &ar)
{
	int n = ar.size();
	vector<int> res(n);
	stack<int> st;
	for(int i =0 ;i<n; i++)
	{
		while(st.size() && ar[st.top()] > ar[i])
		{
			res[st.top()] = i;
			st.pop();
		}
		st.push(i);
	}
	while(st.size())
	{
		res[st.top()] = n;
		st.pop();
	}
	return res;
}
