template <typename T>
class SegmentTree {
private:
  using F = function<T(T,T)>; // min or max

  F f;
  T ti; // 単位元 (INF for min or -INF for max)

  int n;
  vector<T> dat;

  // Find a minimum in [a,b).
  // A node k corresponds to a range [l,r) in the segment tree.
  // So, the initial query should be query(a, b, 0, 0, n)
  T query(const int a, const int b, const int k, const int l, const int r) {
     // 1) No cross between [a,b) and [l, r)
     if (r<=a || b<=l) {
       return ti;
     }

     // 2) [a,b) includes [l ,r)
     if (a <= l && r <= b) return dat[k];

     // 3) otherwise
     const T vl = query(a, b, k*2+1, l, (l+r)/2);
     const T vr = query(a, b, k*2+2, (l+r)/2, r);
     return f(vl, vr);
  }

public:
  SegmentTree(F _f, T _ti)
    : f(_f), ti(_ti) {}

  void init(int n_) {
    // Set n to power of 2
    n = 1;
    while (n < n_) n *= 2;

    dat.resize(2*n-1);
    fill(begin(dat), end(dat), ti);
  }

  void build(const vector<T>& v) {
    const int n_ = v.size();
    init(n_);

    for(int i=0; i<n_; i++) dat[i+n-1] = v[i];
    for(int i=n-2; i>=0 ;i--)
      dat[i] = f(dat[i*2+1], dat[i*2+2]);
  }

  // Update the value of the k-th node (zero indexed) to a.
  void update(int k, T a) {
    k += n-1;
    dat[k] = a;
    // Climbing up the tree
    while (k>0) {
      k = (k-1)/2;
      dat[k] = f(dat[k*2+1], dat[k*2+2]);
    }
  }

  // Find a minimum or maximum in [a,b).
  T query(const int a, const int b) {
    return query(a, b, 0, 0, n);
  }

};

