class xorshift {
public:
	int random() {
		return std::rand();
	}
};

template <class T>
class Treap {
	xorshift rnd;
	struct Node {
		T key;
		int priority;
		Node* l, * r;
		Node(T key, int priority) : key(key), priority(priority), l(nullptr), r(nullptr) {}
	} *root = nullptr;
	using Tree = Node *;

	void split(Tree t, T key, Tree& l, Tree& r) {
		if (!t) {
			l = r = nullptr;
		}
		else if (key < t->key) {
			split(t->l, key, l, t->l), r = t;
		}
		else {
			split(t->r, key, t->r, r), l = t;
		}
	}

	void merge(Tree& t, Tree l, Tree r) {
		if (!l || !r) {
			t = l ? l : r;
		}
		else if (l->priority > r->priority) {
			merge(l->r, l->r, r), t = l;
		}
		else {
			merge(r->l, l, r->l), t = r;
		}
	}

	void insert(Tree& t, Tree item) {
		if (!t) {
			t = item;
		}
		else if (item->priority > t->priority) {
			split(t, item->key, item->l, item->r), t = item;
		}
		else {
			insert(item->key < t->key ? t->l : t->r, item);
		}
	}

	void erase(Tree& t, T key) {
		if (t->key == key) {
			merge(t, t->l, t->r);
		}
		else {
			erase(key < t->key ? t->l : t->r, key);
		}
	}

	bool find(Tree& t, T key) {
		if (!t) {
			return false;
		}
		else if (t->key == key) {
			return true;
		}
		else {
			return find(key < t->key ? t->l : t->r, key);
		}
	}

	//keyより大きいもので一番小さいものを返す
	T upperBound(Tree& t, T key) {
		if (!t) {
			return numeric_limits<T>().max();
		}
		else if (t->key > key) {
			return std::min(upperBound(t->l, key), t->key);
		}
		else {
			return upperBound(t->r, key);
		}
	}

	//keyより小さいもので一番大きいものを返す。
	T lowerBound(Tree& t, T key) {
		if (!t) {
			return numeric_limits<T>().min();
		}
		else if (t->key < key) {
			return std::max(lowerBound(t->r, key), t->key);
		}
		else {
			return lowerBound(t->l, key);
		}
	}

public:
	void insert(T key) {
		insert(root, new Node(key, rnd.random()));
	}

	void erase(T key) {
		erase(root, key);
	}

	bool find(T key) {
		return find(root, key);
	}

	T upperBound(T key) {
		return upperBound(root, key);
	}

	T lowerBound(T key) {
		return lowerBound(root, key);
	}
};

