long long solve() {
  long long ans = 0;
  queue<p> qu;
  qu.push({0, n});
  while(qu.size() > 0) {
    p now = qu.front();
    qu.pop();
    p a = rmq.pick(now.fi, now.se);
    ans += (long long)(a.se - now.fi + 1) *
           (now.se - a.se) * a.fi;
    if(now.fi != a.se) qu.push({now.fi, a.se});
    if(a.se + 1 != now.se) qu.push({a.se + 1, now.se});
  }
  return ans;
}

