        active[x.se] = 1;
        uni(x.se, x.se + 1);
        uni(x.se, x.se - 1);
        int r = root(x.se);
        ll S = (x.se - L[r] + 1) * 1LL * (R[r] - x.se + 1);
        ans += x.fi * S;
    }
    cout << ans;
}

