        cin >> A[i];
        p[A[i]] = i;
    }


    set<int> s;
    for (int i = 1; i <= N; i++) {
        s.insert(p[i]);
    }

    long long int sum = 0;
    for (int i = N; i >= 1; i--) {
        int left, right;
        auto pos = s.find(p[i]);
        auto n_pos = retNextIterator(pos), p_pos = retPreviousIterator(pos);
        if (pos != s.begin()) left = *p_pos + 1;
        if (n_pos != s.end()) right = *n_pos - 1;
        if (pos == s.begin()) left = 0;
        if (n_pos == s.end()) right = N - 1;
        sum += (p[i] - left + 1) * (right - p[i] + 1) * i;
        //cout << left << ", " << right << endl;
        s.erase(p[i]);
    }
    cout << sum << endl;


    return 0;
}

