    long long s = 0;
    auto it = g.upper_bound(B[i]);
    if (it != g.end()) {
      int x = *it;
      s = (long long)(i+1) * (x-B[i]) + C[x];
    }
    else {
      s = (long long)(i+1) * (N-B[i]);
    }
    C[B[i]] = s;
    g.insert(B[i]);
  }
  long long s = 0;
  for (int i=0; i<N; i++) s += C[i];
  cout << s << "\n";
  return 0;
}

