int n;
ll a[N];
int b[N];
ll ans = 0;
int par[N], sz[N];
int l[N], r[N];

int getPar(int v)
{
	return (par[v] == -1 ? v : par[v] = getPar(par[v]));
}
bool unite(int v, int u)
{
	v = getPar(v);
	u = getPar(u);
	if (v == u) return false;
	if (sz[v] < sz[u]) swap(v, u);
	sz[v] += sz[u];
	par[u] = v;
	l[v] = min(l[v], l[u]);
	r[v] = max(r[v], r[u]);
	return true;
}

void on(int p)
{
	sz[p] = 1;
	if (p > 0 && sz[p - 1] > 0)
		unite(p - 1, p);
	if (p < n - 1 && sz[p + 1] > 0)
		unite(p, p + 1);
	int v = getPar(p);
	ans += a[p] * (r[v] - p + 1) * (p - l[v] + 1);
	return;
}

