void build(int tl,int tr,int p){
	if(tl==tr)
	{
		ST[p]=v[tl];
		return ;
	}
	int tm=(tl+tr)/2;
	build(tl,tm,2*p);
	build(tm+1,tr,2*p+1);
	ST[p]=min(ST[2*p],ST[2*p+1]);
}
int query(int tl,int tr,int l,int r,int p){
	if(tl>=l&&tr<=r)
		return ST[p];
	if(tr<l||tl>r)
		return 1000000000;
	int tm=(tl+tr)/2;
	return min(query(tl,tm,l,r,2*p),query(tm+1,tr,l,r,2*p+1));
}
