constexpr ll INF = 1000000000;/* 1e+9a */

ll f(int l, int r, const vector<ll>& a){
    // sum sum min a[l, r)
    if(r - l < 1) return 0;
    ll mi = INF; int mi_i = -1;
    for (int i = l; i < r; ++i) {
        if(mi > a[i]){
            mi = a[i]; mi_i = i;
        }
    } // end i
    ll L = mi_i - l; ll R = r - mi_i-1;
    ll ret = mi * (L + 1) * (R + 1);
    return ret + f(l, mi_i, a) + f(mi_i+1, r, a);

}

