int ni(vector<int> vec, int n, int m) {
	int mi = 0;
	int ma = n - 1;
	int mo;
	int l = 0;
	int r = n - 1;
	while (1) {
		mo = (mi + ma) / 2;
		if (vec.at(mo) < m) {
			l = mo;
			mi = mo;
		}
		else {
			r = mo;
			ma = mo;
		}
		if (l + 1 == r)return r;
	}
}

