	for (int i = 2; i <= n; i++) {
		int b = ta[i];
		if (b < vec.at(0))ans += i * (b + 1)*(vec.at(0) - b);
		else if (vec.at(i - 2) < b)ans += i * (b - vec.at(i - 2))*(n - b);
		else {
			int c = ni(vec, i - 1, b);
			ans += i * (vec.at(c) - b)*(b - vec.at(c - 1));
		}
		vec.push_back(b);
