const int maxn = 2e5+100;

int seg[maxn << 2], seg1[maxn << 2];

void upright(int i, int c = 1, int l = 0, int r = maxn) {
    if (i == l && l == r - 1) {
        seg[c] = i;

        return;
    } else if (l == r - 1) return;
    int le = c << 1;
    int ri = le ^ 1;
    if (l <= i && i < r) {
        int mid = (l + r) >> 1;

        upright(i, le, l, mid);
        upright(i, ri, mid, r);
    }

    seg[c] = std::min(seg[le], seg[ri]);
}

const int inf = 0x3f3f3f3f;
int getright(int ql, int qr, int c = 1, int l = 0, int r = maxn) {
    if (r <= l) return inf;
    if (ql <= l && r <= qr) {
        return seg[c];
    } else if (ql >= r || qr <= l) {
        return inf;
    } else {
        int le = c << 1;
        int ri = le ^ 1;
        int mid = (l + r) >> 1;

        return std::min(getright(ql, qr, le, l, mid), getright(ql, qr, ri, mid, r));
    }
}

void upleft(int i, int c = 1, int l = 0, int r = maxn) {
    if (i == l && l == r - 1) {
        seg1[c] = i;
        return;
    } else if (l == r - 1) return;
    int le = c << 1;
    int ri = le ^ 1;
    if (l <= i && i < r) {
        int mid = (l + r) >> 1;

        upleft(i, le, l, mid);
        upleft(i, ri, mid, r);
    }

    seg1[c] = std::max(seg1[le], seg1[ri]);
}

int getleft(int ql, int qr, int c = 1, int l = 0, int r = maxn) {
    //std::cout << "getleft" _ debug(ql) _ debug(qr) _ debug(c) _ debug(l) _ debug(r) << std::endl;
    if (r <= l) return -1;
    if (ql <= l && r <= qr) {
        //std::cout << debug(seg1[c]) << std::endl;
        return seg1[c];
    } else if (ql >= r || qr <= l) {
        return -1;
    } else {
        int le = c << 1;
        int ri = le ^ 1;
        int mid = (l + r) >> 1;

        return std::max(getleft(ql, qr, le, l, mid), getleft(ql, qr, ri, mid, r));
    }
}

