const int N = 2e5 + 5;
int a[N];
bool active[N];

int dsu[N], R[N], L[N];

int root(int u) {
    return ((u == dsu[u]) ? u : dsu[u] = root(dsu[u]));
}

void uni(int u, int v) {
    if(!active[u] || !active[v]) return;
    u = root(u), v = root(v);
    if(u == v) return;
    dsu[u] = v;
    L[v] = min(L[v], L[u]);
    R[v] = max(R[v], R[u]);
}

void solve() {
	int n;
    sc(n);
    vector<pii> v;
    fr(i, 1, n) {
        dsu[i] = i;
        R[i] = i;
        L[i] = i;
        sc(a[i]);
        v.pb({a[i], i});
    }
    sort(all(v));
    reverse(all(v));
    ll ans = 0;
    for(auto x : v) {
        active[x.se] = 1;
        uni(x.se, x.se + 1);
        uni(x.se, x.se - 1);
        int r = root(x.se);
        ll S = (x.se - L[r] + 1) * 1LL * (R[r] - x.se + 1);
        ans += x.fi * S;
    }
    cout << ans;
}

