//引数：区間[l, r)
//ヒント引数：[l, r)の最小値はid以上
//返り値：[l, r)内でのmin総和
int dfs(int l, int r, int id) {
	if (l >= r || r > n) return 0;

	//[l, r)に含まれる値のうち、最小のものを探す
	while (id <= n) {
		if (l <= pos[id] && pos[id] < r) break;
		id++;
	}

	//値idの左側, 右側で分割する。最小値がidの区間は…(左側長 + 1) * (右側長 + 1)個
	int plus = id * (pos[id] - l + 1) * (r - pos[id]);
	return plus + dfs(l, pos[id], id) + dfs(pos[id] + 1, r, id);
}

