	vector<ll> NEXT(N+1, -1);  // NEXT[i] = iよりも大きい方から降ってきた自分より大きいものの、最大のインデックス-1
	vector<ll> PREV(N+1, -1);  // PREV[i] = iよりも小さい方から降ってきた自分より大きいものの、最小のインデックス+1

	FOR(i, N) {
		POS[A[i]] = i; // A[i] の位置はi 
