	//}

	FOR(_i, N) {
		auto i = N - 1 - _i;
		auto ip1 = N - _i;
		auto indx = POS[ip1];  

		auto up = NEXT[indx] - indx;
		auto down = indx - PREV[indx];
		//ans += ip1 * (NEXT[indx] - indx) * (indx - PREV[indx]); // 初期状態だと、これはどちらも1になる。
		auto amount = ip1 * up * down;
		ans += amount;


		if ( NEXT[indx] < N)
			PREV[NEXT[indx]] = PREV[indx];
		if (PREV[ indx ] >= 0)
			//NEXT[indx - 1] = NEXT[indx];
			NEXT[PREV[indx]] = NEXT[indx];

			//PREV[indx + 1] = PREV[indx];
	}


	cout << ans << endl;


	return 0;
}

