int int_less(const void *a, const void *b) {
  return (*((const int*)a) - *((const int*)b));
}
int int_greater(const void *a, const void *b) {
  return (*((const int*)b) - *((const int*)a));
}

int main() {
    int n = ri();
	int a[n];
	INPUT(a);
	s64 res = 0;

	int pos[n];
	FOR(i,n) pos[a[i]-1] = i;

	set<int> poss = { pos[0] };
	res += ((s64)(pos[0]+1))*(n-pos[0]);
	UPTO(i,1,n-1) {
		auto position = poss.lower_bound(pos[i]);
		if (position == poss.end()) {
			auto low = position;
			low--;
			res += (i+1)*((s64)(pos[i]-*low))*(n-pos[i]);
		} else if (position == poss.begin()) {
			res += (i+1)*((s64)(pos[i]+1))*(*position-pos[i]);
		} else {
			auto low = position;
			low--;
			res += (i+1)*((s64)(pos[i]-*low))*(*position-pos[i]);
		}
		poss.insert(pos[i]);
	}

	cout << res << endl;

    return 0;
}

