        if(I[i]>=l && I[i]<=r){
            mi=I[i];
            min=i;
            break;
        }
    }
    return min*(mi-l+1)*(r-mi+1)+(mi>l?sum(l,mi-1,d+1):0)+(r>mi?sum(mi+1,r,d+1):0);
}
