namespace UnionTree {
	template <typename T>
	int root(vector<T> &u, int x) {
		if(x < 0 || u.size() <= x) return -1;
		if(u[x].parent == -1) return x;
		else return u[x].parent = root(u, u[x].parent);
	}
	template <typename T>
	bool connect(vector<T> &u, int a, int b) {
		a = root(u, a), b = root(u, b);
		if(a == b || a < 0 || b < 0) return false;
		u[b].parent = a;
        u[a].l = u[b].l = min(u[a].l, u[b].l);
        u[a].r = u[b].r = max(u[a].r, u[b].r);
		return true;
	}
}; // namespace UnionTree

