    int ans=0;
    for(int i=n-1; i>=0; i--){
        int pl=b.at(i);
        int s=0,t=0;
        if(pl>0)if(a.at(pl-1)>i+1){
            s=uni.size(pl-1);
            uni.unite(pl,pl-1);
        }
        if(pl<n-1)if(a.at(pl+1)>i+1){
            t=uni.size(pl+1);
            uni.unite(pl,pl+1);
        }
        ans+=(i+1)*(s+1)*(t+1);
    }
