LL ans=0;
int a[N],mi[N];
void solve (int l,int r)
{
	if (l==r) return ans+=a[l],void ();
	int mid=(l+r)>>1;
	mi[mid+1]=a[mid+1];
	for (int i=mid+2; i<=r; i++)
		mi[i]=min (mi[i-1],a[i]);
	mi[mid]=a[mid];
	for (int i=mid-1; i>=l; i--)
