		ans+=(LL)mi[i]*(mid-j+1);
	}
	for (int i=mid,j=mid; i>=l; i--)
	{
		while (j< r&&mi[i]< mi[j+1]) ++j;
		ans+=(LL)mi[i]*(j-mid);
	}
	solve (l,mid),solve (mid+1,r);
}
