#include <bits/stdc++.h>
using namespace std;

int segTree[1000000];
int segSize;

void init(int n){
  segSize = 1;
  while(segSize < n) segSize *= 2;

  for(int i = 0;i < segSize;i++){
    segTree[segSize-1+i] = INT_MAX;
  }

  for(int i = segSize-2;i >= 0;i--){
    segTree[i] = min(segTree[i*2+1],segTree[i*2+2]);
  }
  return;
}

void update(int i, int val){
  i = segSize-1+i;
  segTree[i] = val;

  while(i > 0){
    i = (i - 1) / 2;
    segTree[i] = min(segTree[i*2+1], segTree[i*2+2]);
  }

  return;
}

int getmin(int a, int b, int k = 0, int l = 0, int r = segSize){

  if(r <= a || b <= l) return INT_MAX;
  if(a <= l && r <= b) return segTree[k];

  int vl = getmin(a,b,2*k+1,l,(l+r)/2);
  int vr = getmin(a,b,2*k+2,(l+r)/2,r);
  return min(vl, vr);
}

int main(){
    long long n;
    cin >> n;
    init(n+1);

    int a[200010];
    long long mas[200010];
    for(int i = 0;i < n;i++){
        cin >> a[i];
        mas[a[i]] = i;
    }

    long long ans[200010] = {};

    long long mimi[200010];

    for(int i = 1;i <= n;i++){
        int mi;
        if((mi = getmin(mas[i], n+1)) == INT_MAX){
            mimi[i] = -1;
        }else{
            mimi[i] = mi;
        }
        update(mas[i], mas[i]);
    }

    long long all = 0;
    for(int i = n-1;i >= 0;i--){
        if(mimi[a[i]] == -1){
            ans[i] = (n-i)*a[i];
        }else{
            ans[i] = (mimi[a[i]]-i)*a[i] + ans[mimi[a[i]]];
        }
        all += ans[i];
    }

    cout << all << endl;

    return 0;
}

