const int INF = 1e7;

int n,a[N],b[N],tree[N * 4];
ll ans;

int init(int ind,int l,int r) {
  if (l == r)
     return tree[ind] = a[l];
  int mid = (l + r) / 2;
  return tree[ind] = min(init(ind + ind,l,mid),init(ind + ind + 1,mid + 1,r));
}

int query(int ind,int l,int r,int lw,int rw) {
  if (l > rw || r < lw)
    return INF;
  if (l >= lw && r <= rw)
    return tree[ind];
  int mid = (l + r) / 2;
  return min(query(ind + ind,l,mid,lw,rw),query(ind + ind + 1,mid + 1,r,lw,rw));
}

void solve(int l,int r) {
  if (l > r)
    return;
  int mn = b[query(1,1,n,l,r)];
  ans += (ll) a[mn] * (mn - l + 1) * (r - mn + 1);
  solve(l,mn - 1);
  solve(mn + 1,r);
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);

  cin >> n;
  for (int i = 1 ; i <= n ; i++) {
    cin >> a[i];
    b[a[i]] = i;
  }

  init(1,1,n);

  solve(1,n);

  cout << ans << endl;

}

