template<typename T = long long>
class SegmentTree {
public:
    std::vector<T> ary;
    int n;
    const T default_value = std::numeric_limits<T>::max() / 4;
    SegmentTree(int n) {
        this->n = 1;
        while (this->n < n) this->n *= 2;
        ary.resize(this->n * 2 - 1, 1<<30);
    }
    T ope(T l, T r) {
        return std::min(l, r);
    }
    void update(int k, T d) {
        k += n - 1;
        ary[k] = d;
        while (k > 0) {
            k = (k - 1) / 2;
            ary[k] = ope(ary[2 * k + 1], ary[2 * k + 2]);
        }
    }
    T query(int a, int b) {
        return query(a, b, 0, n, 0);
    }
    T query(int a, int b, int l, int r, int i) {
        if (a <= l && b >= r) return ary[i];
        if (a >= r || b <= l) return default_value; // min
        int m = (l + r) / 2;
        T vl = query(a, b, l, m, 2 * i + 1);
        T vr = query(a, b, m, r, 2 * i + 2);
        return ope(vl, vr);
    }
};

void solve() {
    int n;
    cin >> n;
    VLL a(n);
    REP(i,0,n) cin >> a[i];
    SegmentTree<> seg(n);
    REP(i,0,n) seg.update(i,a[i]);
    LL ans = 0;
    REP(i,0,n) {
        int l, r;
        {
            int ok = i, ng = -1;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (seg.query(mid,i+1) == a[i]) ok = mid;
                else ng = mid;
            }
            l = abs(i - ok) + 1;
        }
        {
            int ok = i, ng = n;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (seg.query(i,mid+1) == a[i]) ok = mid;
                else ng = mid;
            }
            r = abs(i - ok) + 1;
        }
        ans += a[i] * (1LL * l * r);
    }
    cout << ans << endl;
}

signed main() {
    solve();

    return 0;
}

