i32 n, len, a[200000];
i32 seg[400001];

void update(i32 i, i32 x) {
    i32 k = len+i;
    seg[k] = x;
    k /= 2;
    while (k > 0) {
        seg[k] = min(seg[2*k], seg[2*k+1]);
        k /= 2;
    }
}

i32 size(i32 i) {
    return len / pow(2, floor(log2(i)));
}

i32 query(i32 l, i32 r) {
    l += len;
    r += len;
    i32 ret = INT_MAX;
    i32 i = l;
    while(i <= r) {
        i32 k = i;
        while (even(k) and i+size(k/2) <= r) {
            k = k/2;
        }
        ret = min(ret, seg[k]);
        i += size(k);
    }
    return ret;
}

i32 main()
{
