    if (n > 1000) return 0;

    times(n, i) {
        cin >> a[i];
    }
    len = pow(2, ceil(log2(n)));
    upto(n, len - 1, i) {
        a[i] = a[n-1];
    }

    times(len*2, i) {
        seg[i] = INT_MAX;
    }
    times(len, i) {
        update(i, a[i]);
    }

    i64 ans = 0;
    downto(n-1, 0, i) {
        range(i, n, j) {
            ans += query(i, j);
        }
    }
    cout << ans << endl;
    return 0;
}

