template <typename T>
class segment_base{
	int N;//要素数
	vector< T > dat1;
	T VAL_E;//初期値
public:
	segment_base(){};
	segment_base(int n,T val_E ):N(n),VAL_E(val_E){
		dat1.resize(2*n);
		dat1.assign(2*n,val_E);//初期化
	}
	void init(int n,T val_E){
		N = n;
		VAL_E = val_E;
		dat1.resize(2*n);
		dat1.asigne(2*n,val_E);
	}
	T SELECT(T L,T R){//扱う演算子
		T ans;
		ans = min(L,R);//
		return ans;
	}

	//index番目の値をvalに変更,indexは"0-index"
	void update(int index,T val){
		for(dat1[index+=N] = val;index>1;index>>=1){
			dat1[index>>1] = SELECT(dat1[index],dat1[index^1]);//index+0,+1
		}
	}

	//区間[L,R)のSELECT
	T query(int L,int R){
		T ans = VAL_E;//
		for(L+=N,R+=N; L<R;L>>=1,R>>=1){
			if(L&1) ans = SELECT(ans,dat1[L++]);
			if(R&1) ans = SELECT(ans,dat1[--R]);
		}
		return ans;
	}
};
//////////////////

vector<int> B(200001);
//[L,R)
LL dfs(LL L,LL R,segment_base<int>& seg){
	LL val = seg.query(L,R);
	LL index = B[val];
	if( R-L == 1 ){
		return val;
	}

	LL ans = 0;
	ans = (index-L+1) * (R-index) * val;
	LL res;
	if( L < index){
		res = dfs(L,index,seg);
		ans += res;
	}
	if( index+1 < R ){
		res = dfs(index+1,R,seg);
		ans += res;
	}

	return ans;
}
void solve(){
	int N;
	cin >> N;
	segment_base<int> seg(N,INF);
	//seg.init(N,INF);
	for(int i=0;i<N;++i){
		int temp;
		cin >> temp;
		seg.update(i,temp);
		B[temp] = i;
	}
	LL ans = dfs(0,N,seg);//[0,N)
	cout << ans << endl;
}

