int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(NULL);
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < n; i++) t[i][0] = a[i];
	for(int j = 1; j <= k; j++){
		for(int i = 0; i <= n - (1<<j); i++){
			t[i][j] = min(t[i][j-1], t[i+(1<<(j-1))][j-1]);
		}
	}
	ll res = 0;
	for(int i = 0; i < n; i++){
		ll ans = ZERO;
		int l = i;
		int r = l;
		while(1){
			if(r == n) break;
			for(int j = k; j >= 0; j--){
				if(l + (1<<j) - 1 <= r){
					ans = min(ans, t[l][j]);
					l += 1<<j;
				}
			}
			res+=ans;
			r++;
		}
	}
	cout << res;
}

