void build(ll v = 1, ll tl = 1, ll tr = n) {

    if(tl == tr) {t1[v] = -1; t2[v] = INF;return;}

    ll tm = (tl + tr) >> 1;

    build(v + v, tl, tm);
    build(v + v + 1, tm + 1, tr);

    t1[v] = max(t1[v + v], t1[v + v + 1]);
    t2[v] = min(t2[v + v], t2[v + v + 1]);

