void update(ll pos, ll v = 1, ll tl = 1, ll tr = n) {

    if(tl == tr) {t1[v] = t2[v] = pos * 1ll;return;}

    int tm = (tl + tr) >> 1;

    if(pos <= tm) update(pos, v + v, tl, tm);
    else update(pos, v + v + 1, tm + 1, tr);

    t1[v] = max(t1[v + v], t1[v + v + 1]);
    t2[v] = min(t2[v + v], t2[v + v + 1]);

}

ll get(ll l, ll r, bool type, ll v = 1, ll tl = 1, ll tr = n) {

    if(r < tl || tr < l) return (type == 0) * -1ll + (type == 1) * INF * 1ll;

    if(l <= tl && tr <= r) {

        if(!type) {return t1[v];}
        else {return t2[v];}

    }

    ll tm = (tl + tr) >> 1;

    if(!type) return max( get(l, r, type, v + v, tl, tm), get(l, r, type, v + v + 1, tm + 1, tr) );
    else return min( get(l, r, type, v + v, tl, tm), get(l, r, type, v + v + 1, tm + 1, tr) );

