	if(l==r){ans+=a[l];return;}
	int mid=l+r>>1,tmp=1e9,i,j;
	Red(i,mid,l)tmp=min(tmp,a[i]),b[i]=tmp;tmp=1e9;
	Rep(i,mid+1,r)tmp=min(tmp,a[i]),b[i]=tmp;
	for(i=mid,j=mid+1;l<=i&&j<=r;){
		if(b[i]>b[j])ans+=1ll*b[i]*(j-mid-1),i--;
		else ans+=1ll*b[j]*(mid-i),j++;
	}for(;i>=l;i--)ans+=1ll*b[i]*(r-mid);for(;j<=r;j++)ans+=1ll*b[j]*(mid-l+1);
	Solve(l,mid),Solve(mid+1,r);
}
