void update(int i, int x ){
	//葉のノード番号
	i += n-1;
	dat[i] = x;
	//登りながら更新
	while(i>0){
		i = (i-1)/2;
		dat[i] = min(dat[i*2+1] , dat[i*2 + 2]);
	}
}

int query(int a , int b , int k , int l , int r ){
	if(r <= a || b <= l ) return INF;
	else if(a <= l && r <= b ) return dat[k];
	else{
		ll vl = query(a,b,k*2+1,l,(l+r)/2);
		ll vr = query(a,b,k*2+2,(l+r)/2,r);
		return min(vl,vr);
	}
}

