                itr--;
                l=*itr+1;
            }
            else if(itr==begin(s)) {
                r=*itr-1;
                l=0;
            }
            else {
                r=*itr-1;
                itr--;
                l=*itr+1;
            }
            ans+=(j-l+1)*(r-j+1)*a[j];
        }
        s.insert(j);
    }
    cout<<ans<<endl;
    return 0;
}

