ll f(ll p, ll q) {
	ll u =2e9;
	while (p < q) {
		if (p % 2 == 1) u = min(u, d[p++]);
		if (q % 2 == 0) u = min(u, d[q--]);
		p /= 2;
		q /= 2;
	}
	if (p == q) u = min(u, d[p]);
	return u;
}
