// 0, [1], 2, 3, 4, 5
// size = 6, pos = 1
long partial(long size, long pos) {
  long ret = 0;
  for (long s = 1; s <= size; s++) {
    long current_left = max(0l, pos - s + 1);
    long current_right = min(size - 1, pos + s - 1);
    long n = current_right - current_left + 1 - s + 1;
    if (n <= 0) continue;
    ret += n;
  }
  // cout << "size: " << size << ", pos: " << pos << ", ret: " << ret << endl;
  return ret;
}

void solve() {
  long N;
  cin >> N;
  vector<long> a(N);
  rep (i, N) cin >> a[i];

  vector<pair<long, long>> foo;
  rep (i, N) foo.push_back(make_pair(a[i], i));
  sort(foo.begin(), foo.end());

  long ret = 0;

  set<long> already;
  for (auto it: foo) {
    auto ub = upper_bound(already.begin(), already.end(), it.second);
    long end = (ub == already.end()) ? a.size() : *ub;
    long start = -1;
    if (ub != already.begin()) {
      auto tmp = ub;
      tmp--;
      start = (*tmp);
    }
    already.insert(it.second);
    // cout << "---- it: " << it.first << "," << it.second << ", start: " << start << ", end: " << end << endl;
    ret += partial(end - start - 1, it.second - start - 1) * it.first;
  }

  cout << ret << endl;
}

