class segTree{
public:


	struct Node{
	int minIndex;
	int leftIndex;
	int rightIndex;
	struct Node* left;
	struct Node* right;		
	};
	struct Node* head;
	segTree(){
		head=NULL;
	}
	void Construct(int l,int r,int a[]){
		Construct(l,r,head,a);
	}
	void Construct(int l,int r,Node* &head,int a[]){
		if(l!=r){
			head=new Node;
			head->leftIndex=l;
			head->rightIndex=r;
			head->left=NULL;
			head->right=NULL;
			Construct(l,(l+r)/2,head->left,a);
			Construct(1+((l+r)/2),r,head->right,a);
			if(a[head->left->minIndex]>a[head->right->minIndex]) head->minIndex=head->right->minIndex;
			else head->minIndex=head->left->minIndex;
		}
		else{
			head=new Node;
			head->left=NULL;
			head->right=NULL;
			head->leftIndex=l;
			head->rightIndex=r;
			head->minIndex=l;
		}
	}
	int answer(int l,int r, int a[]){
		return answer(l,r,head,a);
	}
	int answer(int l,int r,Node* &head,int a[]){
		if(l==r) return l;
		if(head->leftIndex==l && head->rightIndex==r) return head->minIndex;
		if(l>head->left->rightIndex) return answer(l,r,head->right,a);
		if(r<head->right->leftIndex) return answer(l,r,head->left,a);
		int x=answer(l,head->left->rightIndex,head->left,a);
		int y=answer(head->right->leftIndex,r,head->right,a);
		if(a[x]>a[y]) return y;
		return x; 
	}
	void Update(int index,int *a){
		Update(index,a, head);
	}
	void Update(int index,int* a,Node* &head){
		if(head->leftIndex==index && head->rightIndex==index){
			return;
		}
		if(index<=head->left->rightIndex){
			Update(index,a,head->left);
		}
		else{
			Update(index,a,head->right);
		}
if(a[head->left->minIndex]>a[head->right->minIndex]) head->minIndex=head->right->minIndex;
else head->minIndex=head->left->minIndex;
	}
};
int main(){
	int n;
	cin>>n;
	segTree tree;
	int a[n];
	rep(i,n) cin>>a[i];
	tree.Construct(0,n-1,a);
	ll ans=0;
	rep(i,n){
		rep(j,n){

			if(i<=j) ans+=a[tree.answer(i,j,a)];


		}
	}
	cout<<ans;
}

