// Range Mininum Query
template<typename T>
class SegmentTree {
private:
    int n;
    T dat[2000100];
public:
    SegmentTree(int n_) {
	n = 1;
	while (n < n_) n *= 2;
	for (int i = 0; i < 2*n-1; i++) dat[i] = INT_MAX;
    }

    void update(int k, T a) {
	k += n - 1;
	dat[k] = a;
	while (k > 0) {
	    k = (k - 1) / 2;
	    dat[k] = min(dat[k*2+1], dat[k*2+2]);
	}
    }

    // call query(a, b)
    // return min value for [a, b)
    T query(int a, int b) { return query(a, b, 0, 0, n); }
    T query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l) return INT_MAX;

	if (a <= l && r <= b) return dat[k];
	else {
	    T vl = query(a, b, k*2+1, l, (l+r)/2);
	    T vr = query(a, b, k*2+2, (l+r)/2, r);
	    return min(vl, vr);
	}
    }
};

int idx[200010];
SegmentTree<ll> st(200010);

ll calc(int l, int r) {
    if (l >= r) return 0;
    ll v = st.query(l, r);
    int i = idx[v];
    return (v+1) * (i - l + 1) * (r - i) + calc(l, i) + calc(i+1, r);
}

ll solve() {
    for (int i = 0; i < n; i++) {
        idx[a[i]] = i;
        st.update(i, a[i]);
    }
    return calc(0, n);
}

