ll a[1000000];
ll lookup[1000000][25];
void preprocess(ll n)
{
	for (ll i = 0; i < n; i++)
		lookup[i][0] = i;

	for (ll j=1; (1<<j)<=n; j++)
	{
		for (ll i=0; (i+(1<<j)-1) < n; i++)
		{ 
			if (a[lookup[i][j-1]] < a[lookup[i + (1<<(j-1))][j-1]])
				lookup[i][j] = lookup[i][j-1];
			else
				lookup[i][j] = lookup[i + (1 << (j-1))][j-1];      
		}
	}
}
ll query(ll L, ll R)
{
	ll j = (ll)log2(R-L+1);
	if (a[lookup[L][j]] <= a[lookup[R-(ll)pow(2,j)+1][j]])
		return lookup[L][j];

   else return lookup[R-(ll)pow(2,j)+1][j];
}
ll solve(ll i ,ll j){
	if (i>j)return 0;
	if (i==j)return a[i];
	ll d = query(i,j);
	return a[d]*(d-i+1)*(j-d+1)+solve(i, d-1)+solve(d+1, j);
}
