int getsum( int x )
{
    int sum = 0;
    while( x > 0 )
    {
        sum += c[x];
        x -= lowbit(x);
    }
    return sum;
}

int getl( int step )
{
    int l = 0, r = step - 1, mid;
    int sm = getsum(step);
    while(l <= r)
    {
        mid = (l + r)/2;
        if( sm - getsum(mid) == 1)
            r = mid - 1;
        else
            l = mid + 1;
    }
    return l + 1;
}

int getr( int step )
{
    int l = step, r = STEP, mid;
    int sm = getsum(step);
    while(l <= r)
    {
        mid = (l + r)/2;
        if(getsum(mid) - sm == 0)
            l = mid + 1;
        else
            r = mid - 1;
    }
    return l - 1;
}



