		else{
			return par[x] = root(par[x]);
		}
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);

		if(x==y)return;
		else{
			par[x] = y;
			size[y] += size[x];
			size[x] = 0;
		}
	}
};

int main(){
