		ll r = 0,l = 0;
		if(j>0)if(didj[j-1])l = uf.size[uf.root(j-1)];
		if(j<n)if(didj[j+1])r = uf.size[uf.root(j+1)];
		if(j>0)if(didj[j-1])uf.unite(j,j-1);
		if(j<n)if(didj[j+1])uf.unite(j,j+1);
		ans += a[j]*1LL*(r+1)*(l+1);
	}
