      if(hd > tl) return 0;
      int mindex = get_mindex_between(hd, tl);
      lli include_m = (lli)(mindex - hd + 1) * (lli)(tl - mindex + 1);
      return calculate(hd, mindex-1) + calculate(mindex+1, tl) + include_m * A.at(mindex);
    }
    lli solve(void){return calculate(0, n-1);}
};

