typedef long long ll;

ll t[888888];
ll n;
vector<ll> a;

void build (ll v, ll tl, ll tr) {
    if (tl == tr) {
        t[v] = a[tl];
        return;
    }

    ll tm = (tl + tr) / 2;
    build(v * 2, tl, tm);
    build(v * 2 + 1, tm + 1, tr);

    t[v] = min(t[v * 2], t[v * 2 + 1]);
}

ll getMin(ll v, ll tl, ll tr, ll l, ll r) {
    if (l > r)
        return INT_MAX;

    if (tl == l && tr == r) {
        return t[v];
    }

    ll tm = (tl + tr) / 2;

    ll ans1 = INT_MAX, ans2 = INT_MAX;
    if (l <= min(r, tm))
        ans1 = getMin(v * 2, tl, tm, l, min(r, tm));
    if (max(l, tm + 1) <= r)
        ans2 = getMin(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);

    return min(ans1, ans2);
}

ll find_min_pos (ll x, ll pos) {
    ll l = pos, r = n + 1;
    while (r - l > 1) {
        ll m = (l + r) / 2;
        ll mn = getMin(1, 1, n, pos, m);
        if (mn >= x) {
            l = m;
        }
        else {
            r = m;
        }
    }

    return l + 1;
}


