vector <int> L(vector <int> P) {
	int N = P.size();
	vector <int> stk;
	vector <int> left(N);
	for(int i = 0; i < N; i++) {
		while(!stk.empty() && P[stk.back()] > P[i]) {
			stk.pop_back();
		}
		left[i] = i + 1 - (stk.empty() ? 0 : stk.back() + 1);
		stk.push_back(i);
	}
	return left;
}
int main() {fio;
