int n,i,v[400010],x[200010],ap[200010];
long long sol;
void build()
{
    for(i=n-1; i>=1; --i)
        v[i]=min(v[i*2],v[i*2+1]);
}
void answer(int l,int r)
{
    int L=l+n-1;
    int R=r+n;
    int ans=200010;
    while(L<R)
    {
        if(L%2==1)ans=min(ans,v[L++]);
        if(R%2==1)ans=min(ans,v[--R]);
        L/=2;
        R/=2;
    }
    int poz=ap[ans];
    sol+=1LL*ans*(poz-l+1)*(r-poz+1);
    if(poz!=1&&l<=poz-1)answer(l,poz-1);
    if(poz!=n&&poz+1<=r)answer(poz+1,r);
}
