struct BIT {
    vector<int> dat;
    int n;

    BIT(int n, int init) :n(n) { dat.assign(n + 1, init); }
    void init(int n, int init) { n = n; dat.assign(n + 1, init); }

    //[1, i]
    int max(int i) {
        int m = -1;
        while (i > 0) {
            chmax(m, dat[i]);
            i -= i & -i;
        }
        return m;
    }

    void change(int i, int x) {
        while (i <= n) {
            chmax(dat[i], x);
            i += i & -i;
        }
    }
};
