const ll N = 2e5 + 4;
ll mn[4 * N] , mx[4 * N];
void upd1(ll v , ll l , ll r , ll i , ll x) {
    if(l + 1 == r) {
        mx[v] = x;
        return;
    }
    ll m = (r + l) / 2;
    if(m > i) {
        upd1(2 * v + 1 , l , m , i , x);
    } else {
        upd1(2 * v + 2 , m , r , i , x);
    }
    mx[v] = max(mx[2 * v + 1] , mx[2 * v + 2]);
}
void upd2(ll v , ll l , ll r , ll i , ll x) {
    if(l + 1 == r) {
        mn[v] = x;
        return;
    }
    ll m = (r + l) / 2;
    if(m > i) {
        upd2(2 * v + 1 , l , m , i , x);
    } else {
        upd2(2 * v + 2 , m , r , i , x);
    }
    mn[v] = min(mn[2 * v + 1] , mn[2 * v + 2]);
}
ll gmx(ll v , ll l , ll r , ll L , ll R) {
    if(l >= L && r <= R) {
        return mx[v];
    }
    if(l >= R || r <= L) {
        return 0;
    }
    ll m = (r + l) / 2;
    return max(gmx(2 * v + 1 , l , m , L , R) , gmx(2 * v + 2 , m , r , L , R));
}
ll gmn(ll v , ll l , ll r , ll L , ll R) {
    if(l >= L && r <= R) {
        return mn[v];
    }
    if(l >= R || r <= L) {
        return 1e9;
    }
    ll m = (r + l) / 2;
    return min(gmn(2 * v + 1 , l , m , L , R) , gmn(2 * v + 2 , m , r , L , R));
}
