typedef long long ll;

ll N,dat[2000000];
void init(ll n_) {
	N = 1;
	while (N < n_)N *= 2;
	for (ll i = 0; i < 2 * N - 1; i++)dat[i] = LLONG_MAX;
}
void update(ll k, ll a) {
	k += N - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}
ll query(ll a, ll b, ll k, ll l, ll r) {
	if (r <= a || b <= l)return LLONG_MAX;
	if (a <= l && r <= b)return dat[k];
	else {
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}
int main() {
	ll n; scanf("%lld", &n);
	init(n);
	rep(i, n) {
		ll a; scanf("%lld", &a);
		update(i, a);
	}
	ll sum = 0;
	for (int r = 0; r < n; r++) {
		for (int l = r; l < n; l++) {
			sum += query(r, l+1, 0, 0, N);
		}
	}
	printf("%lld\n", sum);
}

