const ll INF = 1e17 - 1;
int N;
pair<ll, int> bit[20000000];
void update(int i, ll x) {
  i += N - 1;
  bit[i] = { x,i - N + 1 };
  while (i > 0) {
    i = (i - 1) / 2;
    bit[i] = min(bit[i * 2 + 1], bit[i * 2 + 2]);
  }
}
pair<ll, int> Min(int a, int b, int k, int l, int r) {
  if (r <= a || b <= l)return{ INF,-1 };
  if (a <= l && r <= b)return bit[k];

  auto vl = Min(a, b, k * 2 + 1, l, (l + r) / 2);
  auto vr = Min(a, b, k * 2 + 2, (l + r) / 2, r);
  return min(vl, vr);
}
void Calc() {
  ll ans = 0;
  std::queue<pair<int, int>> q;
  int n = in;
  auto a = in.Array(n);
  int aa = 1;
  int tmp = n;
  while (tmp) {
    aa *= 2;
    tmp /= 2;
  }
  N = aa;
  err(N);
  rep(i, 2 * N - 1) {
    bit[i] = { INF,-1 };
  }
  rep(i, n) {
    update(i, a[i]);
  }

  q.push({ 0, n });
  while (q.size()) {
    auto p = q.front(); q.pop();
    if (p.first < 0)continue;
    if (p.second > n)continue;
    auto mini = Min(p.first, p.second, 0, 0, N);
    if (mini.second == -1)continue;
    ll d = mini.first * ((mini.second - p.first + 1) * (p.second - mini.second) - 1);
    d += mini.first;
    ans += d;
    err(ans, d, mini, p);
    q.push({ mini.second + 1, p.second });
    q.push({ p.first , mini.second });
  }
  cout << (ans) << endl;
}

