const int MOD = 1000000007;

const int MAX = 2e5+10;

ll fac[MAX];  /// fac[n] = n!
ll finv[MAX]; /// (fac[n] * finv[n]) % MOD = 1
ll inv[MAX];  /// (n * inv[n]) % MOD = 1

void init() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  FOR (i, 2, MAX) {
    fac[i] = fac[i-1]*i % MOD;
    inv[i] = MOD - inv[MOD%i]*(MOD/i) % MOD;
    finv[i] = finv[i-1]*inv[i] % MOD;
  }
}

ll nCk (int n, int k) {
  if (n < k || k < 0 || n < 0) return 0;
  return fac[n]*finv[k]%MOD*finv[n-k]%MOD;
}

ll nHk (int n, int k) {
  return nCk(n-1+k, n-1);
}

int N;
ll B[MAX];

int main() {

  init();

  cin >> N;
  REP (i, N) {
    int a;
    cin >> a;
    B[a-1] = i+1;
  }

  set<int> right, left;
  left.insert(0);
  right.insert(N+1);

  ll ans = 0;
  REP (i, N) {
    int k = B[i];
    int l = *(prev(left.lower_bound(k),1));
    int r = *right.upper_bound(k)-1;
    ans += (i+1)*(nHk(r-l, 2) - nHk(k-l-1, 2) - nHk(r-k, 2));
    right.insert(k);
    left.insert(k);
  }

  cout << ans << endl;
  return 0;

}

