namespace SGT {
	int v[N*4], ql, qr, qv;
	void _init( int o, int L, int R ) {
		if( L == R ) {
			v[o] = L;
		} else {
			int M = (L+R)/2, lc = o<<1, rc = lc|1;
			_init(lc, L, M), _init(rc, M+1, R);
			v[o] = a[v[lc]] < a[v[rc]] ? v[lc] : v[rc];
		}
	}
	void init() {
		_init(1, 1, n);
	}
	void _query( int o, int L, int R ) {
		if( L >= ql && R <= qr ) {
			if( !qv || a[v[o]] < a[qv] )
				qv = v[o];
		} else {
			int M = (L+R)/2, lc = o<<1, rc = lc|1;
			if( ql <= M ) _query(lc, L, M);
			if( qr > M ) _query(rc, M+1, R);
		}
	}
	int query( int l, int r ) {
		ql = l, qr = r, qv = 0;
		_query(1, 1, n);
		return qv;
	}
}

void solve( int L, int R ) {
	if( L > R ) return;
	int M = SGT::query(L, R);
	ans += 1LL * (M-L+1) * (R-M+1) * a[M];
	solve(L, M-1), solve(M+1, R);
}

