// union by size + path having
class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);  // resize だとなぜか初期化されなかった
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};



main(){
  ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  cout << fixed << setprecision(10);
  /*--------------------------------*/

  int n;cin>>n;
  vector<int> p(n);
  for(int i=0;i<n;i++){cin>>p[i];}
  vector<pair<int,int> >vec(n);
  for(int i=0;i<n;i++){
      vec[i].first=p[i];vec[i].second=i;
  }
  sort(vec.begin(),vec.end());
  reverse(vec.begin(),vec.end());
  UnionFind tree(n);
  vector<int> flag(n);
  ll ans=0;
  for(int i=0;i<n;i++){      
      ll name=vec[i].second,value=vec[i].first;
      //cout<<name<<" "<<value<<endl;
      flag[name]=1;
      ll part=1;
      if(name!=0 && flag[name-1]==1){part*=tree.size(name-1)+1;tree.merge(name,name-1);}
      if(name!=n-1 && flag[name+1]==1){part*=tree.size(name+1)+1;tree.merge(name,name+1);}
      //cout<<value<<" "<<part<<endl;
      ans+=part*value;
  }
  cout<<ans<<endl;
}

