class element {
public:
  i64 index, value;
  element(const i64 index, const i64 value) :
    index(index), value(value) {
  }
};

class range {
public:
  i64 begin_included, end_included;
  range(const i64 begin_included, const i64 end_included) :
    begin_included(begin_included), end_included(end_included) {
  }
  bool operator<(const range& other) const {
    return this->end_included < other.end_included;
  }
};

namespace std {
  std::ostream& operator<<(std::ostream& os, const range& self) {
    return os << '[' << self.begin_included << ", " << self.end_included << ']';
  }
}

int main() {
  i64 N;
  std::cin >> N;
  std::vector<i64> a;
  tools::read(a, N);

  std::vector<element> elements;
  elements.reserve(N);
  for (i64 i = 0; i < N; ++i) {
    elements.emplace_back(i + 1, a[i]);
  }
  std::sort(elements.begin(), elements.end(), [](const element& x, const element& y) {
    return x.value < y.value;
  });

  i64 answer = 0;
  std::set<range> ranges({range(0, N + 1)});
  for (const element& element : elements) {
    auto it = ranges.lower_bound(range(element.index, element.index));
    answer += element.value * (element.index - it->begin_included) * (it->end_included - element.index);
    const std::array<range, 2> new_ranges = {range(it->begin_included, element.index), range(element.index, it->end_included)};
    ranges.erase(it);
    ranges.insert(new_ranges[0]);
    ranges.insert(new_ranges[1]);
  }

  std::cout << answer << std::endl;
  return 0;
}

