struct node{
    int a , b;
    node * l;
    node * r;
    int mmin ;
    node(){
        l = nullptr;
        r = nullptr;
        mmin = -1;
    }
};

void build( node * root , int * m)
{
    if( root->a==root->b ){
        return ;
    }
    if(root->a + 1 == root->b){
        root->mmin = root->a;
        return ;
    }
    int mid = root->a + (root->b - root->a)/2;
    root->l = new node();
    root->r = new node();
    root->l->a = root->a;
    root->l->b = mid;
    root->r->a = mid;
    root->r->b = root->b;
    build(root->l , m);
    build(root->r , m);
    if( m[root->l->mmin] < m[ root->r->mmin ] ){
        root->mmin = root->l->mmin;
    }
    else
        root->mmin = root->r->mmin;
}
int segmin(node * root , int l,int r,int *m)
{
    if( root->a>r || root->b<=l )
        return -1;
    if( root->a>=l && root->b<=r+1 )
        return root->mmin;
    if(root->l!=nullptr && root->r!=nullptr){
        int a1,a2;
        a1 = segmin(root->l , l , r , m );
        a2 = segmin(root->r , l , r , m);
        if(a2==-1 || m[a1]<m[a2])
            return a1;
        else
            return a2;
    }
}
long long  ans  = 0;
void go( node * root,int l , int r ,int *m){
    if(l>r){
        return ;
    }
    int mid =segmin(root , l , r , m);

    ans+=( mid - l +1)*(r - mid + 1)*m[mid];
    go(root , l , mid-1 , m);
    go(root , mid+1,r ,m);
}
int main()
{
    int n;
    cin>>n;
    int *m = new int[n];
    for(int i=0;i<n;i++)
        cin>>m[i];
    node * root = new node();
    root->a = 0;
    root->b = n;
    build(root , m);
    go(root ,0 , n-1 , m );
    cout<<ans<<endl;
    return 0;
}

