void make(int n) {
	N = 1;
	while (N < n)	N *= 2;
	for (int i = N; i < 2*N; i++)	segtree[i] = 300000;
	for (int i = 0; i < n; i++)	segtree[i + N - 1] = i;
	for (int i = N - 2; i >= 0; i--) {
		if (a[segtree[2 * i + 1]] > a[segtree[2 * i + 2]])	segtree[i] = segtree[2 * i + 2];
		else	segtree[i] = segtree[2 * i + 1];
	}
}
int findsml(int l, int r, int p, int q, int k) {
	if (p <= l&&r <= q)	return segtree[k];
	if (r <= p||q <= l)	return 300000;
	int el = findsml(l, (l + r) / 2, p, q, 2 * k + 1);
	int er = findsml((l + r) / 2, r, p, q, 2 * k + 2);
	if (a[el] > a[er]) {
		return er;
	}
	else {
		return el;
	}
}
ll solve(int l,int r) {
	if (r == l)	return 0;
	if (r ==l+1)	return a[l];
	//cout << "start:" << l << " " << r << endl;
	int n = r - l;
	int sml = findsml(0, N, l, r, 0);
	ll ret = (ll)(sml - l + 1)*(r - sml)*a[sml];
	//cout << sml << " " << ret << endl;
	ret += solve(l, sml) + solve(sml+1, r);
	return ret;
}
