void solve() {
  int n;
  cin >> n;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  vector<int> left(n, 0);
  vector<int> right(n, n - 1);
  vector<int> st;
  for (int i = 0; i < n; i++) {
    while (!st.empty() && a[st.back()] > a[i]) {
      st.pop_back();
    }
    if (!st.empty()) {
      left[i] = st.back() + 1;
    }
    st.push_back(i);
  }
  st.clear();
  ll ans = 0;
  for (int i = n - 1; i >= 0; i--) {
    while (!st.empty() && a[st.back()] > a[i]) {
      st.pop_back();
    }
    if (!st.empty()) {
      right[i] = st.back() - 1;
    }
    st.push_back(i);
    ans += (i - left[i] + 1LL) * (right[i] - i + 1LL) * a[i];
  }
  cout << ans << "\n";
}

