template<typename T,T iniv=0>
struct Segtree{
    int n;
    vector<T> dat;
    Segtree(int n_){
        n = 1;
        while(n < n_) n *= 2;
        dat.resize(2*n-1);
        for(int i=0;i<2*n-1;i++) dat[i]=iniv;
    }

    void update(int k,T a){
        k+=n-1;
        dat[k]=a;
        while(k>0){
            k=(k-1)/2;
            dat[k]=min(dat[k*2+1],dat[k*2+2]);
        }
    }

    T query(int a,int b,int k,int l,int r){
        if(r<=a or b<=l) return iniv;
        else if(a<=l and r<=b) return dat[k];
        else{
            T vl = query(a,b,k*2+1,l,(l+r)/2);
            T vr = query(a,b,k*2+2,(l+r)/2,r);
            return min(vl,vr);
        }
    }

    T query(int a,int b){
        return query(a,b,0,0,n);
    }
};

int main(){
    int N; cin >> N;
    vector<int> a(N+2,0);
    rep(i,N) cin >> a[i+1];

    Segtree<int,INF> seg(N+2);
    for(int i=0;i<N+2;i++) seg.update(i,a[i]);

    vector<int> l(N+2),r(N+2);
    for(int i=1;i<=N;i++){
        int p = 0,q = i;
        while(q-p>1){
            int m = (p+q) / 2;
            if(seg.query(m,i+1)==a[i]){
                q = m;
            }else{
                p = m;
            }
        }
        l[i] = p;

        p = i; q = N+1;
        while(q-p>1){
            int m = (p+q)/2;
            if(seg.query(i,m+1) == a[i]){
                p = m;
            }else{
                q = m;
            }
        }
        r[i] = q;
    }

    ll ans = 0;
    for(int i=1;i<=N;i++){
        ll right = r[i] - i;
        ll left = i - l[i];
        //cerr << i << " " << left << " " << right << " " << left * right << endl;
        ans += a[i] * right * left;
    }
    cout << ans << endl;
}

