class seg_tree{

public:
  int n;
  vector<int> seg;

  seg_tree(int nn) {
    n=1;
    while(n<nn) n*=2;

    seg = vector<int>(2*n-1, INF);
  }

  //k番目の値をaに変更
  //(k-1)/2で上の葉
  //(k*2)+1,2で下の葉
  void update(int k, int a) {
    k += n-1;
    seg[k] = a;
    while(k>0){
      k=(k-1)/2;
      seg[k] = min(seg[k*2+1], seg[k*2+2]);
    }
  }

  //query minimun in [a, b)
  //call this from  as query(a, b, 0, 0, tree.n)
  int query(int a, int b, int k, int l, int r){
    if(a==b) return seg[a+n-1];
    if(r <= a || b <= l) return INF;
    if(a <= l && r <= b) return seg[k];
    int vl = query(a, b, k*2+1, l, (l+r)/2);
    int vr = query(a, b, k*2+2, (l+r)/2, r);


    return min(vl, vr);
  }
};

int main(){
  int n;
  cin>>n;
  int a[n];
  REP(i, n)cin>>a[i];

  if(n==1){
    cout<<a[0]<<endl;
    return 0;
  }

  seg_tree tree(n);
  REP(i, n) {
    tree.update(i, a[i]);
  }

  LL ans=0;
  REP(i, n){
    int litr=i, ritr=i;
    if(i>0){
      int l=0, r=i;
      int x=(l+r)/2;
      while(r-l>1){
        if(tree.query(x, i+1, 0, 0, tree.n)==a[i]) r=x;
        else l=x;
        x=(l+r)/2;
      }
      if(tree.query(l, i+1, 0, 0, tree.n)==a[i]) x=l;
      else x=r;

      litr = x;
    }

    if(i<n-1){
      int l=i, r=n-1;
      int x=(l+r)/2;
      while(r-l>1){
        if(tree.query(i, x+1, 0, 0, tree.n)==a[i]) l=x;
        else r=x;
        x=(l+r)/2;
      }
      if(tree.query(i, r+1, 0, 0, tree.n)==a[i]) x=r;
      else x=l;

      ritr = x;
    }

    ans += (LL)(i-litr+1)*(ritr-i+1)*a[i];
    //cout<<litr<<" "<<ritr<<" "<<ans<<endl;
  }
  cout<<ans<<endl;
  return 0;
}

