/* Binary Indexed Tree(0-index) */

struct BIT{
  typedef int Type;
  int bit_size;
  vector<Type> data;

  BIT(int n){
    bit_size = n;
    data.assign(n+1,0);
  }

  //add x to kth value
  void add(int k,Type x){
    k += 1;

    while(k<=bit_size){
      data[k]+=x;
      k+= k&(-k); }
  }

  //sum of [1,k]
  Type query(int k){
    k += 1;

    Type rec=0;
    while(k>0){
      rec+=data[k];
      k-= k&(-k);
    }
    return rec;
  }
};


int main(){
  int n;
  int a[SIZE],t[SIZE];

  scanf("%d",&n);

  for(int i=0;i<n;i++){
    scanf("%d",a+i);
    t[a[i]] = i;
  }

  BIT bit(n+1);
  BIT bit2(n+1);

  ll ans = 0;

  for(int i=1;i<=n;i++){
    int x,y;
    int p = t[i];

    int l,r,mid,u;

    l = p; r = n-1, u = bit.query(p);
    while(l<r){
      mid = (l+r+1)/2;

      if(bit.query(mid) > u){
        r = mid-1;
      }else{
        l = mid;
      }
    }
    y = l - p;

    l = 0; r = p, u = bit2.query(n-p);
    while(l<r){
      mid = (l+r)/2;

      if(bit2.query(n-mid) > u){
        l = mid+1;
      }else{
        r = mid;
      }
    }
    x = p - l;


    ans += (ll)(x+1) * (y+1) * i;


    bit.add(p,1);
    bit2.add(n-p,1);
  }

  printf("%lld\n",ans);

  return 0;
}

