    set<ll> borders;

    srep (val, 1, n+1) {
        ll idx = rmap[val];

        if (borders.empty()) {
            anslist[val] = (idx + 1LL) * (n - idx);
            borders.insert(idx);
            continue;
        }

        ll idx1 = 0;
        ll idx2 = n;
        auto iter = borders.lower_bound(idx);
        if (iter == borders.begin()) {
            idx2 = *iter;
        }
        else if (iter == borders.end()) {
            iter--;
            idx1 = *iter + 1LL;
        }
        else {
            idx2 = *iter;
            iter--;
            idx1 = *iter + 1LL;
        }

        anslist[val] = (idx - idx1 + 1LL) * (idx2 - idx);
        borders.insert(idx);
    }

    ll ans = 0;
    rep (i, 200005) ans += anslist[i] * i;

    debug_printf("---- ans\n");
    cout << ans << endl;
}

