#define MAX 200001
using namespace std;

int mark_right[MAX],mark_left[MAX],a[MAX],n;
long long int res = 0;

int mark_greater(int ar[]){
	for (int i=0;i<=n;i++) mark_left[i] = mark_right[i] = -1;
	int s[n][2],top=0;
	s[0][0] = ar[0];
	s[0][1] = 0;
	int i=1;
	while(i<n){
		if (top==-1||s[top][0]<=ar[i]){
			s[++top][0] = ar[i];
			s[top][1] = i;
			i++;
		}
		else{
			mark_right[s[top][1]] = i;
			top--;
		}
	}
	top=0;
	s[0][0] = ar[n-1];
	s[0][1] = n-1;
	i=n-2;
	while(i>=0){
		if (top==-1||s[top][0]<ar[i]){
			s[++top][0] = ar[i];
			s[top][1] = i;
			i--;
		}
		else{
			mark_left[s[top][1]] = i;
			top--;
		}
	}

	for (int i=0;i<n;i++){
		long long int temp = ar[i];
		long long int l,r;
		l = mark_left[i];
		r = mark_right[i]==-1?n:mark_right[i];
		long long int temp1 = (i-l)*(r-i);
		res+=temp1*temp;
	}

	return 0;
}


int main(){
	scanf("%d",&n);
	int a[n];
	for(int i=0;i<n;i++) scanf("%d",&a[i]);
	mark_greater(a);
	cout << res;
	return 0;
}

