        mp[a] = i;
    }
    ll sum = 0,sqsize = 450;
    vector<bool> used(N),sqused(sqsize);
    sqused[N/sqsize+1] = 1;
    for(auto p:mp){
        int key = p.first,index = p.second;
        ll lcnt = 0,rcnt = 0,i;
        for(i = index-1;i >= index/sqsize*sqsize;i--){
            if(used[i]){
                goto lflag;
            }
            lcnt++;
        }
        for(i = index/sqsize-1;i >= 0;i--){
            if(sqused[i]){
                break;
            }
            lcnt += sqsize;
        }
        for(i = (i+1)*sqsize-1;i >= 0;i--){
            if(used[i]){
                goto lflag;
            }
            lcnt++;
        }
        //lここまで
        lflag:
        for(i = index+1;(i < index/sqsize*sqsize + sqsize) && i < N;i++){
            if(used[i]){
                goto rflag;
            }
            rcnt++;
        }
        for(i = index/sqsize+1;i < sqsize;i++){
            if(sqused[i]){
                break;
            }
            rcnt += sqsize;
        }
        for(i = (i-1)*sqsize+1;index+1 < i && i < N;i++){
            if(used[i]){
                goto rflag;
            }
            rcnt++;
        }
        //rここまで
        rflag:
        sum += key * (lcnt+1) * (rcnt+1);
