        for(int j=i; j>=0; j--){
            if(vec[i] <= vec[j]){
                cnt++;
            }
            else{
                break;
            }
        }
        right[i] = cnt;
    }

    int64_t ans = 0;
    for(int i=0; i<N; i++){
        ans += left[i] * right[i] * vec[i];
    }

