// Union find
struct uf {
  vector<int> d, l, r;
  uf(){}
  uf(int mx):d(mx,-1) {
    l = r = vi(mx);
    rep(i,mx) l[i] = r[i] = i;
  }
  int root(int x) {
    if(d[x] < 0) return x;
    return d[x] = root(d[x]);
  }
  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if(x == y) return false;
    if(d[x] > d[y]) swap(x,y);
    d[x] += d[y]; d[y] = x;
    mins(l[x],l[y]);
    maxs(r[x],r[y]);
    return true;
  }
  int size(int x) { return -d[root(x)];}
};
