int par[MAX_N];  //親
int depth[MAX_N]; //深さ
ll size[MAX_N]; //最小でいられる区間数

//初期化
void init(int n){
    FOR1(n){
        par[i] = i;
        depth[i] = 0;
        size[i] = 1;
    }
}

//根を求める
int find(int x){
    if(par[x] == x){
        return x;
    }else{
        return par[x] = find(par[x]);
    }
}

//xとyの属する集合の併合
ll unite(int x, int y){
    x = find(x);
    y = find(y);
    ll tmp_ans  = size[x] * size[y];
    if(x == y) return 0;

    if(depth[x] < depth[y]){
        par[x] = y;
        size[y] += size[x];
    }else{
        par[y] = x;
        size[x] += size[y];
        if(depth[x] == depth[y]) depth[x]++;
    }

    return tmp_ans;
}

//同じ集合に属するか否か
bool same(int x, int y){
    return find(x) == find(y);
}

