int64 checkB(std::vector<int64>const& vec, std::vector<int64>const& inverse, std::size_t first, std::size_t last)
{
	auto min = [](auto first, auto last)
	{
		auto ret = *first;
		while (++first != last)
		{
			ret = std::min(*first, ret);
		}
		return ret;
	};
	if (first == last)
		return 0;
	auto m = min(vec.begin() + first, vec.begin() + last);
	auto index = inverse[m];
	auto ret = m*(index - first + 1)*(last - index);
	return ret + checkB(vec, inverse, first, index) + checkB(vec, inverse, index + 1, last);
}
