  UnionFind uf(n);
  int ans = 0;
  for (int x = n - 1; x >= 0; x--) {
    int i = rev[x];
    if (i - 1 >= 0 && a[i - 1] >= x) uf.unite(i - 1, i);
    if (i + 1 < n && a[i + 1] >= x) uf.unite(i, i + 1);
    ans += (x + 1) * (i - uf.left(i) + 1) * (uf.right(i) - i);
  }
  cout << ans << endl;
}

