// L[i] := argmax_j j <= i and H[j-1] < H[i]
// R[i] := argmin_j j > i and H[j] < H[i]
template<class T>
struct StockSpan {
    vector<T> H, L, R;
    StockSpan(const vector<T> &_H): H(_H) {
	buildLE();
	//build(greater<T>());
    }
    int range(int i) { return R[i] - L[i]; }
    void buildLE() { // range (H[i] <=)
	const int N = H.size();
	L.resize(N);
	vector<int> S;
	for (int i=0; i<N; i++) {
	    while (!S.empty() && H[i] <= H[S.back()]) S.pop_back();
	    L[i] = S.empty() ? 0 : S.back() + 1;
	    S.push_back(i);
	}
	R.resize(N);
	S.clear();
	for (int i=N; i--; ) {
	    while (!S.empty() && H[i] <= H[S.back()]) S.pop_back();
	    R[i] = S.empty() ? N : S.back();
	    S.push_back(i);
	}
    }

    template<class C>
    void build(C cmp) {
	const int N = H.size();
	L.resize(N);
	vector<int> S;
	for (int i=0; i<N; i++) {
	    while (!S.empty() && cmp(H[i], H[S.back()])) S.pop_back();
	    L[i] = S.empty() ? 0 : S.back() + 1;
	    S.push_back(i);
	}
	R.resize(N);
	S.clear();
	for (int i=N; i--; ) {
	    while (!S.empty() && cmp(H[i], H[S.back()])) S.pop_back();
	    R[i] = S.empty() ? N : S.back();
	    S.push_back(i);
	}
    }
};
