int p[200010], sz[200010];

int find(int x) {
    return x == p[x] ? x : p[x] = find(p[x]);
}

void merge(int x, int y) {
    int px = find(x), py = find(y);
    if(px == py) {
        return ;
    }
    p[px] = py;
    sz[py] += sz[px];
}

void MAIN() {
    int n;
    scanf("%d", &n);
    for(int i = 1; i <= n; ++ i) {
        p[i] = i;
        sz[i] = 1;
    }
    std::vector<int> idx(n + 1), arr(n + 1);
    for(int i = 0; i < n; ++ i) {
        scanf("%d", &arr[i + 1]);
        idx[arr[i + 1]] = i + 1;
    }
    long long ans = 0;
    for(int i = n; i > 0; -- i) {
        int l = 1, r = 1;
        if(idx[i] > 1 && arr[idx[i] - 1] > i) {
            l += sz[find(arr[idx[i] - 1])];
            merge(arr[idx[i] - 1], i);
        }
        if(idx[i] < n && arr[idx[i] + 1] > i) {
            r += sz[find(arr[idx[i] + 1])];
            merge(i, arr[idx[i] + 1]);
        }
        ans += l * 1ll * r * 1ll * i;
    }
    printf("%lld\n", ans);
}

