for(int i = 1; i <= n; ++i) {
    cin >> ai;
    v.pb(mper(ai, i));
}

build();

sort(all(v));

ll ans = 0;

for(auto it : v) {

    ll pos = it.se;
    ll val = it.fe;

    ll left = get(1, pos, 0);
    ll right = get(pos, n, 1);

    if(left == -1) {left = 1;}
    else {left++;}

    if(right == INF) {right = n;}
    else {right--;}

    ll dis = (pos - left + 1) * 1ll * (right - pos + 1) * 1ll;

    ans += (dis * val);

//    cout << left << ' ' << right << ' ' << dis * val << '\n' ;

    update(pos);

}

