using namespace std;

const int maxn=200010;
int dp[maxn][20];
int lg[maxn];

void init(int n)
{
    lg[0]=-1;
    for (int i=1;i<=n;++i)
    {
        lg[i]=((i&(i-1))==0)?lg[i-1]+1:lg[i-1];
    }
    for (int j=1;j<=lg[n];++j)
    {
        for (int i=1;i+(1<<j)-1<=n;++i)
        {
            dp[i][j]=min(dp[i][j-1],dp[i+(1<<(j-1))][j-1]);
        }
    }
}

int rmq(int x,int y)
{
    int len=lg[y-x+1];
    return min(dp[x][len],dp[y-(1<<len)+1][len]);
}

int queryl(int l,int r,int x)
{
    if (l==r) return -1;
    if (rmq(l,r)==x) return -1;
    while (l+1<r)
    {
        int mid=(l+r)/2;
        if (rmq(mid,r)<x) l=mid;
        else r=mid;
    }
    return l;
}

int queryr(int l,int r,int x)
{
    if (l==r) return -1;
    if (rmq(l,r)==x) return -1;
    while (l+1<r)
    {
        int mid=(l+r)/2;
        if (rmq(l,mid)<x) r=mid;
        else l=mid;
    }
    return r;
}

int main()
{
    int n;
    scanf("%d",&n);
    for (int j=1;j<=n;++j)
    {
        scanf("%d",&dp[j][0]);
    }
    init(n);
    LL ans=0;
    for (int j=1;j<=n;++j)
    {
        int l=queryl(1,j,dp[j][0]);
        int r=queryr(j,n,dp[j][0]);
        if (l==-1) l=0;
        if (r==-1) r=n+1;
        l=j-l;
        r=r-j;
        ans+=(LL)dp[j][0]*l*r;
    }
    cout<<ans<<endl;
	return 0;
}

#include<bits/stdc++.h>

using namespace std;

const int INF=1e8;
const int MAX=1000000;

struct segtree {
    int N;
	vector<int> dat;
    segtree() {}
    segtree(int n) {
        N = 1;
        while(N < n) N *= 2;
		dat.resize(2*MAX);
        for(int i = 0; i < 2*N-1; i++)
            dat[i] = INF;
    }
    // update k th element
    void update(int k, int a) {
        k += N-1; // leaf
        dat[k] = a; 
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }
    // min [a, b)
    int query(int a, int b) { return query(a, b, 0, 0, N); }
    int query(int a, int b, int k, int l, int r) {
        if(r <= a or b <= l) return INF;
        if(a <= l and r <= b) return dat[k];
        int m = (l + r) / 2;
        return min(query(a, b, k*2+1, l, m), query(a, b, k*2+2, m, r));
    }
};

