template<typename Monoid>
struct SegmentTree{
  using F = function<Monoid(Monoid, Monoid)>;

  int sz;
  vector<Monoid> seg;

  const F f;
  const Monoid M1;
  /* 
   * int n: size
   * const F f: binary operation
   * const Monoid &M1: initial element
   * 
   * example
   * Range Minimun Query: SegmentTree<int> seg(n, [](int a, int b){return min(a, b);}, INT_MAX);
   * Range Max Query: SegmentTree<int> seg(n, [](int a, int b){return max(a, b);}, 0);
   */
  SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
  }

  void set(int k, const Monoid &x) { // set x to k-th element
    seg[k + sz] = x;
  }

  void build() { // build up the tree
    for(int k = sz - 1; k > 0; k--) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  void update(int k, const Monoid &x) { // update k-th element to x
    k += sz;
    seg[k] = x;
    while(k >> 1) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  Monoid query(int a, int b) { // get result of [a, b)
    Monoid L = M1, R = M1;
    for(a += sz, b += sz; a < b; a >>=1, b >>= 1) {
      if(a & 1) L = f(L, seg[a++]);
      if(b & 1) R = f(seg[--b], R);
    }
    return f(L, R);
  }

  Monoid operator[](const int &k) const { // return k-th element
    return seg[k + sz];
  }
};

map<int, int> m;

ll solve(SegmentTree<ll> &st, int l, int r, int i, int x) {
  if(r - l == 1) return st.query(l, r);
  if(r - l == 0) return 0;
  ll Ll = l, Lr = r;
  ll ans = (i - Ll + 1) * (Lr - i) * x;
  int tmp = st.query(i+1, r);
  ans += solve(st, i+1, r, m[tmp], tmp);
  tmp = st.query(l, i);
  ans += solve(st, l, i, m[tmp], tmp);
  return ans;
}

int main () {
  cin.tie(0);
  cout << setprecision(10);

  int n; cin >> n;
  SegmentTree<ll> st(n, [](ll a, ll b){return min(a, b);}, INT_MAX);

  REP(i, n) {
    ll tmp; cin >> tmp;
    m[tmp] = i;
    st.set(i, tmp);
  }
  st.build();

  int tmp = st.query(0, n);
  cout << solve(st, 0, n, m[tmp], tmp) << endl;
}

