lint calc(lint l, lint r, lint m, lint val){
    lint res = (r - l) * (r - l - 1LL) / 2LL;
    res -= (m - l) * (m - l - 1LL) / 2LL;
    res -= (r - m) * (r - m - 1LL) / 2LL;
    res *= val;
    return res;
}

