int64 checkB(std::vector<int64>const& vec, std::vector<int64>const& inverse, std::size_t first, std::size_t last, std::size_t m)
{
	int64 min = vec.size();

	if (first == last)
		return 0;
	for (int64 i = m + 1;i < vec.size();++i)
	{
		if (first <= inverse[i] && inverse[i] < last)
		{
			min = i;
			break;
		}
	}
	auto index = inverse[min];
	auto ret = min*(index - first + 1)*(last - index);
	return ret + checkB(vec, inverse, first, index, min) + checkB(vec, inverse, index + 1, last, min);
}
