using namespace std;

int main() {
	int n;
	cin >> n;
	vector<int> a(n);
	vector<int> position(n + 1);
	FOR(i, 0, n) {
		scanf("%d", &a[i]);
		position[a[i]] = i;
	}
	set<int> border;
	long long sumx = 0;
	FOR(i, 1, n + 1) {
		int nowpos = position[i];

		// upper_bound(border.begin(), border.end(), nowpos)じゃだめらしい(時間が)
		auto pos = border.upper_bound(nowpos);

		int ub, lb;
		if (border.size() == 0) {
			ub = n, lb = -1;
		}

		else if (pos == border.end()) {
			ub = n;
			lb = *border.rbegin();
		}
		else {
			ub = *pos;
			if (pos == border.begin())
				lb = -1;
			else
				lb = *(--pos);
		}

		long long left = nowpos - lb - 1;
		long long right = ub - nowpos - 1;
		if (left < right)
			swap(left, right);

		long long toadd = (long long)i*(right + 1)*(left + 1);
		sumx += toadd;
		border.insert(nowpos);
	}
	cout << sumx << endl;


	return 0;
}

