int idx = 0;
int N;
void solve(){
    ll res = 0;
    for(int i = 1;i<idx;i++){
        for(int j = i;j<=N;j++){
            if(i%2){
                res += dp1[j];
                dp2[j] = min(dp1[j],dp1[j-1]);
            }
            else{
                res += dp2[j];
                dp1[j] = min(dp2[j],dp2[j-1]);
            }
        }
    }
    ll tmp = (N-idx+1)*(N-idx+2);
    res += tmp/2;
    cout << res << endl;
}

