//    AGC 005 B Minimum Sum
    /**
     * Ai が最小値をとる区間はいくつある？
     * Al ~ Ai ~ Ar という列を考える
     * ここでAlはAiより左にあるうちAiに一番近い、Aiより小さい要素である
     * ここでArはAiより右にあるうちAiに一番近い、Aiより小さい要素である
     * そうすると、Aiが最小となる区間はAl+1 ~ AiとAi ~ Ar-1の区間から作られると分かる
     * (ここでAiは必ず含むがAl+1 ~ Ai-1, Ai+1 ~ Ar-1は含まなくともよい)
     *
     * ここでAiの数値が小さいものから見ていけば、
     * setで管理するものを "使われた(Aiより小さい)要素の位置" だけにして、
     * Aiが最小値になるような区間が探しやすい.
     *
     */

    i32 n; cin >> n;

    vi a(n), place(n+1);
    rep(i,n) {
        cin >> a[i];
        place[a[i]] = i;
    }

    set<i32> used_a_places = {-1, n};
    i64 cnt = 0;
    for(i32 val = 1; val <= n; ++val) {
        i32 plc = place[val];
        auto iter = lower_bound(all(used_a_places), plc);
        i32 R = *iter, L = *(--iter);

        i32 num_of_right_boundary = R - plc;
        i32 num_of_left_boundary = plc - L;
        cnt += val * (num_of_left_boundary * num_of_right_boundary);

        used_a_places.insert(plc);
    }

    cout << cnt << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

