inline ll tri(ll n, ll k)
{
	return (n - k - k) * (k + 1) + k * (k + 1);
}

int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; ++i)
	{
		scanf("%d", a + i);
		--a[i];
		inv[a[i]] = i;
	}
	reverse(a, a + n);
	trbase.push_back(-1);
	trbase.push_back(n);
	ll ans = 0;
	for (int num = 0; num < n; ++num)
	{
		int place = inv[num];
		int itr = find(trbase.begin(), trbase.end(), place) - trbase.begin() - 1;
		int siz = trbase[itr + 1] - trbase[itr] - 1;
		ans += tri(siz,place - trbase[itr] - 1) * (num + 1);
		trbase.push_back(place);
	}
	printf("%lld\n", ans);
	return 0;
}

