int N;
vector<int> a;
set<int> used;
map<int, int> pos;
LONG result = 0;

void calculate() {
  for (int num = 1; num <= N; num++) {
    auto prev = used.lower_bound(pos[num]);
    if (prev == used.begin()) prev = used.end();
    else prev--;
    auto next = used.upper_bound(pos[num]);
    int left, right;
    if (prev == used.end()) {
      left = pos[num];
    } else {
      left = pos[num] - *prev - 1;
    }
    if (next == used.end()) {
      right = N - pos[num] - 1;
    } else {
      right = *next - pos[num] - 1;
    }
    result += (LONG)num * (right * left + right + left + 1);
    used.insert(pos[num]);
  }
}

