struct UnionFind{
    vector<int> parents;
    vector<int> rank;
    vector<ll> size;
    UnionFind(int n){
        parents.resize(n);
        rank.assign(n, 1);
        size.assign(n, 1);
        REP(i, n){
            parents[i] = i;
        }
    }
    int find(int x){
        if(parents[x] == x) return x;
        return parents[x] = find(parents[x]);
    }

    ll unite(int x, int y){
        x = find(x);
        y = find(y);
        ll res = size[x] * size[y];
        size[x] += size[y];
        parents[y] = x;
        return res;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
};

int N;
ll a[200000 + 100];
ll b[200000 + 100];
int main(){
    ios::sync_with_stdio(false);
    cin >> N;
    UnionFind uf(200000 + 100);
    FOR(i, 1, N+1) {
        cin >>  a[i];
        b[a[i]] = i;
    }

    ll ans = 0;
    // 最大値から順番に区間をくっつける
    for(int j=N; j>=1; j--) {
        // 位置
        int i = b[j];
        ans += a[i];

        // 左側が存在 && a[i]より大きい
        if ( i - 1 >= 1 && a[i-1] > a[i] ) {
            ans += uf.unite(i-1, i) * a[i];
        }

        // 右側が存在 && a[i]より大きい
        if ( i + 1 <= N && a[i+1] > a[i] ) {
            ans += uf.unite(i + 1, i) * a[i];
        }
    }

    cout << ans << endl;

    return 0;
}

