ll div(ll n,ll l,ll r){
  //cout << n << "," << l << "," << r << "," << bs[n] << endl;

  ll su = 0;
  su += (bs[n]-l+1)*(r-bs[n]+1)*n;
  if ( l < bs[n] ) su += div( seg.query(l,bs[n]-1+1) ,l,bs[n]-1);
  if ( bs[n] < r ) su += div( seg.query(bs[n]+1,r+1) ,bs[n]+1,r);
  return su;
}

