inline int lb(int x) { return x & -x; }

int read(int x) {
    int tot = 0;
    for (; x; x -= lb(x))tot += c[x];
    return tot;
}

void add(int x, int num) {
    for (; x <= n; x += lb(x))c[x] += num;
}

int main() {
    __;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
