    }
    sort(r + 1, r + 1 + n, cmp);
    ll ans = 0;
    for (int i = 1; i <= n; ++i) {
        int x = r[i];
        int left = 1, right = x;
        while (left < right) {
            int mid = (left + right) >> 1;
            if (read(x) - read(mid - 1) == 0)right = mid;
            else left = mid + 1;
        }
        ll t1 = x - left + 1;
        left = x, right = n;
        while (left < right) {
            int mid = (left + right + 1) >> 1;
            if (read(mid) - read(x) == 0)left = mid;
            else right = mid - 1;
        }
        ll t2 = right - x + 1;
        ans += t1 * t2 * a[x];
        add(x, 1);
