class segtree_min {
public:
	segtree_min(const int N) {
		SIZE = roundup_pow2(N);
		v.clear();
		v.resize(SIZE * 2, 99999999);
	}

	//v[index]=numberとする。
	void update(const int index, const int number) {
		v[index + SIZE] = 99999999;
		for (int i = index + SIZE; i; i = i / 2)v[i] = min(v[i], number);
	}

	//[L,R)の最大値を返す。
	int getmin(const int L, const int R) {
		return getmin_inner(L, R, 1, 0, SIZE);
	}
private:
	int getmin_inner(const int queryL, const int queryR, const int index, const int segL, const int segR) {
		if (queryR <= segL || segR <= queryL)return 99999999;
		if (queryL <= segL && segR <= queryR)return v[index];
		return min(getmin_inner(queryL, queryR, index * 2, segL, (segL + segR) / 2),
			getmin_inner(queryL, queryR, index * 2 + 1, (segL + segR) / 2, segR));
	}

	//x以上であるような2のべき乗数のうち最小のものを返す。
	int roundup_pow2(int x) {
		x--;
		rep(i, 6)x |= x >> (1LL << i);
		return x + 1;
	}

	int SIZE;
	vector<int>v;
};

signed main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;
	vector<int>a(N);
	segtree_min seg(N);
	rep(i, N) {
		cin >> a[i];
		seg.update(i, --a[i]);
	}
	vector<int>inv_a(N);
	rep(i, N)inv_a[a[i]] = i;

	int ans = 0;
	stack<array<int, 2>>S;
	S.push({ 0,N });
	while (!S.empty()) {
		auto x = S.top(); S.pop();
		if (x[0] == x[1])continue;
		int minnum = seg.getmin(x[0], x[1]);
		int minindex = inv_a[minnum];
		ans += (minnum + 1) * (x[1] - minindex) * (minindex - x[0] + 1);
		S.push({ x[0],minindex });
		S.push({ minindex + 1,x[1] });
	}
	cout << ans << endl;
}

