ll aaaa(ll s,ll v)
{
	ll k=(ll)(log((v-s+1)*1.0)/log(2.0));
	if(a[d[s][k]]<a[d[v-(1<<k)+1][k]])
	{
		return d[s][k];
	}
	else 
	{
		return d[v-(1<<k)+1][k];
	}
}
void awsl(ll l,ll r)
{
	if(l==r)
	{
		sum+=a[l];
		return;
	}
	ll minn=aaaa(l,r);
	sum=sum+(ll)(minn-l+1)*(r-minn+1)*a[minn];
	if(l<=minn-1)
	{
		awsl(l,minn-1);
	}
	if(r>=minn+1)
	{
		awsl(minn+1,r);
	}
}
