lint calc(lint l, lint h, lint m, lint val){
    lint res = (h - l) * (h - l - 1LL) / 2LL;
    res -= (m - l) * (m - l - 1LL) / 2LL;
    res -= (h - m) * (h - m - 1LL) / 2LL;
    res *= val;
    return res;
}

