    st.insert(n + 1);
    REP(i, 1, n + 1){
        auto it1 = st.upper_bound(rev[i]);
        auto it2 = it1--;
        ans += calc(*it1, *it2, rev[i], i);
        st.insert(rev[i]);
    }
    cout << ans << endl;
    return 0;
}

