template<typename T>
void RD(vector<T>& v, int n)
{
    v.reserve(n);
    REP(i, n) {
        T e; RD(e);
        v.emplace_back(e);
    }
}

s64 N;

vector<s64> A;

void solve()
{
    vector<s64> pos(N+1, -1);
    REP(i, N) {
        pos[A[i]] = i;
    }

    s64 ans = 0;

    set<s64> s;
    FOR(a, 1, N+1) {
        s64 i = pos[a];
        auto it = s.upper_bound(i);
        s64 l = it == begin(s) ? 0   : *prev(it) + 1;
        s64 r = it == end(s)   ? N-1 : *it - 1;

        s64 addend = a * (i-l+1) * (r-i+1);

#ifdef DEBUG
        DBG(s);
        DBG(i);
        DBG(l);
        DBG(r);
        DBG(addend);
#endif

        ans += addend;

        s.emplace(i);
    }

    PRINTLN(ans);
}

