template<class T>
struct SegTree
{
	lint n;
	vector<T> t;
	T neutral;

	SegTree(lint _n, const T& _neutral) : neutral(_neutral)
	{
		n = 1;
		while (n < _n)
		{
			n *= 2;
		}
		rep(i, n)
		{
			t.resize(2 * n, neutral);
		}
	}

	using funcT = T(T val1, T val2);
	funcT* un;

	void update(lint i, const T& val)
	{
		i += n - 1;
		t[i] = val;
		while (i > 0)
		{
			i = (i - 1) / 2;
			t[i] = un(t[i * 2 + 1], t[i * 2 + 2]);
		}
	}

	T query_impl(lint a, lint b, lint k, lint l, lint r)
	{
		if (r <= a || b <= l)
			return neutral;
		if (a <= l && r <= b)
			return t[k];
		else
		{
			const T c1 = query_impl(a, b, 2 * k + 1, l, (l + r) / 2);
			const T c2 = query_impl(a, b, 2 * k + 2, (l + r) / 2, r);
			return un(c1, c2);
		}
	}

	T query(lint l, lint r)
	{
		return query_impl(l, r, 0, 0, n);
	}

};

template<class T, class Pred>
pair<T, T> bin(T begin, T end, Pred p)
{
	while (end - begin > 1)
	{
		T tgt = begin + (end - begin) / 2;

		if (p(tgt))
		{
			begin = tgt;
		}
		else
		{
			end = tgt;
		}
	}

	return make_pair(begin, end);
}

int main()
{
	lint n;
	cin >> n;
	vec a(n);
	rep(i, n)
		cin >> a[i];

	SegTree<lint> tr(n, inf);
	tr.un = [](lint p, lint q)
	{
		return mmin(p, q);
	};

	rep(i, n)
		tr.update(i, a[i]);

	lint ans = 0;

	rep(i, n)
	{
		auto ll = bin(0LL, i+1, [&](lint pos) {
			return tr.query(pos, i+1) != a[i];
		});

		auto rr = bin(i, n, [&](lint pos) {
			return tr.query(i, pos) == a[i];
		});

		lint lw = i - ll.second + 1, rw = rr.first - (i + 1) + 1;

		if (tr.query(0, i + 1) == a[i])
			lw = i - 0 + 1;
		if (tr.query(i, n) == a[i])
			rw = n - (i+1) + 1;
		ans += lw * rw * a[i];
	}

	cout << ans << endl;

	return 0;
}

