void echoln() {
	fputc('\n', stdout);
}
void echoln(const char * fmt, ...) {
	va_list arg;
	va_start(arg, fmt);
	vprintf(fmt, arg);
	va_end(arg);
	fputc('\n', stdout);
}

int main() {
	vector<int> a = nextIntVec(nextInt());
	vector<int> b(a.size());
	int64 sum = 0;
	for(int l=0; l<(int)a.size(); ++l) {
		int m = a[l];
		int ll = l;
		int difficult = 0;
		for(int r=l; r<(int)a.size(); ++r) {
			if(a[r]<m) {
				++difficult;
				m = a[r];
				b[ll] = r;
				ll = r;
				if(r<b[r]) {
					sum += (int64)m * (b[r]-r);
					r = b[r] - 1;
					continue;
				}
			}
			sum += m;
		}
		b[ll] = (int)a.size();
		if((int)a.size()-l<difficult+difficult) {
			b.clear();
			b.resize(a.size(), a.size());
			for(++l; l<(int)a.size(); ++l) {
				int m = a.back();
				int ll = a.size()-1;
				for(int r=a.size()-1; l<=r; --r) {
					if(a[r]<m) {
						m = a[r];
						b[ll] = r;
						ll = r;
						if(b[r]<r) {
							sum += (int64)m * (r-max(l-1, b[r]));
							r = max(l-1, b[r]) + 1;
							continue;
						}
					}
					sum += m;
				}
				b[ll] = 0;
			}
			break;
		}
	}
	echoln("%lld", sum);
	return 0;
}

