class stree {
public:
    vpi t;
    int s;
    void build (vpi & a, int v, int tl, int tr) {
        if(v==1) {
            t.resize(a.size() * 4);
            s = a.size();
        }
        if (tl == tr)
            t[v] = a[tl];
        else {
            int tm = (tl + tr) / 2;
            build (a, v*2, tl, tm);
            build (a, v*2+1, tm+1, tr);
            t[v] = min(t[v*2], t[v*2+1]);
        }
    }

    pi get (int v, int tl, int tr, int l, int r) {
        if(l>r) return mp(INF,0);
        if (tl == tr)
            return t[v];
        if(l==tl && r==tr)
            return t[v];
        int tm = (tl + tr) / 2;
        return min(get (v*2, tl, tm, l, min(r,tm)), get (v*2+1, tm+1, tr, max(tm+1,l), r));
    }
};

