using namespace std;
typedef long long ll;

const int MAX_N = (1<<21);
const ll INF = LLONG_MAX;
// RMQ
class RMQ{
  int n;
  ll dat[2*MAX_N-1];

public:
  RMQ(int _n = MAX_N){
    n = 1;
    while(n < _n) n *= 2;
    fill(dat,dat+2*n-1,INF);
  }

  // k番目の値をaに変更
  void update(int k, ll a){
    k += n - 1;
    dat[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      dat[k] = min(dat[k*2+1], dat[k*2+2]);
    }
  }

  // [a,b) の最小値を求める
  ll query(int a, int b){ return query(a, b, 0, 0, n);}
  ll query(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) return INF;
    if(a <= l && r <= b) return dat[k];
    else{
      ll vl = query(a, b, k*2+1, l, (l+r)/2);
      ll vr = query(a, b, k*2+2, (l+r)/2, r);      
      return min(vl,vr);
    }
  }  
};


int N;
ll A[200005];
ll L[200005];
ll R[200005];
RMQ rmq;

int getL(int id){
  int st = 0, ed = id;
  int k = id;
  while( st <= ed ){
    int h = (st+ed)/2;
    ll r = rmq.query( h, id );
    if( r > A[id] ) {
      k = h; ed = h-1;
    } else
      st = h+1;
  }
  return abs( id - k )+1;
}
int getR(int id){
  int st = id, ed = N-1;
  int k = id;
  while( st <= ed ){
    int h = (st+ed)/2;
    ll r = rmq.query( id+1, h+1 );
    if( r > A[id] ) {
      k = h; st = h+1;
    } else
      ed = h-1;
  }
  return abs( id - k )+1;  
}

int main(){
  cin >> N;
  for(int i=0;i<N;i++){
    cin >> A[i];
    rmq.update( i, A[i] );
  }

  ll res = 0;
  for(int i=0;i<N;i++){
    ll l = getL( i ), r = getR( i );
    res += l * r * A[i];    
  }
  cout << res << endl;
}

