const int N = 300005;
typedef long long lld;
int n;
int a[N];
int st[N], top = 0;
int lef[N], rig[N];
lld ans = 0;

int main() {
	freopen("data.in", "r", stdin);
	scanf("%d", &n);
	for(int i = 1; i <= n; i++) 
		scanf("%d", &a[i]);
	for(int i = 1; i <= n; i++) {
		if(a[i] > st[top]) {
			st[++top] = a[i]; 
			continue;
		}
		while(a[i] < st[top]) {
			rig[st[top]] = i;
			top--;
		}
		st[++top] = a[i];
	}
	while(top > 0){
		rig[st[top]] = n + 1;
		top--;
	}
	top = 0;
	for(int i = n; i >= 1; i--) {
		if(a[i] > st[top]) {
			st[++top] = a[i];
			continue;
		}
		while(a[i] < st[top]) {
			lef[st[top]] = i;
			top--;
		}
		st[++top] = a[i];
	}
	while(top > 0) {
		lef[st[top]] = 0;
		top--;
	}
	for(int i = 1; i <= n ;i++) {
		int left = i - lef[a[i]];
		int right = rig[a[i]] - i;
		ans += lld(right * left * a[i]);
	}
