#define seg_size 262144
pair<long long, long long> seg_memo[2000000] = {};
pair<long long, long long> seg_find(long long now, long long w_l, long long w_r, long long n_l, long long n_r) {
	if (w_l >= n_r||w_r <= n_l) return make_pair(999999, 0);
	if (w_l <= n_l&&n_r <= w_r) return seg_memo[now];
	pair<long long, long long> a = seg_find(now * 2, w_l, w_r, n_l, (n_l + n_r) / 2),b = seg_find(now * 2 + 1, w_l, w_r,(n_l + n_r) / 2,n_r);
	if (a.first < b.first) {
		return a;
	}
	else {
		return b;
	}
}
long long setting(long long now) {
	if (seg_memo[now * 2].first < seg_memo[now * 2 + 1].first) {
		seg_memo[now] = seg_memo[now * 2];
	}
	else {
		seg_memo[now] = seg_memo[now * 2 + 1];
	}
	if(now != 1) setting(now / 2);
	return 0;
}
int main() {
	int n;
	cin >> n;
	for (int i = 0;i <= seg_size * 2;++i) {
		seg_memo[i].first = 999999;
	}
	for (int i = 0;i < n;++i) {
		cin >> seg_memo[seg_size + i].first;
		seg_memo[seg_size + i].second = i;
		setting((seg_size + i) / 2);
	}
	long long ans = 0;
	queue<pair<long long, long long>> gekogeko;
	gekogeko.push(make_pair(0, n));
	while (gekogeko.empty() == false) {
		pair<long long, long long> now = gekogeko.front();
		gekogeko.pop();
		pair<long long, long long> returned = seg_find(1, now.first, now.second, 0, seg_size);
		long long genya = returned.first * (returned.second - now.first + 1);
		genya %= MAX_MOD;
		genya *= (now.second - returned.second);
		genya %= MAX_MOD;
		ans += genya;
		ans %= MAX_MOD;
		if (returned.second != now.first) {
			gekogeko.push(make_pair(now.first, returned.second));
		}
		if (returned.second + 1 != now.second) {
			gekogeko.push(make_pair(returned.second + 1, now.second));
		}
	}
	cout << ans << endl;
	return 0;
}

