#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ull = unsigned long long;
#define MOD 1000000007

const int MAX_N=200000;

int n,dat[2*MAX_N-1];

void init(int n_){
  n=1;
  while(n<n_) n*=2;
  for(int i=0;i<2*n-1;i++) dat[i]=INT_MAX;
}

// ｋ番目の値をaに変更
void update(int k, int a){
  k+=n-1;
  dat[k]=a;
  while(k>0){
    k=(k-1)/2;
    dat[k]=min(dat[k*2+1],dat[k*2+2]);
  }
}

//[a,b)の最小値を求める
//外からはquery(a,b,0,0,n)とする
int query(int a, int b, int k, int l, int r){
  if(r<=a || b<=l) return INT_MAX;
  if(a<=l && r<=b) return dat[k];
  else{
    int vl=query(a,b,k*2+1,l,(l+r)/2);
    int vr=query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
}


int main(){
  int N;
  cin>>N;
  init(N);
  for(int i=0;i<N;i++){
    int a;
    cin>>a;
    update(i,a);
  }
  int ans=0;
  for(int i=0;i<N;i++){
    for(int j=i;j<N;j++){
      ans+=query(i,j,0,0,n);
    }
  }
  cout<<ans<<endl;
  return 0;
}

