int a[200000] = {0};
int where[200001] = {0};
int n;

ll solve(int mi, int l, int r){
  if(r - l == 1)return mi;
  if(r - l == 2)return a[l] + a[l + 1] + min(a[l], a[l + 1]);
  if(where[mi] == l){
    //pri3(mi, l, r);
    int i;
    for(i = mi + 1;i <= n;++i)if(l + 1 <= where[i] && where[i] < r)break;
    if(i == n + 1)return (ll)mi * (ll)(r - l);
    return (ll)mi * (ll)(r - l) + solve(mi + 1, l + 1, r);
  }
  if(where[mi] + 1 == r){
    //pri3(mi, l, r);
    int i;
    for(i = mi + 1;i <= n;++i)if(l <= where[i] && where[i] < r - 1)break;
    if(i == n + 1)return (ll)mi * (ll)(r - l);
    return (ll)mi * (ll)(r - l) + solve(mi + 1, l, r - 1);
  }
  int qwe = min(where[mi] - l + 1, r - where[mi]), rty = max(where[mi] - l + 1, r - where[mi]);
  ll res = (ll)qwe * (ll)(qwe + 1);
  res += (ll)(1 + r - l - rty - 1) * (ll)(1 + r - l - rty);
  res >>= 1;
  res += qwe * (rty - qwe);
  res *= (ll)mi;
  bool isl = (where[mi] - l > 0), isr = (r - where[mi] > 1);
  for(int i = mi + 1;isl || isr;++i){
    if(i > n)break;
    if(isl && l <= where[i] && where[i] < where[mi]){
      isl = false;
      //debug3(i, l, where[mi]);
      res += solve(i, l, where[mi]);
    }
    if(isr && where[mi] <= where[i] && where[i] < r){
      isr = false;
      res += solve(i, where[mi] + 1, r);
    }
  }
  return res;
}

