	long long int num, sum= 0;
	vector<pair<long long int, long long int> > arr(200000);

	cin>>num;
	for(long long int i= 0; i < num; i++)
	{
		cin>>arr[i].first;
		arr[i].second= 0;
	}

	for(long long int i= num-1; i >= 0; i--)
	{
		for(long long j= i+1; j < num; j++)
			if(arr[i].first > arr[j].first)
			{
				arr[i].second= arr[i].first*(j-i)+arr[j].second;
				break;
			}

		if(!arr[i].second)
			arr[i].second= arr[i].first*(num-i);

		sum+= arr[i].second;
	}

	cout<<sum<<endl;
	return 0;
}

