    for(int i = 0;i<n;++i)
        cin >> a[i],rm[i][0] = a[i];
    for(int i = 1;i<20;++i)
        for(int j = 0;j<(n-(1<<i)+1);++j)
            rm[j][i] = min(rm[j][i-1],rm[j+(1<<(i-1))][i-1]);
    ll ans = 0;
