            {
                if (gt(0,i-1)>a[i])
                    l1 = 0;
                else
                {
                    int r1 = 0;
                    while(l1-r1>1)
                    {
                        int mid = (l1+r1)/2;
                        if (gt(mid,i-1)>a[i])
                            l1 = mid;
                        else
                            r1 = mid;
                    }
                }
            }
