ll Solve(const vector<ll>& a, int l, int r)
{
    if (r - l <= 0) return 0;
    if (r - l == 1) return a[l];

    int minElementIndex = l;
    ll minElement = a[l];
    rep(i, l, r)
    {
        if (chmin(minElement, a[i]))
        {
            minElementIndex = i;
        }
    }

    return (minElement * ((r - minElementIndex) * (minElementIndex - l + 1))) + Solve(a, l, minElementIndex) + Solve(a, minElementIndex + 1, r);
}

