template<typename type>
struct BIT0 { // 0-index
	int N;
	int nn;
	vector<type> data;
	//動的はmap<int?,type>data
	BIT0(int n) {
		N = n + 1;
		data = vector<type>(n + 1, 0);
		nn = 1;
		while (nn * 2 <= N)nn *= 2;
	}
	void add(int i, type w) {
		// a[i] += w
		i++;
		for (int x = i; x < N; x += x & -x) {
			data[x] += w;
		}
	}
	type sum(int i) {
		// iまでの和 [0,i)
		type ret = 0;
		for (int x = i; x > 0; x -= x & -x) {
			ret += data[x];
		}
		return ret;
	}
	// [l, r)
	type sum(int l, int r) {
		return sum(r) - sum(l);
	}

	int lower_bound(type w) {
		//  w≦[0,x]以上となる最小のindex,x
		if (w <= 0) return 0;
		int x = 0;
		for (int k = nn; k > 0; k /= 2) {
			if (x + k <= N && data[x + k] < w) {
				w -= data[x + k];
				x += k;
			}
		}
		return x + 1;
	}
};

LL N;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N;
	VI a(N + 10);
	VI ra(N + 10);
	FOR(i, 0, N) {
		cin >> a[i];
		ra[a[i]] = i;
	}
	BIT0<int>bit(N + 10), rbit(N + 10);
	FOR(i, 1, N + 1) {
		int l = bit.lower_bound(bit.sum(ra[i]));
		int r = N-1  - rbit.lower_bound(rbit.sum(N - 1 - ra[i]));
		//cout << l << "," << r << endl;

		ans += i*(LL)(r - ra[i]+1)*(ra[i] - l+ 1 );
		bit.add(ra[i], 1);
		rbit.add(N - 1 - ra[i], 1);
	}
	cout << ans << "\n";

	return 0;
}

