// セグメント木を持つグロバール配列
ll n, dat[2 * MAX_N - 1];
ll N;
ll a[200010];

// 初期化
void init(ll n_) {
	// 簡単のため、要素数を2のべき乗に
	n = 1;
	while(n < n_) n *= 2;

	// 全ての値をINT_MAXに
	for(int i = 0; i < 2 * n - 1; i++) dat[i] = INF;
}

// k番目の値(0-indexed)をaに変更
void update(ll k, ll a) {
	// 葉の節点
	k += n - 1;
	dat[k] = a;
	// 登りながら更新
	while(k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}

// [a, b)の最小値を求める
// 後ろの方の引数は、計算の簡単のための引数
// kは節点の番号、１、rはその節点が[1,r)に対応づいていることを表す
// したがって、外からはquery(a, b, 0, 0, n)として呼ぶ
ll query(ll a, ll b, ll k, ll l, ll r) {
	// [a, b)と[l,r)が交差しなければ、INT_MAX
	if(r <= a or b <= l) return INF;

	// [a, b)が[l,r)を完全に含んでいれば、この節点の値
	if(a <= l and r <= b) return dat[k];
	else {
		// そうでなければ、2つの子の最小値
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	init(N);
	rep(i, 0, N) {
		cin >> a[i];
		update(i, a[i]);
	}

	ll rsl = 0;
	rep(l, 0, N) rep(r, l, N) {
		rsl += query(l, r + 1, 0, 0, n);
	}

	cout << rsl << endl;
}

