  vector<int> lright = first_exceeder(lb);
  vector<int> lleft = first_exceeder(lc);
  for (int i = 0; i < n; ++i) {
    ll left = n-lleft[n-1-i];
    ll right = lright[i];
    ans += (right-i)*(i-left+1)*(ll)la[i];
    // cerr << i << " " << la[i] << " " << left << " " << right << endl;
  }
  cout << ans << endl;
  return 0;
}

