int Find(int x)
{
	return fa[x]==x?x:fa[x]=Find(fa[x]);
}
void Union(int u,int v)
{
	u=Find(u),v=Find(v);
	if(u==v) return;
	fa[u]=v;
	siz[v]+=siz[u];
}
int main()
{
