	}
	for(int i=n;i>=1;i--)
	{
		int p=b[i],sl=1,sr=1;
		if(a[p-1]>a[p])
		{
			sl+=siz[Find(a[p-1])];
			Union(a[p],a[p-1]);
		}
		if(a[p+1]>a[p])
		{
			sr+=siz[Find(a[p+1])];
			Union(a[p],a[p+1]);
		}
		ans+=1LL*i*sl*sr;
	}
	printf("%lld\n",ans);
}

