int getId(int v) {
    return p[v] == v? v: p[v] = getId(p[v]);
}

void merge(int v, int u) {
    v = getId(v);
    u = getId(u);
    if (v != u) {
        p[v] = u;
        ll[u] = min(ll[u], ll[v]);
        rr[u] = max(rr[u], rr[v]);
    }
}

void solve() {
    for (int i = 0; i < n; i++) {
        p[i] = i;
        ll[i] = i;
        rr[i] = i;
    }
    vector<pair<int, int>> b;
    for (int i = 0; i < n; i++)
        b.pb(mp(a[i], i));

    sort(b.begin(), b.end(), greater<pair<int, int>>());

    long long answer = 0;
    for (auto x: b) {
        int pos = x.sc; 
        use[pos] = 1;
        for (int dx = -1; dx <= 1; dx += 2) {
            int y = pos + dx;
            if (0 <= y && y < n && use[y] == 1) {
                merge(y, pos); 
            }
        }
        int v = getId(pos);
        int left = pos - ll[v] + 1;
        int right = rr[v] - pos + 1;
        answer += x.fr * 1ll * left * right;
    }

    cout << answer << endl;

}

