	}

	build(1, 1, n);

	for (int i = 1; i <= n; i++) {
		ll l = (ll)get_max(1, 1, n, 1, id[i]);
		if (l == (ll)-inf) l = 1;
		else l++;

		ll r = (ll)get_min(1, 1, n, id[i], n);
		if (r == (ll)inf) r = n;
		else r--;

		ll ct = 0;
		if (l == id[i]) ct = r - l + 1;
		else ct = (r - id[i] + 1) * (id[i] - l) + (r - id[i] + 1);


		res += (ct * i);
		update(1, 1, n, id[i]);
	}

	cout << res;	
	return 0;
}

