using namespace std;
typedef long long LL;
typedef pair<LL,LL> P;
const LL mod=1e9+7;
const LL LINF=1LL<<62;

const int M_N=200001;

struct UnionFind{
    int par[M_N];

    void init(int n){
        for(int i=0;i<n;i++){
            par[i]=i;
        }
    }

    void unite(int x,int y){
        if(x>y){
            par[x]=y;
        }
        else{
            if(par[y]==y) return;
            unite(x,par[y]);
        }
    }

};

map<int,int> mp;

int main(){
    LL N;
    cin >> N;
    vector<LL> a;
    for(int i=0;i<N;i++){
        int s;
        cin >> s;
        a.push_back(s);
        mp[s]=i;
    }
    UnionFind uf,ruf;
    uf.init(N+1);
    ruf.init(N+1);
    for(int i=0;i<N-1;i++){
        uf.unite(a[i+1],a[i]);
    }
    for(int i=N-1;i>0;i--){
       ruf.unite(a[i-1],a[i]);
    }
    LL ans=0;
    for(int i=0;i<N;i++){
        LL l,r;
        l=i-mp[uf.par[a[i]]]-1;
        r=mp[ruf.par[a[i]]]-i-1;
        if(a[i]==uf.par[a[i]]){
            l=i;
        }
        if(a[i]==ruf.par[a[i]]){
            r=N-i-1;
        }
        ans+=a[i]*((r+l+1LL)*(r+l+2LL)/2LL-l*(l+1LL)/2LL-r*(r+1LL)/2LL);
    }
    cout << ans << endl;
    return 0;
}

