// sparse_table {{{
template <class Monoid>
class sparse_table {
  public:
    using value_type = typename Monoid::value_type;
  private:
    size_t len;
    vector<vector<value_type>> data;
  public:
    sparse_table(vector<value_type> const& v): len(v.size()), data(len) {
      for (auto i = 0; i < len; i++)
        data[i].push_back(v[i]);
      for (auto j = 1; (1 << j) <= len; j++) {
        for (auto i = 0; i < len; i++) {
          if (i + (1 << j) > len) break;
          data[i].push_back(
              Monoid::product(data[i][j - 1], data[i + (1 << (j - 1))][j - 1]));
        }
      }
    }
    value_type query(int left, int right) {
      int width = right - left, w = 0;
      while ((1 << (w + 1)) <= width) w++;
      value_type ans = Monoid::identity;
      int pos = left;
      for (int i = 0; (1 << i) <= width; i++) {
        int w = 1 << i;
        if (!(w & width)) continue;
        ans = Monoid::product(ans, data[pos][i]);
        pos += w;
      }
      return ans;
    }
};
