using LL = long long;

LL N;
vector<LL> A, I;

LL count(auto l, auto r) {
  if(l < 0 || N <= r) return 0;
  if(r < l) return 0;
  return (r-l+1)*(r-l+2)/2;
}

LL dfs(auto l, auto r, auto i) {
  if(l < 0 || N <= r) return 0;
  if(r < l) return 0;
  if(N <= i) return 0;
  if(I[i] < l || r < I[i]) return dfs(l, r, i+1);
  auto n = count(l, r);
  n -= count(l, I[i]-1);
  n -= count(I[i]+1, r);
  return dfs(l, I[i]-1, i+1) + A[I[i]]*n + dfs(I[i]+1, r, i+1);
}

int main() {
  cin >> N;
  A.resize(N);
  for(auto& i: A) cin >> i;
  I.resize(N);
  for(auto i = 0; i < N; ++i) I[A[i]-1] = i;
  cout << dfs(0ll, N-1, 0) << endl;
}

