void upd(int v , int tl ,int tr , int pos ,int x){
	if(tl == tr){
		t[v] = x;
		return;
	}
	int mid = ( tl + tr) >> 1;
	if(pos <= mid)
		upd(v + v , tl , mid , pos , x);
	else
		upd(v + v + 1 , mid + 1 , tr , pos , x);
	t[v] = min(t[v + v] , t[v + v + 1]);
}
int get(int v , int tl , int tr , int l , int r){
	if(l > r)
		return 1e18;
	if(tl == l && tr == r)
		return t[v];
	int mid = (tl + tr) >> 1;
	return min(get(v + v , tl , mid , l , min(mid , r)) 
			   , get(v + v + 1 , mid + 1 , tr , max(mid + 1 , l) , r));
}
