    vector<mint> dp(N);
    rep(i, N) {
        int l = -1, r = i;
        while (r - l > 1) {
            int mid = (l + r) / 2;
            if (st.query(mid, i + 1) == A[i]) r = mid;
            else l = mid; 
        }
        dp[i] = (l >= 0 ? dp[l] : 0) + A[i] * (i + 1 - r);
    }

    mint ans = 0;
    rep(i, N) ans += dp[i];
    cout << ans << endl;
}

