#define SIZE 200000
class unionfind
{
public:
	int par[SIZE];
	int ran[SIZE];
	int ren[SIZE];
	void init()
	{
		for (int i = 0; i<SIZE; i++)
		{
			par[i] = i;
			ran[i] = 0;
			ren[i] = 1;
		}
	}
	int find(int a)
	{
		if (a == par[a])return a;
		else return par[a] = find(par[a]);
	}
	void unite(int a, int b)
	{
		a = find(a);
		b = find(b);
		if (a == b)return;
		if (ran[a]>ran[b])
		{
			par[b] = a;
			ren[a] += ren[b];
		}
		else
		{
			par[a] = b;
			ren[b] += ren[a];
		}
		if (ran[a] == ran[b])ran[b]++;
	}
};
unionfind uf;
int dat[200000];
typedef long long ll;
int main()
{
	int num;
	scanf("%d", &num);
	uf.init();
	vector<int>v;
	for (int i = 0; i < num; i++)
	{
		int z;
		scanf("%d", &z);
		z--;
		v.push_back(z);
		dat[z] = i;
	}
	ll ans = 0;
	for (int i = num - 1; i >= 0; i--)
	{
		ll m = 0;
		if (dat[i] != 0)if (v[dat[i] - 1] > i)
		{
			ll t = uf.ren[uf.find(dat[i] - 1)];
			m += t*(t + 1) / 2;
			uf.unite(dat[i], dat[i] - 1);
		}
		if (dat[i] != num - 1)if (v[dat[i] + 1] > i)
		{
			ll t = uf.ren[uf.find(dat[i] + 1)];
			m += t*(t + 1) / 2;
			uf.unite(dat[i], dat[i] + 1);
		}
		ll t = uf.ren[uf.find(dat[i])];
		ans += (ll)(i + 1)*(t*(t + 1) / 2 - m);
	}
	printf("%lld\n", ans);
}

