lint sum(lint l,lint r){
    if(l==r) return A[l];

    lint min=200001;
    lint im;
    for(int i=l;i<=r;i++){
        if(A[i]<min){ min=A[i]; im=i; }
    }
    lint s=(im-l+1)*(r-im+1);
    return min*s+(im>l?sum(l,im-1):0)+(im<r?sum(im+1,r):0);    
}
