// SegmentTree<int> seg(n, 0x7FFFFFFF, [](int a, int b){return min(a, b);});
template <typename T>
class SegmentTree {
    using func_t = function<T(T, T)>;
    const int n;
    const T id;
    func_t merge;
    vector<T> data;
    T sub(int l, int r, int node, int lb, int ub) {
        if (ub <= l || r <= lb) return id;
        if (l <= lb && ub <= r) return data[node];
        T vl = sub(l, r, node * 2 + 0, lb, (lb + ub) / 2);
        T vr = sub(l, r, node * 2 + 1, (lb + ub) / 2, ub);
        return merge(vl, vr);
    }
    int size(int n) {
            int res;
            for (res = 1; res < n; res <<= 1);
            return res;
    }
public:
    SegmentTree(int n, T id, func_t merge) :
        n(size(n)), id(id), merge(merge), data(size(n) * 2, id) {}
    void update(int p, T val) {
        assert (0 <= p && p < n);
        p += n;
        data[p] = val;
        while (p /= 2) {
            int l = p * 2, r = p * 2 + 1;
            data[p] = merge(data[l], data[r]);
        }
    }
    T find(int l, int r) {
        return sub(l, r, 1, 0, n);
    }
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);
    int n; cin >> n;
    vector<int> v(n); cin >> v;
    SegmentTree<P> seg(n, P(inf, inf), [](const P& p1, const P& p2) {
        return min(p1, p2);
    });
    REP(i, n) {
        seg.update(i, P(v[i], i));
    }
    ll ans = 0;
    stack<P> S; S.push({0, n});
    while ( !S.empty() ) {
        P p = S.top(); S.pop();
        ll l, r; tie(l, r) = p;
        if (l < r) {
            ll val, pos; P p = seg.find(l, r); tie(val, pos) = p;
            ll left = pos-l+1, right = r-pos;
            ans += left * right * val;
            S.push({l, pos});
            S.push({pos+1, r});
        }
    }
    cout << ans << endl;
}

