			seg[x]++;
			x /= 2;
		}
		if(left[i] > where[i]) while(true);
		else if(right[i] < where[i]) return -1;
	}
	for(int i=1; i<=N; i++){
		ans += ((right[i]-where[i]+1)*(where[i]-left[i]+1)*(lld)i);
		//printf("%lld %lld\n",left[i],right[i]);
	}
