// segtree struct
// 大体 http://arc080.contest.atcoder.jp/submissions/1530583 のパクリ

// to change データ数を2^nになるように水増しする関係で、datに絶対影響しない値(UNDEF)が必要
// 問題によってSEG_UNDEFの中身は書き換えなければならない
const li SEG_UNDEF = 1145141919;


struct segtree{
  li n;
  li dat[2*MAX_N-1]; // ここの型は場合によって変わるはず

  void init(li n_){
    n = 1;
    while(n < n_) n *= 2;
    for(li i = 0; i < 2*n-1; i++) dat[i] = SEG_UNDEF;
  }

  // k番目の値をaに書き換える(to change)
  void update(li k, li a){
    k += n-1;
    dat[k] = a;
    while(k > 0){
      k = (k-1)/2;
      dat[k] = min(dat[k*2+1], dat[k*2+2]);
    }
  }

  // [a:b)の区間におけるデータの呼び出し。
  // a < bじゃないとコアダンプする
  li query(li a, li b){
    return querybody(a,b,0,0,n);
  }

  li querybody(li a, li b, li k, li l, li r){
    if(r <= a || b <= l) return SEG_UNDEF;
    if(a <= l && r <= b) return dat[k];
    else{
      li vl = querybody(a,b,k*2+1,l,(l+r)/2);
      li vr = querybody(a,b,k*2+2,(l+r)/2,r);
      // change
      return min(vl, vr);
    }
  }

  void show(){
    cout<<n*2-1<<"datas"<<endl;
    for(li i=0;i<n*2-1;++i){
      cout<<i<<","<<dat[i]<<endl;
    }
  }
};

// variables

segtree sg;
li N;
vector<li> ids;


li dfs(li beg, li end){
  //cout << beg<<","<<end<<endl;
  li result = 0;
  li value = sg.query(beg,end+1);
  li id = ids[value-1];
  //  cout<<"min is "<<value<<" id is "<<id<<endl; //debug
  li l = id - beg + 1;
  li r = end - id + 1;
  result += value * l * r;
  if(id-1 >= beg) {result += dfs(beg, id-1);}
  if(id+1 <=end ){result += dfs(id+1,end);}
  return result;
}


int main(){
  cin >> N;
  ids.resize(N);
  sg.init(N);
  for(li i=0;i<N;++i){
    li k;
    cin >> k;
    sg.update(i,k);
    ids[k-1]=i;
  }
  //sg.show(); //debug
  cout<<dfs(0,N-1);
  return 0;
}

