void echoln() {
	fputc('\n', stdout);
}
void echoln(const char * fmt, ...) {
	va_list arg;
	va_start(arg, fmt);
	vprintf(fmt, arg);
	va_end(arg);
	fputc('\n', stdout);
}

int main() {
	vector<int> a = nextIntVec(nextInt());
	vector<int> b(a.size());
	int64 sum = 0;
	int rr=a.size()-1;
	for(int l=0; l<=rr; ++l) {
		int m = a[l];
		int ll = l;
		int difficult = 0;
		for(int r=l; r<=rr; ++r) {
			if(a[r]<m) {
				++difficult;
				m = a[r];
				b[ll] = r;
				ll = r;
				if(r<b[r]) {
					sum += (int64)m * (b[r]-r);
					r = b[r] - 1;
					continue;
				}
			}
			sum += m;
		}
		b[ll] = (int)a.size();
		if(rr-l<difficult+difficult) {
			++l;
			b.clear();
			b.resize(a.size(), a.size());
			for(; l<=rr; --rr) {
				int m = a[rr];
				int ll = rr;
				difficult = 0;
				for(int r=rr; l<=r; --r) {
					if(a[r]<m) {
						++difficult;
						m = a[r];
						b[ll] = r;
						ll = r;
						if(b[r]<r) {
							sum += (int64)m * (r-b[r]);
							r = b[r] + 1;
							continue;
						}
					}
					sum += m;
				}
				b[ll] = l-1;
				if(rr-l<difficult+difficult) {
					--rr;
					b.clear();
					b.resize(a.size(), 0);
					break;
				}
			}
		}
	}
	echoln("%lld", sum);
	return 0;
}

