int n;
int a[200005],mina[600000];

void build(int id,int l,int r){
	if(l==r) return (void)(mina[id]=a[l]);
	int mid=(l+r)/2;
	build(id<<1,l,mid);
	build(id<<1|1,mid+1,r);
	mina[id]=min(mina[id<<1],mina[id<<1|1]);
}

int getr(int id,int l,int r,int x,int c){
	if(l==r) return c<=mina[id]?r+1:r;
	int mid=(l+r)/2;
	if(x>mid-1) return getr(id<<1|1,mid+1,r,x,c);
	else{
		if(mina[id<<1]<c){
			int tmp=getr(id<<1,l,mid,x,c);
			if(tmp==mid+1) return getr(id<<1|1,mid+1,r,mid,c);
			else return tmp;
		}
		else return getr(id<<1|1,mid+1,r,mid,c);
	}
}

int getl(int id,int l,int r,int x,int c){
	if(l==r) return c<=mina[id]?l-1:l;
	int mid=(l+r)/2;
	if(x<=mid+1) return getl(id<<1,l,mid,x,c);
	else{
		if(mina[id<<1|1]<c){
			int tmp=getl(id<<1|1,mid+1,r,x,c);
			if(tmp==mid) return getl(id<<1,l,mid,mid+1,c);
			else return tmp;
		}
		else return getl(id<<1,l,mid,mid+1,c);
	}
}

