#include<stdio.h>
#define MAX 200005

int t[MAX << 2], a[MAX];
inline int ls(int x) { return x << 1; }
inline int rs(int x) { return x << 1 | 1; }
inline int min(int a, int b) { return (a < b) ? a : b; }
inline void pushUp(int p) { t[p] = min(t[ls(p)], t[rs(p)]); } 
inline void build(int p, int l, int r) {
	if(l == r) t[p] = a[l];
	else {
		int mid = (l + r) >> 1;
		build(ls(p), l, mid);
		build(rs(p), mid + 1, r);
		pushUp(p);
	}
}
inline int query(int nl, int nr, int l, int r, int p) {
	if(nl <= l && r <= nr) return t[p];
	int mid = (l + r) >> 1, res = 2147483647;
	if(mid >= nl) res = min(res, query(nl, nr, l, mid, ls(p)));
	if(mid < nr) res = min(res, query(nl, nr, mid + 1, r, rs(p)));
	return res;
}

