	}

	for (int i = N; i >= 1;i--) {
		left[i] = num[i];
		right[i] = N - num[i] - 1;
		for (int j = num[i] + 1; j < N;) {

			if (flag[j]) {
				right[i] = j - num[i] - 1;
				break;
			}
			else {
				bag = right[row[j]] + 1;

				j += bag;

			}
