int N;
vi A;
vii range;

int main(int argc, char** argv) {
  cin >> N;
  A.resize(N+2);
  A[0] = -INF; // dummy
  A[N+1] = -INF; // dummy

  for (int i=1; i<=N; i++) {
    int a;
    cin >> a;

    A[i] = a;
  }

  // [a,b) = range[x]
  // xは、Aのindex [a,b)で最小
  range.resize(N+1);

  {
    // Range Minimum Query
    SegmentTree<int> rmq(
            [](int a, int b) {
              return max(a, b);
            },
            -INF);
    rmq.init(N+10);

    for (int i=1; i<=N; i++) {
      int a = A[i];
      int k = rmq.query(1, a);
      range[a].first = k<0 ? 1 : k+1;
      rmq.update(a, i);
//cerr << a << ", k " << k << endl;
    }
  }
  {
    // Range Minimum Query
    SegmentTree<int> rmq(
            [](int a, int b) {
              return min(a, b);
            },
            INF);
    rmq.init(N+10);

    for (int i=N; i>=1; i--) {
      int a = A[i];
      int k = rmq.query(1, a);
      range[a].second = k>N ? N+1 : k;
      rmq.update(a, i);
//cerr << a << ", k " << k << endl;
    }
  }

//for (int i=1; i<=N; i++) {
//  int a = A[i];
//  auto p = range[a];
//  cerr << "a " << a << ": [" << p.first << ", " << p.second << ")" << endl;
//}

  ll ret = 0;
  for (int i=1; i<=N; i++) {
    int a = A[i];
    int s = range[a].first;
    assert(1<=s && s<=i);
    int e = range[a].second;
    assert(i<=e && e<=N+1);

    ret += ll(a)*ll(i-s+1)*ll(e-i);
  }

  cout << ret << endl;

  return 0;
}

