    if (query(mi, rr) < v) {
      lo = mi;
    } else {
      hi = mi;
    }
  }
  return lo + 1;
}

int find_right(int ll, int v) {
  int lo = ll - 1, hi = n;
  fprintf(stderr, "(%d, %d]\n", lo, hi);
  while (hi - lo > 1) {
    int mi = (lo + hi) >> 1;
    fprintf(stderr, "querying[%d,%d] : %d\n", ll, mi, query(ll, mi));
    if (query(ll, mi) < v) {
      hi = mi;
    } else {
      lo = mi;
    }
  }
  return hi - 1;
}

