template<typename T,typename U>
int lower_bound_sg(U& sg,T c,int n){//各点0,1が格納されていて、累積和がcと一致する最小のindexを返す
    int sz = sg.sz;
    int lb = -1;
    int ub = n+2;
    while(ub-lb>1){
        int mid = (lb+ub)/2;
        int temp = sg.query(0, mid, true);//[0,mid)の和
        if(temp<c){
            lb = mid;
        }else{
            ub = mid;
        }
    }
    return lb;
}

