    ll ans = 0;
    UnionFind uf(n + 1);
    for (int j = n; j >= 1; j--) {
        int i = idx[j];
        ans += a[i];
        if (i - 1 >= 1 && a[i - 1] > a[i]) {
            ans += 1LL * uf.size(i - 1) * uf.size(i) * a[i];
            uf.unionSet(i - 1, i);
        }
        if (i + 1 <= n && a[i + 1] > a[i]) {
            ans += 1LL * uf.size(i + 1) * uf.size(i) * a[i];
            uf.unionSet(i + 1, i);
        }
    }
    cout << ans << endl;
    return 0;
}

