		long res = i;
		if (index - 1 >= 0 && usedIndex[index - 1]) {
			res *= (long)uni.size(A[index - 1]) + 1;
			uni.unite(A[index], A[index - 1]);
		}
		if (index + 1 < N && usedIndex[index + 1]) {
			res *= (long)uni.size(A[index + 1]) + 1;
			uni.unite(A[index], A[index + 1]);
		}
		usedIndex[index] = true;
		sum += res;
	}
	cout << sum<<endl;

	return 0;
}

