int main() {
	int n;
	scanf("%d", &n);

	//大きい要素順に取り出せるように要素を指定すると、ai上での添字が返って
	//くるようにする。0,n+1を番兵として1,2,…nに要素を格納していく。
	for (int i = 1; i <= n; i++) {
		scanf("%d", a + i);
		pos[a[i]] = i;
	}

	//各番号の前後をもっておきたい。初期化。
	for (int i = 0; i <= n + 1; i++) {
		pr[i] = i - 1;
		ne[i] = i + 1;
