	for (int i = n; i >= 1; i--) {
		int j = pos[i];
		ans += i * 1LL * (j - pr[j]) * (ne[j] - j);

		//これから先入ってくる要素は、すでにある要素より小さい。
		//つまり今ある要素は以降挿入される要素を最小値区間にかならず含まれる。

		//要素を挿入した区間は拡張される。

		//左端として、挿入した要素の右端を持つ区間は、挿入した要素の左端まで拡張
		pr[ne[j]] = pr[j];

		//右端も同様
		ne[pr[j]] = ne[j];
	}
	cout << ans << endl;
