const int M_N=200001;

struct UnionFind{
    int par[M_N];

    void init(int n){
        for(int i=0;i<n;i++){
            par[i]=i;
        }
    }

    void unite(int x,int y){
        if(x>y){
            par[x]=y;
        }
        else{
            if(par[y]==y) return;
            unite(x,par[y]);
        }
    }

};

