#include <bits/stdc++.h>
template <typename T>
struct SegmentTreeUpdMin {
  int n;
  const T inf = std::numeric_limits<T>::max();
  std::vector<T> node;
  SegmentTreeUpdMin(std::vector<T> v) {
    int sz = v.size();
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n, inf);
    for(int i=0;i<sz;++i) node[i+n-1] = v[i];
    for(int i=n-2;i>=0;--i) node[i] = std::min(node[2*i+1], node[2*i+2]);
  }
  void update(int idx, T val) {
    assert(0 <= idx && idx < n);
    node[idx + n - 1] = val;
    idx = idx + n - 1;
    while(idx > 0) {
      idx = (idx - 1) / 2;
      node[idx] = std::min(node[2*idx + 1], node[2*idx + 2]);
    }
  }
  T query(int a, int b, int k, int l, int r) {
    if(r <= a || b <= l) return inf;
    if(a <= l && r <= b) return node[k];
    T vl = query(a, b, k*2+1, l, (l+r)/2);
    T vr = query(a, b, k*2+2, (l+r)/2, r);
    return std::min(vl, vr);
  }
  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }
};
template <typename T>
class SegmentTreeUpdMax {
    int n;
    const T inf_min = std::numeric_limits<T>::min();
    std::vector<T> node;
public:
    SegmentTreeUpdMax() {}
    SegmentTreeUpdMax(std::vector<T> v) {
        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n, inf_min);
        for(int i=0;i<sz;++i) node[i+n-1] = v[i];
        for(int i=n-2;i>=0;--i) node[i] = std::max(node[2*i+1], node[2*i+2]);
    }
    void update(int idx, T val) {
        assert(0 <= idx && idx < n);
        node[idx + n - 1] = val;
        idx = idx + n - 1;
        while(idx > 0) {
            idx = (idx - 1) / 2;
            node[idx] = std::max(node[2*idx + 1], node[2 * idx + 2]);
        }
    }
    T query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return inf_min;
        if(a <= l && r <= b) return node[k];
        T vl = query(a, b, k*2+1, l, (l+r)/2);
        T vr = query(a, b, k*2+2, (l+r)/2, r);
        return std::max(vl, vr);
    }
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};
