struct ValuePos {
	int value;
	int pos;
	ValuePos(int value, int pos):value(value), pos(pos){}
	ValuePos() {}
};

bool operator > (const ValuePos& left, const ValuePos& right) {
	return tie(left.value, left.pos) > tie(right.value, right.pos);
}

void solve() {
	int N; cin >> N;
	vector<ValuePos> A(N); // value, pos
	for (int i = 0; i < N; ++i) {
		int a; cin >> a;
		A[i] = ValuePos(a, i);
	}

	priority_queue<ValuePos, vector<ValuePos>, greater<ValuePos> > que;
	for (int i = 0; i < N; ++i) {
		que.emplace(A[i]);
	}

	int res = 0;
	set<int> memo;
	memo.insert(-1);
	memo.insert(N);

	while (not que.empty()) {
		ValuePos top = que.top(); que.pop();
		auto it = memo.lower_bound(top.pos);
		pair<int, int> range;
		range.second = *it - top.pos;
		--it;
		range.first = top.pos - *it;

		res += top.value * (range.first * range.second);
		memo.insert(top.pos);
	}
	cout << res << endl;
}

