int N;
int main() {
	cin >> N;
	st.push(make_pair(-1, 0));
	long long sum = 0;
	REP(i, 0, N + 1) {
		int buf;
		if (i == N) {
			buf = 0;
		} else {
			cin >> buf;
		}
		while (st.top().second > buf) {
			int num = st.top().second;
			int idx = st.top().first;
			int left, right;
			right = i - idx;
			st.pop();
			left = idx - st.top().first;
			sum += (long long)num * left * right;
		}
		st.push(make_pair(i, buf));
	}
	cout << sum << endl;
	return 0;
}

