void solve(){
    int N;cin>>N;
    set<ll> st;
    vector<ll> a(N);
    REP(i, N) cin >> a[i];
    vector<ll> ord(N);
    iota(All(ord),0);
    sort(All(ord),[&](int x,int y){return a[x]<a[y];});
    Factorial get(N);
    ll ans=(ord[0]+1)*(N-ord[0]);
    st.insert(ord[0]);
    REP(i,N-1){
        auto x=st.lower_bound(ord[i+1]);
        if(x==st.begin()){
            ans+=(i+2)*(ord[i+1]+1)*((*x)-ord[i+1]);
        }else{
            auto y=x;y--;
            if(x==st.end()){
                ans+=(i+2)*(ord[i+1]-(*y))*(N-ord[i+1]);
            }else{
                ans+=(i+2)*(ord[i+1]-(*y))*((*x)-ord[i+1]);
            }
        }
        st.insert(ord[i+1]);
    }
    cout<<ans<<endl;
}

