using namespace std;
class RMQ{
  private:
    static const int MAX_N = 1 << 17;
    int n, dat[2*MAX_N -1];
    int rec(int a,int b,int k,int l,int r){
      if(b <= l || r <= a){
        return INT_MAX;
      }

      if(a<=l && r<=b){
        return dat[k];
      }else{
        int rl = rec(a,b,2*k+1,l,(l+r)/2);
        int rr = rec(a,b,2*k+2,(l+r)/2,r);
        return min(rl,rr);
      }
    }

  public:
    void init(int n_){
      n=1;
      while(n < n_) n*=2;

      for(int i=0;i<2*n-1;i++){
      dat[i] = INT_MAX;
      }
    }

    void update(int k, int a){
      int reaf = k+n-1;
      dat[reaf]=a;
      while(reaf>0){
        reaf = (reaf-1)/2;
        dat[reaf]=min(dat[reaf*2+1],dat[2*reaf+2]);
      }
    }

    int query(int a,int b){
      return rec(a,b+1,0,0,n);
    }
};

int main(void){

    int n; cin >> n;
    RMQ r;
    r.init(n);
    long long ans = 0;
    for(int i = 0; i< n; i++){
        int tmp;
        cin >> tmp;
        r.update(i,tmp);
        ans += tmp;
    }

    for(int i = 0; i< n; i++) {
        for(int j = i + 1; j < n; j++) {
            ans += r.query(i, j);
        }
    }
    cout << ans << endl;
}

