int n, a[maxn], p[maxn];

int t[maxn];
void add(int x)
{
	while (x <= n)
	{
		++t[x];
		x += lowbit(x);
	}
}
int sum(int x)
{
	int cnt = 0;
	while (x)
	{
		cnt += t[x];
		x -= lowbit(x);
	}
	return cnt;
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++)
	{
		scanf("%d", a + i);
