	}

	ll ans = 0;
	for (int i = 1; i <= n; i++)
	{
		int L, R, l, r, mid;

		l = 1; r = p[i];
		while (l < r)
		{
			mid = (l + r) / 2;
			if (sum(p[i]) - sum(mid - 1))
				l = mid + 1;
			else
				r = mid;
		}
		L = r;

		l = p[i]; r = n;
		while (l < r)
		{
			mid = (l + r) / 2 + 1;
			if (sum(mid) - sum(p[i]))
				r = mid - 1;
