	};
};

class AGC005B
{
public:
	AGC005B()
	{
		cin >> n;
		n += 1;

		a.resize(n);
		a[0].index = 0;
		a[0].value = 0;
		rep(i, 1, n)
		{
			cin >> a[i].value;
			a[i].index = i;
		}
	}
	void Run(void)
	{
		vector<A> a_sort;
		copy(all(a), back_inserter(a_sort));
		sort(all(a_sort));

		ll min = a[1].value;
		vector<ll> memo(n, 0);
		memo[1] = a[1].value;
		rep(i, 2, n)
		{
			if (a[i].value < min)
			{
				memo[i] = a[i].value * a[i].index;
				min = a[i].value;
			}
			else if (a[i - 1].value < a[i].value)
			{
				memo[i] = memo[i - 1] + a[i].value;
			}
			else
			{
				auto it = lower_bound(all(a_sort), a[i]);
				it--;
				memo[i] = a[i].value * (a[i].index - it->index) + memo[it->index];
			}
		}

		cout << accumulate(all(memo), 0LL);
	}
private:
	ll n;
	vector <A> a;
};

int main()
{
	AGC005B agc005b;
	agc005b.Run();

	return 0;
}

