typedef ll bsearch_t;
bsearch_t bin_search(bsearch_t low, bsearch_t high, function<bool(bsearch_t)> func) {
    --low;
    bsearch_t c;
    while (low + 1 < high) {
        c = (low + high) / 2;
        (func(c) ? high : low) = c;
    }
    return high;
}




template<typename T = ll>
class Bitree {
public:
    int size_;
    vector<T> data_;
    Bitree(int size_) :size_(size_ + 1), data_(size_ + 1) {}

    // 1..rの範囲の値の和を求める．
    T sum(int r) {
        T s = 0;
        while (r) {
            s += data_[r];
            r -= r & -r; //  r&-r と書くことで最下のビットを得る
        }
        return s;
    }
    // l..rの範囲の値の和を求める
    inline T sum(int l, int r) { return sum(r) - sum(l - 1); }
    // idxの要素の値をval増やす
    void add(int idx, T val) {
        while (idx <= size_) {
            data_[idx] += val;
            idx += idx & -idx;
        }
    }
};




