// Union-Find
class UF {
public:
    vector<Int> par, sz;
    UF(Int n) : par(n), sz(n) {
        for (Int i = 0; i < n; i++) {
            par[i] = i;
            sz[i] = 1;
        }
    }
    Int root(Int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }
    void unite(Int x, Int y) {
        Int rx = root(x);
        Int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
        sz[ry] += sz[rx];
    }
};

