    vector<int> a(N);
    for (int i = 0; i < N; ++i)
        cin >> a[i];

    SegTree segtree(a);
    ll ans = 0;
    for (int i = 0; i < N; ++i) {
        int l = segtree.rsearch(0, i, a[i]);
        int r = segtree.lsearch(i + 1, N, a[i]);
        ans += (ll)a[i] * (i - l) * (r - i);
    }

    cout << ans << '\n';
    return 0;
}

