function<int(int, int)> lambda = [](int a, int b) {
	return max(a, b);
};

int main() {
	cin >> N;
	pos.resize(N+1);
	for (int n = 1; n <= N; n++) {
		int a;
		cin >> a;
		pos[a] = n;
	}
	segTree_init(seg, N + 2, 0);
	segTree_set(seg,0,1,lambda);
	segTree_set(seg, N + 1, 1, lambda);
	long long ans = 0;
	for (int n = 1; n <= N; n++) {
		//左
		int s = 0, e = pos[n];
		while (e - s > 1) {
			int m = (e + s) / 2;
			if (segTree_get(seg, m, pos[n], lambda, 0) == 1) {
				s = m;
			}
			else e = m;
		}
		long long left = pos[n] - s;
		s = pos[n], e = N + 1;
		while (e - s > 1) {
			int m = (e + s) / 2;
			if (segTree_get(seg, pos[n], m, lambda, 0) == 1) {
				e = m;
			}
			else s = m;
		}
		long long right = e - pos[n];
		ans += n * left * right;
		segTree_set(seg, pos[n], 1, lambda);
	}
	cout << ans << endl;
	return 0;
}

