const int BS=18;

void bitadd(int *bit,int i,int v)
{
  int p=i+1;
  while(p<1<<BS){
    bit[p]=max(bit[p],v);
    p+=p&-p;
  }
}

int bitmax(int *bit,int i)
{
  int p=i+1,ret=-1000000000;
  while(p>0){
    ret=max(ret,bit[p]);
    p-=p&-p;
  }
  return ret;
}




