using namespace std;

class UnionFindS{
private:
    vector<int> par;
public:
    UnionFindS(int n){
        par=vector<int>(n,-1);
    }
    int find(int x){
        if(par.at(x)<0) return x;
        else return par.at(x)=find(par.at(x));
    }
    int size(int x){
        return -par.at(find(x));
    }
    void unite(int x, int y){
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(size(x)<size(y)) swap(x,y);
        par.at(x)+=par.at(y);
        par.at(y)=x;
    }
    bool same(int x, int y){
        return find(x)==find(y);
    }
};

signed main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin>>n;
    vector<int> a(n),b(n);
    rep(i,n){
        cin>>a.at(i);
        b.at(a.at(i)-1)=i;
    }
    UnionFindS uni(n);
    int ans=0;
    for(int i=n-1; i>=0; i--){
        int pl=b.at(i);
        int s=0,t=0;
        if(pl>0)if(a.at(pl-1)>i+1){
            s=uni.size(pl-1);
            uni.unite(pl,pl-1);
        }
        if(pl<n-1)if(a.at(pl+1)>i+1){
            t=uni.size(pl+1);
            uni.unite(pl,pl+1);
        }
        ans+=(i+1)*(s+1)*(t+1);
    }
    cout<<ans<<endl;
}

