  if(r - l < 0) return 0;
  int mn = query(l,r+1,0,0,n);
  int i = mnidx[mn];
  int ret = mn * (i - l + 1) * (r - i + 1);
  ret += dfs(i+1,r);
  ret += dfs(l,i-1);
  return ret;
}

