using namespace std;

llong n, b[MXN], ans, t[MXN * 4];

void build(int v, int tl, int tr){
	if(tl == tr){
		t[v] = b[tl];
		return ;
	}
	int tm = (tl + tr) / 2;
	build(v * 2, tl, tm);
	build(v * 2 + 1, tm + 1, tr);
	t[v] = min(t[v * 2], t[v * 2 + 1]);
}

llong get(int v, int tl, int tr, int L, int R){
	if(L <= tl && tr <= R){
		return t[v];
	}
	if(R < tl || tr < L || L > R){
		return INF;
	}
	int tm = (tl + tr) / 2;
	return min(get(v * 2, tl, tm, L, R), get(v * 2 + 1, tm + 1, tr, L, R));
}

llong getL(llong R, llong x){
	R--;
	llong l = 1, r = R;
	while(r - l > 1){
		llong m = (r + l) / 2;
		if(get(1, 1, n, m, R) > x){
			r = m;
		}else{
			l = m;
		}
	}
	if(get(1, 1, n, l, R) > x) return l;
	else if(get(1, 1, n, r, R) > x) return r;
	else return R + 1;
}

llong getR(llong L, llong x){
	L++;
	llong l = L, r = n;
	while(r - l > 1){
		llong m = (r + l) / 2;
		if(get(1, 1, n, L, m) > x){
			l = m;
		}else{
			r = m;
		}
	}
	if(get(1, 1, n, L, r) > x) return r;
	else if(get(1, 1, n, L, l) > x) return l;
	else return L - 1;
}

