	for(int i = 1; i <= n; i++){
		cin >> b[i];
	}
	build(1, 1, n);
	for(int i = 1; i <= n; i++){
		llong cntL = abs(getL(i, b[i]) - i) + 1, cntR = abs(getR(i, b[i]) - i) + 1;
		ans += cntL * cntR * b[i];
	}
	cout << ans;
	return 0;
}

