		int pos = valpos.second;
		check[pos] = true;
		int right = 1;
		int left = 1;
		if (pos + 1 < N and check[pos + 1]) {
			right += uf.count(pos + 1);
			uf.unite(pos, pos + 1);
		}
		if (pos - 1 >= 0 and check[pos - 1]) {
			left += uf.count(pos - 1);
			uf.unite(pos, pos - 1);
		}

		res += val * (left*right);
	}
	cout << res << endl;
}

