int main(){
    int N;cin>>N;
    vector<int> pos(N+1);
    for(int i=0;i<N;i++){
        int a;
        cin>>a;
        pos[a]=i;
    }
    map<int,int> m;
    m[N-1]=0;
    LL res=0;
    for(int i=1;i<=N;i++){
        auto it=m.lower_bound(pos[i]);
        int l=it->second;
        int r=it->first;
        LL L=pos[i]-l+1;
        LL R=r-pos[i]+1;
        res+=L*R*i;
        if(pos[i]==r){
            m.erase(r);
            m[r-1]=l;
        }
        else if(pos[i]==l){
            m[r]=l+1;
        }
        else{
            m[r]=pos[i]+1;
            m[pos[i]-1]=l;
        }
    }
    cout<<res<<endl;
    return 0;
}

