//区間に対する演算を高速に求めるためのセグメント木
namespace SegmentTree {
	//コンストラクタ
	//tに参照型（ポインタ系）使ったらどうなるか不明、えぐいバグ出しそう
	//int double とかのnumeric系に絞ったほうがよさげ
	//n 要素数
	//invalid_value 無効な数値　任意のaについてmarge(a,invalidvalue) = a, marge(invalid_value, a) = a　となるような値
	//eval_func_invalid_value(t value) valueが不正な数値化どうか調べる
	//　*marge(t a, t, b) aとbから a∪bを求める関数、自分で様々な計算方法をここで決めるemplate<typename t="">
	template<typename t>
	class SegmentTree {
	public:
		SegmentTree(int n, t invalid_value, bool(*eval_func_invalid_value)( t ), t(*marge_method)( t, t ));
		~SegmentTree();
		void SetElem(int k, t val);
		int GetCount();
		t quary(int a, int b);
		t GetElem(int k);
		//invalid_valueを元に不正な数値かどうか調べる
		bool(*IsInvalidValue)( t value );
		//aとbから a∪bを求める関数、自分で計算方法をここで決める
		t(*Marge)( t a, t b );
	private:
		vector<t>
			mTree;
		int mCount;
		t mInvalidValue;
		void Update(int k, t val);
		t InternalQuary(int a, int b, int k, int l, int r);
	};

	template<typename t>
	SegmentTree<t>
		::SegmentTree(int n, t invalid_value, bool(*eval_func_invalid_value)( t ), t(*marge_method)( t, t )) {
		int bin_n = 1;
		while (bin_n < n) bin_n *= 2;
		mTree.resize(2 * bin_n);
		mInvalidValue = invalid_value;
		mCount = bin_n;
		for (int i = 0; i < 2 * bin_n - 1; i++) {
			mTree[i] = invalid_value;
		}
		IsInvalidValue = eval_func_invalid_value;
		Marge = marge_method;
	}

	template<typename t>
	SegmentTree<t>
		::~SegmentTree() {
	}

	template<typename t>
	void SegmentTree<t>
		::SetElem(int k, t val) {
		Update(k, val);
	}

	template<typename t>
	t SegmentTree<t>
		::GetElem(int k) {
		return mTree[mCount - 1 + k];
	}

	template<typename t>
	int SegmentTree<t>
		::GetCount() {
		return mCount;
	}

	template<typename t>
	void SegmentTree<t>
		::Update(int k, t val) {
		k += mCount - 1;
		mTree[k] = val;
		while (k > 0) {
			k = ( k - 1 ) / 2;
			mTree[k] = Marge(mTree[2 * k + 1], mTree[2 * k + 2]);
		}
	}

	//区間[a,b]の値をO(lon(Count))で求める b < GetCountとすること
	template<typename t>
	t SegmentTree<t>
		::quary(int a, int b) {
		return InternalQuary(a, b + 1, 0, 0, mCount);
	}

	template<typename t>
	t SegmentTree<t>
		::InternalQuary(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return mInvalidValue;
		if (a <= l && r <= b)return mTree[k];
		else {
			int vl = InternalQuary(a, b, k * 2 + 1, l, ( l + r ) / 2);
			int vr = InternalQuary(a, b, k * 2 + 2, ( l + r ) / 2, r);
			return Marge(vl, vr);
		}
	}
}


