class UnionFind{
public:
	vector<int> unions,talls,sents,dists,sizes;
	int size;
	UnionFind(){}
	UnionFind(int size):size(size){
		init();
	}
	void init(){
	 	unions=vector<int>(size);
	 	talls=vector<int>(size);
	 	sents=vector<int>(size);
	 	dists=vector<int>(size);
	 	sizes=vector<int>(size);
		FOR(i,0,size){
			unions[i]=i;
			sents[i]=0;
			sizes[i]=1;
//			ns[i].PB(pr(0,1));
			talls[i]=1;
		}
	}
	int find(int x,int t=0){
		if(unions[x]==x || sents[x]>t) return x;
		return find(unions[x],t);

	}
	int minisize(int x){
		if(x==unions[x]) return sizes[x];
		return minisize(find(x));
	}
	bool isFriend(int a,int b,int t=0){
		return find(a,t)==find(b,t);	
	}
	void unite(int a,int b,int t=0){
		if(isFriend(a,b,t)) return;
		a=find(a,t);
		b=find(b,t);
		if(talls[a]<talls[b]) unite(b,a,t);
		else{
 			sizes[a]+=sizes[b];
			sents[b]=t;
			talls[a]=max(talls[a],talls[b]+1);
			unions[b]=a;
			dists[b]=1;
//			ns[a].PB(pr(t,ns[b].back().second+ns[a].back().second));
		}
	}
};

UnionFind uf;
int main(){
	cin >> N;

	uf=UnionFind(N);
	REP(i,N){
		cin >> nums[i];
		pos[nums[i]]=i;
	}
	LL ans=0;
	REP(i,N){
		LL next=N-i;
		int npos=pos[next];
		LL left=1,right=1;
		if(npos+1<N && nums[npos+1]==0) right+=uf.minisize(npos+1);
		if(npos && nums[npos-1]==0) left+=uf.minisize(npos-1);
		ans+=right*left*next;
		nums[npos]=0;
		if(npos+1<N && nums[npos+1]==0) uf.unite(npos+1,npos);
		if(npos && nums[npos-1]==0) uf.unite(npos-1,npos);
	}
	cout << ans << endl;
	return 0;
}

