struct SegR
{
	int value[1<<19],base=1<<18;
	SegR()
	{
		for(int i=0;i<(1<<19);i++)
			value[i]=1e9;
	}
	void add(int p,int v)
	{
		p+=base-1;
		value[p]=v;
		for(p/=2;p;p/=2)
			value[p]=min(value[p*2],value[p*2+1]);
	}
	void del(int p)
	{
		p+=base-1;
		value[p]=1e9;
		for(p/=2;p;p/=2)
			value[p]=min(value[p*2],value[p*2+1]);
	}
	int rangeMin(int s,int e)
	{
		int ans=1e9;
		for(s+=base-1,e+=base-1;s<=e;s/=2,e/=2)
		{
			if(s&1) ans=min(ans,value[s++]);
			if(!(e&1)) ans=min(ans,value[e--]);
		}
		return ans;
	}
