// container の中から key より小さい値を見つける。
// 見つからない場合は container.end() を返す。
template<typename T>
typename T::iterator less_than(T container, typename T::key_type key) {
  typename T::iterator prev = container.lower_bound(key);
  if (prev == container.begin()) prev = container.end();
  else prev--;
  return prev;
}

// container の中から key より大きい値を見つける。
// 見つからない場合は container.end() を返す。
template<typename T>
typename T::iterator greater_than(T container, typename T::key_type key) {
  return container.upper_bound(key);
}

void calculate() {
  for (int num = 1; num <= N; num++) {
    auto prev = less_than(used, pos[num]);
    auto next = greater_than(used, pos[num]);
    int left, right;
    if (prev == used.end()) {
      left = pos[num];
    } else {
      left = pos[num] - *prev - 1;
    }
    if (next == used.end()) {
      right = N - pos[num] - 1;
    } else {
      right = *next - pos[num] - 1;
    }
    if (right < 0) throw runtime_error("bug 1");
    if (left < 0) throw runtime_error("bug 2");
    if (right >= N) throw runtime_error("bug 3");
    if (left >= N) throw runtime_error("bug 4");
    result += (ULONG)num * ((ULONG)right * (ULONG)left + (ULONG)right + (ULONG)left + 1);
    used.insert(pos[num]);
  }
}

