  PQ2 que(200020);

  que.insert(0);
  que.insert(n+1);

  int ans = 0;

  rep(i,0,n){
    que.insert(pl[i]);

    int l,r,now;

    now = pl[i];
    l = que.smaller(pl[i]);
    r = que.bigger(pl[i]);

    int ran = (now-l)*(r-now);

    ans += ran*(i+1);
  }
