int n;

const int SIZE = 2e6 + 1;

long long t[SIZE * 4];
long long nums[SIZE];

long long sum = 0;

void build(int id, int l,  int r)

{
	if (r - l < 2)
	{
		t[id] = nums[l];
		//sum += t[id];
		return;
	}

	int mid = (l + r) / 2;

	build(2 * id, l, mid);
	build(2 * id + 1, mid, r);

	t[id] = min(t[2*id], t[2*id + 1]);
	//sum += t[id];
}

long long query(int x, int y, int id = 1, int l = 0, int r = n) {
	if (x >= r || y <= l)
		return 1e18 + 1;

	if (x <= l && y >= r) {
		return t[id];
	}

	int mid = (r + l) / 2;

	long long a = query(x, y, 2 * id, l, mid);
	long long b = query(x, y, 2 * id + 1, mid, r);

	long long c = min(a, b);
	return c;
}


class Solution {
