		 in >> n;

		for (int i = 0; i < n; i++)
		{
			long long c; in >> c;
			nums[i] = c;
		}

		build(1, 0, n);

		int mid = n / 2;
		for (int i = 0; i < n; i++)
		{
			for (int j = i; j < n; j++) {

				sum += query(i, j + 1);
			}
		}

		out << sum;
    }
};

