void prepare() {
    vector<pii> s = {pii(0, 0)};
    for (int i = 1; i <= n; ++i) {
        while (s.back().second > a[i]) {
            s.pop_back();
        }
        l[i] = s.back().first;
        s.em_back(i, a[i]);
    }

    s = {pii(n + 1, 0)};
    for (int i = n; i > 0; --i) {
        while (s.back().second > a[i]) {
            s.pop_back();
        }
        r[i] = s.back().first;
        s.em_back(i, a[i]);
    }
}

