int N;
vector<int> pos(200001);
ll partition_(ll l, ll r, segment_tree &st){
    if(r-l==1){
        return st.query(l, r);
    }else if(r-l==0){
        return 0;
    }

    ll ret=0;
    ll min_=st.query(l,r);
    ret+=min_*(pos[min_]-l+1)*(r-pos[min_]);
    ret+=partition_(l, pos[min_],st);
    ret+=partition_(pos[min_]+1, r, st);
    return ret;
}

