    for(int i=0; i<N-1; i++){
        int l, r;
        if(bit.sum(pos[i]+1)==0){
            l = pos[i]+1;
        } else {
            int lb = 0, ub = pos[i];
            while(ub-lb>1){
                int mid = (lb+ub)/2;
                if(bit.sum(pos[i]+1)-bit.sum(mid)>0){
                    lb = mid;
                } else {
                    ub = mid;
                }
            }
            l = pos[i]-lb;
