int m;
int seg[600000];

void update(int i, int v) {
	i += m - 1;
	seg[i] = v;
	while (i > 0) {
		i = (i - 1) / 2;
		seg[i] = min(seg[i * 2 + 1], seg[i * 2 + 2]);
	}
}

int segq(int a, int b, int i, int l, int r) {
	if (r <= a || b <= l) return m;
	if (a <= l && r <= b) return seg[i];
	return min(segq(a, b, i * 2 + 1, l, (l + r) / 2), segq(a, b, i * 2 + 2, (l + r) / 2, r));
}

int segq(int a, int b) {
	return segq(a, b, 0, 0, m);
}

