const int N = 1234567;

int a[N], pr[N], ne[N], pos[N];

int main() {
	int n;
	scanf("%d", &n);

	//大きい要素順に取り出せるように要素を指定すると、ai上での添字が返って
	//くるようにする。0,n+1を番兵として1,2,…nに要素を格納していく。
	for (int i = 1; i <= n; i++) {
		scanf("%d", a + i);
		pos[a[i]] = i;
	}

	//各番号の前後をもっておきたい。初期化。
	for (int i = 0; i <= n + 1; i++) {
		pr[i] = i - 1;
		ne[i] = i + 1;
	}


	long long ans = 0;

	//大きい要素から順番に空の区間に加えていく。
	for (int i = n; i >= 1; i--) {
		int j = pos[i];
		ans += i * 1LL * (j - pr[j]) * (ne[j] - j);

		//これから先入ってくる要素は、すでにある要素より小さい。
		//つまり今ある要素は以降挿入される要素を最小値区間にかならず含まれる。

		//要素を挿入した区間は拡張される。

		//左端として、挿入した要素の右端を持つ区間は、挿入した要素の左端まで拡張
		pr[ne[j]] = pr[j];

		//右端も同様
		ne[pr[j]] = ne[j];
	}
	cout << ans << endl;
	return 0;
}

