const int MAX_N = 2 * 1e5 + 2;

ll A[MAX_N];

template <class T>
class RangeMinimumQuerySegTree {
    private:
        int node_size;
        vector<T> node;
    public:
        RangeMinimumQuerySegTree(int n) {
            node_size = 1;
            while (node_size < n) node_size *= 2;
            node.resize(2 * node_size);
            fill(node.begin(), node.end(), numeric_limits<T>::max());
        }
        void update(int idx, T new_value) {
            int node_idx = idx + node_size - 1;
            node[node_idx] = new_value;
            while (node_idx > 0) {
                node_idx = (node_idx - 1) / 2;
                node[node_idx] = min(node[node_idx * 2 + 1], node[node_idx * 2 + 2]);
            }
        }
        T _get_min(int left, int right, int node_idx, int node_left, int node_right) {
            // interval [node_left, node_right) corresponds to node_idx
            if (node_right <= left || right <= node_left) {
                return numeric_limits<T>::max();
            }
            if (left <= node_left && node_right <= right) {
                return node[node_idx];
            }
            else {
                T left_value = _get_min(left, right, node_idx * 2 + 1, node_left, (node_left + node_right) / 2);
                T right_value = _get_min(left, right, node_idx * 2 + 2, (node_left + node_right) / 2, node_right);
                return min(left_value, right_value);
            }
        }
        T get_min(int left, int right) {
            return _get_min(left, right, 0, 0, node_size);
        }
};

ll ans = 0;
map<ll, int> get_idx;
RangeMinimumQuerySegTree<ll> RMQ(MAX_N);

void divide_conquer(int left, int right) {
    if (left == right) return;
    ll min_a = RMQ.get_min(left, right);
    int idx = get_idx[min_a];
    ans += (idx - left + 1) * (right - idx) * min_a;
    divide_conquer(left, idx);
    divide_conquer(idx + 1, right);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        get_idx[A[i]] = i;
        RMQ.update(i, A[i]);
    }
    divide_conquer(0, N);
    cout << ans << endl;
    return 0;
}

