namespace solve {

const int maxn = 200005;

int n, a[maxn], tree[maxn * 2];
int64_t sum = 0;

int cmp(int i, int j) { return a[i] <= a[j] ? i : j; }

int query(int l, int r) {
  int ans = l;
  for (l += n, r += n; l <= r; l = (l + 1) / 2, r = (r - 1) / 2) {
    if (l % 2 != 0) ans = cmp(ans, tree[l]);
    if (r % 2 == 0) ans = cmp(ans, tree[r]);
  }
  return ans;
}

void get_ans(int l, int r) {
  if (r < l) return;
  int pos = query(l, r);
  sum += 1LL * (pos - l + 1) * (r - pos + 1) * a[pos];
  get_ans(l, pos - 1);
  get_ans(pos + 1, r);
}

void solve() {
  cin >> n;
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
    tree[n + i] = i;
  }
  for (int i = n - 1; i > 0; --i) tree[i] = cmp(tree[i * 2], tree[i * 2 + 1]);
  get_ans(0, n - 1);
  cout << sum << '\n';
}
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  solve::solve();
}

