			//cout << i << " " << mid << " " << l << " " << r << " " << m << endl;
		}
		if(st.Query((l + r) / 2, i) < A[i]) l++;
		L[i] = i - (l + r) / 2;

		l = i;
		r = N;
		while(l + 1 < r){
			int mid = (l + r) / 2;
			int m = st.Query(i, mid);
			if(m < A[i]) r = mid;
			else l = mid;
			//cout << i << " " << mid << " " << l << " " << r << " " << m << endl;
		}
		if(st.Query(i, (l + r) / 2) < A[i]) r--;
		R[i] = (l + r) / 2 - i;
	}

//	REP(i, N){
