int RMQ(ll s, ll v)
{
	ll k = (ll)(log(v - s + 1)*1.0 / log(2));
	return dp[dp[s][k]] < dp[dp[v - ((ll)1 << k) + 1][k]] ? dp[s][k] : dp[v - ((ll)1 << k) + 1][k];
}
ll save[250000];
ll sum = 0;
bool judge(ll l, ll r)
{
	if (l == r)
	{
		sum += (ll)save[l];
		return 1;
	}
	return 0;
}
void dfs(ll L, ll R)
{
	if (judge(L, R))return;
	ll temp = RMQ(L, R);
	sum = sum + (ll)(temp - L + 1) * (R - temp + 1) * save[temp];
	if (L <= temp - 1)dfs(L, temp - 1);
	if (R >= temp + 1)dfs(temp + 1, R);
}
void ANS(int i, int j)
{
	dp[i][j] = save[dp[i][j - 1]] < save[dp[i + ((ll)1 << (j - 1))][j - 1]] ? dp[i][j - 1] : dp[i + ((ll)1 << (j - 1))][j - 1];
}
