int main() {
    scanf("%d", &N);
    for (int i = 0; i < N; i++) 
        scanf("%d", &A[i]);

    stack<int> s;
    for (int i = 0; i < N; i++) {
        while (!s.empty() && A[i] < A[s.top()]) 
            s.pop();
        if (s.empty())
            L[i] = -1;
        else
            L[i] = s.top();
        s.push(i);
    }

    while (!s.empty()) s.pop();
    for (int i = N - 1; i >= 0; i--) {
        while (!s.empty() && A[i] < A[s.top()])
            s.pop();
        if (s.empty())
            R[i] = N;
        else
            R[i] = s.top();
        s.push(i);
    }

    ll_t r = 0;
    for (int i = 0; i < N; i++) 
        r += (ll_t) A[i] * (i - L[i]) * (R[i] - i);
    printf("%lld\n", r);
    return 0;
}

