int main(void) {
    ull result = 0UL;
    int n;
    cin >> n;
    int* a = new int[n];
    rar(n, a);
    result += n + (n*(n+1))/2;//l=1, N
    bool** done = new bool*[n];
    for (int i = 0; i < n; ++i)
    {
        done[i] = new bool[n];
        for (int j = 0; j < n; ++j)
        {
            done[i][j] = (i == 0 || i == n-1);
        }
    }

    int* pos = new int[n];
    for (int i = 0; i < n; ++i)
    {
        pos[a[i]] = i;
    }

    for (int i = 0; i < n; ++i)
    {
        ull min_num = (ull)(i+1);
        int base = pos[a[i]];
        for (int j = 1; j < n-1; ++j)
        {
            int len = j+1;
            int start = base-j;
            if (j>base)
            {
                start = 0;
            }

            int end = base;
            if (j >= n-base)
            {
                end = n-len;
            }

            ull count = 0UL;
            for (int k = start; k <= end; ++k)
            {
                if (done[j][k])
                {
                    continue;
                } else {
                    done[j][k] = true;
                    ++count;
                }
            }

            result += count*min_num;
        }
    }

    cout << result << endl;

    //debug output
    if (debug)
    {
        //1D
        cout << "arr" << endl;
        for (int i = 0; i < n; ++i)
        {
            cout << pos[i] << "\t";
        }
    }

    return 0;
}

