struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  bool unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

int main()
{
  int N, A[200000];

  cin >> N;

  int rev[200000];
  for(int i = 0; i < N; i++) {
    cin >> A[i];
    --A[i];
    rev[A[i]] = i;
  }

  int64 ret = 0;
  UnionFind tree(N);
  for(int i = N - 1; i >= 0; i--) {
    int idx = rev[i];

    int64 choku = 1, dai = 1;
    if(idx > 0 && A[idx] < A[idx - 1]) {
      choku += tree.size(idx - 1);
      tree.unite(idx - 1, idx);
    }
    if(idx + 1 < N && A[idx] < A[idx + 1]) {
      dai += tree.size(idx + 1);
      tree.unite(idx + 1, idx);
    }
    ret += 1LL * choku * dai * (i + 1);
  }
  cout << ret << endl;
}

