const int BT = 1 << 18 ;
int MA=214514;
struct segtree {//BT = size
    vector<int> seg;

	void init() {
	seg.resize(BT * 2);
	rep(i, BT * 2 - 1) seg[i] =MA;
    }

    void add(int pos, int x) {//posにxを追加,0-index nodeも0-index
		pos += BT - 1;
		seg[pos] = x;

		while (pos > 0) {
			pos = (pos - 1) / 2;
			seg[pos] = min(seg[pos * 2 + 1], seg[pos * 2 + 2]);
		}
    }

    int minQ(int a, int b, int k = 0, int l = 0, int r = BT) {//[a,b)に対するクエリ
		if (b <= l || r <= a) return MA;//交差しない
		if (a <= l && r <= b) return seg[k];//被覆する
		return min(minQ(a, b, k * 2 + 1, l, (l + r) / 2), minQ(a, b, k * 2 + 2, (l + r) / 2, r));
	}

}segm; 
