	for(int i=0;i<n;i++){
		int l=0,r=n,p=i,q=i;
		int cnt=25;
		while(cnt--){
			int rmid=(q+r)/2,lmid=(l+p)/2;
			if(segm.minQ(i,rmid+1)<a[i]){
				r=rmid;
			}else{
				q=rmid;
			}

			if(segm.minQ(lmid,i+1)<a[i]){
				l=lmid;
			}else{
				p=lmid;
			}
		}
		//cout<<p<<" "<<r<<endl;
		ll R,L;
		R=(ll)(r-i);
		L=(ll)(i-p+1);
		ans+=R*L*a[i];
	}
	cout<<ans<<endl;

}
