struct SegTree {
    int N, dat[2*300000];
    SegTree() {}
    SegTree(int n) {
        N = 1;
        while(N < n) N *= 2;
        for(int i = 0; i < 2 * N - 1; ++i)
            dat[i] = INF;
    }
    SegTree(const SegTree&) = default;
    SegTree(SegTree&&) = default;
    SegTree& operator = (const SegTree&) = default;
    SegTree& operator = (SegTree&&) = default;

    void update(int k, int a) {
        k += N-1; // leaf
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = std::min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    int query(int a, int b) { return query(a, b, 0, 0, N); }
    int query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return dat[k];
        int m = (l + r) / 2;
        return std::min(query(a, b, 2 * k + 1, l, m), query(a, b, 2 * k + 2, m, r));
    }
};

int n;
int arr[MAX + 10];
int lidx[MAX + 10], ridx[MAX + 10];

int main() {
    SegTree tree1(MAX), tree2(MAX);
    std::cin >> n;

    for(int i = 0; i < n; ++i) {
        std::cin >> arr[i];
    }

    for(int i = 0; i < n; ++i) {
        auto it = tree1.query(0, arr[i]);

        int idx;
        if(it == INF) {
            idx = 0;
        }else {
            idx = -it + 1;
        }

        lidx[i] = idx;
        tree1.update(arr[i], -i);
    }

    for(int i = n - 1; i >= 0; --i) {
        auto it = tree2.query(0, arr[i]);

        int idx;
        if(it == INF) {
            idx = n - 1;
        }else {
            idx = it - 1;
        }

        ridx[i] = idx;
        tree2.update(arr[i], i);
    }

    long long sum = 0;
    for(int i = 0; i < n; ++i) {
        sum += arr[i] * 1ll  * (i - lidx[i] + 1) * (ridx[i] - i + 1);
    }

    std::cout << sum << std::endl;
}

