const int inf = 1 << 30;
const ll linf = 1LL << 60;

#define MAX_N (1<<18) //260000
template<typename T>
struct segtree{
    int n;
    T dat[2*MAX_N-1];

    void init(int n_){
        n = 1;
        while(n < n_) n *= 2;
        for(int i = 0; i < 2*n-1; i++) dat[i] = pi(inf,inf);
    }

    void update(int k, T a){
        k += n-1;
        dat[k] = a;
        while(k > 0){
            k = (k-1)/2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }

    //(a,b,0,0,seg.n)で呼ぶ
    T query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return pi(inf,inf);
        if(a <= l && r <= b) return dat[k];
        else{
            T vl = query(a,b,k*2+1,l,(l+r)/2);
            T vr = query(a,b,k*2+2,(l+r)/2,r);
            return min(vl, vr);
        }
    }
};

int n;
int a[200000];
ll ans = 0;
segtree<pi> seg;

void solve (int st, int en) {
    if (st == en) return;
    pi p = seg.query(st, en, 0, 0, seg.n);
    ans += p.first * (ll)(p.second-st+1) * (ll)(en-p.second);
    solve(st, p.second); solve(p.second+1,en);
}

