{
	memset(L , -1 , sizeof(L)) ;
	memset(R , -1 , sizeof(R)) ;
	ios_base::sync_with_stdio(0) ;
	cin.tie(0) ;
	cin>>n ;
	for(int i = 0 ; i < n ; ++i)
		cin>>arr[i] ;
	stack<int>s ;
	for(int i = 0 ; i < n ; ++i)
	{
		while(s.size() > 0 && arr[s.top()] > arr[i])
		{
			R[s.top()] = i-1 ;
			s.pop() ;
		}
		if(!s.size())
			L[i] = 0 ;
		else
			L[i] = s.top()+1 ;
		s.push(i) ;
	}
	for(int i = 0 ; i < n ; ++i)
