	for(int i = 0 ; i < n ; ++i)
	{
		long long x = i - L[i] + 1ll ;
		long long y = R[i] - i + 1ll ;
		ans += x * y * arr[i] ;
	}
	return cout<<ans<<"\n" , 0 ;
