const int N = 1e5 + 10;

#define LD (t << 1)
#define RD (t << 1 | 1)

ll sum[N << 2], tag[N << 2];

void pushup(int t) {
  sum[t] = sum[LD] + sum[RD];
}

void pushnow(int t, int l, int r, int vl) {
  sum[t] = 1ll * (r - l + 1) * vl;
  tag[t] = vl;
}

void pushdown(int t, int l, int r) {
  if (tag[t]) {
    int mid = (l + r) >> 1;
    pushnow(LD, l, mid, tag[t]);
    pushnow(RD, mid + 1, r, tag[t]);
    tag[t] = 0;
  }
}

void modify(int t, int l, int r, int ql, int qr, int vl) {
  if (ql > qr) return;
  if (ql <= l && r <= qr) {
    pushnow(t, l, r, vl);
    return;
  }
  int mid = (l + r) >> 1;
  if (ql <= mid) {
    modify(LD, l, mid, ql, qr, vl);
  }
  if (qr > mid) {
    modify(RD, mid + 1, r, ql, qr, vl);
  }
  pushup(t);
}

