const int INF = (int)1e9 + 7;
const int MAXN = 2e5 + 100;
int n, t1[MAXN * 4], t2[MAXN * 4];

void build(int v = 1, int tl = 1, int tr = n) {

    if(tl == tr) {t1[v] = -1; t2[v] = INF;return;}

    int tm = (tl + tr) >> 1;

    build(v + v, tl, tm);
    build(v + v + 1, tm + 1, tr);

    t1[v] = max(t1[v + v], t1[v + v + 1]);
    t2[v] = min(t2[v + v], t2[v + v + 1]);

}

void update(int pos, int v = 1, int tl = 1, int tr = n) {

    if(tl == tr) {t1[v] = t2[v] = pos;return;}

    int tm = (tl + tr) >> 1;

    if(pos <= tm) update(pos, v + v, tl, tm);
    else update(pos, v + v + 1, tm + 1, tr);

    t1[v] = max(t1[v + v], t1[v + v + 1]);
    t2[v] = min(t2[v + v], t2[v + v + 1]);

}

int get(int l, int r, bool type, int v = 1, int tl = 1, int tr = n) {

    if(r < tl || tr < l) return (type == 0) * -1 + (type == 1) * INF;

    if(l <= tl && tr <= r) {

        if(!type) {return t1[v];}
        else {return t2[v];}

    }

    int tm = (tl + tr) >> 1;

    if(!type) return max( get(l, r, type, v + v, tl, tm), get(l, r, type, v + v + 1, tm + 1, tr) );
    else return min( get(l, r, type, v + v, tl, tm), get(l, r, type, v + v + 1, tm + 1, tr) );

}

