int64 checkB(std::vector<int64>const& vec, std::vector<int64>const& inverse, std::size_t first, std::size_t last)
{
	int64 min = vec.size();
	std::size_t index{};
	if (last - first < vec.size() / 2)
	{
		for (std::size_t i = first;i < last;++i)
		{
			min = std::min(min, vec[i]);
		}
	}
	else
	{
		for (int64 i = 1;i < vec.size();++i)
		{
			if (first <= inverse[i] && inverse[i] < last)
			{
				min = i;
				break;
			}
		}
	}
	index = inverse[min];
	auto ret = min*(index - first + 1)*(last - index);
	return ret + checkB(vec, inverse, first, index) + checkB(vec, inverse, index + 1, last);
}
