    vl v(n);rep(i,n)cin >> v[i],v[i]--;
    vl pls(n);rep(i,n)pls[v[i]]=i;
    ll ans=0;
    SegTree<ll> st(n,0,[](ll a,ll b){return a+b;},[](ll a,ll b){return b;});
    rep(i,n){
        ll p=pls[i];
        ll x=st.query(0,p);
        ll ok=n+1,ng=-1;
        while(ok-ng>1){
            ll mid=(ok+ng)/2;
            if(st.query(0,mid)>=x+1)ok=mid;
