int main() {
	cin >> N;
	rep(i, 0, N) scanf("%d", &a[i]);

	SegTree<int, 1 << 20> st;
	rep(i, 0, N) st.update(i, a[i]);

	ll ans = 0;
	rep(i, 0, N) {
		int left, right;
		int l, r;

		l = -1;
		r = i;
		while (l + 1 != r) {
			int mid = (l + r) / 2;
			if (st.getval(mid, i) == a[i])
				r = mid;
			else
				l = mid;
		}
		left = r;

		l = i;
		r = N;
		while (l + 1 != r) {
			int mid = (l + r) / 2;
			if (st.getval(i, mid) == a[i])
				l = mid;
			else
				r = mid;
		}
		right = l;

		ans += (ll)a[i] * (ll)(i - left + 1) * (ll)(right - i + 1);
	}
	cout << ans << endl;

}

