int m;
int seg[400000];

void update(int i, int v) {
	i += m - 1;
	seg[i] = v;
	while (i > 0) {
		i = (i - 1) / 2;
		seg[i] = min(seg[i * 2 + 1], seg[i * 2 + 2]);
	}
}

int segq(int a, int b, int i, int l, int r) {
	if (r <= a || b <= l) return m;
	if (a <= l && r <= b) return seg[i];
	return min(segq(a, b, i * 2 + 1, l, (l + r) / 2), segq(a, b, i * 2 + 2, (l + r) / 2, r));
}

int segq(int a, int b) {
	return segq(a, b, 0, 0, m);
}

int main(int argc, char **argv) {
	cin >> n;
	REP(i, n) cin >> a[i];

	m = 1;
	while (m < n) m *= 2;
	REP(i, 2 * m - 1) seg[i] = n + 1;
	REP(i, n) update(i, a[i]);

	ll res = 0;
	REP(i, n) {
		ll t = a[i];
		if (segq(0, i) >= a[i]) {
			t *= i + 1;
		}
		else {
			int l = 0, r = i;
			while (l + 1 < r) {
				int m = (l + r) / 2;
				if (segq(m, r) < a[i]) l = m;
				else r = m;
			}
			t *= i - l;
		}
		if (segq(i + 1, n) >= a[i]) {
			t *= n - i;
		}
		else {
			int l = i + 1, r = n;
			while (l + 1 < r) {
				int m = (l + r) / 2;
				if (segq(l, m) < a[i]) r = m;
				else l = m;
			}
			t *= l - i;
		}
		res += t;
	}
	cout << res << endl;
	return 0;
}

