void build(int l, int r, int node){
	if(l==r){
		segtree[node] = make_pair(arr[l], l);
		return;
	}

	int mid = l+r >> 1;

	build(l, mid, 2*node+1);
	build(mid+1, r, 2*node + 2);

	segtree[node] = min(segtree[2*node+1], segtree[2*node+2]);
}

pii query(int s, int e, int l, int r, int node){
	if(s <= l and e >= r){
		return segtree[node];
	}

	if(s > r or e < l){
		return {INT_MAX, -1};
	}

	int mid = l+r >> 1;

	pii a = query(s, e, l, mid, 2*node + 1);
	pii b = query(s, e, mid + 1, r, 2*node + 2);

	return min(a, b);
}

int okay(int l, int r){

	if(l > r) return 0;

	pii a = query(l, r, 0, n-1, 0);

	return (a.y-l+1)*a.x*(r-a.y+1) + okay(l, a.y-1) + okay(a.y+1, r);

}

