template<class Compare>
struct RangeMinimumQuery {
  static constexpr int BLOCKSIZE = 16;
  const int sz;
  Compare comp;
  vector<int> table;
  vector<vector<int>> block;

  explicit RangeMinimumQuery(const int &n, const Compare &x) : sz(n), comp(x), block(1) {
    deque<int> dq;
    table.reserve(sz);
    block[0].reserve(sz / BLOCKSIZE);
    for (int i = 0; i < sz; ++i) {
      while (!dq.empty() && !comp(dq.back(), i)) {
        dq.pop_back();
      }
      table.emplace_back(dq.empty() ? 0 : table[dq.back()]);
      table.back() |= 1 << (i % BLOCKSIZE);
      dq.emplace_back(i);
      if (!((i + 1) % BLOCKSIZE)) {
        block[0].emplace_back(dq.front());
        dq.clear();
      }
    }
    for (int i = 1; i << 1 <= sz / BLOCKSIZE; i <<= 1) {
      vector<int> vec;
      const int cnt = sz / BLOCKSIZE + 1 - (i << 1);
      vec.reserve(cnt);
      for (int k = 0; k < cnt; ++k) {
        vec.emplace_back(get_min(block.back()[k], block.back()[k + i]));
      }
      block.emplace_back(move(vec));
    }
  }

  int get_min(const int L, const int R) const {
    return comp(L, R) ? L : R;
  }

  inline int ctz(const int n) {
    return __builtin_ctz(n);
  }

// [a, b] 0-indexed
  int query(int first, int last) {
    if (first > last) return -1;
    if (first < 0) first = 0;
    if (last >= sz) last = sz-1;
    const int L = first / BLOCKSIZE + 1;
    const int R = last / BLOCKSIZE;
    if (L < R) {
      const int d = 31 - __builtin_clz(R - L);
      int a = get_min((L - 1) * BLOCKSIZE + ctz(table[L * BLOCKSIZE - 1] & (-1 << (first % BLOCKSIZE))), block[d][L]);
      int b = get_min(block[d][R - (1 << d)], R * BLOCKSIZE + ctz(table[last]));
      return get_min(a, b);
    } else if (L == R) {
      return get_min((L - 1) * BLOCKSIZE + ctz(table[L * BLOCKSIZE - 1] & (-1 << (first % BLOCKSIZE))), R * BLOCKSIZE + ctz(table[last]));
    } else {
      return R * BLOCKSIZE + ctz(table[last] & (-1 << (first % BLOCKSIZE)));
    }
  }
};

template<class Compare>
RangeMinimumQuery<Compare> make_rmq(const int n, const Compare &x) {
  return RangeMinimumQuery<Compare>(n, x);
}

void solve() {
  int n; cin >> n;
  vi arr(n); cin >> arr;
  auto rmq = make_rmq(n, [&](int a, int b){ return arr[a] < arr[b]; });
  ll ans = 0;
  auto dfs = [&](auto dfs, int l, int r) -> void {
    int m = rmq.query(l, r);
    ans += 1LL * arr[m] * (m - l + 1) * (r - m + 1);
    if (l != m) dfs(dfs, l, m-1);
    if (r != m) dfs(dfs, m+1, r);
  };
  dfs(dfs, 0, n-1);
  cout << ans << endl;
}


