int main() {
    int N;
    vector<int> A(N + 1);
    cin >> N;
    for (int i = 1; i <= N; i++) cin >> A[i];

    vector<long> idx(N + 1);
    for (int i = 1; i <= N; i++) idx[A[i]] = i;

    long res = 0;
    set<int> st = {0, N + 1};
    for (int i = 1; i <= N; i++) {
        auto itr = st.lower_bound(idx[i]);
        int right = *itr;
        int left = *(--itr);
        res += i * (idx[i] - left) * (right - idx[i]);
        st.insert(idx[i]);
    }

    cout << res << "\n";
    return 0;
}

