ll go(int l, int r) {
  if (r < l) return 0;
  if (r == l) return a[l];
  int t = lg[r - l + 1];
  int m = b[t][l];
  if (a[b[t][r+1-(1<<t)]] < a[m]) m = b[t][r+1-(1<<t)];
  return go(l, m - 1) + go(m + 1, r) + (m - l+1) * 1LL * (r - m+1)*1LL*a[m];
}

