struct UnionFind{
    vector<int> parents;
    vector<int> rank;
    vector<int> size;
    UnionFind(int n){
        parents.resize(n);
        rank.assign(n, 1);
        size.assign(n, 1);
        REP(i, n){
            parents[i] = i;
        }
    }
    int find(int x){
        if(parents[x] == x) return x;
        return parents[x] = find(parents[x]);
    }

    ll unite(int x, int y){
        x = find(x);
        y = find(y);
        ll res = size[x] * size[y];
        size[x] += size[y];
        parents[y] = x;
        return res;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
};

