    {
        st.insert(m.second);

        auto s = st.find(m.second);

        // 0-indexed
        int start = -1;
        int end = N;
        if (s != st.begin())
        {
            s--;
            start = (*s);
            s++;
        }

        if (++s != st.end())
        {
            end = (*s);
        }

        ll L = max((ll)1, (ll)m.second - start);
        ll R = max((ll)1, (ll)end - m.second);
        ans += L * R * m.first;
    }

    cout << ans << endl;
    return 0;
}

