vector<int> findMin(const vector<int> &a) {
    stack<pair<int, int> > ST;
    vector<int> ans;
    ST.push(make_pair(-1, -1));
    for (int i = 0; i < (int)a.size(); ++i) {
        while (ST.top().first > a[i])
            ST.pop();
        ans.push_back(ST.top().second);
        ST.push(make_pair(a[i], i));
    }
    return ans;
}

