#include<bits/stdc++.h>
using namespace std;

int i, n, a[200005], aibmin[200005], aibmax[200005], L[200005], R[200005];
long long rs;

void updatemin(int poz, int val) {
  while(poz <= n) aibmin[poz] = min(aibmin[poz], val), poz += -poz & poz;
}

int querymin(int poz) {
  int ans = 1e9 + 69;
  while(poz) ans = min(ans, aibmin[poz]), poz -= -poz & poz;
  return ans;
}

void updatemax(int poz, int val) {
  while(poz <= n) aibmax[poz] = max(aibmax[poz], val), poz += -poz & poz;
}

int querymax(int poz) {
  int ans = 0;
  while(poz) ans = max(ans, aibmax[poz]), poz -= -poz & poz;
  return ans;
}

int main()
{
  ios_base::sync_with_stdio(0);

  for(i = 1; i <= 200001; ++i) aibmin[i] = 1e9 + 69;

  cin >> n;
  for(i = 1; i <= n; ++i) {
    cin >> a[i];

    L[i] = querymax(a[i] - 1);
    if(!L[i]) L[i] = 1;
    if(a[L[i]] < a[i]) ++L[i];
    updatemax(a[i], i);
  }

  for(i = n; i; --i) {
    R[i] = querymin(a[i] - 1);
    if(R[i] > 1e9) R[i] = n;
    if(a[R[i]] < a[i]) --R[i];
    updatemin(a[i], i);

    rs += 1LL * a[i] * (i - L[i] + 1) * (R[i] - i + 1);
  }

  cout << rs << '\n';

  return 0;
}

