        ord[i].second = i;
    }
    sort(ord.begin(), ord.end());

    vector<int> len(N, 1);

    long long ans = 0;
    for(int i = N-1; i >= 0; --i){
        int cur = ord[i].second;
        int left = 0;
        int right = 0;
        if(cur > 0 && a[cur-1] > a[cur]){
            left = len[cur-1];
        }
        if(cur < N-1 && a[cur+1] > a[cur]){
            right = len[cur+1];
        }
        ans += (long long)(ord[i].first) * (left+1) * (right+1);
        len[cur - left] = left+right+1;
        a[cur -left] = ord[i].first;
        len[cur + right] = left+right+1;
        a[cur + right] = ord[i].first;
    }
    cout << ans << endl;
    return 0;
}

