//最小値がxになる区間の個数は、x未満[A]x[B]x未満 (A,Bは数列で, 値は全てx以上）としたとき|A+1| * |B+1|で求まる。
//xが大きい順に要素を追加していき、ある場所iからの左端l[i], 右端r[i]を逐次更新していけばよい。
//O(N)
//感想：1行目の考察はすぐ思いついたが、l[i]とr[i]を持つという考えを忘れていた。

#include <iostream>
#define int long long
using namespace std;

int n;
int a[200000];
int pos[200001];	//pos[i] = 値iの場所
int l[200000];		//l[i]   = 場所l[i]～iまで要素が存在, iに要素が存在しないときは∞を格納
int r[200000];		//r[i]   = 場所i～r[i]まで要素が存在, iに要素が存在しないときは-∞を格納
int INF = 1145141919;

signed main() {
	int i;

	cin >> n;
	for (i = 0; i < n; i++) { cin >> a[i]; pos[a[i]] = i; l[i] = INF; r[i] = -INF; }

	//最小値 = iとなる区間の個数は？
	int ans = 0;
	for (i = n; i > 0; i--) {
		//iを追加
		l[pos[i]] = min(pos[i], l[max(0LL, pos[i] - 1)]);
		r[pos[i]] = max(pos[i], r[min(n - 1, pos[i] + 1)]);
		//数え上げ
		ans += i * (pos[i] - l[pos[i]] + 1) * (r[pos[i]] - pos[i] + 1);
	}
	cout << ans << endl;
	return 0;
}

