const int ST_MAX = (1 << 20);

template <class T> class ST{
	T x[ST_MAX * 2];

	T eval(T a , T b){			//評価
		return a > b ? a : b;
	}

	void ren(int a){			//更新
		x[a] = eval(x[2 * a] , x[2 * a + 1]);
		if(a > 0) ren(a / 2);
	}

	T read_ST(int a , int b , int e , int s , int f){		//値の取得
		if(e <= s || f <= b) return 0;
		if(s <= b && e <= f) return x[a];
		return eval(read_ST(2 * a , b , (b + e) / 2 , s , f) , read_ST(2 * a + 1 , (b + e) / 2 , e , s , f));
	}

public:

	void put(int a , T b){	//更新の開始
		x[a + ST_MAX] = b;
		ren((a + ST_MAX) / 2);
	}

	T get(int s , int f){	//値の取得の開始
		return read_ST(1 , 0 , ST_MAX , s , f);
	}
};

ST<int> st;
int N;
int a;
LL dp[200010];
LL g[200010];

int main(){
	scanf("%d" , &N);
	for(int i = 1 ; i <= N ; ++i){
		scanf("%d" , &a);
		int y = st.get(0 , a);
		g[i] = g[y] + (LL)a * (i - y);
		dp[i] = g[i] + dp[i - 1];
		st.put(a , i);
	}
	printf("%lld\n" , dp[N]);
	return 0;
}

