bool C(int x, int k) {
    return x > a[k];
}

int main() {
    int n;
    cin >> n;
    a = vector<int>(n, 0);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    reverse(a.begin(), a.end());
    vector<ll> dp(n, 0);

    int minv = n + 1, mini = -1;
    for (int i = 0; i < n; ++i) {
        if (a[i] < minv) {
            dp[i] = (i + 1) * a[i];
            minv = a[i];
            mini = i;
        } else if (a[i] > a[i - 1]) {
            dp[i] = dp[i - 1] + a[i];
        } else {
            int ok = mini, ng = i;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (C(a[i], mid)) ok = mid;
                else ng = mid;
            }

            dp[i] = dp[ok] + (i - ok) * a[i];
        }
    }

    ll ans = 0;
    for (int i = 0; i < n; ++i) {
        ans += dp[i];
    }

    cout << ans << endl;
}

