    S.insert(place[i]);//1の場所から入れてく。
    //入れた値の前後の値をとってくる
    auto IT=S.find(place[i]);
    ll left=*IT;
    ll right=*IT;
    IT--;
    left-=*IT;
    IT++;
    IT++;
    right=*IT-right;
    ans+=left*right*i;
  }
  cout<<ans<<endl;
}

