struct SetTree {
	int mn[N * 8], add[N * 8];

	void push(ll x, ll tl, ll tr){
		if(tr <= tl) return;
		mn[x] += add[x];
		if(tl < tr - 1){
			add[left(x)] += add[x];
			add[rght(x)] += add[x];
		}
		add[x] = 0;
		return;
	}

	ll get(ll x, ll tl, ll tr, ll ql, ll qr){
		//if(ql == 6 && qr == 9) cerr << x << ' ' << tl << ' ' << tr << '\n';
		if(tl >= tr) return INF;
		push(x, tl, tr);
		if(qr <= tl || tr <= ql) return LINF;
		if(ql <= tl && tr <= qr) return mn[x];
		ll md = (tl + tr + 1) >> 1;
		return min(get(left(x), tl, md, ql, qr), get(rght(x), md, tr, ql, qr));	
	}

	void upd(ll x, ll tl, ll tr, ll ql, ll qr, ll val){
		//cerr << x << ' ' << tl << ' ' << tr << ' ' << ql << ' ' << qr << '\n';
		if(tl >= tr) return;
		push(x, tl, tr);
		if(qr <= tl || tr <= ql) return;
		if(ql <= tl && tr <= qr){
			add[x] += val;
			push(x, tl, tr);
			return;
		}
		ll md = (tl + tr + 1) >> 1;
		upd(left(x), tl, md, ql, qr, val);
		upd(rght(x), md, tr, ql, qr, val);
		mn[x] = min(mn[left(x)], mn[rght(x)]);
		return;
	}

} t;

