const int N = 1 << 18, B = 400, oo = 1e9 + 100, M = 5e6 + 7;


int val[N], t[N << 1], ans;


int comp(int a, int b)
{
    if (val[a] < val[b])
        return a;
    else
        return b;
}


int get(int l, int r, int lb, int rb, int ind)
{
    if (l == lb && r == rb)
        return t[ind];

    int m = lb + rb >> 1;
    int first = -1, second = -1;

    if (l <= m)
        first = get(l, min(m, r), lb, m, ind << 1);

    if (r > m)
        second = get(max(l, m + 1), r, m + 1, rb, ind << 1 | 1);

    if (first == -1)
        return second;
    else if (second == -1)
        return first;
    else
        return comp(first, second);
}


int solution(int l, int r)
{
    if (l > r)
        return 0;

    int ind = get(l + 1, r + 1, 1, N, 1);
    int left = ind - l + 1;
    int right = r - ind + 1;
    return left * right * val[ind] + solution(l, ind - 1) + solution(ind + 1, r);
}


void smain()
{
    int n;
    cin >> n;

    for (int i = 0; i < n; ++i)
        cin >> val[i];

    for (int i = 0; i < n; ++i)
        t[i + N] = i;

    for (int i = N - 1; i; --i)
        t[i] = comp(t[i << 1], t[i << 1 | 1]);

    cout << solution(0, n - 1);
}

