  vector< int > ord(N);
  iota(begin(ord), end(ord), 0);
  sort(begin(ord), end(ord), [&](int a, int b) {
    return A[a] > A[b];
  });
  int64 ret = 0;
  UnionFind uf(N);
  vector< int > used(N);
  for(auto &i : ord) {
    used[i] = true;
    int l = i, r = i;
    if(i && used[i - 1]) {
      l = i - uf.size(i - 1);
      uf.unite(i, i - 1);
    }
    if(i + 1 < N && used[i + 1]) {
      r = i + uf.size(i + 1);
      uf.unite(i, i + 1);
    }
    ret += 1LL * A[i] * (r-i+1)*(i-l+1);
  }
  cout << ret << endl;
}

