template<class T> class segtree{
public:
    int n,size_;
    vector<T> dat;
    function<T(T,T)> fun_;
    T id_;
    segtree()=default;
    segtree(int size,function<T(T,T)> fun,T id,T initial_value){ init(size,fun,id,initial_value); }
    void init(int size,function<T(T,T)> fun,T id,T initial_value){
        size_=size;
        fun_=fun;
        id_=id;
        n=1;
        while(n<size) n*=2;
        dat.assign(2*n-1,id);
        for(int i=0; i<size; ++i) update(i,initial_value);
    }
    int size()const{ return size_; }
    void update(int k, T a) {
        k+=n-1; // leaf
        dat[k]=a;
        while(k>0) {
            k=(k-1)/2;
            dat[k]=fun_(dat[k*2+1],dat[k*2+2]);
        }
    }
    T at(int index){ return dat[index+n-1]; }
    void add(int k,T a){ update(k,at(k)+a); }
    T query(int a,int b) { return query(a,b,0,0,n); }
    T query(int a,int b,int k,int l,int r) {
        if(r<=a or b<=l) return id_;
        if(a<=l and r<=b) return dat[k];
        int m=(l+r)/2;
        return fun_(query(a,b,k*2+1,l,m),query(a,b,k*2+2,m,r));
    }
};

void solve(){
    int64_t n;
    cin >> n;
    vector<int64_t> a(n);
    segtree<pair<int64_t,int>> seg(n,[](pair<int64_t,int> p,pair<int64_t,int> q){
        return min(p,q);
    },
    make_pair(inf64,-1),make_pair(int64_t(0),0));
    rep(i,0,n){
        cin >> a[i];
        seg.update(i,make_pair(a[i],i));
    }

    int64_t ans=0;
    function<void(int,int)> rec=[&](int l,int r){
        if(r-l==1){
            ans+=a[l];
            return;
        }
        if(l>=r) return;
        auto p=seg.query(l,r);
        int64_t v=p.first;
        int m=p.second;
        ans+=v*(m-l+1)*(r-m);
        rec(l,m);
        rec(m+1,r);
    };
    rec(0,n);
    cout << ans << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(10);
    solve();
    return 0;
}

