ll calc(int left, int right, int v) {

	if (v > n) return 0;
	if (left > right) return 0;
	int pos = 0;
	while (pos == 0 && v <= n)
	{
		if (left <= m[v] && m[v] <= right) {
			pos = m[v];
			break;
		}
		v++;
	}
	ll res = 0;
	int len = right - left + 1;
	int relp = pos - left + 1;
	res += ((len - (relp - 1)) * relp) * v;
	res += calc(left, pos - 1, v + 1);
	res += calc(pos + 1, right, v + 1);
	return res;
}
