class RangeMinorMaxorSumQuery // 0-index
{
    int const intmax = 2147483647;
    int const intmin = 0;
    vector<int> sgt;
    int n;
    int k;

public:
    RangeMinorMaxorSumQuery(int n1, int f = -1)
    {
        if (f == -1)
            f = intmax;
        else if (f == 0)
            f = intmin;
        int na = 1;
        int ka = 0;
        while (na < n1)
        {
            na *= 2;
            ka++;
        }
        for (int i = 0; i < 2 * na; i++)
            sgt.push_back(f);
        n = na;
        k = ka;
    }

    void update_min(int i, int x)
    {
        i += n;
        sgt[i] = x;
        while (i > 1)
        {
            i /= 2;
            sgt[i] = min(sgt[2 * i], sgt[2 * i + 1]);
        }
    }

    int getmin(int a, int b, int k = 1, int l = 0, int r = -1) //閉区間 l <= x < r とする
    {
        if (r == -1)
            r = n;
        if (r <= a || b <= l)
            return intmax;
        if (a == l && b == r)
            return sgt[k];
        else
            return min(getmin(a, min(b, (l + r) / 2), 2 * k, l, (l + r) / 2), getmin(max(a, (l + r) / 2), b, 2 * k + 1, (l + r) / 2, r));
    }

    void printsegtree()
    {
        for (int i = 0; i < 2 * n; i++)
        {
            cout << sgt[i] << " ";
        }
        cout << endl;
    }
};

void solve(ll &ans, RangeMinorMaxorSumQuery &segtree, const VI & mindex, const int l, const int r)
{
    if (r == l) return;

    int min_in_range = segtree.getmin(l, r);
    int m = mindex[min_in_range];
    ll s, sl, sr;
    s = ((r - l) * (r - l + 1)) / 2;
    sr = ((r - m) * (r - m - 1)) / 2;
    sl = ((m - l) * (m - l + 1)) / 2;

    ans += min_in_range * (s - sr - sl);

    solve(ans, segtree, mindex, l, m);
    solve(ans, segtree, mindex, m + 1, r);

}

