const int maxn = 1 << 18;
vi t(2 * maxn);

void upd(int v, int vl, int vr, int i, int x) {
    if (i < vl || i > vr) return;
    if (vl == vr) {
        t[v] = x;
        return;
    }
    int vm = (vl + vr) >> 1;
    upd(v * 2 + 1, vl, vm, i, x);
    upd(v * 2 + 2, vm + 1, vr, i, x);
    t[v] = min(t[v * 2 + 1], t[v * 2 + 2]);
}

int query(int v, int vl, int vr, int l, int r) {
    if (vl > r || l > vr) return 1e9;
    if (vl >= l && vr <= r) return t[v];
    int vm = (vl + vr) >> 1;
    return min(query(v * 2 + 1, vl, vm, l, r), query(v * 2 + 2, vm + 1, vr, l, r));
}

void solve() {
    int n;
    cin >> n;
    vll a(n);
    forn(i, n){
        cin >> a[i];
        upd(0, 0, maxn - 1, i, a[i]);
    }
    ll ans = 0;
    forn(i, n) {
        ll l1 = 0, l2 = 0;
        if (query(0, 0, maxn - 1, 0, i) >= a[i]) l1 = i;
        else {
            int l = 0, r = i;
            while (l != r) {
                int m = (l + r + 1) >> 1;
                if (query(0, 0, maxn - 1, i - m, i - 1) < a[i]) r = m - 1; else l = m;
            }
            l1 = l;
        }
        if (query(0, 0, maxn - 1, i, n - 1) >= a[i]) l2 = n - i - 1;
        else {
            int l = 0, r = n - i - 1;
            while (l != r) {
                int m = (l + r + 1) >> 1;
                if (query(0, 0, maxn - 1, i + 1, i + m) < a[i]) r = m - 1; else l = m;
            }
            l2 = l;
        }
        ans += a[i] * (l1 + 1) * (l2 + 1);
    }
    cout << ans << '\n';
}

bool multitest = false;

int main() {
    init();
    int t = 1;
    if (multitest) cin >> t;
    forn(i, t) solve();
}

