int recursion(vector<int> v) {
	vector<int>::iterator minIt = min_element(v.begin(), v.end());
	int sum = 0;
	int dist = min(distance(v.begin(), minIt), distance(minIt, v.end()));
	for (int i = 1; i < v.size(); i++) {
		sum += v[distance(v.begin(),minIt)] * min(dist + 1, i);
	}
	vector<int> v1; vector<int> v2;
	copy(v.begin(), minIt - 1, back_inserter(v1));
	copy(minIt + 1, v.end(), back_inserter(v2));
	return sum + recursion(v1) + recursion(v2);
}

