    for(int i = 1; i <= n; i++){
        cin >> a[i];
        inv[a[i]] = i;
    }
    ll ans = 0;
    for(ll i = 1; i <= n; i++){
        ll now = inv[i];
        ll under_ok = now;
        ll under_ng = 0;
        while(under_ok - under_ng > 1){
            ll mid = (under_ok + under_ng) / 2;
            if(seg.getmax(mid, now) > 0){
                under_ng = mid;
            } else {
                under_ok = mid;
            }
        }
        ll upper_ok = now;
        ll upper_ng = n + 1;
        while(upper_ng - upper_ok > 1){
            ll mid = (upper_ok + upper_ng) / 2;
            if(seg.getmax(now + 1, mid + 1) > 0){
                upper_ng = mid;
            } else {
                upper_ok = mid;
            }
        }
        //cout << i << " " << under_ok << " " << upper_ok << endl;
        ans += i * (now - under_ok + 1) * (upper_ok - now + 1);
        seg.update(inv[i], 1);
    }
    cout << ans << endl;
    return 0;
}

