template <typename S>
struct sparseTable {
    using T = typename S::T;
    int n;
    vector<int> log2;
    vector<vector<T>> t;

    sparseTable(int nn) {
        n = nn;
        log2.assign(n+1, 0);
        for(int i=2; i<=n; ++i) log2[i] = log2[i >> 1] + 1;
        t = vector<vector<T>>(log2[n]+1, vector<T>(n));
    }
    void init(vector<T> v) {
        for(int i=0; i<n; ++i) t[0][i] = v[i];
        for(int j=1; j<=log2[n]; ++j) {
            int w = 1LL<<(j-1);
            for (int i = 0; i+(w<<1) <= n; ++i) {
                t[j][i] = S::op(t[j-1][i], t[j-1][i+w]);
            }
        }
    }
    // [l, r]
    T query(int l, int r) {
        int j = log2[r - l];
        return S::op(t[j][l], t[j][r-(1 << j)+1]);
    }
};

// 集合T、結合則・可換・冪等律が成り立つ二項演算op
struct minnimum {
    using T = ll;
    static T op(const T& a, const T& b) { return min(a, b); }
};

signed main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n;
    cin >> n;
    vector<ll> a(n);
    REP(i, n) cin >> a[i];

    // auto f = [](ll a, ll b){ return min(a, b); };
    // auto g = [](ll a, ll b) { return b; };
    // segtree<ll> seg(n, f, g, INF);
    // seg.build(a);

    sparseTable<minnimum> seg(n);
    seg.init(a);

    ll ret = 0;
    REP(i, n) {
        // a[i]が最小になる区間
        ll lb=-1, ub=i;
        while(ub-lb>1) {
            ll mid = (lb+ub)/2;
            if(seg.query(mid, i) >= a[i]) ub = mid;
            else lb = mid;
        }
        ll l=ub;
        lb=i, ub=n;
        while(ub-lb>1) {
            ll mid = (lb+ub)/2;
            if(seg.query(i, mid) >= a[i]) lb = mid;
            else ub = mid;
        }
        ll r = lb;

        ret += (i-l+1) * (r-i+1) * a[i];
    }
    cout << ret << endl;

    return 0;
}

