ll rmq(ll l, ll r)
{
	if(r < 0) return 1000000;
	if(l > r) return 1000000;
	int k = 31 - __builtin_clz(r-l);
	return min(st[l][k], st[r - (1<<k) + 1][k]);
}

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	//freopen("minsum.in","r",stdin);
	int n; cin >> n;
	for(int i = 0; i < n; i++)
	{
		cin >> a[i];
	}
	for(ll j = 0; j < LG; j++)
	{
		for(ll i = 0; i < n; i++)
		{
			st[i][j] = 1000000;
			if(i + (1<<j) - 1 < n)
			{
				if(j == 0) st[i][j] = a[i];
				else st[i][j] = min(st[i][j-1], st[i + (1<<(j-1))][j-1]);
			}
		}
	}
	//cerr << "OK" << endl;
	ll ans = 0;
	for(int i = 0; i < n; i++)
	{
		int lo = 0; int hi = i - 1;
		int l = i; int r = i;
		while(lo <= hi)
		{
			int mid = (lo+hi)>>1;
			if(rmq(mid, i - 1) < a[i])
			{
				lo = mid + 1;
			}
			else
			{
				l = mid;
				hi = mid - 1;
			}
		}
		lo = i + 1; hi = n - 1;
		r = i;
		while(lo <= hi)
		{
			int mid = (lo+hi)>>1;
			if(rmq(i + 1, mid) <= a[i])
			{
				hi = mid - 1;
			}
			else
			{
				r = mid;
				lo = mid + 1;
			}
		}
		//cerr << l << ' ' << r << '\n';
		ans += ll(a[i])*ll(i-l+1)*ll(r-i+1);
	}
	cout << ans;
}

