	VI indices( N ), ls, rs;
	iota( ALL( indices ), 0 );
	ls = rs = indices;
	sort( ALL( indices ), [&]( const int i, const int j ){ return A[i] > A[j]; } );

	VT< bool > added( N );
	UnionFind uf( N );

