//from interval [L,R]
void make_tree(x40 L, x40 R, x40 curr,vector< x40 >&elements,  vector< pair<x40,x40 > > &Tree)
{
	if (L == R)
	{
		Tree[curr].first = elements[L];
		Tree[curr].second = R ;
		return;
	}
	else
	{
		x40 mid = (L + R) / 2;
		make_tree(L, mid, 2 * curr, elements, Tree);
		make_tree(mid + 1, R, 2 * curr + 1, elements, Tree);
		Tree[curr].first=min(Tree[2 * curr].first , Tree[2 * curr + 1].first);
		if (Tree[curr].first == Tree[2 * curr].first)
			Tree[curr].second = Tree[curr * 2].second;
		else
			Tree[curr].second = Tree[curr * 2 + 1 ].second;
	}
	return;
}
//update from [L,R] with value new_val where current node index is curr
void update_tree(x40 new_val, x40 curr, x40 pos, x40 L, x40 R, vector<pair<x40,x40 > >&Tree)
{
	if (L == R)
	{
		Tree[curr].first = new_val;
		return;
	}
	else
	{
	x40 mid = (L + R) / 2;
	if (pos <= mid)
	update_tree(new_val, 2 * curr, pos, L, mid, Tree);
	else
		if (pos>mid)
			update_tree(new_val, 2 * curr + 1, pos, mid + 1, R, Tree);
		Tree[curr].first = min(Tree[2 * curr].first, Tree[2 * curr + 1].first);
		if (Tree[curr].first == Tree[2 * curr].first)
			Tree[curr].second = Tree[2 * curr].second;
		else
			Tree[curr].second = Tree[2 * curr + 1].second;
}
return;
}
//find minimum of range [l,r] and current interval is [L,R]
pair<x40,x40> find_min(x40 curr, x40 L, x40 R, x40 l, x40 r, vector< pair<x40,x40 > > &Tree)
{
	if (r<L || l>R)
	{
	return make_pair(LLONG_MAX,-1);
	}
	else
	{
		if (l <= L && r >= R)
			return Tree[curr];
		else
		{
			x40 mid = (L + R) / 2;
			pair<x40,x40> P1=find_min(2 * curr, L, mid, l, r, Tree),P2= find_min(2 * curr + 1, mid + 1, R, l, r, Tree);
			return P1.first < P2.first ? P1 : P2;
		}
	}
}
