ll segn;
void build(ll n) {  // build the tree
	segn=n;
  for (ll i = segn - 1; i > 0; --i) t[i] = min(t[i<<1], t[i<<1|1]);
}

ll query(ll l, ll r) {  // min on interval [l,r]
	r++;
  ll res = INF;
  for (l += segn, r += segn; l < r; l >>= 1, r >>= 1) {
    if (l&1) res=min(res, t[l++]);
    if (r&1) res=min(res, t[--r]);
  }
  return res;
}
