    // up
    if (p != n - 1) {
      long long low = p;
      long long high = n - 1;

      while (low < high) {
        long long mid = (high + low + 1) >> 1;
        if (query_mx(p, mid + 1, 0, 0, nn_mx) == 0) {
          low = mid;
        }
        else {
          high = mid - 1;
        }
      }
      r = low;
    }
    // down
    if (p != 0) {
      long long low = 0;
      long long high = p;

      while (low < high) {
        long long mid = (high + low) >> 1;

        if (query_mx(mid, p + 1, 0, 0, nn_mx) == 0) {
          high = mid;
        }
        else {
          low = mid + 1;
        }
      }
      l = low;
    }
    update_mx(p, 1);
    ans += (i + 1) * (r - p + 1) * (p - l + 1);
  }
  printf("%lld\n", ans);
  return 0;
}

