    mm[0] = -1;
    for (int i = 1; i < MAXN; ++i) {
      mm[i] = mm[i >> 1] + 1;
    }
  }
  void build(int n) {
    this->n = n;
    for (int i = 0; i < n; ++i) u[i][0] = i;
    for (int j = 1; (1 << j) <= n; ++j) {
      for (int i = 0; i + (1 << j) <= n; ++i) {
        u[i][j] = opt(u[i][j- 1 ], u[i + (1 << (j - 1))][j - 1]);
