long long N,DAT[2*MAX_N-1];
//前処理
void init(int N_){
  N=1;
  while(N<N_){
    N*=2;
  }
  FOR(i,0,2*N-1){
    DAT[i]=1e15;
  }
}
//初期化
void update(int K,int A){
  K+=N-1;
  DAT[K]=A;
  while(K>0){
    K=(K-1)/2;
    DAT[K]=min(DAT[K*2+1],DAT[K*2+2]);
  }
}
//[A,B)の最小値を返す
long long query(int A,int B,int K,int L,int R){
  if(R<=A||B<=L){
    return 1e15;
  }else if(A<=L&&R<=B){
    return DAT[K];
  }else{
    long long VL=query(A,B,K*2+1,L,(L+R)/2);
    long long VR=query(A,B,K*2+2,(L+R)/2,R);
    return min(VL,VR);
  }
}
int main(){
  int M,P;
  cin>>M;
  N=M;
  init(N);
  FOR(i,0,M){
    cin>>P;
    update(i,P);
  }
  long long sum=0;
  //i個の連続した部分列の最小値を足していく
  FOR(i,1,M+1){
    FOR(j,0,M-i+1){
      //a[j]~a[j+i]の最小値
      sum+=query(j,j+i,0,0,N);
    }
  }
  cout<<sum<<endl;
  return 0;
}

