    for(int i=0;i<n;i++) scanf("%lld", &A[i]);
    for(int j=0;j<L;j++) for(int i=0;i<n;i++) if(i+(1<<j)<=n){
        st[i][j] = !j?A[i]:min(st[i][j-1], st[i+(1<<(j-1))][j-1]);
    }
    for(int i=0;i<n;i++){
        int l = 0, r = i;
        while(r-l>1){
            int mid = ((l+r)>>1);
            if(get(mid, i)!=A[i]) l = mid;
            else r = mid;
        }
        if(l<i && get(l, i)!=A[i]) l++;
        if(l && get(l-1, i)==A[i]) l--;
        int d1 = i-l;
        l = i, r = n;
