            int mid = ((l+r)>>1);
            if(get(i, mid)!=A[i]) r = mid;
            else l = mid;
        }
        if(l>i && get(i, l)!=A[i]) l--;
        if(l^n ** get(i, l+1)==A[i]) l++;
