    ifstream file("../../../../../in.txt"); if(file.is_open()) cin.rdbuf(file.rdbuf());
#endif
    ios_base::sync_with_stdio(false); cin.tie(nullptr);

    ll N; cin >> N; vl A(N); rep(i, N) cin >> A[i];
    auto seg = SegmentTree<ll>(N, [](ll a, ll b){return min(a, b);}, LINF);
    rep(i, N) seg.update(i, A[i]);

    ll ans = 0;
    rep(i, N){
        ll ok = i+1, ng = -1;
        while(abs(ok-ng)>1){
            ll mid = (ok+ng)/2;
            ll q = seg.query(mid, i+1);
            if(q >= A[i]) ok = mid;
            else ng = mid;
        }
        ll lc = i-ok;

        ok = i; ng = N;
        while (abs(ok-ng)>1) {
            ll mid = (ok+ng)/2;
            ll q = seg.query(i, mid+1);
            if(q >= A[i]) ok = mid;
            else ng = mid;
        }
        ll rc = ok-i;

        ans += (lc+1)*(rc+1)*A[i];
    }

    cout << ans << endstr;

    return 0;
}

