template <typename ValueType, ValueType defaultVal,
          void (*chadd)(ValueType&, ValueType)>
class BIT {
 private:
  vector<ValueType> a;
  int n;
  inline int lowbit(int x) { return x & -x; }

 public:
  BIT(int n_) : n(n_) { a = vector<ValueType>(n + 1, defaultVal); }

  ValueType sum(int k) {
    ValueType s = defaultVal;
    while (k >= 1) {
      chadd(s, a[k]);
      k -= lowbit(k);
    }
    return s;
  }

  void add(int k, ValueType x) {
    while (k <= n) {
      chadd(a[k], x);
      k += lowbit(k);
    }
  }
};

void chmin(int& a, int b) { a = min(a, b); }
void chmax(int& a, int b) { a = max(a, b); }

int N;
vector<int> a;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  cin >> N;
  a.resize(N);
  for (int i = 0; i < N; i++) {
    cin >> a[i];
  }

  vector<int> maxIdxLess(N), minIdxLess(N);
  BIT<int, INT_MIN, chmax> left(N);
  for (int i = 0; i < N; i++) {
    maxIdxLess[i] = left.sum(a[i]);
    if (maxIdxLess[i] == INT_MIN) {
      maxIdxLess[i] = -1;
    }
    left.add(a[i], i);
  }
  BIT<int, INT_MAX, chmin> right(N);
  for (int i = N - 1; i >= 0; i--) {
    minIdxLess[i] = right.sum(a[i]);
    if (minIdxLess[i] == INT_MAX) {
      minIdxLess[i] = N;
    }
    right.add(a[i], i);
  }

  int ans = 0;
  for (int i = 0; i < N; i++) {
    ans = add(ans, mul(a[i], mul(i - minIdxLess[i], maxIdxLess[i] - i)));
  }
  cout << ans << endl;
}

