using namespace std;
class RMQ{
  private:
    static const long long MAX_N = 1 << 17;
    long long n, dat[2*MAX_N -1];
    long long rec(long long a,long long b,long long k,long long l,long long r){
      if(b <= l || r <= a){
        return INT_MAX;
      }

      if(a<=l && r<=b){
        return dat[k];
      }else{
        long long rl = rec(a,b,2*k+1,l,(l+r)/2);
        long long rr = rec(a,b,2*k+2,(l+r)/2,r);
        return min(rl,rr);
      }
    }

  public:
    void init(long long n_){
      n=1;
      while(n < n_) n*=2;

      for(long long i=0;i<2*n-1;i++){
      dat[i] = INT_MAX;
      }
    }

    void update(long long k, long long a){
      long long reaf = k+n-1;
      dat[reaf]=a;
      while(reaf>0){
        reaf = (reaf-1)/2;
        dat[reaf]=min(dat[reaf*2+1],dat[2*reaf+2]);
      }
    }

    long long query(long long a,long long b){
      return rec(a,b+1,0,0,n);
    }
};

int main(void){

    long long n; cin >> n;
    RMQ r;
    r.init(n);
    long long ans = 0;
    for(long long i = 0; i< n; i++){
        long long tmp;
        cin >> tmp;
        r.update(i,tmp);
        ans += tmp;
    }

    for(long long i = 0; i< n; i++) {
        for(long long j = i + 1; j < n; j++) {
            ans += r.query(i, j);
        }
    }
    cout << ans << endl;
}

