template<class Type>
class SparseTable {
private:
	std::vector<std::vector<Type> > st;
public:
	void init(std::vector<Type> v) {
		int b = 0;
		for (; (1 << b) <= v.size(); b++);
		st.assign(b, std::vector<Type>(1 << b));
		for (int i = 0; i < v.size(); i++) st[0][i] = v[i];
		for (int i = 1; i < b; i++) {
			for (int j = 0; j + (1 << i) <= (1 << b); j++) {
				st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
			}
		}
	}
	Type query(int l, int r) {
		assert(l < r);
		int b = 32 - __builtin_clz(r - l) - 1;
		return std::min(st[b][l], st[b][r - (1 << b)]);
	}
	SparseTable() {}
	SparseTable(std::vector<Type> v) { init(v); }
};
