int main() {
	cin >> n; a.resize(n);
	for (int i = 0; i < n; i++) cin >> a[i];
	vector<int> b(a);
	reverse(b.begin(), b.end());
	SparseTable<int> st(a), st2(b);
	vector<int> p(n), q(n);
	for (int i = 0; i < n; i++) {
		int l = 0, r = i + 1;
		while (r - l > 1) {
			int m = (l + r) / 2;
			if (st.query(m, i + 1) != a[i]) l = m;
			else r = m;
		}
		if(st.query(l, i + 1) == a[i]) p[i] = l;
		else p[i] = r;
	}
	for (int i = 0; i < n; i++) {
		int l = 0, r = i + 1;
		while (r - l > 1) {
			int m = (l + r) / 2;
			if (st2.query(m, i + 1) != b[i]) l = m;
			else r = m;
		}
		if (st2.query(l, i + 1) == b[i]) q[n - i - 1] = n - l;
		else q[n - i - 1] = n - r;
	}
	long long ret = 0;
	for (int i = 0; i < n; i++) ret += 1LL * (i - p[i] + 1) * (q[i] - i) * a[i];
