  UnionFind uf(N);
  int ans = 0;
  for(int i = N; i >= 1; i--) {
    int idx = mp[i];
    ans += a[idx];
    if(idx-1 >= 0 && a[idx] < a[idx-1]) {
      ans += uf.size(idx)*uf.size(idx-1)*a[idx];
      uf.unite(idx, idx-1);
    }
    if(idx+1 < N && a[idx] < a[idx+1]) {
      ans += uf.size(idx)*uf.size(idx+1)*a[idx];
      uf.unite(idx, idx+1);
    }
  }
  cout << ans << endl;

  return 0;
}

