#include <bits/stdc++.h>
#define ll long long
using namespace std;

int mn[4*200005];
ll ans;
int ar[200005];
int pos[200005];
int N;

void build(int lo,int hi,int at)
{
    if(lo==hi)
    {
        mn[at]=ar[lo];
        return;
    }
    int mid=(lo+hi)/2;

    build(lo,mid,2*at);
    build(mid+1,hi,2*at+1);
    mn[at]=min(mn[2*at],mn[2*at+1]);
}

int q(int lo,int hi,int at,int from,int to)
{
    if(lo==from && hi==to)
    {
        return mn[at];
    }

    int mid=(lo+hi)/2;

    if(mid>=to) return q(lo,mid,2*at,from,to);
    else
    {
        if(mid<from) return q(mid+1,hi,2*at+1,from,to);
        else
        {
            int c=q(lo,mid,2*at,from,mid);
            c=min(c, q(mid+1,hi,2*at+1,mid+1,to));
            return c;
        }
    }

}

void recur(int lo,int hi)
{
    if(lo>hi) return;

    ll len=hi-lo+1;
    int m=q(1,N,1,lo,hi);
    ans = ans + len*m + 1ll*(pos[m]-lo)*(hi-pos[m])*m;

    if(lo==hi) return;

    recur(lo, pos[m]-1);
    recur(pos[m]+1, hi);
}

int main()
{

    int a,b,c,d,e,x,y,z,l;

    scanf("%d",&N);

    for(a=1;a<=N;a++)
    {
        scanf("%d",&ar[a]);
        pos[ ar[a] ]=a;
    }

    ans=0;

    build(1,N,1);

    recur(1,N);

    cout<<ans<<endl;


    return 0;
}

