void solve() {
	ll N;
	cin >> N;
	vector<ll> A(N);
	vector<pair<ll, ll>> B(0);
	rep(i, N) {
		cin >> A[i];
		B.emplace_back(A[i], i);
	}
	std::sort(B.begin(), B.end());

	set<ll> st;
	ll result = 0;

	rep(i, N) {
		ll currIndex = B[i].second;
		st.insert(currIndex);
		auto it = st.find(currIndex);

		ll left = 0;
		auto temp = it;
		if (temp == st.begin()) {
			left = currIndex + 1;
		}
		else {
			temp--;
			left = currIndex - (*temp);
		}

		ll right = 0;
		temp = it;
		temp++;
		if (temp == st.end()) {
			right = N - currIndex;
		}
		else {
			right = (*temp) - currIndex;
		}

		result += left * right * B[i].first;
	}

	cout << result << endl;
}

