        ll ai;
        cin >> ai;
        indices[ai] = i;
    }

    set<ll> used{ -1, N };

    ll ans = 0;
    for (ll val = 1; val <= N; val++) {
        ll index = indices[val];

        auto p = used.emplace(index);
        auto it = p.first;

        --it;
        ll left = *it;
        ++it;
        ++it;
        ll right = *it;

        ans += val * (index - left) * (right - index);
    }

    cout << ans << endl;

