template<typename T> void m_sort_(T a[], T b[], int l, int r, bool as) {
	if(r - l < 2) { return; }

	int m = (l + r) / 2;
	m_sort_(a, b, l, m, as);
	m_sort_(a, b, m, r, as);

	int ll = l, rr = m, bb = 0;
	while(bb < r - l) {
		bool l_flag;
		if(rr == r || ll == m) { l_flag = (rr == r); }
		else { l_flag = ( as ? (a[ll] <= a[rr]) : (a[rr] <= a[ll]) ); }

		b[bb++] = (l_flag ? a[ll++] : a[rr++]);
	}

	for(int i = l; i < r; i++) { a[i] = b[i - l]; }
}
template<typename T> void m_sort(T a[], int l, int r, bool as = true) {
	T *b = new T[r - l];
	m_sort_(a, b, l, r, as);
	delete[] b;
}

struct P {
	int a, b;
	bool operator<=(const P &obj) {
		return (*this).a <= obj.a;
	}
};

int n;
P a[200000];
LL ans;

#define SEG (1 << 19)

int sl[SEG], sr[SEG];
void init() {
	INC(i, SEG) { sl[i] = -1; sr[i] = -1; }
}

void add(P arg) {
	int v = arg.a;
	int m = arg.b;

	int j;
	bool f;

	// L
	j = SEG + m; j /= 2;
	int ll = -1;
	f = true;
	while(j != 0) {
		if(sl[j] == -1) { j /= 2; }
		else if(sl[j] < m) {
			ll = (m < sr[j] ? sl[j] : sr[j]);
			break;
		} else {
			if(f && m != 0) { j--; f = false; } else { break; }
		}
	}

	// R
	j = SEG + m; j /= 2;
	int rr = n;
	f = true;
	while(j != 0) {
		if(sr[j] == -1) { j /= 2; }
		else if(m < sr[j]) {
			rr = (sl[j] < m ? sr[j] : sl[j]);
			break;
		} else {
			if(f && m != n - 1) { j++; f = false; } else { break; }
		}
	}

	// UPDATE
	j = SEG + m; j /= 2;
	while(j != 0) {
		if(sl[j] == -1) { sl[j] = m; sr[j] = m; j /= 2; }
		else if(sl[j] < m && m < sr[j]) { break; }
		else {
			setmin(sl[j], m);
			setmax(sr[j], m);
			j /= 2;
		}
	}

	ans += static_cast<LL>(m - ll) * (rr - m) * v;
}

int main() {
	scanf("%d", &n);
	INC(i, n) { scanf("%d", &a[i].a); a[i].b = i; }

	init();

	m_sort(a, 0, n);
	INC(i, n) { add(a[i]); }

	printf("%lld\n", ans);

	return 0;
}

