using namespace std;

typedef long long ll;

struct Union_Find {
    //各要素が属する集合の代表(根)を管理する
    //もし、要素xが根であればdata[x]は負の値を取り、-data[x]はxが属する集合の大きさに等しい
    vector<int> data;

    Union_Find(int size) : data(size, -1) {}
    bool Union(int x, int y) {
        x = Find(x);
        y = Find(y);
        bool is_union = (x != y);
        if (is_union) {
            if (data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return is_union;
    }
    int Find(int x) {
        if (data[x] < 0) { //要素xが根である
            return x;
        } else {
            data[x] = Find(data[x]); //data[x]がxの属する集合の根でない場合、根になるよう更新される
            return data[x];
        }
    }
    bool same(int x, int y) {
        return Find(x) == Find(y);
    }
    int size(int x) {
        return -data[Find(x)];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> a(n);
    vector<int> index(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        index[a[i] - 1] = i;
    }
    Union_Find uf(n);
    ll ans = n;
    for (int i = n - 1; i > 0; i--) {
        int idx = index[i - 1];
        int l = 1, r = 1;
        if (idx != 0 && a[idx - 1] > i) {
            l += uf.size(idx - 1);
            uf.Union(idx, idx - 1);
        }
        if (idx != n - 1 && a[idx + 1] > i) {
            r += uf.size(idx + 1);
            uf.Union(idx, idx + 1);
        }
        ans += (ll)i * l * r;
    }
    cout << ans << "\n";
    return 0;
}

