    scanf("%d",&v[g]);

    rep1(g,n){
    {
      int cur = g - 1;
      while(v[cur] > v[g]) cur = L[cur];
      L[g] = cur;
    }

  for(int g = n ; g >= 1 ; g--)
    {
      int cur = g + 1;

      while(v[cur] > v[g]) cur = R[cur];

      R[g] = cur;
