    // vl[i] = (a[j]<a[i] であるi未満の最大のj)
    vector<ll> vl(n);
    {
        segtree<max_monoid<ll>> seg(n);
        seg.build(vector<ll>(n, -1));
        REP(i, n) {
            vl[i] = seg.query(0, a[i]+1);
            seg.update(a[i], i);
        }
    }

    // vr[i] = (a[j]<a[i] であるiより大きい最小のj)
    vector<ll> vr(n);
    {
        segtree<min_monoid<ll>> seg(n);
        seg.build(vector<ll>(n, n));
        for(ll i=n-1; i>=0; --i) {
            vr[i] = seg.query(0, a[i]+1);
            seg.update(a[i], i);
        }
    }

    ll ans = 0;
    REP(i, n) ans += (i-vl[i]) * (vr[i]-i) * (a[i]+1);
    cout << ans << endl;

    return 0;
}

