template<class T>class BIT {
	int n; vector<T> a;
public:
	BIT(int n_) :n(n_), a(n_ + 1) {}
	T operator()(int i) { // [0, i]の和
		assert(0 < ++i);
		int ret = 0;
		while (i > 0) {
			ret += a[i];
			i -= i & -i;
		}
		return ret;
	}
	T operator()(int i, int j) { // [i, j]の和
		return operator()(j) - (i ? operator()(i - 1) : 0);
	}
	void add(int i, T x) {
		assert(0 < ++i);
		while (i <= n) {
			a[i] += x;
			i += i & -i;
		}
	}
};

int main() {
