	rep(j, n) {
		int i = pos[j];

		int left = 0;
		{
			int l = -1, r = i + 1;
			while (abs(l - r) > 1) {
				int mid = (l + r) / 2;
				(bit(mid, i) ? l : r) = mid;
			}
			left = r;
		}
		int right = 0;
		{
			int l = i - 1, r = n;
			while (abs(r - l) > 1) {
				int mid = (l + r) / 2;
				(bit(i, mid) ? r : l) = mid;
			}
			right = l;
		}
		ans += a[i] * (LL)(i - left + 1) * (LL)(right - i + 1);
		bit.add(i, 1);
	}
