struct RMQ {
	int n;
	int d[262244];	//2^xであることに注意
	void init(int nmin) {
		for (n = 1; n < nmin; n *= 2);
		memset(d, INF, 2 * n);
	}
	void update(int i, int x) {
		d[n + i] = x;
		for (int k = (n + i) / 2; k > 0; k >>= 1)
			d[k] = min(d[k * 2], d[k * 2 + 1]);
	}
	int get(int l, int r) const {
		int m = INF;
		for (; l && l + (l&-l) <= r; l += l&-l)
			m = min(m, d[(n + l) / (l&-l)]);
		for (; l < r; r -= r&-r)
			m = min(m, d[(n + r) / (r&-r) - 1]);
		return m;
	}
};

