struct range{
    int size;
    long number;
};

int main(){
    int N;
    cin >> N;
    long ans;
    cin >> ans;
    long sum = ans;
    vector<range> minimum_ranges{{1, ans}};
    for(int i = 1; i < N; i++){
        long num;
        cin >> num;
        sum += num;
        if(minimum_ranges.back().number <= num){
            ans += sum;
            minimum_ranges.push_back({1, num});
            continue;
        }
        int left = -1, right = int(minimum_ranges.size()) - 1; // (left, right]
        while(left + 1 < right){
            int middle = (left + right) / 2;
            if(minimum_ranges[middle].number > num){
                right = middle;
            }else{
                left = middle;
            }
        }
        int size_sum = 0;
        int minimum_ranges_size = int(minimum_ranges.size());
        for(int j = 0; j < minimum_ranges_size - right; j++){
            sum -= minimum_ranges.back().size * (minimum_ranges.back().number - num);
            size_sum += minimum_ranges.back().size;
            minimum_ranges.pop_back();
        }
        ans += sum;
        minimum_ranges.push_back({size_sum + 1, num});
    }
    cout << ans << endl;
}

