int main() {
  ll n;
  cin>>n;
  vector<tuple<ll, ll>> vt;
  REP(i,n) {
    ll a;
    cin>>a;
    vt.emplace_back(a, i);
  }
  sort(ALL(vt));
  set<ll> s;
  s.insert(-1);
  s.insert(n);
  ll sum = 0;
  REP(i,n) {
    ll val, idx;
    tie(val, idx) = vt[i];
    const auto ritr = s.upper_bound(idx);
    const auto r = *ritr;
    const auto l = *prev(ritr);
    sum += (idx - l) * (r - idx) * val;
    s.insert(idx);
  }
  cout << sum << endl;
  return 0;
}

