int N, Par[200005], L[200005], R[200005], In[200005];
pii A[200005];

int find(int n)
{
    if(Par[n] == n) return n;
    else return Par[n] = find(Par[n]);
}

void join(int a, int b)
{
    int ca = find(a), cb = find(b);
    L[ca] = min(L[ca],L[cb]);
    R[ca] = max(R[ca],R[cb]);
    Par[cb] = ca;
}

