    ll ans = 0;

    f(p,1,N)
    {
        int x = A[p].first, i = A[p].second;
        if(In[i-1] && find(i-1) != find(i)) join(i-1,i);
        if(In[i+1] && find(i+1 != find(i))) join(i+1,i);

        int c = find(i);
        ll left = i - L[c] + 1;
        ll right = R[c] - i + 1;
        ans += left*right*x;

        In[i] = 1;
    }
    cout << ans;
}

