#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 2e5+10;
int n,a[maxn];
#define lson l,mid,rt<<1
#define rson mid+1,r,rt<<1|1

int maxv[maxn<<2];
void build(int l,int r,int rt){
	if(l==r){
		scanf("%d",a+l);
		maxv[rt]=a[l];return;
	}
	int mid=l+r>>1;
	build(lson);build(rson);
	maxv[rt]=min(maxv[rt<<1],maxv[rt<<1|1]);
}
int query(int L,int R,int l,int r,int rt){
	if(L<=l&&R>=r)return maxv[rt];
	int mid=l+r>>1,ret=0x3f3f3f3f;
	if(L<=mid)ret=min(ret,query(L,R,lson));
	if(R>mid)ret=min(ret,query(L,R,rson));
	return ret;
}

int main(){
	scanf("%d",&n);
	build(1,n,1);
	ll ans=0;
	int l,r,mid;
	int len1,len2;
	for(int i=1;i<=n;i++){
		l=0,r=i+1;
		while(r-l>1){
			mid=l+r>>1;
			if(query(mid,i,1,n,1)==a[i])r=mid;
			else l=mid;
		}
		len1=i-r+1;
		l=i-1,r=n+1;
		while(r-l>1){
			mid=l+r>>1;
			if(query(i,mid,1,n,1)==a[i])l=mid;
			else r=mid;
		}
		len2=l-i+1;
		ans+=1ll*a[i]*len1*len2;
		//cout<<len1<<" "<<len2<<endl;
	}
	cout<<ans;
	return 0;
}

