const db pi = acos(-1.0);
const int MAXN = 2e5 + 5;

ll n, a[MAXN], t[MAXN * 4], z[MAXN * 4], id[MAXN];
int T[MAXN * 4];

void build(int v, int tl, int tr) {
    T[v] = inf;
	if (tl == tr) {
		t[v] = tl;
		return;
	}
	int tm = (tl + tr) >> 1;
	build(v + v, tl, tm);
	build(v + v + 1, tm + 1, tr);
	t[v] = t[v + v] + t[v + v + 1];
}

void push(int v, int tl, int tr) {
	if (z[v] != 0) {
		t[v] = t[v] - (tr - tl + 1) * z[v];
		z[v + v] += z[v];
		z[v + v + 1] += z[v];
		z[v] = 0;
	}
}

ll get_sum(int v, int tl, int tr, int l, int r) {
	push(v, tl, tr);
	if (tl > r || tr < l) return 0;
	if (tl >= l && tr <= r) return t[v];
	int tm = (tl + tr) >> 1;
	return get_sum(v + v, tl, tm, l, r) + get_sum(v + v + 1, tm + 1, tr, l, r);
}

int get_r(int v, int tl, int tr, int l, int r) {
	if (tr < l || r < tl) return inf;
	if (tl >= l && tr <= r) return T[v];
	int tm = (tl + tr) >> 1;
	return min(get_r(v + v, tl, tm, l, r), get_r(v + v + 1, tm + 1, tr, l, r));	
}

void updateR(int v, int tl, int tr, int pos, int val) {
	if (tl == tr) {
		T[v] = val;
		return;
	}
	int tm = (tl + tr) >> 1;
	if (pos >= tl && pos <= tm) updateR(v + v, tl, tm, pos, val);
	if (pos >= tm + 1 && pos <= tr) updateR(v + v + 1, tm + 1, tr, pos, val); 
	T[v] = min(T[v + v], T[v + v + 1]);
}


void update(int v, int tl, int tr, int l, int r, ll val) {
	push(v, tl, tr);
	if (tl > r || tr < l) return;
	if (tl >= l && tr <= r) {
		z[v] += val;
		push(v, tl, tr);
		return;
	}
	int tm = (tl + tr) >> 1;
	update(v + v, tl, tm, l, r, val);
	update(v + v + 1, tm + 1, tr, l, r, val);
	t[v] = t[v + v] + t[v + v + 1];
}

void solve() {
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		id[a[i]] = i;
	}
	build(1, 1, n);
	ll res = 0;
	for (int i = 1; i <= n; i++) {
		ll x = get_sum(1, 1, n, id[i], id[i]);
		int r = get_r(1, 1, n, id[i], n);
		if (r == inf) r = n;
		else r--;
		ll sum = (r - id[i] + 1ll) * x;
		res += (sum * i);		
		update(1, 1, n, id[i], r, x);
		updateR(1, 1, n, id[i], id[i]);
	}
	cout << res;
}

int main() {


    int tt = 1;
	while (tt--) {
		solve();	
	}
	return 0;
}

