int F()
{
	char ch;
	int x, a;
	while (ch = getchar(), (ch < '0' || ch > '9') && ch != '-');
	if (ch == '-') ch = getchar(), a = -1;
	else a = 1;
	x = ch - '0';
	while (ch = getchar(), ch >= '0' && ch <= '9')
		x = (x << 1) + (x << 3) + ch - '0';
	return a * x;
}

const int N = 2e5 + 10;

int a[N];

long long ans;

void solve(int l, int r)
{
	if (l == r)
	{
		ans += a[l];
		return;
	}
	long long res = 0;
	int mid = (l + r) >> 1;
	vector<int> L, R;
	for (int i = mid; i >= l; --i)
	{
		if (!SZ(L) || a[L[SZ(L) - 1]] > a[i])
			L.pb(i);
	}
	for (int i = mid + 1; i <= r; ++i)
	{
		if (!SZ(R) || a[R[SZ(R) - 1]] > a[i])
			R.pb(i);
	}
	L.pb(l - 1);
	R.pb(r + 1);
	for (int i = 0, j = 0; i < SZ(L) - 1; ++i)
	{
		while (a[R[j]] > a[L[i]] && j < SZ(R) - 1) ++j;
		res += 1LL * (R[j] - mid - 1) * (L[i] - L[i + 1]) * a[L[i]];
	}
	for (int i = 0, j = 0; i < SZ(R) - 1; ++i)
	{
		while (a[R[i]] < a[L[j]] && j < SZ(L) - 1) ++j;
		res += 1LL * (mid - L[j]) * (R[i + 1] - R[i]) * a[R[i]];
	}
	ans += res;
	solve(l, mid);
	solve(mid + 1, r);
}

