int bs(ll n,vector<pair<ll,ll>> &v){
  int l = -1,r = v.size();
  while(r-l > 1){
    int mid = (l+r)/2;
    if(v[mid].first < n)l = mid;
    else r = mid;
  }
  return r;
}

