using namespace std;

const int DEPTH = 18;
const int INF = 1e+9;
class RMQ {
	int data[1 << (DEPTH + 1)];
public:
	RMQ() { for (int i = 0; i < (1 << (DEPTH + 1)); i++) data[i] = INF; }
	void update(int p, int x) {
		p += (1 << DEPTH) - 1;
		data[p] = x;
		while (p > 0) {
			p = (p - 1) / 2;
			data[p] = min(data[p * 2 + 1], data[p * 2 + 2]);
		}
	}
	int getMin(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (l >= b || r <= a) { return INF; }
		if (l <= a && b <= r) { return data[id]; }
		int u = getMin(l, r, a, a + (b - a) / 2, id * 2 + 1);
		int v = getMin(l, r, a + (b - a) / 2, b, id * 2 + 2);
		return min(u, v);
	}
};

int n;
int a[200000];
RMQ rmq;

int checkL(int i) {
	int st = -1, ed = i, mid;	//xxxooo, (st, ed]
	while (ed - st >= 2) {
		mid = (st + ed) / 2;
		if (rmq.getMin(mid, i + 1) < a[i]) st = mid;
		else ed = mid;
	}
	return ed;
}

int checkR(int i) {
	int st = i, ed = n, mid;	//oooxxx, [st, ed)
	while (ed - st >= 2) {
		mid = (st + ed) / 2;
		if (rmq.getMin(i, mid + 1) < a[i]) ed = mid;
		else st = mid;
	}
	return st;
}

signed main() {
	int i;
	cin >> n;
	rep(i, n) cin >> a[i];
	rep(i, n) rmq.update(i, a[i]);

	int ans = 0;
	rep(i, n) {
		int l = checkL(i);	//j <= i, a[j]～a[i] >= a[i]なる最小のj
		int r = checkR(i);	//j >= i, a[i]～a[j] >= a[i]なる最大のj
		//a[i]を含む区間であって、[l, r]に収まるものの個数は
		int cnt = (i - l + 1) * (r - i + 1);
		ans += cnt * a[i];
	}
	cout << ans << endl;
	return 0;
}

