constexpr ll INF = 1000000000;/* 1e+9a */

class SegTree{
    vector<pair<ll, int>> st;

    ll N;
    int root(int x) const{
        return x / 2;
    }
    int left(int x) const {
        return x*2 + 1;
    }
    int right(int x) const{
        return 2*x + 2;
    }
    pair<ll, int> min_s(int a, int b, int k, int l, int r) const{
        ll ans = 0;
        if(r <= a || b <= l) return {INF, -1};
        if(a <= l && r <= b) return st[k];
        else{
            auto vl = min_s(a, b, left(k), l, (l+r)/2);
            auto vr = min_s(a, b, right(k), (l+r)/2, r);
            return min(vl, vr);
        }
    }

public:
    SegTree(const vector<ll>& X) :st() {
        ll k = X.size();
        N = 1;
        while(N < k) N *= 2;
        st.resize(2*N-1, {INF, INF});
        for (int i = 0; i < X.size(); ++i) {
            st[i+N-1] = {X[i], i};
        } // end i
        for (int i = N - 2; i >= 0; --i) {
            st[i] = min(st[left(i)] , st[right(i)]);
        } // end i
    }

    pair<ll, int> get_min(int a, int b) const{
        return min_s(a, b, 0, 0, N);
    }

};

ll f(int l, int r, const SegTree& a){
    // sum sum min a[l, r)
    if(r - l < 1) return 0;
    auto mini = a.get_min(l, r);
    int mi_i = mini.second;
    int mi = mini.first;

    ll L = mi_i - l; ll R = r - mi_i-1;
    ll ret = mi * (L + 1) * (R + 1);
    return ret + f(l, mi_i, a) + f(mi_i+1, r, a);

}

