void input(){
    fast_io();
    cin >> N;
    A.push_back(0);
    for (int i = 0; i < N; i++)
    {
        int a; cin >> a;
        A.push_back(a);
    }
}

int solve(){
    // A[i]の左l(i),右r(i)個はA[i]以上。
    // A[i]の足される回数はl(i)*r(i)回。
    vector<int> L(N+1,0),R(N+1,0);
    SegmentTree< int > seg(N+2, [](int a, int b) { return min(a, b); }, INT_MAX);
    for (int i = 1; i <= N; i++)
    {
        seg.set(i,A[i]);
    }
    seg.set(0,0);
    seg.set(N+1,0);
    seg.build();
    for (int i = 1; i <= N; i++)
    {
        int lok,rok,lng,rng;
        lok = rok = i;
        lng = 0;
        rng = N+1;
        while(abs(rok-rng)>1){
            int rmid = (rok+rng)/2;
            if(seg.query(i,rmid+1)==A[i]) rok = rmid;
            else rng = rmid;
        }
        while(abs(lok-lng)>1){
            int lmid = (lok+lng)/2;
            if(seg.query(lmid,i+1)==A[i]) lok = lmid;
            else lng = lmid;
        }
        L[A[i]] = i-lok+1;
        R[A[i]] = rok-i+1;
    }
    ll ans = 0;
    for (int i = 1; i <= N; i++)
    {
        ans += i*L[i]*R[i];
    }
    cout << ans << endl;
    return 0;
}   

