class UnionFind {
public:
	vector<int> s, p, es;
	map<int, int>sizemp;

	UnionFind() {}
	UnionFind(int size) {
		s.resize(size, 0);
		p.resize(size, 0);
		es.resize(size, 0);
		sizemp[1] = size;
		rep(i, 0, size)makeSet(i);
	}

	void makeSet(int x) {
		p[x] = x;
		s[x] = 0;
		es[x] = 0;
	}

	void givesize(int x){
		s[x] = 1;
	}

	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}

	void unite(int x, int y) {
		x = findSet(x);
		y = findSet(y);
		es[x]++;
		if (x == y)return;
		if (s[x] < s[y])swap(x, y);
		int szx = size(x);
		int szy = size(y);
		sizemp[szx]--;
		sizemp[szy]--;
		sizemp[szx + szy]++;
		if (sizemp[szx] == 0)sizemp.erase(szx);
		if (sizemp[szy] == 0)sizemp.erase(szy);
		p[y] = x;
		s[x] += s[y];
		es[x] += es[y];
	}


	int findSet(int x) {
		if (x == p[x]) {
			return x;
		}
		else {
			return p[x] = findSet(p[x]);
		}
	}

	int size(int x) {
		return s[findSet(x)];
	}
	int esize(int x) {
		return es[findSet(x)];
	}
	int minsz() {
		auto beg = sizemp.begin();
		return beg->first;
	}
};


int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int N;
	cin >> N;
	map<ll, ll>mp;
	for (int i = 0; i < N; i++) {
		ll a;
		cin >> a;
		mp[a] = i;
	}
	vector<ll>li(N, -1);

	UnionFind un = UnionFind(N);

	ll ans = 0;
	for (ll i = N; i >= 1; i--) {
		ll idx = mp[i];
		ll cntr = 0;
		ll cntl = 0;
		li[idx] = i;
		un.givesize(idx);
		if (idx < N-1) {
			if (li[idx + 1] != -1) {
				cntr += un.size(idx+1);
				un.unite(idx, idx + 1);
			}
		}
		if (idx > 0) {
			if (li[idx - 1] != -1) {
				cntl += un.size(idx - 1);
				un.unite(idx, idx - 1);
			}
		}
		ans += i * (cntr*cntl + cntr + cntl + 1);
	}
	puts(ans);

	return 0;
}

