using namespace std;
const int INF = (int)1e9;
struct RMQ {
	vector<pair<int, int>> data;
	int N;
	RMQ(int size) {
		N = 1;
		while(N < size) N *= 2;
		data.assign(2*N - 1, make_pair(INF, -1));
	}
	void update(int k, int a) {
		k += N - 1;
		data[k] = make_pair(a, k - N + 1);
		while(k > 0) {
			k = (k - 1)/2;
			data[k] = min(data[2*k + 1], data[2*k + 2]);
		}
	}
	pair<int, int> minimum(int a, int b) const {
		return minimum_sub(a, b, 0, 0, N);
	}
	pair<int, int> minimum_sub(int a, int b, int k, int l, int r) const {
		if(r <= a || b <= l) return make_pair(INF, -1);
		if(a <= l && r <= b) return data[k];

		return min(minimum_sub(a, b, 2*k + 1, l, (l + r)/2),
				minimum_sub(a, b, 2*k + 2, (l + r)/2, r));
	}
};
int solve(int l, int r, const RMQ &rmq) {
  if(r < l) return 0;
  auto rmqret = rmq.minimum(l, r + 1);
  int retval = (rmqret.second - l + 1) * (r - rmqret.second + 1) * rmqret.first;
  // cerr << "[" << l << "," << r << "] retval = " << retval << " rmqret = " << rmqret.first << "," << rmqret.second << endl;
  retval += solve(l, rmqret.second - 1, rmq);
  retval += solve(rmqret.second + 1, r, rmq);
  return retval;
}
