	ios::sync_with_stdio(false);
  int N; cin >> N;
  RMQ rmq(N);
  REP(i,N) {
    int a; cin >> a;
    rmq.update(i, a);
  }
  cout << solve(0, N - 1, rmq) << endl;
}

