using i64 = long long;
vector<i64> calc(const vector<i64>& h) {
    stack<pair<i64, i64>> sta;
    int N = h.size();
    vector<i64> res(N, 0LL);
    for(int i : _in(N)) {
        i64 k = i;
        while(!sta.empty() && sta.top().first > h[i]) {
            k = sta.top().second;
            sta.pop();
        }
        sta.emplace(h[i], k);
        res[i] = i - k;
    }
    return res;
}
