    i64 sum = accumulate(a.begin(), a.end(), 0LL);
    for(int i : _in(N)) {
        i64 l = vec[i], r = vec2[i];
        {// right range
            sum += r * a[i];
        }
        {// left
            i64 rlen = r + 1LL;
