#define N 200010

int n;

int val[N];
void add(int p, int x) {
  while (p <= n) {
    val[p] = max(val[p], x);
    p += lowbit(p);
  }
}

int get(int p) {
  int ret = 0;
  while (p) {
    ret = max(ret, val[p]);
    p -= lowbit(p);
  }
  return ret;
}

