ll t[4*N], a[N];
void build(ll v, ll l, ll r) {
    if(l == r) {
        t[v] = a[l];
        return;
    }
    build(v*2, l, m); build(v*2+1, m+1, r);
    t[v] = min(t[v*2], t[v*2+1]);
}
ll get(ll v, ll l, ll r, ll x, ll y) {
    if(x > r || y < l) return INF;
    if(x <= l && r <= y) return t[v];
    return min(get(v*2, l, m, x, y), get(v*2+1, m+1, r, x, y));
}

