using namespace std;

int n, st[400009], a[200009];

void up(int tn, int s, int e, int t, int w)
{
	if (t > e || t < s) return;
	if (s == e) {
		st[tn] = s;
		return;
	}
	int md = (s + e) / 2;
	up(tn * 2, s, md, t, w); up(tn * 2 + 1, md + 1, e, t, w);
	if (a[st[tn * 2]] < a[st[tn * 2 + 1]]) st[tn] = st[tn * 2];
	else st[tn] = st[tn * 2 + 1];
}

int qry(int tn, int s, int e, int ts, int te)
{
	if (te < s || ts > e) return 0;
	if (ts <= s && e <= te) return st[tn];
	int md = (s + e) / 2;
	int qa = qry(tn * 2, s, md, ts, te), qb = qry(tn * 2 + 1, md + 1, e, ts, te);
	if (a[qa] < a[qb]) return qa;
	else return qb;
}

long long ps(int s, int e)
{
	if (s < 1 || e > n || s > e) return 0;
	int t = qry(1, 1, n, s, e);
	long long rs = 1LL * (t - s + 1) * (e - t + 1) * a[t];
	return rs + ps(s, t - 1) + ps(t + 1, e);
}

