  A[0]=0,A[N+1]=0;
  ZERO(L),ZERO(R);
  SegmentTree LT(N+2);
  LT.update(0,0);
  FORE(i,1,N) {
    L[i]=i+LT.query(0,A[i]).val;
//    dump3(i,LT.query(0,A[i]).val,L[i]);
    Node x(-i);
    LT.update(A[i],x);
  }

  SegmentTree RT(N+2);
  RT.update(0,N+1);
  for(int i=N; i>0; --i) {
    R[i]=RT.query(0,A[i]).val-i;
//    dump3(i,RT.query(0,A[i]).val,R[i]);
    Node x(i);
    RT.update(A[i],x);
  }

  LL res=0;
  FORE(i,1,N) res+=1LL*A[i]*L[i]*R[i];
  cout<<res<<endl;
}

