using namespace std;

template <class Type>
class SegmentTree {
    public:

    SegmentTree(Type *a, int n, Type Default = 1e9) : DEFAULT(Default) {
        for (size = 1; size < n; ) size <<= 1;

        data = (Type *)malloc(sizeof(Type) * size * 2);
        for (int i = 0; i < size * 2; i++) data[i] = DEFAULT;
        for (int i = 0; i < n; i++) data[i + size] = a[i];
        for (int i = size - 1; i > 0; i--) data[i] = min(data[i * 2], data[i * 2 + 1]);
    }

    ~SegmentTree() {
        free(data);
    }

    void update(int index, Type value) {
        index += size;
        data[index] = value;

        while (index > 1) {
            index >>= 1;
            data[index] = min(data[index * 2], data[index * 2 + 1]);
        }
    }

    //[x,y)
    Type query(int x, int y) {
        Type value = DEFAULT;

        while (0 < x && x + (x & -x) <= y) {
            value = min(value, data[(size + x) / (x & -x)]);
            x += x & -x;
        }

        while (x < y) {
            value = min(value, data[(size + y) / (y & -y) - 1]);
            y -= y & -y;
        }

        return value;
    }

    private:

    int size;
    Type DEFAULT;
    Type *data;
};

int a[200000];
int b[200001];

long long dfs(int x, int y, SegmentTree <int> &s) {
    int z, p;
    long long ans = 0;

    if (x >= y) return 0;
    if (x + 1 == y) return a[x];

    z = s.query(x, y);
    p = b[z];

    ans += (long long)(p - x + 1) * (y - p) * z;
    ans += dfs(x, p, s);
    ans += dfs(p + 1, y, s);

    return ans;
}

