void build(int v,int s,int f)
{
	l[v]=s;r[v]=f;
	if (s==f) 
	{
		tree[v]=a[s];
		return;
	}
	build(2*v,s,(s+f)/2);
	build(2*v+1,(s+f)/2+1,f);
	tree[v]=min(tree[2*v],tree[2*v+1]);
}
