typedef long long int ll;
ll sumSubarrayMins(ll A[], ll n) 
{ 
    ll left[n], right[n]; 

    stack<pair<ll, ll> > s1, s2; 

    for (ll i = 0; i < n; ++i) { 
        ll cnt = 1; 

        while (!s1.empty() && (s1.top().first) >= A[i]) { 
            cnt += s1.top().second; 
            s1.pop(); 
        } 

        s1.push({ A[i], cnt }); 
        left[i] = cnt; 
    } 

    for (ll i = n - 1; i >= 0; --i) { 
        ll cnt = 1; 

        while (!s2.empty() && (s2.top().first) > A[i]) { 
            cnt += s2.top().second; 
            s2.pop(); 
        } 

        s2.push({ A[i], cnt }); 
        right[i] = cnt; 
    } 

    ll result = 0; 

    // calculating required result
    for (ll i = 0; i < n; ++i) 
        result = (result + A[i] * left[i] * right[i]); 

    return result; 
} 
