int main()
{
	scanf("%d",&n);

	v[0] = v[n + 1] = -MAX;

	for(int g = 1 ; g <= n ; g++)
		scanf("%d",&v[g]);

	for(int g = 1 ; g <= n ; g++)
	{
		int cur = g - 1;

		while(v[cur] > v[g]) cur = L[cur];

		L[g] = cur;
	}

	for(int g = n ; g >= 1 ; g--)
	{
		int cur = g + 1;

		while(v[cur] > v[g]) cur = R[cur];

		R[g] = cur;
	}

