#define D_SEGT_CNT		262144									// セグメントツリーデータ数(2の累乗)

// 内部構造体 - セグメントツリー情報
typedef struct SegT {
	int miNo;													// 位置 0～
	int miVal;													// 値
} SegT;

// 内部変数
static FILE *szpFpI;											// 入力
static int siNCnt;												// 数値数
static SegT sz1SegT[D_SEGT_CNT * 2];							// セグメントツリー

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpA;
#endif

// セグメントツリー - 親データセット
int
fSegTSetP(
)
{
	int i;

	// 最初の親番号範囲
	int liPNo1 = D_SEGT_CNT / 2;
	int liPNo2 = D_SEGT_CNT - 1;

	// 作成
	while (liPNo1 > 0) {
		for (i = liPNo1; i <= liPNo2; i++) {

			// 子番号
			int liCNo1 = i * 2;
			int liCNo2 = liCNo1 + 1;

			// セット
			if (sz1SegT[liCNo1].miVal < sz1SegT[liCNo2].miVal) {
				sz1SegT[i] = sz1SegT[liCNo1];
			}
			else {
				sz1SegT[i] = sz1SegT[liCNo2];
			}
		}

		// 次の親番号範囲
		liPNo2 = liPNo1 - 1;
		liPNo1 /= 2;
	}

	return 0;
}

// セグメントツリー - 取得
SegT *
fSegTGet(
	int piNNo					// <I> 現在番号 1～
	, int piNowS				// <I> 現在範囲 - 開始 0～D_SEGT_CNT-1
	, int piNowE				// <I> 現在範囲 - 終了 0～D_SEGT_CNT-1
	, int piGetS				// <I> 取得範囲 - 開始 0～D_SEGT_CNT-1
	, int piGetE				// <I> 取得範囲 - 終了 0～D_SEGT_CNT-1
)
{
	// 内包チェック
	if (piGetS <= piNowS && piNowE <= piGetE) {
		return &sz1SegT[piNNo];
	}

	// 中間位置
	int liCenter = (piNowS + piNowE) / 2;

	SegT *lzpRet = NULL;

	// 左側
	if (piGetS <= liCenter) {
		lzpRet = fSegTGet(piNNo * 2, piNowS, liCenter, piGetS, piGetE);
	}

	// 右側
	if (piGetE >= liCenter + 1) {
		SegT *lzpRet2 = fSegTGet(piNNo * 2 + 1, liCenter + 1, piNowE, piGetS, piGetE);
		if (lzpRet == NULL) {
			lzpRet = lzpRet2;
		}
		else {
			if (lzpRet->miVal > lzpRet2->miVal) {
				lzpRet = lzpRet2;
			}
		}
	}

	return lzpRet;
}

// 総和の取得
long long
fGetSum(
	int piGetS					// <I> 取得範囲 - 開始 0～D_SEGT_CNT-1
	, int piGetE				// <I> 取得範囲 - 終了 0～D_SEGT_CNT-1
)
{
	// 範囲内の最小値 - 取得
	SegT *lzpSegT = fSegTGet(1, 0, D_SEGT_CNT - 1, piGetS, piGetE);

	// 最小値の高さ
	long long llH = piGetE - piGetS + 1;

	// 最小値の総和
	long long llSum = llH * (llH + 1) / 2 * (long long)lzpSegT->miVal;

	// 最小値の左側の高さ
	llH = lzpSegT->miNo - piGetS;
	if (llH > 0) {

		// 重複(最小値の左側の総和)の削除
		llSum -= llH * (llH + 1) / 2 * (long long)lzpSegT->miVal;

		// 最小値の左側の総和
		llSum += fGetSum(piGetS, lzpSegT->miNo - 1);
	}

	// 最小値の右側の高さ
	llH = piGetE - lzpSegT->miNo;
	if (llH > 0) {

		// 重複(最小値の右側の総和)の削除
		llSum -= llH * (llH + 1) / 2 * (long long)lzpSegT->miVal;

		// 最小値の右側の総和
		llSum += fGetSum(lzpSegT->miNo + 1, piGetE);
	}

	return llSum;
}

