  segment_tree *s = new_segment_tree (&ini, n, sizeof (node), func);
  for (i32 i = 0; i < n; ++i) {
    i32 a;
    scanf ("%" SCNi32, &a);
    update (s, i, &((node){i, a}));
  }
  range stack[32];
  i32 top = 0;
  stack[top++] = (range) {0, n};
  i64 ans = 0;
  while (top > 0) {
    range t = stack[--top];
    if (t.r <= t.l) continue;
    node v;
    find (s, t.l, t.r, &v);
    i32 k = v.index;
    ans += (i64) (k - t.l + 1) * (t.r - k) * v.val;
    if (k - t.l <= t.r - k) {
      stack[top++] = (range) {k + 1, t.r};
      stack[top++] = (range) {t.l, k};
    } else {
      stack[top++] = (range) {t.l, k};
      stack[top++] = (range) {k + 1, t.r};
    }
  }
  printf ("%" PRIi64 "\n", ans);
}

