int L(int l,int r){//printf("L:%d %d\n",l,r);
  if(l==r)return l;
  int m=(l+r)/2;//printf("::m%d r%d m%d\n",m,bsum(r),bsum(m));
  if(bsum(r)-bsum(m)==0)return L(l,m);
