}
int R(int l,int r){//printf("R:%d %d\n",l,r);
  if(l+1==r)return l+1;
  int m=(l+r)/2;//printf("::m%d l%d m%d\n",m,bsum(l),bsum(m));
  if(bsum(m)==bsum(l))return R(m,r);
  return R(l,m);
}
