i64 calc (i32 *a, i32 n) {
  static i32 *tmp = NULL;
  if (tmp == NULL) {
    tmp = (i32 *) calloc (n, sizeof (i32));
  }
  if (n == 1) {
    return a[0];
  }
  i32 m = n / 2;
  i64 ans = calc (a, m) + calc (a + m, n - m);
  i32 *b = tmp;
  i32 *c = b + m;
  for (i32 i = m - 1, x = 200000; i >= 0; --i) {
    x = min (x, a[i]);
    b[m - 1 - i] = x;
  }
  for (i32 i = m, x = 200000; i < n; ++i) {
    x = min (x, a[i]);
    c[i - m] = x;
  }
  i32 p = m - 1;
  i32 q = n - m - 1;
  while (p >= 0 && q >= 0) {
    if (b[p] <= c[q]) {
      ans += (i64) (q + 1) * b[p];
      --p;
    } else {
      ans += (i64) (p + 1) * c[q];
      --q;
    }
  }
  return ans;
}

