#include <stdio.h>

const int sup = 1 << 30;

typedef struct {
	int left, right, min;
} seg_node;

void init_seg_tree(seg_node v[], int p[], int k, int l, int r)
{
	int i;
	v[k].left = l;
	v[k].right = r;
	v[k].min = sup;
	if (l < r) {
		init_seg_tree(v, p, k * 2, l, (l + r) / 2);
		init_seg_tree(v, p, k * 2 + 1, (l + r) / 2 + 1, r);
	} else p[l] = k;
}

int get_min(seg_node v[], int k, int l, int r)
{
	int tmp[2];
	if (v[k].left >= l && v[k].right <= r) return v[k].min;
	else if (v[k].right < l || v[k].left > r) return sup;
	else {
		tmp[0] = get_min(v, k * 2, l, r);
		tmp[1] = get_min(v, k * 2 + 1, l, r);
		return (tmp[0] < tmp[1])? tmp[0]: tmp[1];
	}
}

int main()
{
	int i, N, a[200001];
	scanf("%d", &N);
	for (i = 1; i <= N; i++) scanf("%d", &(a[i]));

	int j, p[200001], pos[200001];
	seg_node v[600001];
	init_seg_tree(v, p, 1, 1, N);
	for (i = 1; i <= N; i++) {
		pos[a[i]] = i;
		for (j = p[i]; j >= 1; j /= 2) if (v[j].min > a[i]) v[j].min = a[i];
	}

	int l[2], r[2], m;
	long long ans = 0;
	for (i = 1; i <= N; i++) {
		l[0] = 1;
		r[0] = pos[i];
		while (l[0] < r[0]) {
			m = (l[0] + r[0]) / 2;
			if (get_min(v, 1, m, pos[i] - 1) > i) r[0] = m;
			else l[0] = m + 1;
		}
		l[1] = pos[i];
		r[1] = N;
		while (l[1] < r[1]) {
			m = (l[1] + r[1] + 1) / 2;
			if (get_min(v, 1, pos[i] + 1, m) > i) l[1] = m;
			else r[1] = m - 1;
		}
		ans += (long long)(pos[i] - l[0] + 1) * (l[1] - pos[i] + 1) * i;
	}

	printf("%lld\n", ans);
	fflush(stdout);
	return 0;
}

