void badd(int i,int a){for(;i<=n;i+=i&-i)B[i]+=a;}
int  bsum(int i){
  int s=0;
  for(;i;i-=i&-i)s+=B[i];
  return s;
}
int L(int l,int r){//printf("L:%d %d\n",l,r);
  if(l==r)return l;
  int m=(l+r)/2;//printf("::m%d r%d m%d\n",m,bsum(r),bsum(m));
  if(bsum(r)-bsum(m)==0)return L(l,m);
  return L(m+1,r);
}
int R(int l,int r){//printf("R:%d %d\n",l,r);
  if(l+1==r)return l+1;
  int m=(l+r)/2;//printf("::m%d l%d m%d\n",m,bsum(l),bsum(m));
  if(bsum(m)==bsum(l))return R(m,r);
  return R(l,m);
}
