long long ssize=524288;
long long stree[1048576],vd=llinf;

void sinit(){
    long long i,j;
    for(i=0;i<2*ssize;i++){
        stree[i]=llinf;
    }
}

void upd(long long k,long long a){
    long long i,m;
    long long ld,rd,md;
    k+=ssize-1;
    stree[k]=a;
    while(k>0){
        k=(k-1)/2;
        ld=stree[2*k+1];
        rd=stree[2*k+2];
        md=llmin(ld,rd);
        stree[k]=md;
    }
}

//calc min[a,b)
//call:k=0,l=0,r=ssize
long long query(long long a,long long b,long long k,long long l,long long r){
    long long ld,rd,md;
    long long i,lp,rp;
    if(r<=a || b<=l){return vd;}
    if(a<=l && r<=b){
        return stree[k];
    }
    else{
        ld=query(a,b,k*2+1,l,(l+r)/2);
        rd=query(a,b,k*2+2,(l+r)/2,r);
        lp=0;rp=0;
        md=llmin(ld,rd);
        return md;
    }
}

