#define INF 22222222

#define KI_MAX (1 << 18) /* 262144 */

int ki[KI_MAX * 2 - 1];

void ki_koutiku(void) {
	int i;
	for (i = (KI_MAX - 1) - 1; i >= 0; i--) {
		int l = ki[i * 2 + 1], r = ki[i * 2 + 2];
		ki[i] = l <= r ? l : r;
	}
}

int ki_get_i(int idx, int smin, int smax, int qmin, int qmax) {
	if (smax <= qmin || qmax <= smin) { /* クエリとセグメントが全く重ならない */
		return INF;
	} else if (qmin <= smin && smax <= qmax) { /* セグメントがクエリに完全に含まれる */
		return ki[idx];
	} else {
		int smid = smin + (smax - smin) / 2;
		int l = ki_get_i(idx * 2 + 1, smin, smid, qmin, qmax);
		int r = ki_get_i(idx * 2 + 2, smid, smax, qmin, qmax);
		return l <= r ? l : r;
	}
}

int ki_get(int qmin, int qmax) {
	return qmin < qmax ? ki_get_i(0, 0, KI_MAX, qmin, qmax) : INF;
}

