	ki_koutiku();
	for (i = 1; i <= N; i++) {
		int yes, no;
		int hidari, migi;

		no = 0; yes = basyo[i];
		while (no + 1 < yes) {
			int mid = no + (yes - no) / 2;
			if (ki_get(mid, basyo[i] + 1) >= i) yes = mid; else no = mid;
		}
		hidari = yes;

		yes = basyo[i]; no = N + 1;
		while (yes + 1 < no) {
			int mid = yes + (no - yes) / 2;
			if (ki_get(basyo[i], mid + 1) >= i) yes = mid; else no = mid;
		}
		migi = yes;

		kotae += (uint64_t)i * (uint64_t)(basyo[i] - hidari + 1) * (uint64_t)(migi - basyo[i] + 1);
	}
	printf("%" PRIu64 "\n", kotae);
