import java.util.*

fun f(a: List<Long>): Array<Long> {
    val res = Array(a.size) { 0L }
    val stack = ArrayDeque<Pair<Long, Int>>()

    stack.push(Pair(0L, -1))
    for (i in a.indices) {
        while (stack.peek().first > a[i]) {
            stack.pop()
        }
        res[i] = i - stack.peek().second.toLong()
        stack.push(Pair(a[i], i))
    }

    return res
}

