final class UnionFindRoot {
	int l;
	int r;

	UnionFindRoot(int left, int right) {
		l = left;
		r = right;
	}

	UnionFindRoot combine(UnionFindRoot another) {
		return new UnionFindRoot(min(l, another.l), max(r, another.r));
	}

	private int min(int a, int b) {
		return a < b ? a : b;
	}

	private int max(int a, int b) {
		return a > b ? a : b;
	}

	@Override
	public String toString() {
		return "Root[" + l + ", " + r + "]";
	}
}

final class UnionFind2 {
	int[] parent;
	int[] rank;
	UnionFindRoot[] root;

	public UnionFind2(int n) {
		parent = new int[n];
		root = new UnionFindRoot[n];
		rank = new int[n];

		for (int i = 0; i < n; i++) {
			parent[i] = i;
			root[i] = new UnionFindRoot(i, i);
		}
	}

	public int find(int i) {
		int p = parent[i];
		if (i == p) {
			return i;
		}
		return parent[i] = find(p);
	}

	public UnionFindRoot findRoot(int i) {
		int p = parent[i];
		if (i == p) {
			return root[i];
		}
		return root[parent[i] = find(p)];
	}

	public void union(int i, int j) {
		int root1 = find(i);
		int root2 = find(j);

		if (root2 == root1)
			return;

		UnionFindRoot newRoot = root[root1].combine(root[root2]);

		if (rank[root1] > rank[root2]) {
			parent[root2] = root1;
			root[root1] = newRoot;
		} else if (rank[root2] > rank[root1]) {
			parent[root1] = root2;
			root[root2] = newRoot;
		} else {
			parent[root2] = root1;
			root[root1] = newRoot;
			rank[root1]++;
		}
	}
}

