        }
        long ans = 0L;
        add(1, 1);
        add(N+2, 1);
        for (int i=0;i<n;i++) {
            int index = inv[i]+1;
            ans+=((index+1)-get(sum(index)-1))*(get(sum(index))-(index+1))*(i+1);
            add(index+1, 1);
        }
