		for(int i=0; i<n; i++) a[i]=sc.nextLong();
		long[]bkt=new long[400];
		Arrays.fill(bkt, Long.MAX_VALUE);
		for(int i=0; i<n; i++) {
			bkt[i/SZ]=Math.min(a[i], bkt[i/SZ]);
		}
		long ans=0;
		for(int i=0; i<n; i++) {
			int l=0;
			for(;l<400; l++) {
				if(bkt[l]==a[i])
					break;
			}
			if(l>399) {
				int kl;
				for(kl=0; i-kl>=0; kl++) {
					if(a[i]>a[i-kl]) break;
				}
				int kr;
				for(kr=0; i+kr<n; kr++) {
					if(a[i]>a[i+kr]) break;
				}
				//ans+=(1+kr)*(1+kl);
				long b=kr*kl;
				ans+=b*a[i];
			} else {
				int r=l;
				for(;r<400; r++) {
					if(bkt[r]!=a[i])
						break;
				}
				// l*SZ..r*sz
				l=Math.max(0, (l-1)*SZ);
				r=Math.min(n-1, (r+2)*SZ);
				int kl;
				for(kl=0; i-kl>=l; kl++) {
					if(a[i]>a[i-kl]) break;
				}
				int kr=0;
				for(;i+kr<=r; kr++) {
					if(a[i]>a[i+kr]) break;
				}
				//ans+=(1+kr)*(1+kl);
				long b=kr*kl;
				ans+=b*a[i];
			}
