public void solve() {
	int num = ni();
	int a[] = ni(num);
	LazySegTree l = new LazySegTree(num + 5, 0);
	LazySegTree r = new LazySegTree(num + 5, (num - 1));
	int index[] = new int[num];
	for(int i = 0; i < num; i ++) {
		index[a[i] - 1] = i;
	}
	long ans = 0;
	for(int i = 0; i < num; i ++) {
		int j = index[i];
		int ll = (int)l.find(j, j + 1);
		int rr = (int)r.find(j, j + 1);
		ans += (long)(j - ll + 1) * (rr - j + 1) * (i + 1);
		l.update(j, rr + 1, j + 1);
		r.update(ll, j + 1, j - 1);
	}
	prtln(ans);
}

class LazySegTree {
