                return tooSmall;
            }

            for (tooBig = 1; !tooManyOnRight(currentIndex, currentValue, tooBig); tooBig *= 2) ;

            if (!tooManyOnRight(currentIndex, currentValue, tooBig - 1)) {
                return tooBig;
            }

            while (tooBig - tooSmall > 1) {
                int center = (tooBig + tooSmall) / 2;
                if (!tooManyOnRight(currentIndex, currentValue, center)) {
                    tooSmall = center;
                } else {
                    tooBig = center;
                }
            }

            return tooBig;
        }

        private boolean tooManyOnLeft(int currentIndex, int currentValue, int elementCount) {
            if (elementCount <= 0) {
                return false;
            }

            if (currentIndex - elementCount < 0) {
                return true;
            }

            return min.query(currentIndex - elementCount, currentIndex - 1) < currentValue;
        }

        private boolean tooManyOnRight(int currentIndex, int currentValue, int elementCount) {
            if (elementCount <= 0) {
                return false;
            }

            if (currentIndex + elementCount >= n) {
                return true;
            }

            return min.query(currentIndex + 1, currentIndex + elementCount) < currentValue;
        }

        static long nc2(long n) {
            if (n < 2) return 0;
            return n * (n - 1) / 2;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }

    static class IntSegmentTree {
        public int size;
        public int[] value;
        private final BiFunction<Integer, Integer, Integer> combiner;
        private final int identityElement;

        public IntSegmentTree(int size, BiFunction<Integer, Integer, Integer> combiner, int identityElement) {
            this.size = size;
            value = new int[2 * size];
            Arrays.fill(value, identityElement);
            this.combiner = combiner;
            this.identityElement = identityElement;
        }

        private int combine(int a, int b) {
            return combiner.apply(a, b);
        }

        public int get(int i) {
            return value[size + i];
        }

        public void update(int i, int v) {
            i += size;
            value[i] = v;
            while (i > 1) {
                i /= 2;
                value[i] = combine(value[2 * i], value[2 * i + 1]);
            }
        }

        public int query(int i, int j) {
            int res_left = identityElement, res_right = identityElement;
            for (i += size, j += size; i <= j; i /= 2, j /= 2) {
                if ((i & 1) == 1) res_left = combine(res_left, value[i++]);
                if ((j & 1) == 0) res_right = combine(value[j--], res_right);
            }
            return combine(res_left, res_right);
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;

import java.util.Arrays;

public class Main {
  static int n;
  static int[] a;

  public static void main(String[] args){
    FastScanner sc = new FastScanner();

    n = sc.nextInt();
    a = new int[n];
    for(int i = 0; i < n; i++){
      a[i] = sc.nextInt();
    }

    int[] pos = new int[n + 1];
    for(int i = 0; i < n; i++){
      pos[a[i]] = i;
    }

    // left most right
    int[] lmr = new int[n];
    for(int i = 0; i < n; i++){
      int j = i - 1;
      while(j != -1 && a[j] > a[i]){
        j = lmr[j];
      }
      lmr[i] = j;
    }

    // right most left
    int[] rml = new int[n];
    for(int i = n - 1; i >= 0; i--){
      int j = i + 1;
      while(j != n && a[i] < a[j]){
        j = rml[j];
      }
      rml[i] = j;
    }

    int[] left = new int[n + 1];
    left[1] = pos[1];
    for(int i = 2; i <= n; i++){
      if(lmr[pos[i]] < pos[i]){
        left[i] = pos[i] - lmr[pos[i]] - 1;
      }
      else{
        left[i] = pos[i];
      }
    }

    int[] right = new int[n + 1];
    int ml = pos[1];
    right[1] = n - pos[1];
    for(int i = 2; i <= n; i++){
      if(pos[i] < rml[pos[i]]){
        right[i] = rml[pos[i]] - pos[i];
      }
      else{
        right[i] = n - pos[i];
      }
    }

    long sum = 0;
    for(int i = 1; i <= n; i++){
      sum += (long)i * ((long)right[i] * left[i] + right[i]);
    }

    System.out.println(sum);
  }
}

class FastScanner {
  private static final InputStream in = System.in;
  private static final PrintWriter out = new PrintWriter(System.out);
  private final byte[] buffer = new byte[2048];
  private int p = 0;
  private int buflen = 0;

  public FastScanner(){
  }

  private boolean hasNextByte() {
    if(p < buflen){
      return true;
    }
    p = 0;
    try{
      buflen = in.read(buffer);
    }catch (IOException e) {
      e.printStackTrace();
    }
    if(buflen <= 0){
      return false;
    }
    return true;
  }

  public boolean hasNext() {
    while(hasNextByte() && !isPrint(buffer[p])){
      p++;
    }
    return hasNextByte();
  }

  private boolean isPrint(int ch) {
    if(ch >= '!' && ch <= '~'){
      return true;
    }
    return false;
  }

  private int nextByte() {
    if(!hasNextByte()){
      return -1;
    }
    return buffer[p++];
  }

  public String next() {
    if(!hasNext()){
      throw new NoSuchElementException();
    }
    StringBuilder sb = new StringBuilder();
    int b = -1;
    while(isPrint((b = nextByte()))){
      sb.appendCodePoint(b);
    }
    return sb.toString();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }
}

