public class Main {
  private static class Task {
    void solve(FastScanner in, PrintWriter out) throws Exception {
      int N = in.nextInt();
      int[] A = in.nextIntArray(N);
      int[] left = new int[N];

      // [a, i]
      ArrayDeque<int[]> stack = new ArrayDeque<>();
      stack.add(new int[]{0, -1});
      for (int i = 0; i < N; i++) {
        int a = A[i];
        while (stack.peekLast()[0] > a) stack.pollLast();
        left[i] = stack.peekLast()[1] + 1;
        stack.addLast(new int[]{a, i});
      }

      stack.clear();
      stack.add(new int[]{0, N});
      int[] right = new int[N];
      for (int i = N - 1; i >= 0; i--) {
        int a = A[i];
        while (stack.peekLast()[0] > a) stack.pollLast();
        right[i] = stack.peekLast()[1] - 1;
        stack.add(new int[]{a, i});
      }

      long sum = 0;
      for (int i = 0; i < N; i++) {
        long l = i - left[i] + 1;
        long r = right[i] - i + 1;
        sum += (l * r * A[i]);
      }
      out.println(sum);

    }
  }

