import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		for(int i = 0;i < n;i++)a[i] = -a[i];
		int[] pre = enumPrevWall(a);
		rev(a);
		int[] nex = enumPrevWall(a);
		rev(a);
		long ret = 0;
		for(int i = 0;i < n;i++){
			ret += (long)-a[i]*(i-pre[i])*((n-1-i)-nex[n-1-i]);
		}
		out.println(ret);
	}

	public static int[] rev(int[] a)
	{
		for(int i = 0, j = a.length-1;i < j;i++,j--){
			int c = a[i]; a[i] = a[j]; a[j] = c;
		}
		return a;
	}



	public static int[] enumPrevWall(int[] a)
	{
		int n = a.length;
		int[] L = new int[n];
		for(int i = 0;i < n;i++){
			L[i] = i-1;
			while(L[i] >= 0 && a[L[i]] < a[i])L[i] = L[L[i]];
		}
		return L;
	}


