		ArrayList<Mountain> mountains = new ArrayList<Mountain>();
		Mountain m = new Mountain(1, N);
		mountains.add(m);
		for(int i=1; i<=N; i++) {
			for(int j=0; j<mountains.size(); j++) {
				Mountain checkM = mountains.get(j);
				if (checkM.begin <= a[i] && a[i] <= checkM.end) {
					sum += checkM.counter(a[i]) * i;
