/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Denis Nedelyaev
 */
public class Main {
    public static void main(String[] args) throws Exception {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AtB solver = new AtB(in, out);
        solver.solve(1);
        out.close();
    }

    static class AtB {
        private final FastScanner in;
        private final PrintWriter out;
        private Pair[] a;

        public AtB(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        public void solve(int testNumber) throws InterruptedException {
            Thread thread = new Thread(null, this::solve, "solution", 1 << 24);
            thread.setUncaughtExceptionHandler((t, e) -> {
                throw new RuntimeException(e);
            });
            thread.start();
            thread.join();
        }

        public void solve() {
            int n = 0;
            n = in.nextInt();

            a = new Pair[n];
            for (int i = 0; i < n; i++) {
                int val = in.nextInt();
                a[i] = new Pair(val, i);
            }

            Arrays.sort(a, Comparator.comparingInt(x -> x.value));

            out.println(calc(0, 0, n - 1));
        }

        private BigInteger calc(int i, int from, int to) {
            if (i == a.length || from > to) {
                return BigInteger.ZERO;
            }
            int index = a[i].index;
            if (index < from || index > to) {
                return calc(i + 1, from, to);
            }
            BigInteger sum = BigInteger.valueOf(a[i].value * (index - from + 1L) * (to - index + 1L));
            return sum.add(calc(i + 1, from, index - 1)).add(calc(i + 1, index + 1, to));
        }

    }

    static class FastScanner {
        private final static int BUFFER_SIZE = 4096;
        private final InputStream in;
        private byte[] buffer = new byte[BUFFER_SIZE];
        private int pos = 0;
        private int size;

        public FastScanner(InputStream inputStream) throws IOException {
            in = inputStream;
            size = 0;
        }

        public int nextInt() {
            int c = skipWhitespace();

            int sign = -1;
            if (c == '-') {
                sign = 1;
                c = read();
            }

            int ans = 0;

            while (c > ' ') {
                ans *= 10;
                ans -= c - '0';
                c = read();
            }

            return sign * ans;
        }

        private int skipWhitespace() {
            while (true) {
                int c = read();
                if (c > ' ' || c == -1) {
                    return c;
                }
            }
        }

        private int read() {
            if (pos >= size) {
                try {
                    size = in.read(buffer, 0, BUFFER_SIZE);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (size <= 0) {
                    return -1;
                }
                pos = 0;
            }
            return buffer[pos++];
        }

    }

    static class Pair {
        final int value;
        final int index;

        Pair(int value, int index) {
            this.value = value;
            this.index = index;
        }

    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.TreeSet;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String[] sa = br.readLine().split(" ");
		Obj[] arr = new Obj[n];
		for (int i = 0; i < n; i++) {
			Obj o = new Obj();
			o.i = i;
			o.a = Integer.parseInt(sa[i]);
			arr[i] = o;
		}
		br.close();

		Arrays.sort(arr, (o1, o2) -> o1.a - o2.a);
		TreeSet<Integer> set = new TreeSet<>();
		set.add(-1);
		set.add(n);
		long ans = 0;
		for (Obj o : arr) {
			long l = o.i - set.lower(o.i);
			long r = set.higher(o.i) - o.i;
			ans += l * r * o.a;
			set.add(o.i);
		}
		System.out.println(ans);
	}

	static class Obj {
		int i, a;
	}
}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int[] a = new int[N];
		int[] rev = new int[N+1];
		for(int i=0; i<N; i++) {
			a[i] = sc.nextInt();
			rev[a[i]] = i;
		}

		long ans = 0;

		TreeSet<Integer> sorted = new TreeSet<>();
		sorted.add(-1);
		sorted.add(N);

		for(int i=1; i<=N; i++) {
			int l = sorted.lower(rev[i]);
			int r = sorted.higher(rev[i]);
			ans += (long)i*(rev[i]-l)*(r-rev[i]);
			sorted.add(rev[i]);
		}

		System.out.println(ans);
		sc.close();
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line = br.readLine();
		int n = Integer.parseInt(line);
		line = br.readLine();
		String[] flds = line.split(" ");
		int[] nums = new int[n];
		for (int i=0; i<n; i++) {
			nums[i] = Integer.parseInt(flds[i]);
		}
		long sum = 0;
		List<Integer> list = new ArrayList<Integer>();
		for (int l=0; l<n; l++) {
			int min = nums[l];
			for (int r=l; r<n; r++) {
				if (nums[r] < min) {
					min = nums[r];
				}
				if (min == 1) {
					sum += n-r;
					break;
				}
				if (min-2<list.size() && min-1 == list.get(min-2)) {
					sum += (n-r) * min;
					break;
				}
				sum += min;
			}
			list.add(nums[l]);
			Collections.sort(list);
		}
		System.out.println(sum);
	}

}

