public class Main {

    private void solve(FastScanner sc) {
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[sc.nextInt() - 1] = i;
        }
        long ans = 0;
        TreeSet<Integer> s = new TreeSet<>();
        s.add(-1);
        s.add(n);
        for (int i = 0; i < n; i++) {
            int p = a[i];
            s.add(p);
            ans += (i + 1) * ((long) (p - s.lower(p))) * (s.higher(p) - p);
        }
        System.out.println(ans);
    }

    /*
     * template
     */

