import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        System.out.println( solve() );
    }

    private static long solve() {
        Node first = build();

        long sum = 0;
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(first);

        while(!q.isEmpty()) {
            Node node = q.poll();
            int prev = 0;
            while(node != null) {
                sum += (long)node.a * (prev + 1) * (node.underSize + 1);

                if( node.under != null ) {
                    q.add(node.under);
                }
                prev += node.underSize + 1;
                node = node.right;
            }
        }

        return sum;
    }

    static Node build() {
        Focus focus = new Focus(A[0]);
        for (int i = 1; i < N; i++) {
            focus.add(A[i]);
        }
        return focus.first;
    }

    static class Focus {

        private Node first;
        private List<Node> nodes = new ArrayList<>(N);

        public Focus(int a) {
            first = new Node(a);
            nodes.add(first);
        }

        public void add(int a) {
            Node arg = new Node(a);

            int low = 0;
            int high = nodes.size();
            while(low < high) {
                int mid = (low+high)/2;
                if( nodes.get(mid).a < a ) {
                    low = mid+1;
                } else {
                    high = mid;
                }
            }

            if( low < nodes.size() ) {
                for (int i = 0; i < low; i++) {
                    Node node = nodes.get(i);
                    node.underSize ++;
                }

                nodes.get(low).right = arg;
                nodes.set(low, arg);

                int rem = nodes.size() - low - 1;
                for (int i = 0; i < rem; i++) {
                    nodes.remove(low + 1);
                }

            } else {
                for (Node node : nodes) {
                    node.underSize++;
                }
                nodes.get(nodes.size() - 1).under = arg;
                nodes.add(arg);
            }
        }
    }

    static class Node {
        int a;
        private Node right;
        private Node under;
        private int underSize;

        public Node(int a) {
            this.a = a;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

