        {
            rev[A[i]] = i;
        }

        TreeSet<Integer> nums = new TreeSet<>();
        nums.add(-1);
        nums.add(N);

        long sum = 0;
        for (int i = 1; i < N+1; i++)
        {
            int revIndex = rev[i];
            nums.add(revIndex);
            int l = revIndex - nums.lower(revIndex);
            int r = nums.higher(revIndex) - revIndex;
            sum += (long)l * r * i;
        }
        System.out.println(sum);

    }

