public class Main {

    static int N;
    static int[] A;
    static int[] X;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = new int[N];
        X = new int[N+1];
        X[0] = -1;
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            X[A[i]] = i;
        }
        System.out.println( solve() );
    }

    private static long solve() {
        List<Integer> indice = new ArrayList<>();
        long sum = 0;
        for (int a = 1; a <= N; a++) {
            int ai = X[a];
            add(indice, ai);

            int ii = indice.indexOf(ai);
            int l;
            if( ii == 0 ) {
                l = ai + 1;

            } else {
                int lai = indice.get(ii-1);
                l = ai - lai;
            }

            int r;
            if( ii == indice.size()-1) {
                r = N - ai;

            } else {
                int rai = indice.get(ii+1);
                r = rai - ai;
            }

            sum += (long)a * l * r;
        }
        return sum;
    }

    static void add(List<Integer> indice, int i) {
        int low = 0;
        int high = indice.size();

        while( low < high ) {
            int mid = (low + high) / 2;

            if( indice.get(mid) < i ) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        indice.add(low, i);
    }

