import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println( solve() );
    }

    private static long solve() {
        return count(0, N);
    }

    static long count(int start, int end) {
        long count = 0;
        int curr = start;
        for (int i = start + 1; i < end; i++) {
            if( A[curr] < A[i] ) continue;

            int turn = curr - start + 1;
            int size = i - curr;
            count += (long)A[curr] * turn * size;

            if( size > 1 ) {
                long sub = count(curr+1, i);
                count += sub;
            }

            curr = i;
        }

        int turn = curr - start + 1;
        int size = end - curr;
        count += (long)A[curr] * turn * size;

        if( size > 1 ) {
            long sub = count(curr+1, end);
            count += sub;
        }

        return count;
    }

    static Graph build(int start, int end) {
        List<Node> nodes = new ArrayList<>();
        Node node = new Node(A[start]);
        nodes.add(node);
        int prev = start;
        for (int i = start + 1; i < end; i++) {
            if( node.n < A[i] ) continue;

            if( i - prev > 1 ) {
                node.sub = build(prev+1, i);
            }

            Node next = new Node(A[i]);
            nodes.add(next);
            prev = i;
            node = next;
        }
        if( prev != end-1 ) {
            node.sub = build(prev+1, end);
        }

        return new Graph(nodes);
    }

    static class Graph {
        List<Node> nodes;
        int sizeCache = -1;

        public Graph(List<Node> nodes) {
            this.nodes = nodes;
        }

        public String toString() {
            return nodes.toString();
        }

        public long calcCountSum(int prev) {
            long sum = 0;
            for (int i = 0; i < nodes.size(); i++) {
                Node node = nodes.get(i);
                sum += node.calcCountSum(prev);
                prev += node.size();
            }
            return sum;
        }

        public int size() {
            if( sizeCache == -1 ) {
                int sum = 0;
                for (Node node : nodes) {
                    sum += node.size();
                }
                sizeCache = sum;
            }
            return sizeCache;
        }
    }

    static class Node {
        int n;
        Graph sub;

        int sizeCache = -1;

        public Node(int n) {
            this.n = n;
        }

        @Override
        public String toString() {
            if( sub != null ) {
                return "Node(" + n + ", " + sub + ")";
            } else {
                return "Node(" + n + ")";
            }
        }

        public long calcCountSum(int prev) {
            long sum = 0;
            sum += (long)n * (prev+1) * size();
            if( sub != null ) {
                sum += sub.calcCountSum(0);
            }
            return sum;
        }

        public int size() {
            if( sizeCache == -1 ) {
                sizeCache = sub != null ? 1 + sub.size() : 1;
            }
            return sizeCache;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
