	void solve(){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		long[]a=new long[n];
		for(int i=0;i<n;i++){
			a[i]=sc.nextLong();
		}
		int[] count=new int[n];
		for(int i=0;i<n;i++){
			int left=1;
			int right=1;
			while(i-left>=0 && a[i-left]>a[i]){
				left++;
			}
			while(i+right<=n-1 && a[i+right]>a[i]){
				right++;
			}
			count[i]=right*left;
		}
		long ans=0;
		for(int i=0;i<n;i++){
			ans+=a[i]*count[i];
		}
		System.out.println(ans);
	}
}

import java.util.Scanner;
import java.util.TreeSet;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int a[] = new int[n];
		int p[] = new int[n];
		for(int i=0;i<n;i++) {
			a[i] = sc.nextInt()-1;
			p[a[i]] = i;
		}
		TreeSet<Integer> x = new TreeSet<Integer>();
		int l[] = new int[n];
		int r[] = new int[n];
		for(int i=0;i<n;i++) {
			x.add(p[i]);
			if(x.first()==p[i]) {
				l[i] =p[i]+1;
			}
			else {
				int lower = x.lower(p[i]);
				l[i] = p[i]-lower;
			}
			if(x.last()==p[i]) {
				r[i] = n-p[i];
			}
			else {
				int high = x.higher(p[i]);
				r[i] = high-p[i];
			}
		}
		long ans = 0;
		for(int i=0;i<n;i++) {
			ans+=(long) l[i]*r[i]*(i+1);
		}
		System.out.println(ans);

	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println( solve() );
    }

    private static long solve() {
        Graph g = build(0, N);

        return g.calcCountSum(0);
    }

    static Graph build(int start, int end) {
        List<Node> nodes = new ArrayList<>();
        Node node = new Node(A[start]);
        nodes.add(node);
        int prev = start;
        for (int i = start + 1; i < end; i++) {
            if( node.n < A[i] ) continue;

            if( i - prev > 1 ) {
                node.sub = build(prev+1, i);
            }

            Node next = new Node(A[i]);
            nodes.add(next);
            prev = i;
            node = next;
        }
        if( prev != end-1 ) {
            node.sub = build(prev+1, end);
        }

        return new Graph(nodes);
    }

    static class Graph {
        List<Node> nodes;

        public Graph(List<Node> nodes) {
            this.nodes = nodes;
        }

        public String toString() {
            return nodes.toString();
        }

        public long calcCountSum(int prev) {
            long sum = 0;
            for (int i = 0; i < nodes.size(); i++) {
                Node node = nodes.get(i);
                sum += node.calcCountSum(prev);
                prev += node.size();
            }
            return sum;
        }

        public int size() {
            int sum = 0;
            for (Node node : nodes) {
                sum += node.size();
            }
            return sum;
        }
    }

    static class Node {
        int n;
        Graph sub;

        public Node(int n) {
            this.n = n;
        }

        @Override
        public String toString() {
            if( sub != null ) {
                return "Node(" + n + ", " + sub + ")";
            } else {
                return "Node(" + n + ")";
            }
        }

        public long calcCountSum(int prev) {
            long sum = 0;
            sum += n * (prev+1) * size();
            if( sub != null ) {
                sum += sub.calcCountSum(0);
            }
            return sum;
        }

        public int size() {
            return sub != null ? 1 + sub.size() : 1;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

