class Main{
    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        int[] a = new int[N];
        for(int i=0;i<N;++i){
            a[i] = scan.nextInt();
        }
        int[] leftl = new int[N];
        int[] rightl = new int[N];

        ArrayDeque<Integer> que = new ArrayDeque<>();
        int index = 0;
        while(index<N){
            while(!que.isEmpty() && a[que.peek()] > a[index]){
                int ind = que.poll();
                rightl[ind] = index-ind -1;
            }
            que.push(index++);
        }
        while(!que.isEmpty()){
            int ind = que.poll();
            rightl[ind] = N - ind -1;
        }

        index = N-1;
        while(index>=0){
            while(!que.isEmpty() && a[que.peek()] > a[index]){
                int ind = que.poll();
                leftl[ind] = ind - index -1;
            }
            que.push(index--);
        }
        while(!que.isEmpty()){
            int ind = que.poll();
            leftl[ind] = ind - index -1;
        }

        long ans = 0;
        for(int i=0;i<N;++i){
            ans += (long)a[i]*(leftl[i]+1)*(rightl[i]+1);
        }
        System.out.println(ans);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println( solve() );
    }

    private static long solve() {
        Graph g = build(0, N);
        g.calcCount();
        long sum = 0;

        while(!g.isEmpty()) {
            sum += g.count;
            g.removeFirst();
        }
        return sum;
    }

    static Graph build(int start, int end) {
        List<Node> nodes = new ArrayList<>();
        Node node = new Node(A[start]);
        nodes.add(node);
        int prev = start;
        for (int i = start + 1; i < end; i++) {
            if( node.n < A[i] ) continue;

            if( i - prev > 1 ) {
                node.sub = build(prev+1, i);
            }

            Node next = new Node(A[i]);
            nodes.add(next);
            prev = i;
            node = next;
        }
        if( prev != end-1 ) {
            node.sub = build(prev+1, end);
        }

        return new Graph(nodes);
    }

    static class Graph {
        List<Node> nodes;
        long count = 0;

        public Graph(List<Node> nodes) {
            this.nodes = nodes;
        }

        public String toString() {
            return nodes.toString();
        }

        public boolean isEmpty() {
            return nodes.isEmpty();
        }

        public void removeFirst() {
            Node first = nodes.remove(0);
            count -= first.count;

            if( first.sub != null ) {
                // addFirstAll みたいなのがあるといいんだけどね
                int len = first.sub.nodes.size();
                for (int i = 0; i < len; i++) {
                    Node n = first.sub.nodes.get(i);
                    nodes.add(i, n);
                    count += n.count;
                }
            }
        }

        public void calcCount() {
            long sum = 0;
            for (Node node : nodes) {
                node.calcCount();
                sum += node.count;
            }
            count = sum;
        }

        public int size() {
            int sum = 0;
            for (Node node : nodes) {
                sum += node.size();
            }
            return sum;
        }
    }

    static class Node {
        int n;
        Graph sub;
        int count;

        public Node(int n) {
            this.n = n;
        }

        @Override
        public String toString() {
            if( sub != null ) {
                return "Node(" + n + ", " + sub + ")";
            } else {
                return "Node(" + n + ")";
            }
        }

        public void calcCount() {
            count = sub != null ? n * (sub.size()+1) : n;
            if( sub != null ) sub.calcCount();
        }

        public int size() {
            return sub != null ? 1 + sub.size() : 1;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;
import java.util.TreeSet;

public class Main {
    static class Node {
        int value;
        int index;

        Node(int value, int index) {
            this.value = value;
            this.index = index;
        }

        @Override
        public String toString() {
            return "Node{" +
                   "value=" + value +
                   ", index=" + index +
                   '}';
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Node> value = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Node node = new Node(scanner.nextInt(), i);
            value.add(node);
        }
        Collections.sort(value, new Comparator<Node>() {
            @Override
            public int compare(Node o1, Node o2) {
                return o1.value - o2.value;
            }
        });
        TreeSet<Node> set = new TreeSet<>(new Comparator<Node>() {
            @Override
            public int compare(Node o1, Node o2) {
                return o1.index - o2.index;
            }
        });
        BigDecimal r = new BigDecimal((n - value.get(0).index) * (value.get(0).index + 1));
        set.add(value.get(0));

        for (int i = 2; i <= n; i++) {
            Node my = value.get(i - 1);
            set.add(my);
            int myIndex = my.index;
            Node left = set.lower(my);
            Node right = set.higher(my);
            BigDecimal current = new BigDecimal(my.value);
            if (left != null) {
                current = current.multiply(new BigDecimal(myIndex - left.index));
            } else {
                current = current.multiply(new BigDecimal(myIndex + 1));
            }
            if (right != null) {
                current = current.multiply(new BigDecimal(right.index - myIndex));
            } else {
                current = current.multiply(new BigDecimal(n - myIndex));
            }
            r = r.add(current);
        }
        System.out.println(r);
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Function;


/**
 * Created by Katushka on 11.03.2020.
 */
public class Main {

    public static final Comparator<int[]> COMPARATOR = Comparator.comparingInt(o -> o[0]);

    static Integer[] readArray(int size, InputReader in) {
        Integer[] a = new Integer[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextInt();
        }
        return a;
    }

    static long[] readLongArray(int size, InputReader in) {
        long[] a = new long[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextLong();
        }
        return a;
    }

    static void sortArray(int[] a) {
        Random random = new Random();

        for (int i = 0; i < a.length; i++) {
            int randomPos = random.nextInt(a.length);
            int t = a[i];
            a[i] = a[randomPos];
            a[randomPos] = t;
        }
        Arrays.sort(a);
    }

    interface AssociativeFunction<A> {
        A apply(A a, A b);
    }

    static class SegTree<A, B> {
        private final AssociativeFunction<A> func;
        private final A start;
        private final Function<B, A> converter;
        private int size;
        private final A[] tree;

        SegTree(B[] a, AssociativeFunction<A> func, Function<Integer, A[]> arrayConstructor, A start, Function<B, A> converter) {
            this.func = func;
            this.start = start;
            this.converter = converter;
            size = 1;
            while (size < a.length) {
                size *= 2;
            }
            tree = arrayConstructor.apply(2 * size - 1);

            build(a, 0, 0, size, converter);
        }

        private void build(B[] a, int x, int lx, int rx, Function<B, A> converter) {
            if (rx - lx == 1) {
                if (lx < a.length) {
                    tree[x] = converter.apply(a[lx]);
                }
            } else {
                int m = (rx + lx) / 2;
                build(a, 2 * x + 1, lx, m, converter);
                build(a, 2 * x + 2, m, rx, converter);
                tree[x] = func.apply(tree[2 * x + 1], tree[2 * x + 2]);
            }
        }

        public void set(int i, B v) {
            set(i, v, 0, 0, size);
        }

        private void set(int i, B v, int x, int lx, int rx) {
            if (rx - lx == 1) {
                tree[x] = converter.apply(v);
                return;
            }
            int m = (rx + lx) / 2;
            if (i >= m) {
                set(i, v, 2 * x + 2, m, rx);
            } else {
                set(i, v, 2 * x + 1, lx, m);
            }
            tree[x] = func.apply(tree[2 * x + 1], tree[2 * x + 2]);
        }

        public A result(int l, int r) {
            return result(l, r, 0, 0, size);
        }

        private A result(int l, int r, int x, int lx, int rx) {
            if (l >= rx || lx >= r) {
                return start;
            }
            if (lx >= l && rx <= r) {
                return tree[x];
            }
            int m = (lx + rx) / 2;
            return func.apply(result(l, r, 2 * x + 1, lx, m), result(l, r, 2 * x + 2, m, rx));
        }
    }

    public static void main(String[] args) throws FileNotFoundException {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = in.nextInt();
        Integer[] a = readArray(n, in);

        int[] pos = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pos[a[i]] = i;
        }
        SegTree<Integer, Integer> segTree = new SegTree<>(a, Math::min, t -> {
            Integer[] res = new Integer[t];
            Arrays.fill(res, Integer.MAX_VALUE);
            return res;
        }, Integer.MAX_VALUE, integer -> integer);
        long ans = solve(0, n, segTree, pos, n);
        out.println(ans);
        out.close();
    }

    private static long solve(int l, int r, SegTree<Integer, Integer> segTree, int[] pos, int n) {
        int min = segTree.result(l, r);
        int p = pos[min];
        long ans = ((long) (p - l + 1)) * (r - p) * min;
        if (r - l > 1) {
            if (p > l) {
                ans += solve(l, p, segTree, pos, n);
            }
            if (p < r - 1) {
                ans += solve(p + 1, r, segTree, pos, n);
            }
        }
        return ans;
    }


    private static void outputArray(long[] ans, PrintWriter out) {
        StringBuilder str = new StringBuilder();
        for (long an : ans) {
            str.append(an).append(" ");
        }
        out.println(str);
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            return tokenizer.nextToken();
        }

        private void createTokenizer() {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public String nextString() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }

        public int[] nextInts() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            List<Integer> res = new ArrayList<>();
            while (tokenizer.hasMoreElements()) {
                res.add(Integer.parseInt(tokenizer.nextToken()));
            }
            int[] resArray = new int[res.size()];
            for (int i = 0; i < res.size(); i++) {
                resArray[i] = res.get(i);
            }
            return resArray;
        }
    }
}

import java.io.BufferedReader;
