namespace AtCoder
{
    static class Extension
    {
        public static int SmallerValue(this SortedSet<int> set, int n)
        {
            int N = set.Count;
            int a = 0;
            int b = N - 1;
            if (n < set.ElementAt(a)) { return set.ElementAt(a); }
            if (set.ElementAt(b) < n) { return set.ElementAt(b); }
            while (b - a > 1)
            {
                int i = (a + b) / 2;
                if (set.ElementAt(i) < n) { a = i; } else { b = i; }
            }
            return set.ElementAt(a);
        }
        public static int GreaterValue(this SortedSet<int> set, int n)
        {
            int N = set.Count;
            int a = 0;
            int b = N - 1;
            if (n < set.ElementAt(a)) { return set.ElementAt(a); }
            if (set.ElementAt(b) < n) { return set.ElementAt(b); }
            while (b - a > 1)
            {
                int i = (a + b) / 2;
                if (set.ElementAt(i) < n) { a = i; } else { b = i; }
            }
            return set.ElementAt(b);
        }
    }
    class Program
    {
        private const int MODULO = 1000000007;
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static long Solve(int N, int[] A)
        {
            var pos = new int[N];
            for (int i = 0; i < N; ++i) { pos[A[i] - 1] = i; }
            var set = new SortedSet<int> { -1, N };
            long sum = 0;
            for (int i = 0; i < N; ++i)
            {
                int p = pos[i];
                var a = set.SmallerValue(p);
                var b = set.GreaterValue(p);
                sum += Math.BigMul(p - a, b - p) * (i + 1);
                set.Add(p);
            }
            return sum;
        }
        static void Main(string[] args)
        {
            var N = ReadInt();
            var A = ReadInts();
            Console.WriteLine(Solve(N, A));
        }
    }
