        public class UnionFind
        {
            private int[] parents;
            private int[] min;
            private int[] max;

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public UnionFind(int count)
            {
                parents = Enumerable.Repeat(-1, count).ToArray();
                min = Enumerable.Range(0, count).ToArray();
                max = Enumerable.Range(0, count).ToArray();
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool TryUnite(int x, int y)
            {
                var rootX = GetRoot(x);
                var rootY = GetRoot(y);

                if (rootX == rootY)
                    return false;

                if (parents[rootY] < parents[rootX])
                {
                    var temp = rootX;
                    rootX = rootY;
                    rootY = temp;
                }
                parents[rootX] += parents[rootY];
                parents[rootY] = rootX;

                min[rootY] = min[rootX] = Math.Min(min[rootX], min[rootY]);
                max[rootY] = max[rootX] = Math.Max(max[rootX], max[rootY]);

                return true;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool Find(int x, int y) => GetRoot(x) == GetRoot(y);

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public int GetRoot(int x)
            {
                while (parents[x] >= 0)
                    x = parents[x];
                return x;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public int GetMin(int x)
            {
                return min[GetRoot(x)];
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public int GetMax(int x)
            {
                return max[GetRoot(x)];
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public long GetSize(int x) => -parents[GetRoot(x)];
        }
        public class IterTools
