    class SparseTable<T>
    {
        private const int MAX_LENGTH = 100000;
        private static int[] log = new int[MAX_LENGTH + 1];

        private readonly Comparison<T> comparison;
        private readonly int[,] table;
        private readonly T[] data;
        private readonly int length;
        private readonly int height;

        static SparseTable()
        {
            int c = 1;
            for (int i = 1; c <= MAX_LENGTH; i++)
                for (; c <= MAX_LENGTH && c < 1 << i; c++)
                    log[c] = i - 1;
        }

        public SparseTable(Comparison<T> comparison, T[] array)
        {
            this.comparison = comparison;
            data = array;
            length = array.Length;
            height = log[length] + 1;

            table = new int[length, height];
            for (int i = 0; i < length; i++)
                table[i, 0] = i;

            for (int i = 1; i < height; i++)
            {
                int bi = 1 << i;
                int pbi = 1 << i - 1;
                for (int j = 0; j + bi <= length; j++)
                {
                    int left = table[j, i - 1];
                    int right = table[j + pbi, i - 1];
                    if (comparison(data[left], data[right]) < 0)
                        table[j, i] = left;
                    else
                        table[j, i] = right;
                }
            }
        }

        public int Query(int l, int r)
        {
            int w = log[r - l + 1];
            int left = table[l, w];
            int right = table[r - (1 << w) + 1, w];
            if (comparison(data[left], data[right]) < 0)
                return left;
            return right;
        }
    }

    int[] a;
    SparseTable<int> table;

    long Fun(int l, int r)
    {
        if (l > r)
            return 0;
        int x = table.Query(l, r);
        return 1L * a[x] * (x - l + 1) * (r - x + 1) + Fun(l, x - 1) + Fun(x + 1, r);
    }

    public void Solve()
