        int n = ReadInt();
        a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = ReadInt();
        table = new SparseTable<int>((x1, x2) => x1.CompareTo(x2), a);

        Write(Fun(0, n - 1));
    }

