	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int N;
		int[] a;
		void Read()
		{
			N = sc.Int;
			a = sc.ReadMany<int>();
		}
		void SolveOne()
		{
			var b = new int[N];
			for (var i = 0; i < N; i++) b[--a[i]] = i;
			var bit = new BinaryIndexedTree(N);
			var sum = 0L;
			for (var i = 0; i < N; i++)
			{
				var left = b[i] == 0 ? 0 : FirstBinary(0, b[i] + 1, x => bit.Sum(b[i] - x, b[i] + 1) > 0) - 1;
				var right = FirstBinary(1, N - b[i], x => bit.Sum(b[i], b[i] + x + 1) > 0) - 1;
				sum += (i + 1L) * (left + 1L) * (right + 1L);
				bit.Add(b[i], 1);
			}
			pr.WriteLine(sum);
		}
	}
