public class Program
{
    public void Solve()
    {
        int N = Reader.Int();
        var A = Reader.IntArray(N);
        long ans = 0;
        var uf = new UnionFind(N, A);
        var at = new int[N + 2];

        for (int i = 0; i < N; i++)
            at[A[i]] = i;
        for (int num = N; num >= 1; num--)
        {
            int x = at[num];
            bool isL = x > 0 && uf.Min[x - 1] > num;
            bool isR = x < N - 1 && uf.Min[x + 1] > num;
            int L = isL ? uf.NumElements(x - 1) : 0;
            int R = isR ? uf.NumElements(x + 1) : 0;
            ans += (long)num * (L + 1) * (R + 1);
            if (isL) uf.Unite(x, x - 1);
            if (isR) uf.Unite(x, x + 1);
        }

        Console.WriteLine(ans);
    }


    class UnionFind
    {
        private int[] parent;
        private int[] rank;
        private int[] numElements;
        public int[] Min;

        public UnionFind(int N, int[] A)
        {
            parent = new int[N];
            rank = new int[N];
            numElements = new int[N];
            Min = new int[N];

            for (int i = 0; i < N; i++)
            {
                parent[i] = i;
                numElements[i] = 1;
                Min[i] = A[i];
            }
        }
        public int Root(int x)
        {
            if (parent[x] == x) return x;
            return parent[x] = Root(parent[x]);
        }
        public bool Same(int x, int y)
        {
            return Root(x) == Root(y);
        }
        public int NumElements(int x)
        {
            return numElements[Root(x)];
        }
        public bool Unite(int x, int y)
        {
            x = Root(x); y = Root(y);
            if (x == y) return false;
            if (rank[x] > rank[y]) { var t = x; x = y; y = t; }
            if (rank[x] == rank[y]) rank[y]++;
            parent[x] = y;
            numElements[y] += numElements[x];
            Min[y] = Math.Min(Min[y], Min[x]);
            return true;
        }
        public Dictionary<int, List<int>> Components()
        {
            var dic = new Dictionary<int, List<int>>();
            for (int i = 0; i < parent.Length; i++)
            {
                int root = Root(i);
                if (!dic.ContainsKey(root)) dic[root] = new List<int>();
                dic[root].Add(i);
            }
            return dic;
        }
    }
}


