	    public class Calc
	    {
	        public void Solve() {
	            // AGC005 B

	            var N = NextInt();
	            var A = NextLongList();

                //Rootが最大値になる区間をUnion-Findで表す
                var suf=new SectionUnionFind(N);

	            var pos = new int[N];
	            for (int i = 0; i < N; i++) {
	                pos[A[i] - 1] = i;
	            }

	            var ans = 0L;
	            for (int i = N - 1; i >= 0; i--) {
	                var idx = pos[i];
	                ans += A[idx];
                    //左右がidxより大きかったら区間に加える
	                if (idx - 1 >= 0 && A[idx - 1] > A[idx]) ans += suf.Unite(idx, idx-1) * A[idx];
	                if (idx + 1 < N && A[idx + 1] > A[idx]) ans += suf.Unite(idx, idx+1) * A[idx];
	            }
                ans.WL();

                return;
	        }
	        public struct SectionUnionFind
	        {
	            private readonly int N;
	            public int[] Parent { get; private set; }
	            public long[] Cost { get; private set; }

	            public SectionUnionFind(int n)
	            {
	                N = n;
	                Parent = Enumerable.Range(0, N).ToArray();
	                Cost = Enumerable.Repeat(1L, N).ToArray();
	            }

	            public int Root(int x)
	            {
	                return Parent[x] == x ? x : Parent[x] = Root(Parent[x]);
	            }

	            public long Unite(int x, int y)
	            {
	                x = Root(x);
	                y = Root(y);
	                var res = Cost[x] * Cost[y];
	                Cost[x] += Cost[y];
	                Parent[y] = x;
	                return res;
	            }
	        }
        }
    }
}
namespace Nakov.IO {
	using System;
	using System.Text;
	using System.Globalization;

	public static class Cin {
		public static string NextToken() {
			StringBuilder tokenChars = new StringBuilder();
			bool tokenFinished = false;
			bool skipWhiteSpaceMode = true;
			while (!tokenFinished) {
				int nextChar = Console.Read();
				if (nextChar == -1) {
					tokenFinished = true;
				} else {
					char ch = (char)nextChar;
					if (char.IsWhiteSpace(ch)) {
						if (!skipWhiteSpaceMode) {
							tokenFinished = true;
							if (ch == '\r' && (Environment.NewLine == "\r\n")) {
								Console.Read();
							}
						}
					} else {
						skipWhiteSpaceMode = false;
						tokenChars.Append(ch);
					}
				}
			}

			string token = tokenChars.ToString();
			return token;
		}

		public static int NextInt() {
			string token = Cin.NextToken();
			return int.Parse(token);
		}
		public static long NextLong() {
			string token = Cin.NextToken();
			return long.Parse(token);
		}
		public static double NextDouble(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				double result = double.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				double result = double.Parse(token);
				return result;
			}
		}
		public static decimal NextDecimal(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				decimal result = decimal.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				decimal result = decimal.Parse(token);
				return result;
			}
		}

	}
