    class Program
    {
        static int N;
        static long ans;
        static void Main(string[] args)
        {
            N = scan[0];
            var A = scan;

            //区間は NC2 （始点と終点を選ぶ）
            var B = new int[N + 1];
            for (int i = 1; i <= N; i++)
            {
                B[A[i - 1]] = i;
            }

            //C#のSetにはLowerBoundがないけども
            var G = new SortedSet<int>();
            for (int i = 1; i <= N; i++)
            {
                G.Add(B[i]);
                var D = G.ToArray();
                var d = LowerBound(D, B[i]);
                int l = (d == 0) ? D[d] : D[d] - D[d - 1];
                int r = (d == i - 1) ? N -  D[d] + 1 : D[d + 1] - D[d];
                ans += (long)l * r * i;
                //Console.WriteLine(d+" " +l+" "+r+" "+ans);

            }
            Console.WriteLine(ans);

        }

        static int LowerBound(int[] arr, int val)
        {
            int low = 0, high = arr.Count();
            int mid;

            while (low < high)
            {
                mid = ((high - low) >> 1) + low;
                if (arr[mid] < val) low = mid + 1;
                else high = mid;
            }
            return low;
        }
        static int[] scan { get { return Array.ConvertAll(Console.ReadLine().Split(), int.Parse); } }
    }
}

