public static long BS<T>(BinaryIndexedTree seq, T value,int count)  where T : IComparable<T> {
	int left = -1;
	int right = count;
	while (right - left > 1) {
		int mid = left + (right - left) / 2;
		if (0<=seq.Sum(mid).CompareTo(value)) right = mid;
		else left = mid;
	}
	return right;
}
public class BinaryIndexedTree {
	private long[] data;

	public BinaryIndexedTree(long sz) { data = new long[++sz]; }
	public long Sum(long k) {
		long ret = 0;
		for(++k; k > 0; k -= k & -k) ret += data[k];
		return (ret);
	}
	public void Add(long k, long x) { for(++k; k < data.Length; k += k & -k) data[k] += x; }
}
















