class Magatro
{
    private int N;
    private int[]A;
    private void Scan()
    {
        N=int.Parse(Console.ReadLine());
        var l=Console.ReadLine().Split(' ');
        A=new int[N];
        for(int i=0;i<N;i++)
        {
            A[i]=int.Parse(l[i]);
        }
    }

    public void Solve()
    {
        Scan();
        var index=new int[N+1];
        for(int i=0;i<N;i++)
        {
            index[A[i]]=i;
        }
        var sortedSet=new SortedSet<int>();
        sortedSet.Add(-1);
        sortedSet.Add(N);
        long anser=0;
        for(int i=1;i<=N;i++)
        {
            int left,right;
            var array = sortedSet.ToList();
            //Console.WriteLine(string.Join(" ",array));
            //hidari
            left=0;
            right=array.Count;
            while(right-left>1)
            {
                int mid=(left+right)/2;
                if(array[mid]<index[i])
                {
                    left=mid;
                }
                else
                {
                    right=mid;
                }
            }
            //Console.WriteLine($"{i} {index[i]} {array[left]} {array[right]}");
            anser+=(long)(index[i]-array[left])*(array[right]-index[i])*i;
            sortedSet.Add(index[i]);
        }
        Console.WriteLine(anser);
    }
}

