		{
			using var cin = new Scanner();
			int n = cin.Int();
			var a = new (int a, int i)[n];
			for (int i = 0; i < n; i++) {
				a[i] = (cin.Int(), i);
			}

			var b = a.OrderBy(x => x.a).ToArray();

			long ans = 0;
			var set = new RedBlackTree<int>();
			set.Add(-1);
			set.Add(n);
			for (int i = 0; i < n; i++) {
				var t = b[i];

				var temp = set.UpperBoundIndex(t.i);
				int left = set.FindByIndex(temp - 1).Item;
