	class UnionFind
	{
		int N;
		int[] parent;
		int[] rank;
		int[] size;

		public UnionFind(int N)
		{
			this.N = N;
			parent = new int[N];
			rank = new int[N];
			size = new int[N];
			for (int i = 0; i < N; i++)
			{
				parent[i] = i;
				size[i] = 1;
			}
		}

		public int find(int x)
		{
			if (parent[x] == x)
			{
				return x;
			}
			else
			{
				return parent[x] = find(parent[x]);
			}
		}

		public long unite(int x, int y)
		{
			x = find(x);
			y = find(y);
			long s = (long)size[x] * size[y];
			if (rank[x] < rank[y])
			{
				parent[x] = y;
				size[y] += size[x];
			}
			else
			{
				parent[y] = x;
				size[x] += size[y];
				if (rank[x] == rank[y]) rank[x]++;
			}
			return s;
		}

		public bool same(int x, int y)
		{
			return find(x) == find(y);
		}
	}
}

