namespace atcoder
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            Dictionary<int,int> A = Console.ReadLine().Split().Select((f,i) => new Tuple<int,int>(int.Parse(f),i)).ToDictionary(f=>f.Item1,f=>f.Item2);

            long sum = 0;
            for (int i = 1; i <= n; i++)
            {
                int lef = 0;
                int rig = n-1;
                var lefB = A.Where(f => f.Key < i && f.Value < A[i]);
                if (lefB.Count() > 0)
                    lef = lefB.Max(f => f.Value)+1;
                var rigB = A.Where(f => f.Key < i && f.Value > A[i]);
                if (rigB.Count() > 0)
                    rig = rigB.Min(f => f.Value)-1;
                sum += i * (A[i] - lef + 1) * (rig - A[i] + 1);
            }
            Console.WriteLine(sum);
        }
    }
}

