            var A = scan;
            //区間は NC2 （始点と終点を選ぶ）
            var B = new int[N];
            for (int i = 0; i < N; i++)
            {
                B[A[i] - 1] = i;
            }

            //C#のSetにはLowerBoundがないけども
            var G = new SortedSet<int>();
            for (int i = 0; i < N; i++)
            {
                G.Add(B[i]);
                var D = G.ToArray();
                var d = LowerBound(D, B[i]);

                int l = (d == 0) ? D[d] + 1 : D[d] - D[d - 1];
                int r = (d == i) ? N -  D[d] : D[d + 1] - D[d];
                ans += (long)l * r * (i + 1);
                //Console.WriteLine(d+" " +l+" "+r+" "+ans);

            }
            Console.WriteLine(ans);

        }

        static int LowerBound(int[] arr, int val)
        {
            int low = 0, high = arr.Count();
            int mid;

            while (low < high)
            {
                mid = ((high - low) >> 1) + low;
                if (arr[mid] < val) low = mid + 1;
                else high = mid;
            }
            return low;
        }
        static int[] scan { get { return Array.ConvertAll(Console.ReadLine().Split(), int.Parse); } }
    }
}

