func minSum(n int, a []int) int {
	sum := 0
	for l := 0; l < n; l++ {
		for r := l; r < n; r++ {
			isSet := false
			min := 0
			for i := l; i <= r; i++ {
				if !isSet || a[i] < min {
					isSet = true
					min = a[i]
				}
			}
			sum += min
		}
	}
	return sum
}

