type Segment struct {
	n, h, i int
	unit    []int
	bucket  [][]int
}

func (seg *Segment) init(n int) {
	seg.n = n
	seg.unit = make([]int, 1)
	seg.unit[0] = 1
	seg.bucket = make([][]int, 1)
	seg.bucket[0] = make([]int, n)

	chunk := 2
	i := 0
	for n > chunk+1 {
		n = (n-1)/chunk + 1
		seg.bucket = append(seg.bucket, make([]int, n))
		seg.unit = append(seg.unit, seg.unit[i]*chunk)
		i++
	}
	seg.h = len(seg.unit)
}

func (seg *Segment) add(index, value int) {
	for i := 0; i < seg.h; i++ {
		seg.bucket[i][index/seg.unit[i]] += value
	}
}

func (seg *Segment) nextLeft(index int) int {
	raw := seg.bucket[0]
	for index = index - 1; index >= 0; index-- {
		if raw[index] > 0 {
			return index
		}
		for seg.i = 0; seg.i < seg.h; seg.i++ {
			if (index+1)%seg.unit[seg.i] != 0 {
				break
			}
			if seg.bucket[seg.i][index/seg.unit[seg.i]] != 0 {
				break
			}
		}
		seg.i--
		index -= seg.unit[seg.i] - 1
	}

	return -1
}

func (seg *Segment) nextRight(index int) int {
	raw := seg.bucket[0]
	for index = index + 1; index < seg.n; index++ {
		if raw[index] > 0 {
			return index
		}
		for seg.i = 0; seg.i < seg.h; seg.i++ {
			if index%seg.unit[seg.i] != 0 {
				break
			}
			if seg.bucket[seg.i][index/seg.unit[seg.i]] != 0 {
				break
			}
		}
		seg.i--

		index += seg.unit[seg.i] - 1
	}

	return seg.n
}

func (seg *Segment) get(index int) int {
	for i := 0; i < seg.n; i++ {
		for seg.i = 0; seg.i < seg.h; seg.i++ {
			if index%seg.unit[seg.i] != 0 {
				break
			}
			if seg.bucket[seg.i][index/seg.unit[seg.i]] >= index {
				break
			}
		}
		seg.i--

		index -= seg.bucket[seg.i][index/seg.unit[seg.i]]
		i += seg.unit[seg.i] - 1

		if index == 0 {
			return i
		}
	}

	return -1
}

