func query(a, b, k, l, r int, st []int) int {
	if r <= a || b <= l {
		return math.MaxInt64
	}
	if a <= l && r <= b {
		return st[k]
	}
	return min(query(a, b, k*2+1, l, (l+r)/2, st), query(a, b, k*2+2, (l+r)/2, r, st))
}

func main() {
	N := readInt()
	a := make([]int, N)
	for i := 0; i < N; i++ {
		a[i] = readInt()
	}

	n := 1
	for n < N {
		n *= 2
	}

	st := make([]int, 2*n-1)
	for i := 0; i < 2*n-1; i++ {
		st[i] = math.MaxInt64
	}

	for i := 0; i < N; i++ {
		k := i + n - 1
		st[k] = a[i]
		for k > 0 {
			k = (k - 1) / 2
			st[k] = min(st[k*2+1], st[k*2+2])
		}
	}

	result := 0
	for l := 0; l < N; l++ {
		for r := l; r < N; r++ {
			result += query(l, r+1, 0, 0, n, st)
		}
	}
	fmt.Println(result)
}

