type Node struct {
	childL, childR *Node
	value int // index
	priority int // value
	countL, countR int
}

func (n *Node) count() int {
	if n == nil {
		return 0
	}
	return n.childL.count() + n.childR.count() + 1
}

func (r *Node) rotateLeft() *Node {
	p := r.childR
	//a := r.childL
	b := p.childL
	//c := p.childR
	r.childR, p.childL = b, r
	r.countR = b.count()
	p.countL = r.count()
	return p
}

func (r *Node) rotateRight() *Node {
	p := r.childL
	//a := p.childL
	b := p.childR
	//c := r.childR
	r.childL, p.childR = b, r
	r.countL = b.count()
	p.countR = r.count()
	return p
}

func (n *Node) insert(value, priority int) *Node {
	if n == nil {
		return &Node{
			nil, nil,
			value,
			priority,
			0, 0,
		}
	}
	if value <= n.value {
		n.childL = n.childL.insert(value, priority)
		n.countL = n.childL.count()
		if n.childL.priority < n.priority {
			return n.rotateRight()
		}
		return n
	} else if value > n.value {
		n.childR = n.childR.insert(value, priority)
		n.countR = n.childR.count()
		if n.childR.priority < n.priority {
			return n.rotateLeft()
		}
		return n
	} else {
		panic("")
	}
}

func (n *Node) traverse(consumer func(*Node)) {
	if n == nil {
		return
	}
	n.childL.traverse(consumer)
	n.childR.traverse(consumer)
	consumer(n)
}

type Treap struct {
	root *Node
}

func (t *Treap) Insert(value, priority int) {
	t.root = t.root.insert(value, priority)
}

func (t *Treap) Traverse(consumer func(*Node)) {
	t.root.traverse(consumer)
}

func minSum(n int, a []int) int {
	t := &Treap{}
	for i, x := range a {
		t.Insert(i, x)
	}

	sum := 0
	consumer := func(n *Node) {
		sum += (n.countL + 1) * (n.countR + 1) * n.priority
	}
	t.Traverse(consumer)
	return sum
}

