	scanner.Split(bufio.ScanWords)

	n := scanInt(scanner) // 1 <= n <= 200,000
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = scanInt(scanner)
	}
	fmt.Println(minSum(n, a))
}

