func SlidingWindowMinimum(n, w int, a []int) []int {
	if w > n {
		w = n
	}
	result := make([]int, n-w+1)
	q := list.New()
	for i := 0; i < w; i++ {
		for q.Len() != 0 && a[i] <= a[q.Back().Value.(int)] {
			q.Remove(q.Back())
		}
		q.PushBack(i)
	}
	for i := w; i < n; i++ {
		result[i-w] = a[q.Front().Value.(int)]
		for q.Len() != 0 && a[i] <= a[q.Back().Value.(int)] {
			q.Remove(q.Back())
		}
		for q.Len() != 0 && q.Front().Value.(int) <= (i-w) {
			q.Remove(q.Front())
		}
		q.PushBack(i)
	}
	result[n-w] = a[q.Front().Value.(int)]
	return result
}

func minSum(n int, a []int) int {
	sum := 0
	for w := 1; w <= n; w++ {
		mins := SlidingWindowMinimum(n, w, a)
		for _, min := range mins {
			sum += min
		}
	}
	return sum
}

