module List = struct
  include List

  let rec repf' ~init ~n ~f =
    if n = 0 then init else repf' ~init:(f () :: init) ~f ~n:(n-1)

  let repf ~n ~f =
    assert (n >= 0);
    rev (repf' ~init:[] ~f ~n)

  let rec iteri' i t ~f =
    match t with
    | [] -> ()
    | hd::tl ->
      f i hd;
      iteri' (i+1) tl ~f

  let iteri t ~f = iteri' 0 t ~f

  let rec range' acc stride start_i stop_i =
    if (stop_i - start_i) * stride <= 0 then acc
    else
      range' (start_i::acc) stride (start_i + stride) stop_i

  let range ?(stride=1) start_i stop_i =
    rev (range' [] stride start_i stop_i)

  let fold t ~init ~f = fold_left f init t
end

