void solve(){
    int n = scan!int;
    long[] as = scan!long(n);

    auto psta = new Stack!S;
    long[] xs = new long[](n); // xs[i] は i の左方に続く as[i] より大きい数の最終位置
    foreach(i, a; as){
        while(! psta.isEmpty && psta.peek.value > a) psta.pop;
        if(psta.isEmpty) xs[i] = 0;
        else xs[i] = psta.peek.pos + 1;
        psta ~= S(i, a);
    }
    log("xs:", xs);

    auto qsta = new Stack!S;
    long[] ys = new long[](n); // ys[i] は i の右方で初めて as[i] より小さい数の位置
    foreach_reverse(i, a; as){
        while(! qsta.isEmpty && qsta.peek.value > a) qsta.pop;
        if(qsta.isEmpty) ys[i] = n;
        else ys[i] = qsta.peek.pos;
        qsta ~= S(i, a);
    }
    log("ys:", ys);

    long ans;
    foreach(i; 0 .. n) ans += as[i] * (i - xs[i] + 1) * (ys[i] - i);

    ans.writeln;
}
