struct Stack(T) {
    private {
        size_t cap, top;
        T[] data;
    }

    this (int n) in {
        assert(n > 0, "The capacity of a stack must be a positive integer.");
    }
    body {
        cap = n;
        data = new T[](cap);
    }

    void clear() {
        top = 0;
    }

    bool empty() {
        return !top;
    }

    bool full() {
        return top == cap;
    }

    size_t length() {
        return top;
    }

    T front() in {
        assert(!empty, "The stack is empty.");
    }
    body {
        return data[top - 1];
    }

    void removeFront() in {
        assert(!empty, "The stack is empty.");
    }
    body {
        top--;
    }

    alias popFront = removeFront;

    void insertFront(T x) in {
        assert(!full, "The stack is full.");
    }
    body {
        data[top++] = x;
    }

    alias insert = insertFront;

    T[] array() {
        import std.algorithm.mutation : reverse;

        T[] arr = data[0 .. cap].dup;
        arr.reverse();
        return arr;
    }

    string toString() {
        import std.format : format;
        import std.range : retro;

        return format("[%(%s, %)]", data[0 .. top].retro());
    }
}



