auto solve( long[] as )
{
	// 添字と値を逆にした配列を作成
	auto ais = new long[ as.length ];
	foreach( i, a; as )
	{
		ais[ a - 1 ] = i;
	}

	// 値が小さい順に処理
	auto ans = 0L;
	auto rbt = redBlackTree( -1L, ais.length.signed );
	foreach( a, ai; ais.enumerate( 1L ) )
	{
		// aより小さい値が含まれない最大範囲を二分検索して、パターン数を計算
		auto li = rbt.lowerBound( ai ).back;
		auto ri = rbt.upperBound( ai ).front;
		ans += a * ( ri - ai ) * ( ai - li );
		rbt.insert( ai );
	}
	return ans;
}

