type Op2[T] = proc(a, b: T): T 
type SegmentTree[T] = object
  size: int
  node: seq[T]
  default: T
  f: Op2[T]

proc initSegmentTree[T](n: int, default: T, f: Op2[T]): SegmentTree[T] =
  var size = 1
  while size < n:
    size *= 2
  result.size = size
  result.node = newSeqWith(2 * size, default)
  result.default = default
  result.f = f

proc update[T](this: var SegmentTree[T], x: int, value: T) =
  this.node[x + this.size] = value
  var idx = (x + this.size) div 2
  while idx > 0:
    this.node[idx] = this.f(this.node[idx * 2], this.node[idx * 2 + 1])
    idx = idx div 2

proc query[T](this: var SegmentTree[T], left, right: int): T =
  var L = left + this.size
  var R = right + this.size
  result = this.default
  while L < R:
    if (R mod 2 == 1):
      R.dec
      result = this.f(result, this.node[R])
    if (L mod 2 == 1):
      result = this.f(result, this.node[L])
      L.inc
    R = R div 2
    L = L div 2

