const INF = 10 ^ 9
var N = input(int, 1)
var A = input(int)

var idx = newseq[int](N + 1)
for i in 0..<N:
  idx[A[i]] = i

var seg = initSegmentTree[int](N, INF, (a: int, b: int) => min(a, b))
for i in 0..<N:
  seg.update(i, A[i])

var res = 0

var stack = newseq[tuple[s, t: int]]()
stack.add((0, N))
while stack.len > 0:
  var (s, t) = stack.pop()
  var m = seg.query(s, t) # 最小値
  var u = idx[m]
  res += (u - s + 1) * (t - u) * m
  if u - s > 0:
    stack.add((s, u))
  if t - (u + 1) > 0:
    stack.add((u + 1, t))

echo res

