class _UnionFind:
    __slots__ = ['id']
    def __init__(self, n):
        self.id = [-1] * n
    def find(self, x):
        if self.id[x] < 0:
            return x
        else:
            self.id[x] = self.find(self.id[x])
            return self.id[x]
    def union(self, x, y):
        x, y = self.find(x), self.find(y)
        res = self.id[x] * self.id[y]
        self.id[x] += self.id[y]
        self.id[y] = x
        return res

