def bin_search(queue, num):
    if len(queue) == 0:
        return 0
    l = 0
    r = len(queue)
    while r-l > 1:
        m = (l+r) // 2
        if queue[m] < num:
            l = m
        else:
            r = m

    if l == 0 and queue[0] > num:
        r = 0
    return r


