def get_range_minsum(l, r):
    if r - l == 1:
        return a[l]
    if r - l == 0:
        return 0 
    range_min, min_index = rmq.query(l,r)
    val = 0
    if min_index > l:
        val += get_range_minsum(l, min_index)
    if min_index < r-1:
        val += get_range_minsum(min_index+1, r)
    val += range_min * (min_index - l + 1) * (r - min_index)
    return val

