class Avltree:

  def __init__(self, key=None):
    self.key = key
    self.left = None
    self.right = None
    self.balance = "Even"

  def search(self, key):
    node = self
    while node is not None:
      if node.key == key:
        return node
      if node.key > key:
        node = node.left
      elif node.key < key:
        node = node.right
    return None

  def search_lower(self, key, key_lower):
    node = self
    if node.key is None:
      return key_lower
    ans = key_lower
    while node is not None:
      if node.key < key:
          if ans < node.key:
            ans = node.key
          node = node.right
      elif node.key >= key:
        node = node.left
    return ans

  def search_higher(self, key, key_higher):
    node = self
    if node.key is None:
      return key_higher
    ans = key_higher
    while node is not None:
      if node.key > key:
        if ans > node.key:
          ans = node.key
        node = node.left
      elif node.key <= key:
        node = node.right
    return ans

  def end_lower(self, end_lower_key):
    node = self
    while node.left is not None:
      node = node.left
    return node.key

  def end_higher(self, end_higher_key):
    node = self
    while node.right is not None:
      node = node.right
    return node.key

  def DoubleRightRotation(self):
    tl = self.left
    self.left = tl.right.right
    tl.right.right = self
    tlr = tl.right
    tl.right = tlr.left
    tlr.left = tl
    if tlr.balance == "Left":
      tlr.right.balance = "Right"
      tlr.left.balance = "Even"
    elif tlr.balance == "Right":
      tlr.right.balance = "Even"
      tlr.left.balance = "Left"
    elif tlr.balance == "Even":
      tlr.right.balance = "Even"
      tlr.left.balance = "Even"
    tlr.balance = "Even"
    return tlr

  def DoubleLeftRotation(self):
    tr = self.right
    self.right = tr.left.left
    tr.left.left = self
    trl = tr.left
    tr.left = trl.right
    trl.right = tr
    if trl.balance == "Right":
      trl.left.balance = "Left"
      trl.right.balance = "Even"
    elif trl.balance == "Left":
      trl.left.balance = "Even"
      trl.right.balance = "Right"
    elif trl.balance == "Even":
      trl.left.balance = "Even"
      trl.right.balance = "Even"
    trl.balance = "Even"
    return trl

  def SingleLeftRotation(self):
    tr = self.right
    tr.balance = "Even"
    self.balance = "Even"
    self.right = tr.left
    tr.left = self
    return tr

  def SingleRightRotation(self):
    tl = self.left
    tl.balance = "Even"
    self.balance = "Even"
    self.left = tl.right
    tl.right = self
    return tl

  def replace(self, p, v):
    if p.left == self:
      p.left = v
    else:
