class BITD:
  def __init__(self, n):
    self.size = n
    self._body = [-1] * (n+1)
  def __repr__(self):
    return ("BIT([" + ", ".join(str(self.at(i)) for i in range(self.size)) + "])")
  def ins(self, i):
    v = i
    i += 1
    while(i <= self.size):
      self._body[i] = max(self._body[i], v)
      i += i & -i
  def at(self, i): # max{x | x in self and x <= i}
    i += 1
    s = -1
    while(i > 0):
      s = max(s, self._body[i])
      i -= i & -i
    return s

class BITU:
  def __init__(self, n):
    self.size = n
    self._body = [N] * (n+1)
  def __repr__(self):
    return ("BIT([" + ", ".join(str(self.at(i)) for i in range(self.size)) + "])")
  def ins(self, i):
    v = i
    i = self.size-1 - i
    i += 1
    while(i <= self.size):
      self._body[i] = min(self._body[i], v)
      i += i & -i
  def at(self, i): # max{x | x in self and x <= i}
    i = self.size-1 - i
    i += 1
    s = N
    while(i > 0):
      s = min(s, self._body[i])
      i -= i & -i
    return s

