def cal(A):
    if len(A) == 0:
        return 0
    else:
        B = sorted(A)
        C = [B[len(B)-1-i] for i in range(len(B))]
        if A == B or A == C:
            if A == B:
                output = 0
                for i in range(len(A)):
                    output += (A[i] * (len(A)-i))
                return output
            else:
                output = 0
                for i in range(len(A)):
                    output += (A[N-i-1] * (len(A)-i))
                return output
        else:
            min_A = B[0]
            for i in range(len(A)):
                if A[i] == min_A: #最小
                    pt = i
                    break
            A_left,A_right = A[:pt],A[pt+1:]
            ans = min_A * (len(A_left)+1) * (len(A_right)+1)
            return ans + cal(A_left) + cal(A_right)

