INF = float('inf')

def query(a, b, k, l, r, st):
  if r <= a or b <= l:
    return INF
  if a <= l and r <= b:
    return st[k]
  else:
    k *= 2
    t = (l + r) // 2
    vl = query(a, b, k + 1, l, t, st)
    vr = query(a, b, k + 2, t, r, st)
    return min(vl, vr)

def main():
  N = int(input())
  a = list(map(int, input().split()))

  n = 1 << N.bit_length()
  st = [INF] * (2 * n - 1)

  for i in range(N):
    k = i + n - 1
    st[k] = a[i]
    while k > 0:
      k = (k - 1) // 2
      st[k] = min(st[k * 2 + 1], st[k * 2 + 2])

  result = 0
  for l in range(N):
    for r in range(l, N):
      result += query(l, r + 1, 0, 0, n, st)
  print(result)

main()

