class UnionFind():
  def __init__(self, elements):
    self.elements = elements
    self._root = {}
    self.size = [1] * (len(self.elements)+1)
    for e in self.elements:
      self._root[e] = e

  def unite(self, x, y):
    x = self.root(x)
    y = self.root(y)
    res = self.size[x] + 1
    self.size[x] += self.size[y]

    if x != y:
      self._root[y] = x

    return res

  def root(self, x):
    if self._root[x] != x:
      self._root[x] = self.root(self._root[x])
    return self._root[x]

