class RMQ:
    def __init__(self, n):
        _n = 1
        while _n < n:
            _n <<= 1
        self.n = _n
        self.dat = [INF] * (2 * _n - 1)

    def update(self, k, x):
        k += self.n - 1
        self.dat[k] = x
        while k > 0:
            k = (k - 1) >> 1
            self.dat[k] = min(self.dat[2 * k + 1], self.dat[2 * k + 2])

    def __query(self, s, t, k, l, r):
        if r <= s or t <= l:
            return INF
        if s <= l and r <= t:
            return self.dat[k]

        mid = (l + r) >> 1
        vl = self.__query(s, t, 2 * k + 1, l, mid)
        vr = self.__query(s, t, 2 * k + 2, mid, r)
        return min(vl, vr)

    def query(self, s, t):
        return self.__query(s, t, 0, 0, self.n)

