class Treap():
    class Node():
        def __init__(self, data):
            self.left = None
            self.right = None
            self.data = data
            self.priority = random.random()
            # print(data, self.priority)

        def to_dict(self):
            d = {
                'data': self.data,
            }

            if self.left:
                d['left'] = self.left.to_dict()
            if self.right:
                d['right'] = self.right.to_dict()

            return d

        def __str__(self):
            return json.dumps(self.to_dict(), indent='  ')

    def __init__(self):
        self.__root = None

    def __insert(self, node, data):
        if node is None:
            return self.Node(data)
        if data < node.data:
            node.left = self.__insert(node.left, data)
            if node.priority < node.left.priority:
                node = self.__rotate_right(node)
        else:
            node.right = self.__insert(node.right, data)
            if node.priority < node.right.priority:
                node = self.__rotate_left(node)

        return node

    def __rotate_left(self, node):
        tmp_node = node.right
        node.right = tmp_node.left
        tmp_node.left = node
        return tmp_node

    def __rotate_right(self, node):
        tmp_node = node.left
        node.left = tmp_node.right
        tmp_node.right = node
        return tmp_node

    def insert(self, data):
        self.__root = self.__insert(self.__root, data)
        return self

    def __find_lcr(self, data, node, lv, rv):
        if node is None:
            return lv, None, rv
        if data == node.data:
            return lv, data, rv
        if lv < node.data < data:
            lv = node.data
        if data < node.data < rv:
            rv = node.data
        if data < node.data:
            return self.__find_lcr(data, node.left, lv, rv)
        else:
            return self.__find_lcr(data, node.right, lv, rv)

    def find_lcr(self, data):
        return self.__find_lcr(data, self.__root, -sys.maxsize, sys.maxsize)

    def __hight(self, node):
        if node is None:
            return 0
        lh = 1
        if node.left:
            lh += self.__hight(node.left)

        rh = 1
        if node.right:
            rh += self.__hight(node.right)
        return max(lh, rh)

    @property
    def hight(self):
        return self.__hight(self.__root)


