    def __init__(self,key=None):
        self.key = key
        self.left = None
        self.right = None
        self.balance = "Even"
    def search(self,key):
        if self.key == None:
            return None
        if self.key > key:
            if self.left == None:
                return None
            else:
                return self.left.search(key)
        if self.key < key:
            if self.right == None:
                return None
            else:
                return self.right.search(key)
        return self # self.key == keyの場合

    def search1(self,key):#key以下の値で最大のものを出力（ない場合は-1）
        ans=-1
        if self.key==None:
            return None
        if self.key>key:
            if self.left==None:
                return ans
            else:
                return max(ans,self.left.search1(key))
        if self.key<key:
            if self.right==None:
                return max(ans,self.key)
            else:
                return max(ans,self.right.search1(key),self.key)
        return self.key

    def search2(self,key):#key以上の値で最小のものを出力（ない場合は10**20）
        ans=10**20
