        if self.key>key:
            if self.left==None:
                return min(ans,self.key)
            else:
                return min(ans,self.left.search2(key),self.key)
        if self.key<key:
            if self.right==None:
                return ans
            else:
                return min(ans,self.right.search2(key))
        return self.key

