class SparseTable:
    def __init__(self, N, a):
        n = 1
        log = 0
        while n <= N:
            n <<= 1
            log += 1
        lookup = [[0] * log for _ in range(N)]
        for i in range(N):
            lookup[i][0] = a[i]
        for j in range(1, log):
            for i in range(N - (1 << j) + 1):
                lookup[i][j] = min(lookup[i][j-1], lookup[i + (1 << (j-1))][j-1])
        self.lookup = lookup
        self.log = log

    def query(self, l, r):
        lb, ub = 0, self.log + 1
        while ub - lb > 1:
            m = (lb + ub) // 2
            if (1 << m) <= r - l:
                lb = m
            else:
                ub = m
        return min(self.lookup[l][lb], self.lookup[r - (1 << lb)][lb])


