import sys
input = sys.stdin.readline


class BIT:
    # 1,,,,,,,Nまでの数値を扱える
    def __init__(self, n):
        self.n = n
        self.data = [0]*(n+1)

    def to_sum(self, i):
        # i番目のところまで要素を足し合わせる
        s = 0
        while i > 0:
            s += self.data[i]
            i -= (i & -i)
        return s

    def add(self, i, x):
        # i 番目のところに要素を足し合わせる
        while i <= self.n:
            self.data[i] += x
            i += (i & -i)

    def get(self, i, j):
        # i番目からj番目までの要素の合計値を数える(1<=i<=j<=Nという制約がついているけど)
        return self.to_sum(j)-self.to_sum(i-1)

    def bisect_right(self, i):
        # i 番目から　次に初めて1増えるところまでの最大の値 j を求める
        l = i
        r = self.n
        if self.get(i, r) == r-i+1:
            return r
        while r-l > 1:
            M = (l+r)//2
            if self.get(i, M) < M-i+1:
                r = M
            else:
                l = M
        return l

    def bisect_left(self, i):
        # i 番目から最後に初めて1減るところまでの最小のjを求める
        l = 1
        r = i
        if self.get(l, i) == i+1-l:
            return l
        while r-l > 1:
            M = (r+l)//2
            if self.get(M, i) < i+1-M:
                l = M
            else:
                r = M
        return r


def main():
    N = int(input())
    a = list(map(int, input().split()))
    b = [(a[i], i+1) for i in range(N)]
    b.sort(reverse=True)
    tree = BIT(N)
    ans = 0

    for value, index in b:
        tree.add(index, 1)

        ans += (tree.bisect_right(index)-index+1) * \
            (index-tree.bisect_left(index)+1)*value

    print(ans)


if __name__ == "__main__":
    main()

