INF = 10**18

class RMQ:
    def __init__(self, size):
        n = 1
        while n < size:
            n <<= 1
        self.n = n
        self.data = [INF] * (2*n-1)

    def update(self, i, x):
        i += self.n-1  # the leaf
        self.data[i] = x
        while i > 0:
            i = (i-1)//2
            vl = self.data[i*2+1]
            vr = self.data[i*2+2]
            self.data[i] = min(vl, vr)

    def query(self, a, b, i=0, l=0, r=-1):
        if r == -1:
            r = self.n

        if r <= a or b <= l:
            return INF
        if a <= l and r <= b:
            return self.data[i]

        m = (l+r)//2
        vl = self.query(a, b, i*2+1, l, m)
        vr = self.query(a, b, i*2+2, m, r)
        return min(vl, vr)

