        }
        let mut posr = pos;
        while posr < vals.len() - 1 && vals[posr + 1] > val {
            posr = posr + 1;
        }
        let num_pat = ((pos - posl) + 1) * (posr - pos + 1);
         sum += (val + 1) * num_pat as u64;
    }
    println!("{}", sum);
