struct SegT<T, F, G> where T: Copy, F: FnMut(T, T) -> T, G: FnMut(T, T) -> T {
    n: usize,
    v: Vec<T>,
    def: T,
    upf: F,
    getf: G
}

impl<T, F, G> SegT<T, F, G> where T: Copy, F: FnMut(T, T) -> T, G: FnMut(T, T) -> T {
    fn new(n: usize, def: T, upf: F, getf: G) -> SegT<T, F, G> {
        let mut s = 1;
        while s < n {
            s *= 2;
        }
        SegT{n: s, v: vec![def; 2 * s - 1], def: def, upf: upf, getf: getf}
    }

    fn from_vec(xs: &Vec<T>, def: T, upf: F, mut getf: G) -> SegT<T, F, G> {
        let l = xs.len();
        let mut s = 1;
        while s < l {
            s *= 2;
        }
        let mut v: Vec<T> = vec![def; 2 * s - 1];
        for i in 0..l {
            v[i + s - 1] = xs[i];
        }
        for i in 2..s + 1 {
            let p = s - i;
            v[p] = getf(v[2 * p + 1], v[2 * p + 2]);
        }
        SegT{n: s, v: v, def: def, upf: upf, getf: getf}
    }

    fn update(&mut self, i: usize, x: T) {
        let n = self.n;
        self.update_rec(i, x, 0, 0, n - 1);
    }

    fn update_rec(&mut self, i: usize, x: T, p: usize, pl: usize, pr: usize) {
        if pl > i || pr < i {
            return;
        } else if p == i + self.n - 1 {
            self.v[p] = (self.upf)(self.v[i], x);
        } else {
            self.update_rec(i, x, 2 * p + 1, pl, (pl + pr - 1) / 2);
            self.update_rec(i, x, 2 * p + 2, (pl + pr + 1) / 2, pr);
            self.v[p] = (self.getf)(self.v[2 * p + 1], self.v[2 * p + 2]);
        }
    }

    fn get(&mut self, l: usize, r: usize) -> T {
        let n = self.n;
        self.get_rec(l, r, 0, 0, n - 1)
    }

    fn get_rec(&mut self, l: usize, r: usize, p: usize, pl: usize, pr: usize) -> T {
        if pl > r || pr < l {
            self.def
        } else if l <= pl && pr <= r {
            self.v[p]
        } else {
            let a = self.get_rec(l, r, 2 * p + 1, pl, (pl + pr - 1) / 2);
            let b = self.get_rec(l, r, 2 * p + 2, (pl + pr + 1) / 2, pr);
            (self.getf)(a, b)
        }
    }
}

