use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [usize1; n],
    }
    let mut uf = UnionFind::new(n + 2);
    let xs_rev = gen_rev(&xs);
    let mut res = 0i64;
    for i in (0..n).rev() {
        let k = xs_rev[i];
        let left = if k > 0 && xs[k - 1] > xs[k] {
            uf.num(k - 1) + 1
        } else {
            1
        };
        let right = if k < n - 1 && xs[k] < xs[k + 1] {
            uf.num(k + 1) + 1
        } else {
            1
        };
        let t = left * right * (i + 1);
        // eprintln!("i={}, k={}, t={}", i, k, t);
        res += t as i64;
        if k > 0 && xs[k - 1] > xs[k] {
            uf.unite(k - 1, k);
        }
        if k < n - 1 && xs[k] < xs[k + 1] {
            uf.unite(k, k + 1);
        }
    }
    writeln!(buf, "{}", res);
    buf
}

