fn main() {
    let mut buffer = String::new();
    if let Err(e) = io::stdin().read_line(&mut buffer) {
        eprintln!("{}", e);
        return;
    }
    buffer = buffer.trim_right().to_string();

    let mut buffer = String::new();
    // read all values
    if let Err(e) = io::stdin().read_line(&mut buffer) {
        eprintln!("{}", e);
        return;
    }
    let mut vals: Vec<u64> = buffer.split_whitespace().map(|v| v.parse::<u64>().unwrap()).collect();

    let pos_map: HashMap<u64, usize> = vals.iter().enumerate().map(|(i,val)| (val-1,i)).collect();

    let mut sum = 0;
    for val in 0..vals.len() {
        let pos = pos_map[&(val as u64)];
        let val = val as u64;
        // how much it can be expanded to left
        let mut posl = pos;
        while posl > 0 && vals[posl-1] > val {
            posl = posl - 1;
        }
        let mut posr = pos;
        while posr < vals.len() - 1 && vals[posr + 1] > val {
            posr = posr + 1;
        }
        let num_pat = ((pos - posl) + 1) * (posr - pos + 1);
         sum += (val + 1) * num_pat as u64;
    }
    println!("{}", sum);
}

