fn main() {
    input! {
        n: usize,
        a: [usize1; n]
    };
    let mut pos = vec![0; n];
    for i in 0..n {
        pos[a[i]] = i+1;
    }

    let mut treap = Treap::new();
    treap.push(0);
    treap.push(n+1);

    let mut ans = 0;
    for i in 0..n {
        let c = pos[i];
        let left = treap.peek_less(c).unwrap();
        let right = treap.peek_greater(c).unwrap();
        ans += ((c-left) as i64) * ((right-c) as i64) * (i+1) as i64;
        treap.push(c);
    }
    println!("{}", ans);
}

