struct SegTree<T> {
    n: usize,
    acc: fn(&T, &T) -> T,
    node: Vec<T>,
    init: T,
}

impl<T: Clone> SegTree<T> {
    pub fn new(n: usize, init: T, acc: fn(&T, &T) -> T) -> SegTree<T> {
        let mut m = 1;
        while m < n {
            m *= 2;
        }
        SegTree {
            n: m,
            node: vec![init.clone(); m * 2],
            acc,
            init,
        }
    }

    pub fn add(&mut self, pos: usize, val: T) {
        let mut x = pos + self.n - 1;
        self.node[x] = (self.acc)(&self.node[x], &val);
        while x > 0 {
            x = (x-1)/2;
            self.node[x] = (self.acc)(&self.node[x], &val);
        }
    }

    fn sum_inner(&self, pos: usize, x: usize, y: usize, p: usize, q: usize) -> T {
        if x<= p && q <= y {
            return self.node[pos].clone();
        }
        if y <= p || q <= x {
            return self.init.clone();
        }

        let left = pos * 2 + 1;
        let mid = (p + q) / 2;
        let right = pos * 2 + 2;
        (self.acc)(&self.sum_inner(left, x, y, p, mid), &self.sum_inner(right, x, y, mid, q))
    }

    pub fn sum(&self, x: usize, y: usize) -> T {
        self.sum_inner(0, x, y, 0, self.n)
    }
}



fn main() {
    let n: usize = read_line().trim().parse().unwrap();
    let a: Vec<i64> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();

    let mut pos = HashMap::new();
    for i in 0..n {
        pos.insert(a[i], i);
    }

    let mut ans = 0i64;

    let mut pr = vec![0i32; n+1];
    let mut nr = vec![0i32; n+1];
    for i in 0..n {
        pr[i] = i as i32 -1;
        nr[i] = i as i32 +1;
    }

    for i in (1i64..(n+1) as i64).rev() {
        let x = pos.get(&i).unwrap();
        let v = *x as i64;
        let n = nr[*x];
        let p = pr[*x];
        ans += i * (v - p as i64) * (n as i64 - v);

        if (n >= 0) {
            pr[n as usize] = p;
        }
        if (p >= 0) {
            nr[p as usize] = n;
        }
    }

    println!("{}", ans);
}

