struct BIT<T: Clone, F: Fn(&T, &T) -> T> {
    buf: Vec<T>,
    f: F,
    zero: T,
}

impl<T: Clone, F: Fn(&T, &T) -> T> BIT<T, F> {
    fn new(n: usize, zero: &T, f: F) -> BIT<T, F> {
        BIT {
            buf: vec![zero.clone(); n + 1],
            f: f,
            zero: zero.clone(),
        }
    }
    fn sum(&self, i: usize) -> T {
        let mut i = i;
        let mut s = self.zero.clone();
        while i > 0 {
            s = (self.f)(&s, &self.buf[i]);
            i = i & (i - 1);
        }
        s
    }

    fn add(&mut self, i: usize, x: &T) {
        let mut i = i as i64;
        while i < self.buf.len() as i64 {
            let y = {
                let t = &self.buf[i as usize];
                (self.f)(t, x)
            };
            self.buf[i as usize] = y;
            i += i & -i;
        }
    }
}

fn main() {
    let n = get!(usize);
    let aa = util::gets::<u64>();

    let mut bit = BIT::new(n + 1, &0, |&a, &b| max(a, b));

    let mut idx = vec![0; n + 1];

    for (i, &a) in aa.iter().enumerate() {
        idx[a as usize] = i;
    }

    let mut ans = vec![0; n + 1];

    for a in 1..n + 1 {
        let i = idx[a] + 1;

        let k = bit.sum(i);

        ans[i] = (i - k) as u64 * a as u64 + ans[k];
        bit.add(i, &i);
    }

    println!("{}", ans.iter().sum::<u64>());
}

