#[derive(Debug)]
struct SegmentTree<T, U> {
    len: usize,
    nodes: Vec<T>,
    phantom: std::marker::PhantomData<U>,
}
impl<T, U> SegmentTree<T, U>
where
U: Monoid<T>,
T: Copy + Clone + std::fmt::Debug,
{
#[allow(dead_code)]
    fn new(n: usize) -> Self {
        let mut len = 1;
        while len < n {
            len *= 2;
        }
        SegmentTree {
            len: len,
            nodes: vec![U::identity(); 2 * len - 1],
            phantom: Default::default(),
        }
    }
#[allow(dead_code)]
    fn from_vec(vec: &Vec<T>) -> Self {
        let mut len = 1;
        while len < vec.len() {
            len *= 2;
        }
        let mut nodes = vec![U::identity(); 2 * len - 1];
        for i in 0..vec.len() {
            nodes[i + len - 1] = vec[i];
        }
        for i in (0..len - 1).rev() {
            nodes[i] = U::operation(nodes[2 * i + 1], nodes[2 * i + 2]);
        }
        SegmentTree {
            len: len,
            nodes: nodes,
            phantom: Default::default(),
        }
    }
#[allow(dead_code)]
    fn update(&mut self, index: usize, val: T) {
        let mut index = index;
        index += self.len - 1;
        self.nodes[index] = val;
        while index > 0 {
            index = (index - 1) / 2; self.nodes[index] = U::operation(self.nodes[2 * index + 1], self.nodes[2 * index + 2]);
        }
    }
    fn get(&self, l: usize, r: usize) -> T {
        self._get(l, r, 0, 0, self.len)
    }
    fn _get(&self, ql: usize, qr: usize, index: usize, l: usize, r: usize) -> T {
        if r <= ql || qr <= l {
            return U::identity();
        }
        if ql <= l && r <= qr {
            return self.nodes[index];
        }
        let vl = self._get(ql, qr, 2 * index + 1, l, (l + r) / 2);
        let vr = self._get(ql, qr, 2 * index + 2, (l + r) / 2, r);
        U::operation(vl, vr)
    }
}

fn dfs(tree: &SegmentTree<usize, Calc>, ainv: &Vec<usize>, left: usize, right: usize) -> usize {
    let minval = tree.get(left,right);
    let minind = ainv[minval];
    if left + 1 == right {
        return minval;
    }
    let mut res = 0;
    res += (minind-left+1)*(right-minind)*minval;
    if minind > left {
        res += dfs(tree, ainv, left, minind);
    }
    if right > minind+1 {
        res += dfs(tree, ainv, minind+1, right);
    }
    res
}

fn solve() {
    let n = get!(usize);
    let a = get!([usize]);

    let mut ainv = vec![0; n+1];
    let mut tree = SegmentTree::<usize, Calc>::new(n);
    for i in 0..n {
        ainv[a[i]] = i;
        tree.update(i, a[i]);
    }
    println!("{}", dfs(&tree, &ainv, 0, n));
}

