    mat
  }

  pub fn chars() -> Vec<char> {
    let mut buf = String::new();
    let s = stdin();
    s.lock().read_line(&mut buf).ok();
    buf.trim_right().chars().collect()
  }
}

use std::io::{self, Read,Error};
use std::u64;
use std::collections::HashMap;

fn main() {
    let mut buffer = String::new();
    if let Err(e) = io::stdin().read_line(&mut buffer) {
        println!("{}", e);
        return;
    }
    buffer = buffer.trim_right().to_string();

    let mut buffer = String::new();
    // read all values
    if let Err(e) = io::stdin().read_line(&mut buffer) {
        println!("{}", e);
        return;
    }
    let mut vals: Vec<u64> = buffer.split_whitespace().map(|v| v.parse::<u64>().unwrap()).collect();

    // 5 4 8 1 2 6 7 3
    let mut sum = 0;
    let n = vals.len();
    for l in 0..n {
        let mut min = vals[l];
        for r in l..n {
            let v = vals[r];
            if v == 1 {
                sum = sum + (n as u64 - r as u64);
                break;
            }
            if v < min {
                min = v;
            }
            sum = sum + min;
        }
     }
    println!("{}", sum);
}
